\section{Homotopy groups of $p$-perfect monoids}\label{sec:pperf}
%\section{$p$-perfect commutative monoids}

\begin{defn}
Let $M$ be a commutative monoid. $M$ is called \textit{$p$-perfect} if it belongs to $\CMon[\frac{1}{p}]$, i.e., if the Frobenius map $p:M\to M$ is an equivalence.
\end{defn}

In this section, we analyze the structure of homotopy groups of $p$-perfect commutative monoids. The main result of this section is the following theorem.

\begin{thm}\label{thm:simple}
    Let $M$ be a $p$-perfect commutative monoid. Then:
    \begin{enumerate}
        \item $M$ is a simple space, that is, $\pi_1(M,m)$ is abelian for every $m \in M$, and its action on $\pi_n(M,m)$ is trivial for all $n\geq 1$; 
        \item $\pi_n(M,m)$ is uniquely $p$-divisible for all $n\geq 1$. 
    \end{enumerate}
\end{thm}


Before proving \Cref{thm:simple}, we would like to point out two differences with the grouplike case that are at the heart of our difficulties. First, not all components of a commutative monoid $M$ are the same, and in particular we may not reduce to the component of $0\in~M$. Specifically, the Frobenius map typically goes from $(M,m)$ to $(M, pm)$ and is thus not an endomorphism of pointed spaces, which complicates $\pi_*$-considerations. Second, for essentially the same reason, $M$ itself need not be a simple space: its fundamental groups can be arbitrarily noncommutative (to wit, $\F$ has $\Sigma_n$ as the fundamental group at the basepoint $n$), and they can act non-trivially on higher homotopy groups.


The idea to prove \Cref{thm:simple} is to consider the following map of pointed spaces: \[(M,m)^p\xrightarrow{\mu} (M,pm) \xrightarrow{\simeq} (M,m)\] where the first map is the addition, and the second map is the inverse of the Frobenius map (which is an equivalence by the assumption that $M$ is $p$-perfect). 

    This induces, for $n \geqslant 1$, a family of maps
   \begin{equation}\label{eq: rho_n}
 \rho_n:~\pi_n(M,m)^p\to~\pi_n(M,m)
\end{equation}
  satisfying certain conditions coming from properties of $M$, thus providing an extra algebraic structure on these homotopy groups. The general claim is that this algebraic structure is enough to guarantee the conclusions of \Cref{thm:simple}.

    First, we will analyse the extra structure on the fundamental groups of $M$. 

    \begin{prop}\label{prop: rho}
        Let $G$ be a group with a group morphism $\rho: G^p\to G$ such that: 
        \begin{enumerate}
            \item For all $g\in G$, $\rho(g,...,g) = g$; 
            \item For any permutation $\sigma\in\Sigma_p$, there is a fixed $k_\sigma\in G$ such that $\rho\circ \sigma = k_\sigma \rho k_\sigma^{-1}.$
        \end{enumerate}

        In this case, $G$ is abelian and uniquely $p$-divisible. Furthermore, the map $\rho_1$ defined in (\ref{eq: rho_n}) satisfies these two conditions with $G=\pi_1(M,m)$. 
    \end{prop}
    \begin{proof}
        Let us first justify that $\rho_1:\pi_1(M,m)^p\to \pi_1(M,m)$ satisfies these two conditions. The first one is evident, as the composite $(M,m)\xrightarrow{\Delta}(M,m)^p\xrightarrow{\mu} (M,pm)\xrightarrow{\simeq}(M,m)$ is by definition the composition of an equivalence and its inverse, i.e., the identity. 

        For the second one, this comes from the fact that the addition  on $M$ is homotopy commutative. Note that the homotopy commutativity of the addition does not give pointed homotopies, it only gives homotopies, hence the need for conjugation by $k_\sigma$. In fact, for a general $M$, $k_\sigma$ can be viewed as a power operation applied to $m$.

        Now let us prove the algebraic claim. Specializing the second condition to diagonal elements, and using the first condition, we find that for any $g$ and $\sigma$, $$g=\rho(g,...,g)= \rho\circ \sigma(g,...,g) = k_\sigma \rho(g,...,g) k_\sigma^{-1} = k_\sigma g k_\sigma^{-1}.$$ Hence $k_\sigma$ is central, and so the second condition simplifies to $\rho\circ \sigma = \rho$. 

    In particular, we find: $$g=\rho(g,...,g) = \rho(g,1,...,1)\rho(1,g,1,...,1)... \rho(1,...,1,g) = \rho(g,1,...,1)^p$$ so that $G$ is indeed $p$-divisible. Moreover since $ g \mapsto \rho(g,1,...,1)$ is a group homomorphism, $G$ is uniquely $p$-divisible. We also find $gh= \rho(g,1,...,1)^p \rho(1,h,1,...)^p$, and since $(g,1,...,1)$ and $(1,h,1,...)$ commute in $G^p$, we get that $gh= hg$ and we deduce that $G$ is abelian.

    \end{proof}

    \begin{rmk}
    Note that under the conditions of \Cref{prop: rho} we get that $\rho: G^p\to G$ is simply equal to $\frac{1}{p}\sum_{i=1}^p$. 
    \end{rmk}

    We can then argue similarly for higher homotopy groups. The maps \[\rho_n:~\pi_n(M,m)^p \to~\pi_n(M,m),\] defined in (\ref{eq: rho_n}), have the same first property as in \Cref{prop: rho}, and in the second property the conjugation by $k_\sigma$ is replaced by the \emph{action} of $k_\sigma\in\pi_1(M,m)$ on $\pi_n(M,m)$ which we denote as $\rho_n\circ \sigma = k_\sigma\cdot \rho_n$. To sum up, we want to prove the following statement.

    \begin{prop}\label{prop: rho_n}
        Let $G$ be a group acting on an abelian group $A$. Assume there is a morphism $\rho: A^p\to A$ of abelian groups such that: 
         \begin{enumerate}
            \item For all $a\in A$, $\rho(a,...,a) = a$; 
            \item For any permutation $\sigma\in\Sigma_p$, there is a fixed $k_\sigma\in G$ such that $\rho\circ \sigma = k_\sigma \cdot\rho $.
        \end{enumerate}
        In this case, $A$ is uniquely $p$-divisible. If, furthermore, $G$ is abelian, uniquely $p$-divisible, and the map $\rho: A^p \to A$ is compatible with the action of $G^p$ (where $G^p$ acts on $A$ via $G^p \xrightarrow{\frac{1}{p}\sum_{i=1}^p}G$), then the action of $G$ on $A$ is trivial. 


        Furthermore, each map $\rho_n$ defined in (\ref{eq: rho_n})  provides the group $A=\pi_n(M,m)$ with this structure, where  $G=\pi_1(M,m)$ with the standard action of $G$ on $A$.
    \end{prop}
    \begin{proof}
       The proof that homotopy groups of $M$ have this extra structure with these properties is exactly the same as in the proof of \Cref{prop: rho}. 

       For the algebraic fact, we may again plug in a diagonal element, to find that $$a= \rho(a,...,a) = \rho\circ \sigma(a,...,a) = k_\sigma \cdot \rho (a,...,a) = k_\sigma \cdot a$$ from which it follows that $k_\sigma$ acts trivially on $\pi_n(M,m)$. So we have the same argument for unique $p$-divisibility as in \Cref{prop: rho}. 

Now for the trivial action, we note that $\rho: A^p \to A$ must also be $\frac{1}{p}\Sigma_{i=1}^p$ by the previous computation. So the equivariance condition for $\rho$ reads as follows: for $\underline g\in G^p, \underline a\in A^p$, $$\frac{1}{p}\sum_{i=1}^p( g_i\cdot a_i)= (\frac{1}{p}\sum_i g_i)\cdot (\frac{1}{p}\sum_i a_i).$$
Putting all of the $g_i$'s except $g_1$ to be trivial, and all of the $a_i$'s except for $a_p$ to be trivial, we find $\frac{1}{p}a_p= (\frac{1}{p}g_1)(\frac{1}{p}a_p)$. Multiplying this by $p$, we find that $\frac{1}{p}g_1$ acts trivially on $a_p$. However both $g_1$ and $a_p$ were chosen to be arbitrary, so the action is indeed trivial. 
    \end{proof}
\begin{proof}[Proof of \Cref{thm:simple}]
   For a commutative monoid $M$, combine \Cref{prop: rho} and \Cref{prop: rho_n} to find that all the actions of $\pi_1(M,m)$ on $\pi_n(M,m)$ are trivial for all basepoints $m\in M$, and all $\pi_n(M,m)$ are uniquely $p$-divisible. 
\end{proof}
\begin{cor}\label{cor:homologypperf}
    Let $M$ be a $p$-perfect commutative monoid. The map $M\to\pi_0(M)$ is an $\mathbb F_p$-homology isomorphism. 
\end{cor}

\begin{proof}
    Indeed, from \Cref{thm:simple} and (a slight extension of) Serre's version of Hurewicz theorem (see e.g. the main theorem of \cite{modC}, p.55)  it follows that for a $p$-perfect monoid $M$, the groups $H_*(M;\mathbb F_p)$ are $p$-divisible for ${* \geqslant 1}$. Given that these groups are $\mathbb F_p$-vector spaces, it follows that they all vanish except $H_0(M;\mathbb F_p) \simeq H_0(\pi_0 (M);\mathbb F_p)$.
\end{proof}

\begin{rmk}
    It is not hard to prove that $\pi_0(M[\frac{1}{p}]) \cong \pi_0(M)[\frac{1}{p}]$ where the latter is meant in the classical sense (in particular, it equals $\pi_0 (\tel_p(M))$), so we can completely compute $H_*(M[\frac{1}{p}];\mathbb F_p)$. We will improve on this calculation in the rest of the paper.  
    %However, we will prove a more general statement in \Cref{cor: Fp-homol}, so we refrain from doing so here. 
\end{rmk}

Next, we consider the following ``approximation'' to $p$-perfection.

%A natural question to ask about $p$-perfection can be computed in the following way:

\begin{cons}\label{cons:telp}
    Let $M$ be a commutative monoid. The \textit{$p$-telescope} of M is  \[\tel_p(M) := \colim(M\xrightarrow{p}M\xrightarrow{p}\dots),\] the colimit being taken in $\CMon$. 
\end{cons}

\begin{ques}\label{ques: telescope}
For a commutative monoid $M$, is the canonical map $\tel_p(M) \to M[\frac{1}{p}]$ an equivalence?
\end{ques}

For discrete commutative monoids, as well as grouplike commutative monoids (and more generally spectra) the answer to \Cref{ques: telescope} is indeed positive. However, using \Cref{thm:simple} we can see that in general it can be negative, as in the following example.

\begin{prop}\label{prop:counterex}
    Let $M=\F$. In this case, the canonical map $\tel_p(M)\to M[\frac{1}{p}]$ is \emph{not} an equivalence, i.e., the monoid $\tel_p(M)$ is \emph{not} $p$-perfect. 
\end{prop}

\begin{proof}
Fix $1\in \F$ and let $\underline 1 \in \tel_p(\F)$ be its image under the canonical map. Since the fundamental group functor commutes with filtered colimits, we get: $$\pi_1(\tel_p(\F),\underline 1)\cong \colim_k \pi_1(\F, p^k) \cong \colim_k \Sigma_{p^k}$$ and each of the maps $\Sigma_{p^k}\to \Sigma_{p^{k+1}}$ sends $\sigma$ to $(\sigma, ... ,\sigma)$ and in particular is injective. 

Thus $\Sigma_{p}$ embeds in $\pi_1(\tel_p(\F),\underline 1)$, which is therefore not abelian. It follows from \Cref{thm:simple} that $\tel_p(\F)$ is not $p$-perfect, and thus not equivalent to $\F[\frac{1}{p}]$. 
\end{proof}
\begin{rmk}\label{rmk:counterexfurther}
    With a similar argument, one may prove that the image of the group $\Sigma_p$ in $\pi_1(\tel_p(\F),\underline 1)$ is not $p$-divisible. The moral here is that $\sigma \in \Sigma_p$ is indeed sent to $(\sigma, ..., \sigma) = (\sigma, 1,...,1)(1,\sigma,1,...,1)\dots(1,...,1, \sigma) \in \Sigma_{p^2}$ \emph{but} each of the 
    $(1,...,1,\sigma,1,...)$ differs from the others by a conjugation. We explain this conjugation below. 

The failure of $\tel_p(\F)$ to be $p$-perfect is closely related to the failure of telescopes to be group complete, cf. \cite{thomas}. The idea here is that the Frobenius map on the space $\colim (M\to M\to ...)$ is induced by a map of diagrams, namely a map which looks like: 
\[\begin{tikzcd}
	M & M & M & \dots \\
	M & M & M & \dots
	\arrow["p", from=1-1, to=1-2]
	\arrow["p"', from=1-1, to=2-1]
	\arrow["p", from=1-2, to=1-3]
	\arrow[""{name=0, anchor=center, inner sep=0}, "p", from=1-2, to=2-2]
	\arrow[from=1-3, to=1-4]
	\arrow["p", from=1-3, to=2-3]
	\arrow[from=1-4, to=2-4]
	\arrow["p"', from=2-1, to=2-2]
	\arrow["p"', from=2-2, to=2-3]
	\arrow[from=2-3, to=2-4]
	\arrow["h"', draw=none, from=1-1, to=0]
\end{tikzcd}\]
The homotopy $h$ that is here is an \emph{interesting} homotopy, it is the one that witnesses that $p:M\to M$ is a map of commutative monoids, and hence commutes with the ``scalar'' $p$. It is a \emph{different} one than the homotopy $f\circ f= f\circ f$ that exists for any endomorphism $f$. If it were the latter, then the induced map on colimits would in fact be an equivalence, but because it is the former, there is no reason for it to be the case. 
%\comment{I've changed ''accounts for'' into ''is related to''}
This difference in homotopies is related to the fact that $(\sigma, ..., \sigma)$ is $p$-divisible \emph{up to conjugacy} in $\Sigma_{p^2}$ --- note that conjugacies in $\pi_1$ arise precisely from \emph{unpointed} homotopies, and they influence the induced map on colimits. 
\end{rmk}
In fact, we can make that precise with the following result --- this is analogous to \cite[Proposition 6]{thomas}, and the method is similar so for simplicity we only state the parts that will be relevant to the rest of the paper:
%\comment{Is this ok ?}
\begin{prop}\label{prop: sigma^3}
    Let $M$ be a commutative monoid. 
    \begin{enumerate}
        \item \label{item: tel p-perfect} Suppose $\tel_p(M)$ is $p$-perfect. Then it is the $p$-perfection of $M$. 
        \item Suppose $\pi_1(M,x)$ is hypoabelian for all $x$. Then $\tel_p(M)$ is $p$-perfect. More generally, $\tel_p(M)$ is $p$-perfect if for every $m\in M$, the image of $p^{\textnormal{3-cycle}}\in \Sigma_{p^3}$ in $\pi_1(M,p^3 m)$ is trivial, or the same statement with $3$ replaced by some $n\geq 3$.  
        \item More generally, suppose that for some $n\geq 3$ the image of $p^{n\textnormal{-cycle}}$ in $\pi_1(\tel_p(M), m)$ is $0$ for every $m\in M$. Then $\tel_p(M)$ is $p$-perfect. 
    \end{enumerate}
\end{prop}
\begin{proof}
The proofs are the same as in \cite[Proposition 6]{thomas} (see also \Cref{cor:agreemarc} for a formal relation between the two statements --- note that the latter does not depend on this statement, so there is no circularity).

    Let $N$ be a commutative monoid. Since $p: X\to X$ is a natural transformation of the identity on commutative monoids, the following two maps $$\map_{\CMon}(p\cdot -, N): \Map_{\CMon}(M,N)\to \Map_{\CMon}(M,N)$$ and $$\map_{\CMon}(M, p\cdot -):\Map_{\CMon}(M,N)\to \Map_{\CMon}(M,N)$$ are homotopic. Therefore, if $N$ is $p$-perfect, the first one is an equivalence because the second one is. It follows that in this case, restriction along $M\to \tel_p(M)$ induces an equivalence $$\map_{\CMon}(\tel_p(M),N)\xrightarrow{\simeq}\map_{\CMon}(M,N).$$
    The first point then follows immediately by the universal property of $M[\frac{1}{p}]$. 

    For the second point, recall that a group is hypoabelian if it contains no nontrivial perfect subgroups. Since the $p^{3-\textnormal{cycle}}$ is a product of disjoint $3$-cycles, it belongs to $A_{p^3}\subset \Sigma_{p^3}$, which is perfect for all $p$ The images of perfect subgroups are perfect, hence the hypoabelian case is indeed a special case of the ``More generally'' statement. 

    Suppose then that the $p^{3-\textnormal{cycle}}$ is trivial in each $\pi_1(M,p^3m)$, and consider the diagram of commutative monoids $M\xrightarrow{p^2}M\xrightarrow{p^2 }M \to \dots $. 

    By \emph{naturality} of multiplication by $p$, this induces a commutative diagram of spaces --- we added  basepoints but it is not a priori a diagram of pointed spaces:
    \[\begin{tikzcd}
	{(M,m)} & {(M,p^2m)} & {(M,p^4 m)} & \dots & {(M,p^{2k}m)} \\
	{(M,pm)} & {(M,p^3m)} & {(M,p^5m)} & \dots & {(M,p^{2k+1}m)}
	\arrow["{p^2}", from=1-1, to=1-2]
	\arrow["p"', from=1-1, to=2-1]
	\arrow["{p^2}", from=1-2, to=1-3]
	\arrow["p"', from=1-2, to=2-2]
	\arrow["p"', from=1-3, to=2-3]
	\arrow["p"', from=1-5, to=2-5]
	\arrow["{p^2}"', from=2-1, to=2-2]
	\arrow["{p^2}"', from=2-2, to=2-3]
\end{tikzcd}\]

Here the $2$-cells are obtained using the fact that $p^2$ is a map of commutative monoids and $p$ is natural with respect to those. 

Unwinding this, we find that the homotopy $p\circ p^2\simeq p^2\circ p$ sends the point $m$ to the image of $p^{3-\textnormal{cycle}}\in \Sigma_{p^3}$ in $\pi_1(M,p^3m)$. 

This element is trivial in each $\pi_1(M,p^{2k+3}m)$ by assumption, and so the $2$-cells are homotopies of pointed maps, and so this map of diagrams lifts to a map of diagrams of pointed spaces. Then we may take $\pi_n$, and we find that the vertical map induces an isomorphism on $\pi_n$ on colimits. Since $\pi_n$ commutes with colimits, this implies that $p: \tel_p(M)\to \tel_p(M)$ induces an isomorphism on $\pi_n$ at every point and for all $n$, and is thus an equivalence, which is what we wanted to prove. 

More generally, if the image of $p^{3\textnormal{-cycle}}$ only vanishes in $\pi_1(\tel_p(M),m)$, we know it must vanish at some finite stage of the telescope, and we can run the same argument simply by cofinality. For details about this last point, see \cite{thomas}.
\end{proof}

\begin{rmk}
In particular, if $\pi_1(M)$ is hypoabelian at all points, then $\tel_p(M)$ is simple by \Cref{thm:simple} and hence hypoabelian as well. This is not \emph{a priori} clear, in the sense that in general, a filtered colimit of hypoabelian groups need not be hypoabelian. To give a concrete example, note that subgroups of free groups are free, so that if $F$ is a free group on countably many generators, there is an abstract isomorphism $f: F\cong [F,F]$. In particular, we may follow it up with the inclusion $[F,F]\subset F$ to build a sequence $F\to F\to F \to \dots$ of inclusions whose filtered colimit is a perfect group, while each $F$ is hypoabelian. 
\end{rmk}

As in \cite[Example 5.2]{algcob}, the above also works in the context of motivic spaces, i.e., $\mathbb A^1$-invariant sheaves on the site of smooth $S$-schemes $\mathrm{Sm}_S$ for some scheme $S$. Considering, for example, $M=\mathrm{Vect}\simeq\coprod_n \mathrm{BGL}_n$, we find that for any ring $R$, the relevant matrix corresponding to $p^{\textnormal{3-cycle}}$ is given by  permutation matrix. 

Since this matrix belongs to $\mathrm{SL}_{p^3}(\mathbb Z)$ (determinants of permutation matrices agree with the signature of the permutation), it is $\mathbb A^1$-homotopic to the identity. Thus we find:
\begin{cor}
   The canonical map of presheaves of spaces on $\mathrm{Sm}_S$ 
   $$\tel_p (\mathrm{Vect})\to \mathrm{Vect}[\frac{1}{p}]$$
   is an $\mathbb A^1$-homotopy equivalence on affines. In particular, it is a motivic equivalence.
\end{cor}


%\begin{cor}
    %In $\mathbb A^1$-invariant sheaves on $\mathrm{Sm}_S$, the canonical map induces an equivalence $$\tel_p (\mathrm{Vect})\to \mathrm{Vect}[\frac{1}{p}]$$
%\end{cor}

\section{Comparison of $p$-perfection and group completion}\label{sec:group}

In this section, we prove our main result for many commutative monoids, including $\F$ and $\Proj(R)^\simeq$ with connected $\Spec R$: after $p$-perfection, connected components of such commutative monoid embed as ``positive'' components of its group completion, except for the component of 0. 

First, we introduce some notation.

\begin{nota}
    Let $x \in M$ be a point in a commutative monoid. 
    \begin{itemize}

    \item The \textit{telescope of $M$ at $x$} is 
    \[\tel^x(M) := \colim(M\xrightarrow{+x}M\xrightarrow{+x}\dots),\] the colimit being taken in $\Ss$.

    \item The formal inversion of $x$ on $M$ is $M[-x]$,  which is typically not the same as the telescope $\tel^x(M)$. 
    \end{itemize}
\end{nota}



\begin{defn}\label{def:locmon}
    Let $M$ be a commutative monoid. We say that $M$ is \textit{locally monogenic} if for any non-zero $x, y 
    \in M$ there exists $n \in \N$ and $z \in M$ such that $nx = y+z$.
\end{defn}

We introduce locally monogenic monoids because of the following nice property, which follows immediately from the definition. 

\begin{prop}\label{prop: invert anything}
    Let $M$ be a locally monogenic monoid. Then for any non-zero $x \in M$ the map $M[-x] \to M^\gp$ is an equivalence.
\end{prop}

\begin{proof}
    Since for a fixed non-zero $x$ and for any $y$ we have a presentation of the form $nx = y + z$, we get that any $y$ becomes invertible in $M[-x]$, so the two share the same universal property.
\end{proof}


\begin{ex}\
The monoid $\F$ is locally monogenic.
\end{ex}

\begin{ex}\
For a ring $R$ with connected $\Spec R$, the monoid $\Proj(R)^\simeq$ is locally monogenic by~\Cref{prop: Proj connected} below.
\end{ex}


\begin{prop}\label{prop: Proj connected}
    Let $R$ be a ring and $P$ a finitely generated projective $R$-module. Assume that the rank of $P$ is a non-vanishing function on $\Spec R$ (for example, $P$ is non-zero and $\Spec R$ is connected). Then there exists $n \in \N$ such that $P^n$ splits off a trivial summand $R$.
\end{prop}

\begin{proof}
    $P$ is a projective module hence locally free. Since $\Spec R$ is quasicompact, there is a finite cover by distinguished open sets  $\Spec R = \bigcup_{i=1}^n D(f_i)$ such that $P[\frac{1}{f_i}]$ is a free $R[\frac{1}{f_i}]$-module for every $i$.
    %on each $D(f_i)$.

    For each $i$, pick a surjection $\bar{r}_{i} \colon P[\frac{1}{f_i}] \to R[\frac{1}{f_i}]$.
    %on $D(f_i)$. 
    Since $P$ is finitely generated projective, up to a power of $f_i$ we can lift $\bar{r}_{i}$ to a map $r_i \colon P \to R$. Consider the map of $R$-modules $r = \bigoplus_{i=1}^n r_i \colon  P^{n} \to R$. The map $r$ induces a map of $R$-modules which is a surjection locally on $\Spec R$, hence it is surjective. Since its target is $R$, it automatically splits.
\end{proof}

\begin{thm}\label{thm:group completion}
    Let $M$ be a locally monogenic commutative monoid. Consider the pullback square of monoids, induced by the group completion map $M \to M^\gp$:

   \[\begin{tikzcd}
	N & M^\gp[\frac{1}{p}]  \\
\pi_0(M)[\frac{1}{p}] & \pi_0(M)^\gp[\frac{1}{p}] 
	\arrow[from=1-1, to=1-2]
	\arrow[from=1-1, to=2-1]
	\arrow[from=1-2, to=2-2]
	\arrow[from=2-1, to=2-2]
\end{tikzcd}\]

Then the natural map $M[\frac{1}{p}] \to N$ is an isomorphism on $\pi_0$ and an equivalence at all components except 0.

\end{thm}

The statement of \Cref{thm:group completion} has this ``except 0'' condition for a concrete reason. To describe it, we introduce:
\begin{defn}
Let $M$ be a commutative monoid. We say that \textit{$0$ is isolated in $M$} if the following two conditions hold:
\begin{itemize}
    \item The inclusion $0\to M$ is an inclusion of components, i.e., $\Omega(M,0)\simeq \pt$; 
    \item For $x,y\in M, (x+y\simeq 0)\implies (x\simeq y\simeq 0)$
\end{itemize}
\end{defn}
\begin{ex}
Let $C$ be a category with coproducts such that $x\coprod y \simeq 0$ implies $x = 0$ or $y=0$, e.g. if $C$ is semiadditive, or $C= \Fin$. In this case, $0$ is isolated in $(C^\simeq,\coprod)$. 
\end{ex}
\begin{lm}
    Let $M$ be a commutative monoid. $0$ is isolated in $M$ if and only if $M=N_+$ for some non-unital commutative monoid $N$, where $(-)_+$ is the left adjoint to the forgetful functor from commutative monoids to non-unital commutative monoids. 
\end{lm}
\begin{proof}
``If'': By \cite[Proposition 5.4.4.8]{HA}, the underlying space of $N_+$ is $N\coprod \{0\}$, proving the first condition of $0$ being isolated; the map $N\to N_+$ being a map of nonunital commutative monoids shows that the second condition is also satisfied. 

``Only if'': Suppose $0$ is isolated in $M$. By the second condition in the definition of isolated, the full sub-space of $M$ spanned by non-zero components is closed under products and therefore defines a non-unital commutative monoid $N$ with a non-unital commutative monoid map $N\to M$, which induces a map $N_+\to M$. Again by \cite[Proposition 5.4.4.8]{HA}, and now using the first condition in the definition, we see that $N_+\to M$ is an equivalence.
\end{proof}

\begin{prop}\label{prop: isolated}
    If $M$ is a commutative monoid and 0 is an isolated point, then 0 is also isolated in $M[\frac{1}{p}]$.
\end{prop}

\begin{proof}
    If $M = N_+$ where $N$ is a non-unital commutative monoid then $M[\frac{1}{p}] \simeq N[\frac{1}{p}]_+$, where now we consider $(-)[\frac{1}{p}]$ as functor on non-unital commutative monoids. Indeed, $(-)[\frac{1}{p}]$ and $(-)_+$ commute as they are left adjoints of commuting forgetful functors.
\end{proof}

\begin{rmk}
    \Cref{thm:group completion} is not true for an arbitrary commutative monoid, for example, it does not hold for $ M = \Proj(R)^\simeq$ when $R = \Z \times \Z$. Indeed, consider the point $(\Z, 0)$ in $M[\frac{1}{p}] \simeq \Proj(\Z)^\simeq [\frac{1}{p}] \times \Proj(\Z)^\simeq [\frac{1}{p}]$. By \Cref{prop: isolated}, $0$ is isolated in the second summand and so the component of $(\Z,0)$ in this product is equivalent to a component of $K(\Z)[\frac{1}{p}]\times \{0\}$. However, the point $0$ is not isolated in the second summand of $M^\gp[\frac{1}{p}] \simeq K(\Z)[\frac{1}{p}] \times K(\Z)[\frac{1}{p}]$ and the component of $(\Z,0)$ therein is equivalent to a product of a component of $ K(\Z)[\frac{1}{p}]$ with itself. 

    On the other hand, \Cref{thm:group completion} can also be true for a monoid that is not locally monogenic: for example, it holds for formal reasons for the monoid $M = K(\Z)_{\geqslant 0} \times K(\Z)_{\geqslant 0}$, where $K(\Z)_{\geqslant 0} = K(\Z) \times_\Z \N$.
\end{rmk}


We first prove the following partial case of \Cref{thm:group completion}.

\begin{prop}\label{prop: one generator}
Let $M$ be a $p$-perfect commutative monoid such that for some $x \in M$ the group completion map $M[-x] \to M^\gp$ is an equivalence. Denote $T = \tel^x(M)$. Then
the map \[(M, x) \to (T,x) \to (M^\gp, x)\]
is an equivalence between the component of $x$ in $M$ and the component of (the image of) $x$ in $M^\gp$. 
\end{prop}

\begin{proof}
Since $M$ is a simple space by \Cref{thm:simple}, we have
$M[-x] \simeq M^\gp \simeq T$ by~\cite[Corollary 7]{thomas}. 
 We want to show that the map $(M, x) \to (T,x)$ is an equivalence of corresponding connected components of $M$ and $T$. 

Since $M$ is $p$-perfect, the composition $(M,x)\xrightarrow{\Delta}(M,x)^p\xrightarrow{\mu} (M,px)$ is an equivalence. On $G = \pi_n(M, x)$ this composition induces 
$G \to G \times \ldots \times G \to H$ which was computed in \cite[Proposition 2.9]{ben}: this composition sends every element $g$ to  $p \cdot \trans(g)$ where $\trans \colon 
(M, x) \to (M, px)$ is the translation by $(p-1)x$. Since the composition is an isomorphism of groups and $G$ is uniquely $p$-divisible for $n \geqslant 1$ by \Cref{thm:simple}, the map $\trans \colon (M, x) \xrightarrow{+(p-1)x} (M, px)$ must be an equivalence as well. 
Observe that $T = \tel^x(M) \simeq \tel^{(p-1)x}(M)$.
Hence the map $(M, x) \to (T,x)$ is an equivalence of components, as we wanted to show.
\end{proof}

\begin{proof}[Proof of \Cref{thm:group completion}]
The theorem follows immediately from \Cref{prop: one generator} applied to the $p$-perfect locally monogenic monoid $M[\frac{1}{p}]$, thanks to \Cref{prop: invert anything}.
\end{proof}

\begin{ex}
    Let $M=\Fin^\simeq$. In this case, $M^\gp\simeq \Sph$ is the sphere spectrum, so \Cref{thm:group completion} tells us that 
    \[\Fin^\simeq[\frac{1}{p}]\setminus\{0\} \, \simeq \, \Sph[\frac{1}{p}]\times_{\Z[\frac{1}{p}]}(\mathbb N[\frac{1}{p}]\setminus\{0\}), \]
    i.e., the union of positive components of $\Sph[\frac{1}{p}]$. 
\end{ex}

