\begin{prop}
  $\Equiv_k$ has $\aleph_0$-bounded $(2k-1)$-splitting.
\end{prop}
\begin{proof}
  Fix a set of parameters $B$ in a model of $\Equiv_k$ and a $(2k-1)$-partitioned type $\tp(\abar_0;\dots;\abar_{2k-2}/B)$. For each $k$-tuple $\dbar = d_0\dots d_{k-1}$ of elements from the tuple $\abar_0\abar_1\dots \abar_{2k-2}$, if there is a $k$-tuple $\cbar \in B\abar_0\dots \abar_{k-1}$ not entirely contained in $\abar_0\dots\abar_{k-1}$ such that $E(\dbar,\cbar)$ holds, let $\cbar_{\dbar}$ be some such $k$-tuple. Let $C$ be the set of elements of $B$ occurring in the tuples $\cbar_{\dbar}$. Clearly $|C| < \aleph_0$. We need to show that $\tp(\abar_0;\dots;\abar_{2k-2}/B)$ does not $(2k-1)$-split over $C$.

  Fix $\bbar =b_0\dots b_{\ell-1}$ and $\dbar = d_0\dots d_{\ell-1}$ in $B$ satisfying that $\bbar \equiv_{C\abar_0\dots \hat{\abar}_i \dots \abar_{2k-2}} \dbar$ for each $i < 2k-1$. By quantifier elimination, all we need to do is check that whenever there is an instance of the $E$ relation involving elements of $\bbar$, then the same relation holds with the corresponding elements of $\dbar$. Any instance of the $E$ relation that does not involve an element from each of the tuples $\abar_i$ for $i < 2k-1$ must be the same for $\bbar$ and $\dbar$ by our assumption, so the only cases we need to check are those that involve elements from each $\abar_i$.

  Assume that $E(\tbar,\sbar)$ holds, where every element of $\tbar$ and $\sbar$ is either in $C$, $\abar_i$ for some $i < 2k-1$, or $\bbar$ and some element is from $\bbar$. Since we need an element from each of the $\abar_i$'s to occur in either $\tbar$ or $\sbar$, there can be only one element of $\tbar\sbar$ that is not from $\abar_i$ for some $i < 2k-1$. Therefore no elements of $C$ can be involved, and, by symmetry, we may assume that the relation is of the form $E(e_0\dots e_{k-1},e_k\dots e_{2k-3} b_m$ for some $m < \ell$, where for each $j < 2k-2$, $e_j \in \abar_i$ for some $i < 2k-1$. By construction, we must have placed some $c \in C$ satisfying that $E(e_0\dots e_{k-1},e_k \dots e_{2k-3} c)$, so now we have that $E(e_k\dots e_{2k-3} c , e_k\dots e_{2k-3} b_m)$. By our type condition, we also have that $E(e_k\dots e_{2k-3} c, e_k\dots e_{2k-3} d_m)$, whereby $E(e_0\dots e_{k-1},e_k\dots e_{2k-3}d_m)$.

  We have established that whenever an instance of the $E$ relation occurs involving elements of $\bbar$, the same relation occurs involving the corresponding elements of $\dbar$. By symmetry the reverse is also true, so by quantifier elimination we have that $\bbar \equiv_{C \abar_0\dots \abar_{2k-2}} \dbar$, as required.
\end{proof}

Finally, it is natural to wonder about the status of $\FOP_k$ and $\IP_k$ in $\Equiv_k$. Gabriel Conant has provided us with the following adaptation to the case of stable formulas of \cite[Lem.~3.26]{FOP} and its proof. 

\begin{lem}\label{lem:Gabe}
  Let $T$ be a complete theory. Suppose $\varphi(\xbar;\ybar)$ is stable in $T$ (as a partitioned formula), with $|\xbar| = |\ybar| = k$. Let $z_0,\dots,z_{k}$ be a partition of the $2k$ free variables in $\varphi(\xbar;\ybar)$. Then $\theta(z_0;\dots;z_k)\coloneq \varphi(\xbar,\ybar)$ is $\NFOP_k$ in $T$.
\end{lem}
\begin{proof}
  We will prove the contrapositive. Assume that $\theta(z_0;\dots;z_k)$ has $\FOP_k$ in $T$. We will show that the formula $\varphi(\xbar;\ybar)$ is unstable in $T$.

  Just as in the proof of \cite[Lem.~3.26]{FOP}, there must be $s,t < k+1$ such that $z_s \subseteq \xbar$ and $z_t \subseteq \ybar$. By switching $\xbar$ and $\ybar$ if necessary, we may assume without loss of generality that $s < t$. There are now two cases.

  \vspace{0.5em}

  \noindent \emph{Case 1.} $t = k$.

  For $i < \omega$, let $\tau_i = 0^{s-1}\concat i \concat 0^{k-s} \in \omega^k$. Choose a linear order $<_\ast$ on $\omega^k \cup \omega$ such that for $j \in \omega$, $\tau_i <_\ast j$ if and only if $i < j$. By \cite[Prop.~2.3]{FOP}, there is an array $(a_i^j)_{i<\omega,j\leq k}$ such that $\theta(a^0_{i_0};\dots ; a_{i_k}^k)$ holds if and only if $(i_0,\dots,i_{k-1}) <_\ast i_k$. For $r \in (k-1)\setminus \{s\}$, let $c_r$ be the subtuple of $a_0^r$ corresponding to the overlap between $z_r$ and $\xbar$, and let $d_r$ be the subtuple of $a_0^r$ corresponding to the overlap between $z_r$ and $\ybar$. For $i < \omega$, let $\gbar_i$ be the enumeration of $(c_0,\dots,c_{s-1},a_i^{s},c_{s+1},\dots,c_{k-1},\varnothing)$ in the order corresponding to $\xbar$, and let $\hbarr_i$ be the enumeration of $(d_0,\dots,d_{s-1},\varnothing,d_{s+1},\dots,d_{k-1},a^k_j)$ in the order corresponding to $\ybar$. By construction, $\varphi(\gbar_i,\hbarr_j)$ is the same thing as $\theta(a_0^0;\dots;a_0^{s-1};a_i^s;a_0^{s+1};\dots;a_0^{k-1},a_0^k)$. Therefore we have that $\varphi(\gbar_i,\hbarr_j)$ holds if and only if $\tau_i <_\ast j$ and so if and only if $i < j$, whereby $\varphi(\xbar;\ybar)$ is unstable in $T$.

  \vspace{0.5em}

  \noindent \emph{Case 2.} $t < k$.

  For $i,j < \omega$, let $\tau_{i,j} = 0^{s-1}\concat i \concat 0^{t-s-1}\concat j \concat 0^{k-1} \in \omega^k$. Choose a linear order $<_\ast$ on $\omega^k \cup \omega$ such that for $i,j < \omega$, $\tau_{i,j} <_\ast 0$ if and only if $i<j$. By \cite[Prop.~2.3]{FOP}, there is an array $(a_i^j)_{i<\omega,j\leq k}$ such that $\theta(a^0_{i_0};\dots ; a_{i_k}^k)$ holds if and only if $(i_0,\dots,i_{k-1}) <_\ast i_k$. For $r \in (k+1)\setminus \{s,t\}$, let $c_r$ be the subtuple of $a_0^r$ corresponding to the overlap between $z_r$ and $\xbar$, and let $d_r$ be the subtuple of $a_0^r$ corresponding to the overlap between $z_r$ and $\ybar$. For $i < \omega$, let $\gbar_i$ be the enumeration of $(c_0,\dots,c_{s-1},a_i^s,c_{s+1},\dots,c_{t-1},\varnothing,c_{t+1},\dots,c_{k})$ in the order corresponding to $\xbar$, and let $\hbarr_i$ be the enumeration of $(d_0,\dots,d_{s-1},\varnothing,d_{s+1},\dots,d_{t-1},a_i^t,d_{t+1},\dots,d_k)$ in the order corresponding to $\ybar$. By construction $\varphi(\gbar_i,\hbarr_j)$ is the same thing as $\theta(a_0^0;\dots;a_0^{s-1};a_i^{s};a_0^{s+1},\dots,a_0^{t-1},a_j^t;a_0^{t+1},\dots,a_0^k)$. Therefore we have that $\varphi(\gbar_i,\hbarr_j)$ holds if and only if $\tau_{i,j} <_\ast 0$ and so if and only if $i < j$, whereby $\varphi(\xbar;\ybar)$ is unstable in $T$.
\end{proof}

\begin{prop}\label{prop:Equiv-NFOP-k}
  $\Equiv_k$ is $\NFOP_k$ and has IP$_{k-1}$.
\end{prop}
\begin{proof}
  It is immediate from the fact that $E$ is an equivalence relation on $k$-tuples that the partitioned formula $E(\xbar;\ybar)$ (with $|\xbar|=|\ybar| = k$) is stable in $\Equiv_k$. Therefore, by quantifier elimination, \cref{lem:Gabe}, and \cite[Thm.~1.5]{FOP}, $\Equiv_k$ is $\NFOP_k$.

 To see that $\Equiv_k$ has IP$_{k-1}$ fix a $k$-tuple $\abar$ and an array $(b_{i}^j)_{i<\omega,j<k-1}$ of distinct elements. For any $X \subseteq \omega^{k-1}$, we can find a $c$ such that for any $(i_0,\dots,i_{k-2}) \in \omega^{k-1}$, $E(\abar;b_{i_0}^0\dots b_{i_{k-2}}^{k-2}c)$ if and only if $(i_0,\dots,i_{k-2}) \in X$ (since any such pattern occurs in a model of $\Equiv_k^0$ and the class of models of $\Equiv_k^0$ has free amalgamation).
\end{proof}



So we've established that for every $k > 1$, the theory $\Equiv_k$ has IP$_{k-1}$, is $\NFOP_k$, has unbounded $(2k-2)$-splitting and bounded $(2k-1)$-splitting, and is $2k$-ary but not $(2k-1)$-ary, giving a simultaneous separation of $\NFOP_k$, bounded $k$-splitting, and $k$-arity.


%


Since $\Equiv_k$ is still $2k$-ary, we know that \cref{thm:bounded-k-splitting-indisc-extraction} is not entirely optimal for it, at least in some sense. \cref{thm:bounded-k-splitting-indisc-extraction} establishes that if $\mu$ is $k$-ineffable, then $\mu \to (\mu)_{\Equiv_k,n}$ for any $n < \omega$. Often in applications, merely finding an infinite indiscernible sequence (or an indiscernible sequence of length $\alpha$ for some relatively small countable ordinal $\alpha$) rather than an indiscernible sequence of some large cardinality is what really matters. Since $\Equiv_k$ is $2k$-ary, \cref{fact:Erdos-Rado-extraction} applies and implies that $\beth_{2k}^+ \to ((2^{\aleph_0})^+)_{\Equiv_k,n}$ for any $n < \omega$.

\section{Relationship to other higher-arity notions}
\label{sec:relationship-to-other}

%

In order to compare bounded $k$-splitting to $\NFOP_k$, we'll first recall some notation and facts from \cite[Sec.~3.2]{FOP}. $\Lc_k = \{P_0,\dots,P_{k},<,<_k,R\}$ is a language with $P_0,\dots,P_{k}$ unary relations, $<$ a binary relation, $<_k$ a $2k$-ary relation, and $R$ a $(k+1)$-ary relation. This language is used in \cite{FOP} for the indexing structure of a kind of generalized indiscernible that characterizes $\FOP_k$. $T_k$ is the universal $\Lc_k$-theory that says
\begin{itemize}
\item $P_0,\dots,P_{k}$ is a partition, 
\item $<$ is a linear order satisfying $P_0 < \dots < P_{k}$,
\item if $R(x_0,\dots,x_{k})$ holds, then $P_i(x_i)$ holds for each $i \leq k$,
\item $<_k$ only holds on $(P_0\times \dots \times P_{k-1})^2$ and is a linear order (i.e., a linear order on $k$-tuples in $P_0\times \dots \times P_{k-1}$), and
\item if $\xbar \leq_k \ybar$, $R(\ybar,w)$, and $w \leq z$, then $R(\xbar,z)$.\footnote{Note that the assumptions of this imply that $w$ and $z$ are in $P_k$.}
\end{itemize}
Note that $T_k$ imposes no restriction on the relationship between the relation $<$ on $P_0,\dots,P_{k-1}$ and the relations $<_k$ and $R$.

In \cite[Cor.~3.15]{FOP}, it is shown that the finite models of $T_k$ form a \Fraisse\ class. We let $\Hc_k$ denote its \Fraisse\ limit. Recall that given a structure $M$, a map $f : \Hc_k \to M^{<\omega}$ (where $M^{<\omega}$ is the set of finite tuples of elements of $M$) is an \emph{$\Hc_k$-indexed indiscernible sequence} if for any finite tuple $a_0,\dots,a_{k-1} \in \Hc_k$, the sorts of $f(a_0),\dots,f(a_{k-1})$ and $\tp(f(a_0),\dots, f(a_{k-1}))$ only depend on the quantifier-free type of $a_0\dots a_{k-1}$ in $\Hc_k$.

\begin{fact}[{\cite[Prop.~3.20]{FOP}}]\label{fact:FOP-k-indisc-witness}
  $T$ has $\FOP_k$ if and only if there is a model $M \models T$, a formula $\varphi(x_0,\dots,x_{k})$, and an $\Hc_k$-indexed indiscernible sequence $f : \Hc_k \to M^{<\omega}$ such that for any $(h_0,\dots,h_{k}) \in P_0(\Hc_k)\times \dots \times P_{k}(\Hc_k)$, we have that $f(h_i)$ is of the same sort as $x_i$ for each $i \leq k$ and $\varphi(f(h_0),\dots,f(h_k))$ holds if and only if $\Hc \models R(h_0,\dots,h_k)$.
\end{fact}



\begin{prop}\label{prop:if-bounded-k-then-NFOP-k}
  If $T$ has bounded $k$-splitting, then $T$ is $\NFOP_k$.
\end{prop}
\begin{proof}
  We will prove the contrapositive. Assume that $T$ has $\FOP_k$. Find $\varphi(x_0,\dots,x_{k})$, $M \models T$, and $f : \Hc_k \to M^{<\omega}$ as in the statement of \cref{fact:FOP-k-indisc-witness}.

  Fix $\ell < \omega$, and let $K$ consider the following finite model of $T_k$:
  \begin{itemize}
  %
  \item There are elements $b_0 < c_0 < b_1 < c_2 < \dots < b_{\ell -1} < c_{\ell-1}$ in $P_0$. 
  \item For each $i \leq k$ with $i > 0$, there is a single element $a_i$ in $P_i$.
  \item $(b_0,a_1,\dots,a_{k-1})  <_k (b_1,a_1,\dots,a_{k-1}) <_k \dots <_k (b_{\ell -1},a_1,\dots,a_{k-1}) < _k (c_{\ell -1},a_1,\dots,a_{k-1}) <_k \dots <_k (c_1,a_1,\dots,a_{k-1}) <_k (c_0,a_1,\dots,a_{k-1})$. 
  \item For each $j < \ell$, $R(b_j,a_1,\dots,a_{k})$ and $\neg R(c_j,a_1,\dots,a_{k})$ hold. 
  \end{itemize}
    Note that by construction, we have that for each $i < k$ and $j < \ell$, $b_j$ and $c_j$ have the same quantifier-free type over $b_{<j}c_{<j}a_0\dots \hat{a}_i \dots a_{k-1}$.

  \begin{sloppypar}
    We may regard $K$ as an $\Lc_k$-substructure of $\Hc_k$. Note that since $f$ is an $\Hc_k$-indexed indiscernible sequence, we have that for each $i < k$ and $j < \ell$, $f(b_j) \equiv_{f(b_{<j}c_{<j}a_0\dots \hat{a} \dots a_{k-1})} f(c_j)$. Since $\varphi(f(a_0),\dots,f(a_{k-1}),f(b_j))$ and $\neg \varphi(f(a_0),\dots,f(a_{k-1}),f(c_j))$ hold, we have that $\tp(f(a_0);\dots;f(a_{k-1})/f(b_{\leq j}c_{\leq j}))$ $k$-splits over $f(b_{<j}c_{<j})$. By compactness, we can stretch this to arbitrary length, implying that $T$ has unbounded $k$-splitting. \qedhere
  \end{sloppypar}
\end{proof}

At the moment, there isn't a known analog of \cref{fact:FOP-k-indisc-witness} for $\OP_2$, which raises the following question.

\begin{quest}
  Does bounded $2$-splitting imply $\NOP_2$?
\end{quest}

The converse of \cref{prop:if-bounded-k-then-NFOP-k} fails strongly. It turns out that even an $\NIP$ theory can have unbounded $k$-splitting for every $k$. 
%
Recall that $\kappa(\omega)$ is the smallest $\omega$-Erd\H{o}s cardinal. By convention, let $\kappa(\omega) = \infty$ if no such cardinal exists. %

\begin{fact}[{Kaplan, Shelah \cite{Kaplan_2014}}]\label{fact:NIP-no-indisc}
  $(\ZFC)$ There is a countable $\NIP$ theory $T_{2^{<\omega}}$ such that for every $\alpha < \kappa(\omega)$, there is a sequence $(a_i)_{i < \alpha}$ in a model of $T_{2^{<\omega}}$ containing no infinite indiscernible subsequence.
\end{fact}

%

\begin{prop}\label{prop:k-ineff-not-NFOP}
  %
The theory $T_{2^{<\omega}}$ from \cite{Kaplan_2014} is $\NIP$ but does not have bounded $k$-splitting for any $k < \omega$.
\end{prop}
\begin{proof}
  $T_{2^{<\omega}}$ is $\NIP$ by \cref{fact:NIP-no-indisc}. Assume the existence of a $k$-inaccessible cardinal for each $k < \omega$ (which is a fairly small assumption in the grand scheme of the large cardinal hierarchy). By \cite[Lem.~13]{Friedman_2001}, the smallest $k$-ineffable cardinal is smaller than the smallest $\omega$-Erd\H{o}s cardinal (if it exists). Therefore if $T_{2^{<\omega}}$ has bounded $k$-splitting, we arrive at a contradiction given \cref{thm:bounded-k-splitting-indisc-extraction} and \cref{fact:NIP-no-indisc}. (For the dour large cardinal skeptic, we give a direct proof of unbounded $k$-splitting in $T_{2^{<\omega}}$ in \cref{sec:unbounded-k-splitting-in-example}.)
\end{proof}

In particular by \cite[Prop~2.8]{FOP}, this theory $T$ has $\NFOP_k$ for all $k > 1$, so this establishes that for any $\ell$ and $k > 1$, $\NFOP_k$ does not imply bounded $\ell$-splitting. Of course, the triangle-free random graph demonstrates that bounded $2$-splitting does not even imply NATP (and so does not imply $\NIP$, $\NTP_2$, or $\NSOP_1$).

This allows us to completely characterize implications between $k$-arity, bounded $k$-splitting, $\NFOP_k$, and $k$-dependence for various $k$ (see Figure~\ref{fig:more-implications}).
