\section{\texorpdfstring{Treelessness implies $\NOP_2$ (and therefore $\NFOP_2$)}{Treelessness implies NOP\texttwoinferior\ (and therefore NFOP\texttwoinferior)}}
\label{sec:treelessness-implies-NFOP}

Here we will give a proof that treeless theories are $\NOP_2$ (sharpening \cite[Prop.~3.21]{Kaplan_2024}) which was worked out by the author and Gabriel Conant during his visit to the University of Maryland in 2023. Chernikov has proved the analogous implication for $\Cc$-lessness in \cite{ChernikovUpcoming2025}.

Recall that a theory $T$ has the \emph{$2$-order property} or $\OP_2$ if there is a formula $\varphi(x;y,z)$ and sequences $(b_i)_{i \in \Qb}$ and $(c_j)_{j \in \Qb}$ such that for any non-decreasing function $f : \Qb \to \Qb$, there is an $a_f$ such that $\varphi(a_f;b_i,c_j)$ holds if and only if $j \leq f(i)$ \cite{Takeuchi2OrderProperty}. By a fairly easy compactness argument, if $T$ has $\OP_2$, then it has the same condition with any linear order in place of $\Qb$.

\begin{defn}
  Given a linear order $L$, say that a set $X \subseteq L^2$ is \emph{downright closed} if for any $(i,j) \in X$ and $(k,\ell) \in L^2$ with $k \geq i$ and $\ell \leq j$, $(k,\ell) \in X$.
\end{defn}

Note that for any non-increasing function $f : L \to L$, the set $\{(i,j) : j \leq f(i)\}$ is downright closed. Note also that any intersection of downright closed sets is downright closed.

\begin{lem}\label{lem:downright-conversion}
  If $T$ has the $2$-order property, then for any linear order $L$, we can find $(b_i)_{i \in L}$ and $(c_j)_{j \in L}$ such that for any downright closed set $X \subseteq L^2$, there is an $a_X$ such that $\varphi(a_X;b_i,c_j)$ holds if and only if $(i,j) \in X$.
\end{lem}
\begin{proof}
    Let $K$ be the completion of the linear order $2 \cdot L$ (i.e., $L$ with each point replaced by an increasing pair of points). We will regard $L$ as a subset of $K$ by identifying each $\ell \in L$ with $(1,\ell)$ (i.e., the larger of the two points associated to $\ell$).

    By compactness, we can find $(b_i)_{i \in K}$ and $(c_j)_{j \in K}$ such that for any non-decreasing function $f : K \to K$, there is an $a_f$ such that $\varphi(a_f;b_i,c_f)$ holds if and only if $j \leq f(i)$. 

    Fix a downright closed set $X \subseteq L^2$. Define a function $f : K \to K$ by $f_X(i) = \sup\{j \in L : (\exists \ell \in L)\ell \leq i\wedge (\ell,j) \in X\}$, where the supremum is computed in $K$ and therefore always exists. Note that $f_X$ is a non-decreasing function by construction.

    \vspace{0.5em}

    \begin{claim}{}
      For any $(i,j) \in L^2$, $j \leq f_X(i)$ if and only if $(i,j) \in X$.
    \end{claim}
    \begin{claimproof}{}
      First assume that $(i,j) \in X$. The clearly $j$ is in the set in the supremum that defines $f_X(i)$, so $j \leq f_X(i)$.

      Now assume that $j \leq f_X(i)$. By definition, this implies that $j \leq \sup\{m \in L : (\exists \ell \in L)\ell \leq i\wedge (\ell,m) \in X\}$. Since $X$ is downright closed as a subset of $L$, whenever $(\ell,m) \in X$ for some $\ell \leq i$, we also have that $(i,m) \in X$. Therefore $j \leq \sup\{m \in L : (i,m) \in X\}$. Since $K$ is not dense below $j$ (by our choice of embedding of $L$ into $K$), we must have that $j \in \{m : (i,m) \in X\}$, or in other words that $(i,j) \in X$.
    \end{claimproof}
    \vspace{0.5em}

    Now by restricting to $L$ as a subset of $K$, we can take $a_{f_X}$ for $a_X$ for any downright closed $X$ in order to get the required configuration.
\end{proof}

For the remainder of this proof we will use some notation and terminology from \cite{Kaplan_2024}. In particular, we will denote the lexicographical ordering on $\omega^{\leq \omega}$ by $<_{\lex}$ and the extension ordering on $\omega^{\leq \omega}$ by $\triangleleq$. Given $\alpha$ and $\beta$ in $\omega^{\leq \omega}$, we will write $\alpha\wedge \beta$ for the greatest common initial segment of $\alpha$ and $\beta$. A family $(a_\eta)_{\eta \in \omega^\omega}$ is a \emph{treetop indiscernible} if the family $(a_\eta)_{\eta \in \omega^{\leq \omega}}$ (where $a_\eta = \varnothing$ for $\eta \in \omega^{<\omega}$) is a generalized indiscernible family in the sense that for any tuple $\eta_0,\dots,\eta_{k-1} \in \omega^{\omega}$, $\tp(a_{\eta_0},\dots,a_{\eta_{k-1}})$ only depends on the quantifier-free type of $\eta_0,\dots,\eta_{k-1}$ in the language $\{\triangleleq,\wedge,<_{\lex},P\}$, where $P$ is a unary predicate selecting out the leaves of $\omega^{\leq \omega}$ (i.e., the elements of height $\omega$).

Consider the sets $(X_\eta)_{\eta \in \omega^\omega}$ in the proof of \cite[Prop.~3.21]{Kaplan_2024}:
\[
  X_\eta = \{(\nu,\xi) \in \omega^\omega\times \omega^\omega : \eta <_{\lex} \nu <_{\lex} \xi~\text{and}~\eta \wedge \nu \triangleless \nu \wedge \xi\}.
\]

\begin{lem}\label{lem:X-downright-closed}
  For each $\eta \in \omega^\omega$, there are downright closed (relative to $<_{\lex}$) sets $Y_\eta$ and $Z_\eta$ such that $X_\eta = Y_\eta \setminus Z_\eta$.
\end{lem}
\begin{proof}
  Define $Y_\eta$ and $Z_\eta$ as follows:
  \begin{align*}
    Y_\eta &= \{(\nu,\xi) \in \omega^\omega \times \omega^\omega : \eta <_{\lex} \nu~\text{and}~(\nu \wedge \eta \triangleless \nu \wedge \chi~\text{or}~\nu \geq_{\lex} \xi)\} \\
    Z_\eta &= \{(\nu,\xi) \in \omega^\omega \times \omega^\omega : \nu \geq_{\lex} \xi\}.
  \end{align*}
  Clearly $X_\eta = Y_\eta \setminus Z_\eta$. Furthermore, $Z_\eta$ is clearly downright close, so we just need to show that $Y_\eta$ is downright closed. Fix $(\nu,\xi) \in Y_\eta$ and assume that $\alpha \geq_{\lex} \nu$ and $\beta \leq_{\lex} \xi$. Since $\alpha \geq_{\lex} \nu$, we still have that $\eta <_{\lex} \alpha$. At this point there are two cases.
  \begin{enumerate}
  \item Assume $\alpha \geq_{\lex} \beta$. We have immediately that $(\alpha,\beta) \in Y_\eta$.
  \item Assume $\alpha <_{\lex} \beta$. It is a basic fact about trees that if $\nu \leq_{\lex} \alpha \leq_{\lex} \beta \leq_{\lex}\xi$, then $\nu \wedge \xi \triangleleq \alpha \wedge \beta$. Furthermore, if $\nu <_{\lex} \nu \leq_{\lex} \alpha \leq_{\lex} \xi$ and $\nu \wedge \nu \triangleless \nu \wedge \xi$, then $\eta \wedge \nu = \eta \wedge \alpha$. Therefore we have that
    \[
      \eta \wedge \alpha = \eta \wedge \nu \triangleless \nu \wedge \xi \triangleleq \alpha \wedge \beta,
    \]
    and so $\eta \wedge \alpha \triangleless \alpha \wedge \beta$. \qedhere
  \end{enumerate}
\end{proof}

\begin{prop}\label{prop:treeless-NOP}
  Any treeless theory $T$ does not have the $2$-order property.
\end{prop}
\begin{proof}
  We will prove the contrapositive. Let $T$ be a theory with the $2$-order property witnessed by the formula $\varphi(x;y,z)$. We would like to show that $T$ is `treeful' (i.e., not treeless). With the groundwork of our two lemmas, the proof is mostly the same as the proof of \cite[Prop.~3.21]{Kaplan_2024}.

  Consider $(\omega^\omega,<_{\lex})$ as a linear order. By \cref{lem:downright-conversion}, we can find $(b_\eta)_{\eta \in \omega^\omega}$ and $(c_\eta)_{\eta \in \omega^\omega}$ such that for any downright closed $X \subseteq \omega^\omega\times \omega^\omega$, there is an $a_X$ such that $\varphi(a_X;b_\eta,c_\xi)$ holds if and only if $(\eta,\xi) \in X$. 

  Let $(Y_\eta)_{\eta \in \omega^\omega}$ and $(Z_\eta)_{\eta\in \omega^\omega}$ be as in \cref{lem:X-downright-closed}. For each $\eta \in \omega^\omega$, let $d_\eta = a_{Y_\eta}$ and $e_\eta = a_{Z_\eta}$. Consider the treetop-indexed family $(d_\eta e_\eta b_\eta c_\eta)_{\eta \in \omega^\omega}$. Let $\psi(x,w;y,z) = \varphi(x;y,z) \wedge \neg \varphi(w;y,z)$. We now have that for each $\eta,\nu,\xi \in \omega^\omega$, $\psi(d_\eta,e_\eta;b_\nu,c_\xi)$ holds if and only if $(\nu,\xi) \in X_\eta$. Let $(e'_\eta d'_\eta b'_\eta c'_\eta)_{\eta \in \omega^\omega}$ be a treetop indiscernible locally based on $(d_\eta e_\eta b_\eta c_\eta)_{\eta \in \omega^\omega}$. By construction, it will still be the case that $\psi(e'_\eta,d'_\eta;b'_\nu,c'_\xi)$ holds if and only if $(\nu,\xi) \in X_\nu$ (i.e., if and only if $\eta <_{\lex} \nu <_{\lex} \xi$ and $\eta \wedge \nu \triangleless \nu \wedge \xi$). Any $\eta_0,\eta_1,\eta_2,\eta_3 \in \omega^\omega$ satisfying $\eta_0 <_{\lex} \eta_1 <_{\lex} \eta_2 <_{\lex} \eta_3$ and $\eta_0 \wedge \eta_1 \trianglegess \eta_1 \wedge \eta_3$ and $\eta_0 \wedge \eta_2 \triangleless \eta_2 \wedge \eta_3$ now witnesses that $(e'_\eta d'_\eta b'_\eta c'_\eta)_{\eta \in \omega^\omega}$ is not an indiscernible sequence, whereby $T$ is treeful.
\end{proof}


\begin{cor}
  If $T$ is treeless, then it is $\NFOP_2$.
\end{cor}
\begin{proof}
  This is immediate from \cref{prop:treeless-NOP} and the fact that $\NOP_2$ implies $\NFOP_2$.
\end{proof}

Of course it already followed from \cite[Prop.~3.21]{Kaplan_2024} and \cite[Prop.~2.8]{FOP} that any treeless theory is $\NFOP_k$ for any $k\geq 3$. Moreover, by \cite[Ex.~3.17]{Kaplan_2024}, we know that the inclusion of treeless theories into $\NOP_2$ theories is strict. As noted in \cite{FOP}, it is open whether the inclusion of $\NOP_2$ theories into $\NFOP_2$ theories is strict, but by \cite[Prop.~3.25]{FOP} this is the only implication in Figure~\ref{fig:implications} that is not known to be strict.

