\section{Explicit unbounded $k$-splitting in the Kaplan-Shelah theory}
\label{sec:unbounded-k-splitting-in-example}

Here we will remove the large cardinal assumption from \cref{prop:k-ineff-not-NFOP}. See \cite[Sec.~3]{Kaplan_2014} for the relevant notation (except for concatenation of sequences, which we will denote by $\sigma \concat \tau$). We will be working with the specific case of $S = 2^{<\omega}$, although our argument makes it clear that we get unbounded $k$-splitting in $T_S$ whenever the indexing tree $S$ has height at least $k$, so even $S = (\omega, <)$ would work for our purposes here. It is likely that there is an even simpler example, but we have not pursued this. %

%

Fix $k < \omega$ and a limit ordinal $\alpha$. We will describe a model $M$ of $T_{2^{<\omega}}^{\forall}$ containing a $k$-splitting chain of length $\alpha$. Let each tree $(P_\eta,<_\eta)_{\eta \in 2^{<\omega}}$ in $M$ be a copy of $2^{<\omega\cdot \alpha+\omega}$ (ordered by extension). Everything important in the construction will be happening in the trees $(P_{0^n}, <_{0^n})_{n < k}$. Note that all of the $\Lc_{2^{<\omega}}$-structure of $M$ is now defined except for the functions $G_{\eta,\eta\concat i}$ for $\eta \in 2^{<\omega}$ and $i < 2$. The definitions of the $G_{\eta,\eta\concat i}$'s will be clearer if we name some specific elements of the above trees first before defining the $G_{\eta,\eta\concat i}$'s. Fix the following names:
\begin{itemize}
\item For each $i < k$, let $a_i = 0^{\omega\cdot \alpha}$ in $P_{0^i}$.
\item Let $a'_{k-1} = 1^{\omega\cdot \alpha}$ in $P_{0^{k-1}}$.
%
\item For each $i < k-1$ and $\beta < \alpha$, let $c_{i,\beta} = 0^{\omega \cdot \beta}\concat 1$ and let $b_{i,\beta} = c_{i,\beta} \concat 1^{\omega}$.
%
%
%
%
\end{itemize}
Note that $\mathrm{suc}_{0^i}(a_i\wedge_{0^i} b_{i,\beta},b_{i,\beta}) = c_{i,\beta}$ for each $i < k-1$ and $\beta < \alpha$. Now we need to give a complete definition of the $G_{\eta,\eta\concat i}$'s, but first we should specify the important values for later in the proof. What matters is the following:
\begin{itemize}
\item $G_{0^i,0^{i+1}}(c_{i,\beta}) = b_{i+1,\beta}$ for each $i < k-2$.
\item $G_{0^{k-2},0^{k-1}}(c_{k-2,\beta})$ is $a_{k-1}$ if $\beta$ is an even ordinal and is $a'_{k-1}$ if $\beta$ is an odd ordinal.
\end{itemize}
The rest of the definition is just chosen to satisfy the axioms of $T_{2^{<\omega}}^{\forall}$ and avoid spoiling the type equalities we need to establish $k$-splitting: %
\begin{itemize}
\item For each $i < k-2$ and $\beta < \alpha$, if $\sigma\in P_{0^i}$ is a finite extension of $c_{i,\beta}$, let $G_{0^i,0^{i+1}}(\sigma) = b_{i+1,\beta}$.
\item For even $\beta < \alpha$, if $\sigma$ is a finite extension of $c_{k-2,\beta}$, let $G_{0^{k-2},0^{k-1}}(\sigma) = a_{k-1}.$
\item For odd $\beta < \alpha$, if $\sigma$ is a finite extension of $c_{k-2,\beta}$, let $G_{0^{k-2},0^{k-1}}(\sigma) = a'_{k-1}.$
\item For any $\eta \in 2^{<\omega}$, $i < 2$, and $\sigma \in \mathrm{Suc}(P_\eta)$, if $G_{\eta,\eta\concat i}(\sigma)$ is not already defined, let it be $\varnothing$ in $P_{\eta \concat i}$.
\item For $\sigma \notin \bigcup_{\eta \in 2^{<\omega}}\mathrm{Suc}(P_\eta)$, $G_{\eta,\eta\concat i}(\sigma) = \sigma$ (as required by $T_{2^{<\omega}}^{\forall}$).
\end{itemize}
This completes the description of the model $M \models T_{2^{<\omega}}^{\forall}$.

Since $T_{2^{<\omega}}$ has quantifier elimination and is the model completion of $T_{2^{<\omega}}^{\forall}$ \cite[Cor.~3.20]{Kaplan_2014}, this structure $M$ uniquely specifies the type of a subset of a model of $T_{2^{<\omega}}$. Our goal is to show that for every even $\beta < \alpha$, $\tp(a_0;\dots;a_{k-1}/b_{0,\leq \beta+1})$ $k$-splits over $b_{0,<\beta}$, specifically as witnessed by the elements $b_{0,\beta}$ and $b_{0,\beta+1}$. The formula on which they differ is (relatively) straightforward:
\begin{align*}
  f_0(x_0,y) &\coloneq G_{\varnothing,0}(\mathrm{suc}_{\varnothing}(x_0 \wedge_{\varnothing} y,y)), \\
  f_1(x_0,x_1,y) &\coloneq G_{0,0^2}(\mathrm{suc}_{0}(x_1 \wedge_{0} f_0(x_0,y),f_0(x_0,y))), \\
  f_2(x_0,x_1,x_2,y) &\coloneq G_{0^2,0^3}(\mathrm{suc}_{0^2}(x_2 \wedge_{0^2} f_1(x_0,x_1,y),f_1(x_0,x_1,y))), \\
  & \vdots  \\
  f_{k-2}(x_0,\dots,x_{k-2},y) &\coloneq G_{0^{k-2},0^{k-1}}(\mathrm{suc}_{0^{k-2}}(x_{k-2} \wedge_{0^{k-2}} f_{k-3}(x_0,\dots,x_{k-3},y),f_{k-3}(x_0,\dots,x_{k-3},y))), \\
  \varphi(x_0,\dots,x_{k-1},y) &\coloneq (f_{k-2}(x_0,\dots,x_{k-2},y) = x_{k-1}).
\end{align*}
A direct calculation now shows that for any $\beta < \alpha$, we have
\begin{align*}
  f_0(a_0,b_{0,\beta}) &= G_{\varnothing,0}(\mathrm{suc}_{\varnothing}(a_0\wedge_{\varnothing} b_{0,\beta},b_{0,\beta})) =  G_{\varnothing,0}(c_{0,\beta}) = b_{1,\beta},\\
  f_1(a_0,a_1,b_{0,\beta}) &= G_{0,0^2}(\mathrm{suc}_{0}(a_1\wedge_{0} b_{1,\beta},b_{1,\beta})) =  G_{0,0^2}(c_{1,\beta}) = b_{2,\beta}, \\
                       & \vdots \\
  f_{k-3}(a_0,\dots,a_{k-3},b_{0,\beta}) &= G_{0^{k-3},0^{k-2}}(\mathrm{suc}_{0^{k-3}}(a_{k-3}\wedge_{0^{k-3}} b_{k-3,\beta},b_{k-3,\beta})) =  G_{0^{k-3},0^{k-2}}(c_{k-3,\beta}) = b_{k-2,\beta}, \\
  f_{k-2}(a_0,\dots,a_{k-2},b_{0,\beta}) & = \dots =  G_{0^{k-2},0^{k-1}}(c_{k-2,\beta}) = \begin{cases}
    a_{k-1}, & \beta~\text{even} \\
    a'_{k-1}, & \beta~\text{odd}
  \end{cases}, \\ %
\end{align*}
and so in particular $\varphi(a_0,\dots,a_{k-1},b_{0,\beta})$ is true if and only if $\beta$ is even.

For any $\beta < \alpha$, let $M_\beta$ be the substructure of $M$ consisting of all elements (in each $P_\eta$) of height less than $\omega\cdot \beta$.

\begin{lem}\label{lem:generation}
  For any $i < k$, $\beta < \alpha$, and $\gamma < \alpha$ with $\beta \leq \gamma$, the substructure of $M$ generated by $M_\beta \cup \{a_0,\dots,\hat{a}_i,\dots,a_{k-1},b_{0,\gamma}\}$ consists of
  \begin{itemize}
  \item the elements of $M_\beta$,
  \item the elements $a_0,\dots,\hat{a}_i,\dots,a_{k-1}$,
  \item for each $j< i$, $0^{\omega\cdot \gamma}\concat 0^n$ and $0^{\omega\cdot \gamma}\concat 1\concat 0^n$ for $n<\omega$ as elements of $P_{0^j}$ (including in particular $c_{j,\gamma}$), and
  \item the element $b_{j,\gamma} \in P_{0^j}$ for each $j \leq i$.
  \end{itemize}
\end{lem}
\begin{proof}
  It is straightforward to check that each of the elements listed in the lemma is generated by the elements of $M_\beta \cup \{a_0,\dots,\hat{a}_i,\dots,a_{k-1},b_{0,\gamma}\}$ and moreover that this list is closed under the functions of $\Lc_{2^{<\omega}}$.
\end{proof}

\begin{lem}\label{lem:same-type}
  For any $i < k$, $\beta < \alpha$, and $\gamma,\gamma'$ with $\beta \leq \gamma,\gamma'$, the map consisting of the identity on $M \cup \{a_0,\dots,\hat{a}_i,\dots,a_{k-1}\}$ and $b_{0,\gamma}\mapsto b_{0,\gamma'}$ extends uniquely to an isomorphism of the substructure of $M$ generated by $M_\beta\cup\{a_0,\dots,\hat{a}_i,\dots,a_{k-1},b_{0,\gamma}\}$ to that generated by $M_\beta\cup\{a_0,\dots,\hat{a}_i,\dots,a_{k-1},b_{0,\gamma'}\}$.

  In particular, we have that in an ambient model of $T_{2^{<\omega}}$, $b_{0,\gamma} \equiv_{M_\beta a_0\dots \hat{a}_i \dots a_{k-1}}b_{0,\gamma'}$.
\end{lem}
\begin{proof}
  The fact that the map extends to an isomorphism is immediate from \cref{lem:generation}. The final statement follows from quantifier elimination for $T_{2^{<\omega}}$.
\end{proof}

Applying \cref{lem:same-type} to the specific case of $\beta$ and $\beta+1$ for even $\beta$ now gives that $\tp(a_0;\dots;a_{k-1}/b_{\leq \beta+1})$ $k$-splits over $b_{0,<\beta}$. Therefore $\tp(a_0;\dots;a_{k-1}/b_{< \alpha})$ $k$-splits over $b_{<\gamma}$ for any $\gamma < \alpha$. Since we can do this for any $k < \omega$ and ordinal $\alpha$, we have that $T_{2^{<\omega}}$ has unbounded $k$-splitting for every $k$.





