\subsection{Observed Data and Notation}

Let $Z$ denote treatment assignment and $\mathbf{X}$ denote a vector of the baseline covariates. Let $Y_P = Y_P^Z$, $Y_{D_1} = Y_{D_1}^Z$, $Y_{D_2} = Y_{D_2}^Z$, and $C = C^Z$. Let $T_1 = Y_P \wedge Y_{D_1} \wedge Y_{D_2} \wedge C$, $\delta = I(Y_P < Y_{D_1} \wedge Y_{D_2} \wedge C)$, $T_2 = Y_{D_1} \wedge Y_{D_2} \wedge C$, $\xi_1 = I(Y_{D_1} < Y_{D_2} \wedge C)$ and $\xi_2 = I(Y_{D_2} < Y_{D_1} \wedge C)$ denote the observed event times and event indicators. The observed data for each observation are $O = (T_1, T_2, \delta, \xi_1, \xi_2, Z, \mathbf{X})$.
We assume that we observe $n$ i.i.d. copies of $O$.\\

We use the following notation to define key variables, and functions used in the model and analysis.\\

\begin{itemize}
\item $\bullet$ $G_\mathbf{x}^ z $ (identified from the observed data) denotes the conditional distribution of $Y_{D_1}^z $ given $Y_{D_2}^z$  and $\mathbf{X=x}$ 
$$G_\mathbf{x}^ z (s \mid t) = Pr ( Y_{D_1}^z \leq s \mid Y_{D_2}^z = t, \mathbf{X=x}, Z=z), \quad \text{for} \quad t \geq s.$$


\item $\bullet$ $V_{\mathbf{x}}^z$ (identified from the observed data) denotes the conditional subdistribution function of $Y_p^z$ given $(Y_{D_1}^z, Y_{D_2}^z)$ and $\mathbf{X=x}$
\begin{align*}
  V_{\mathbf{x}}^z(r\mid s,t) &= \Pr(Y_P^z \leq r,  \mid Y_{D_1}^z= s,  Y_{D_2}^z=t)\\
  &= \Pr(T_1 \leq r, \delta=1 \mid T_2=\min(t,s), \mathbf{X=x}, Z=z),  
\end{align*}
where $r \leq \min( s, t)$.



\item $\bullet$ $\lambda_{\mathbf{x}}^z$ denotes the hazard function of the non-terminal event
\begin{equation}
    \lambda_{\mathbf{x}}^z(t)= \lim _{dt \rightarrow 0} \left\{ \frac{\Pr(t \leq T_1 < t+ dt, \delta=1 \mid T_1 \geq t, T_2 \geq t, \mathbf{X}=\mathbf{x}, Z=z)}{dt}\right \}.
\end{equation}

\item $\bullet$ $\lambda_{D_1}^z$ denotes the cause-specific hazard function of death due to CVD, i.e., the instantaneous risk of experiencing death due to CVD at time $t$, given that the individual has survived up to time $t$.
\begin{equation}
    \lambda_{D_1}^z(t)= \lim _{dt \rightarrow 0} \left\{ \frac{\Pr(t \leq T_2 < t+ dt, \xi_1=1 \mid T_2 \geq t, \mathbf{X}=\mathbf{x}, Z=z)}{dt}\right \}
\end{equation}

\item $\bullet$ $\lambda_{D_2}^z$ denotes the cause-specific hazard function of death due to non-CVD, i.e., the instantaneous risk of experiencing death due to non-CVD at time $t$, given that the individual has survived up to time $t$.
\begin{equation}
    \lambda_{D_2}^z(t)= \lim _{dt \rightarrow 0} \left\{ \frac{\Pr(t \leq T_2 < t+ dt, \xi_2=1 \mid T_2 \geq t, \mathbf{X}=\mathbf{x}, Z=z)}{dt}\right \}.
\end{equation}
\end{itemize}


\subsection{Identification Assumptions}\label{Sec. Assumptions two deaths}

We introduce the following six assumptions that are sufficient for identifying our causal estimand.

\noindent \textbf{Assumption 1:}  No unmeasured
confounders (NUC). Given a set of observed covariates $\mathbf{X=x}$, there are no unmeasured variables that confound the relationships between the treatment $Z$ and the variables $Y_p^z$,  $Y_{D_1}^z$, $Y_{D_2}^z$ and $C^z$. This can be expressed as: 
$$(Y_P^z, Y_{D_1}^z, Y_{D_2}^z, C^z) \perp Z \mid \mathbf{X=x}.$$

\vspace{6pt}
\noindent \textbf{Assumption 2:} Censoring is non informative in the sense that
$$C^z \perp (Y_P^z, Y_{D_1}^z, Y_{D_2}^z)  \mid (Z=z, \mathbf{X}= \mathbf{x}).$$

\vspace{6pt}
\noindent \textbf{Assumption 3:} The conditional joint distribution function of $(Y_{D_2}^1, Y_{D_2}^{0})$ given $\mathbf{X}=\mathbf{x}$,  $H_\mathbf{x}$ follows a Gaussian copula model, i.e.,
 \begin{equation*}
 H_\mathbf{x}(t,w)= \Phi_{2,\rho}\Big[\Phi^{-1}\left\{ \Pr(Y_{D_2}^1 \leq t)\right\}, \Phi^{-1}\left\{ \Pr(Y_{D_2}^{0} \leq w)\right\}\Big],  
\end{equation*} 

\noindent where $ \Pr(Y_{D_2}^1 \leq t)$ and $\Pr(Y_{D_2}^{0} \leq w)$ are identified from the observed data. \\
\noindent A single sensitivity parameter $\rho$ is required in this assumption.\\
 \vspace{6pt} 

\noindent \textbf{Assumption 4:} The conditional joint distribution function of $(Y_{D_1}^z, Y_{D_2}^{1-z})$ given $(Y_{D_2}^z =t, X=x)$, $J_\mathbf{x} ^{z}$, for $z = 0, 1$ follows a Gaussian copula model, i.e.,
\begin{equation*}
 J_\mathbf{x}^{z}(s,w \mid t) = \Phi_{2,\rho^*_z}\Big[\Phi^{-1}\left\{ \Pr(Y_{D_1}^z \leq s \mid Y_{D_2}^z=t)\right\}, \Phi^{-1}\left\{\Pr(Y_{D_2}^{1-z} \leq w  \mid Y_{D_2}^z=t)\right\}\Big],
\end{equation*} 

\noindent where  $\Pr(Y_{D_1}^z \leq s \mid Y_{D_2}^z=t)=G_\mathbf{x} ^z (s \mid t)$ and $\Pr(Y_{D_2}^{1-z} \leq w  \mid Y_{D_2}^z=t)$ can be identified through ${H_\mathbf{x}(t,w)}$ for $z=0,1$.\\
\noindent Two sensitivity parameters $\rho^*_z$, for $z=0,1$ are required in this assumption.\\
\vspace{6pt}

\noindent \textbf{Assumption 5:} Conditional cross independence for progression.\\
\noindent $Y_p^z$ is conditionally independent of $Y_{D_2}^{1-z}$ given $Y_{D_1}^z$, $Y_{D_2}^z$ and $\mathbf{X}= \mathbf{x}$, ie.,
\begin{equation*}
    Y_P^z \perp Y_{D_2}^{1-z} \mid Y_{D_1}^z, Y_{D_2}^z, \quad z=0,1.
\end{equation*} 

\noindent $Y_p^z$ is conditionally independent of $Y_{D_1}^{1-z}$ given $Y_{D_1}^z$, $Y_{D_2}^z$, $Y_{D_2}^{1-z}$ and $\mathbf{X}= \mathbf{x}$, ie.,
\begin{equation*}
   Y_P^z \perp  Y_{D_1}^{1-z} \mid Y_{D_1}^z, Y_{D_2}^z, Y_{D_2}^{1-z} \quad z=0,1.
\end{equation*} 
\vspace{6pt}
\noindent \textbf{Assumption 6:} The conditional joint distribution function of $(Y_{D_1}^1, Y_{D_1}^0)$ given $(Y_{D_2}^1=t, Y_{D_2}^0=w, \mathbf{X}=\mathbf{x})$, $L_\mathbf{x}$, follows a copula model, i.e.,
\small{
\begin{equation*}
 L_\mathbf{x}(s,v \mid t, w)= \Phi_{2,\rho^{**}}\Big[\Phi^{-1}\left\{ \Pr(Y_{D_1}^1 \leq s \mid Y_{D_2}^1=t, Y_{D_2}^0=w)\right\}, \Phi^{-1}\left\{ \Pr(Y_{D_1}^0 \leq v  \mid Y_{D_2}^1=t, Y_{D_2}^0=w)\right\}\Big],  
\end{equation*}}

\noindent where $\Pr(Y_{D_1}^z \leq s \mid Y_{D_2}^z=t, Y_{D_2}^{1-z}=w)$ can be identified through $J_\mathbf{x}^{z}(s, w \mid t)$ and $G_\mathbf{x}^z(s \mid w)$, $z=0,1$. \\
\noindent A single sensitivity parameter $\rho^{**}$ is required to specify the correlation in the copula distribution.\\

In this assumption we employ a Gaussian copula to unite the two event time distributions CVD and non-CVD death under both treatments arms. Because the two potential outcomes cannot be observed simultaneously, the copula reduces all assumptions about their counterfactual dependence to a single correlation parameter. This construction allows us to transparently evaluate how varying degrees of correlation affect our estimand, without imposing any additional structure on the marginal models.

\subsection{Estimand Identification}

Recall the estimand $\tau(u)$ defined in (\ref{new-estimand}),
$$\tau(u) = \frac{\Pr(Y_P^1 < u \mid Y_{D_2}^1 \geq Y_{D_1}^1 \geq u, Y_{D_2}^0\geq  Y_{D_1}^0 \geq u )}{\Pr(Y_P^0 < u \mid Y_{D_2}^1 \geq Y_{D_1}^1 \geq u, Y_{D_2}^0\geq  Y_{D_1}^0 \geq u)}.$$

The probabilities defining the estimand  are conditional on two related survival criteria. First, subjects must survive past the threshold $u$; and second, under either medication status, the subject must experience death due to CVD ``before" death from other causes. Thus, we integrate only over the regions where $Y_{D_1}^z\geq u$, $Y_{D_1}^{1-z}\geq u$, $Y_{D_2}^z\geq Y_{D_1}^z$, and $Y_{D_2}^{1-z}\geq Y_{D_1}^{1-z}$ for $z=0,1$. \\

 \noindent Thus the numerator of  $\tau(u)$ can be expressed as the integral of the joint density over those regions,
  \small{
\begin{equation*}
    \int_ \mathbf{x} \int_{r <u}\int _{s \geq u} \int _{t \geq s} \int _{v \geq u} \int _{w \geq v}   \Pr(Y_P^1=r \mid Y_{D_1}=s, Y_{D_2}^1=t, Y_{D_1}^0=v, Y_{D_2}^0=w)dL_{\mathbf{x}}(s,v \mid t, w) dH_\mathbf{x}(t,w)dK(\mathbf{x})
\end{equation*}}


\noindent where $dL_\mathbf{x}(s,v \mid t,w)$ and $dH_\mathbf{x}(t, w)$ are determined by Assumption 6 and Assumption 3 respectively.\\

Under Assumption 5 (conditional cross‐independence of progression), it follows that

$$\Pr(Y_P^1=r \mid Y_{D_1}=s, Y_{D_2}^1=t, Y_{D_1}^0=v, Y_{D_2}^0=w)=dV_\mathbf{x}^1(r \mid s,t).$$ 
Therefore, proceeding similarly for the denominator,  $\tau(\cdot)$ can be identified from the distribution of the observed data. 

\begin{theorem} 
Under Assumptions 1-6 , $\tau(\cdot)$,  is identified from the distribution of the observed data as follows:
\begin{equation*}
     \tau(u)=\frac{ \int_ \mathbf{x} \int _{r < u} \int _{s \geq u} \int _{t \geq s} \int _{v \geq u} \int _{w \geq v} dV_{\mathbf{x}}^1(r \mid s, t) dL_{\mathbf{x}}(s,v \mid t, w) dH_\mathbf{x}(t,w)dF(\mathbf{x}) }{ \int_ \mathbf{x} \int _{r < u}\int _{s \geq u} \int _{t \geq s} \int _{v \geq u} \int _{w \geq v} dV_{\mathbf{x}}^0(r \mid v,w) dL_{\mathbf{x}}(s,v \mid t, w) dH_\mathbf{x}(t,w) dF(\mathbf{x})}.
\end{equation*}
\end{theorem}

\section{Observed Data Models}

\subsection{Enriched Dirichlet Process Mixture}
When modeling the joint density of the response and covariates $(Y, X)$ as a DPM with a large number of predictors, difficulties arise. Subjects with similar covariates tend to cluster together, causing clusters to be primarily based on covariate similarity, which results in poor estimates \citep{wade2011enriched}. The enriched Dirichlet process mixture (EDPM) is a conjugate nonparametric prior that extends the DPM by enabling a nested clustering structure, where the top level $y$-clusters are based on the regression of the response on the predictors and within each $y$-cluster there
are bottom level $x$-clusters based on the predictors \citep{wade2014improving}. This structure addresses the challenges of jointly modeling $(Y,X)$, resulting in improved predictions.
\begin{align*}
    [Y_i \mid X_i, \theta_i ]& \sim p(y \mid x,\theta_i)\\
    [X_{i,j} \mid \omega _i] &\sim p(x_j \mid \omega _i)\\
    [(\theta_i, \omega_i) \mid F] & \sim F \\
    F & \sim EDP(\alpha_\theta, \alpha_\omega, H).
\end{align*}

\noindent The term $F \sim EDP(\alpha_\theta, \alpha_\omega, H)$ means that $F(d\theta, d\omega)= F_\theta(d\theta) \times F_{\omega \mid \theta}(d\omega \mid \theta)$ with $F_\theta \sim DP(\alpha _\theta,H_\theta)$, $F_{\omega \mid \theta} \sim DP(\alpha_\omega,H_{\omega \mid \theta})$ and $H=H_\omega \times H_{\omega \mid \theta}$. 

Analogous to the stick-breaking construction for the DP, the joint distribution of $(Y,X)$ can be represented using a squared breaking construction given by
\begin{equation}\label{eq:EDPM}
    p(y; \theta) = \sum_{k=1}^\infty  \gamma_k p(y\mid x; \theta) \sum_{j=1}^\infty \gamma_{j\mid k} p(x; \omega_{j\mid k}), 
\end{equation}
where 
\begin{equation*}
   \gamma_k =\nu_k\prod _{l < k} (1 - \nu _l), \quad \nu_l \sim Beta(1, \alpha_\theta), \quad \theta_k  \overset{\text{iid}}{\sim} H_\theta
\end{equation*}
\begin{equation*}
   \gamma_{j\mid k} =\nu_{j\mid k}\prod _{l < j} (1 - \nu _{l \mid k}), \quad \nu_{l\mid j} \sim Beta(1, \alpha_\omega), \quad \omega_{j\mid k}  \overset{\text{iid}}{\sim} H_{\omega \mid \theta}
\end{equation*}

 \citet{burns2023truncation} propose a truncated version of the EDPM, where (\ref{eq:EDPM}) is rewritten as:

\begin{equation}\label{eq:Trun EDPM}
    p(y; \theta) = \sum_{k=1}^N \sum_{j=1}^M  \gamma_k   \gamma_{j\mid k} p(y\mid x; \theta) p(x; \omega_{j\mid k}), 
\end{equation}

\noindent where $\gamma_1 =\nu_1$,  $\gamma_k =\nu_k\prod _{l=1}^{k-1} (1 - \nu _l)$, $k=2,\dots, N$; $\gamma_{1\mid k} =\nu_{1\mid k}$, $\gamma_{j\mid k} =\nu_{j\mid k}\prod _{l=1}^{j-1} (1 - \nu _{l \mid k})$, $k = 1, \dots, N$  and $j = 2, \dots,M$; $\nu_k \sim Beta(1, \alpha_\theta)$, $k=1, \dots, N-1$; $\nu_N=1$; and for  $k=1, \dots, N$  $\nu_{j\mid k} \sim Beta(1, \alpha_\omega)$ , $j=1, \dots, M-1$, and $\nu_{M\mid k}=1$. This truncation facilitates a simple blocked Gibbs sampler for posterior computation (see Appendix \ref{appendix A}).

\section{Cardiovascular Health Data Analysis}

We used the proposed causal estimand on Section \ref{sect.One.Terminal.Events} and \ref{sect.Two.Terminal.Events} to estimate the causal effect of treatment in a cohort study where the occurrence of the first non-terminal HF event, may be censored by two terminal events: death due to CVD and death due to other causes, but not vice versa. HF is considered non-terminal if the subject does not die within 30 days following the HF event. Additionally, we focus on a baseline age range between 40 and 59 years. The analysis aims to understand how the treatment impacts the timing of the non-terminal HF event while accounting for the possibility that these terminal events can prevent its observation.\\

The data used in this analysis come from the Framingham Heart Study (FHS), a longitudinal cohort study designed to investigate risk factors for CVD. We restrict our attention to participants who were free of CVD at baseline, specifically excluding individuals with a history of coronary heart disease. The final analytic sample consists of 1833 individuals.

Each individual is characterized by a set of nine baseline covariates measured at the start of the study: systolic blood pressure, total cholesterol, high-density lipoprotein cholesterol, age, sex, smoking status, diabetes status, race, and whether the participant was receiving treatment for hypertension. 

In addition to these covariates, we consider three time-to-event outcomes. First, the time to non-terminal HF, recorded as the number of years from baseline to the first diagnosis of HF. Second, the time to death due to CVD, and third, the time to death from any cause. For each of these events, we define binary indicators to denote whether the event occurred during the follow-up period. Specifically, we define an indicator for incident HF, an indicator for death due to CVD, and an indicator for death due to any cause. Censoring occurs when a participant does not experience the event of interest during the observed follow-up time.

All individuals were followed prospectively from their baseline visit until the earliest of the following: death, loss to follow-up, or the end of the study period. Table \ref{tab:FHS} summarizes the joint distribution of incident HF status and vital status (CVD‐related death, non‐CVD death, or alive) among the 1833 Framingham Heart Study participants.

