\section*{Appendix A: Post-processing steps for estimation of causal estimand (G-computation) for the semi-competing risks model with one terminal event}\label{appendix A}

\begin{enumerate}   
 \item  Let the index $k\in\{1,\dots,N\}$ refer to an upper level cluster, and for  index $j\in\{1,\dots,M\}$ refer to a lower level cluster. Extract posterior draws from the MCMC output for the following quantities:
        \begin{itemize}
        \item Cluster-specific weights, $\gamma_k$ and $\gamma_{jk}$.
          \item Regression coefficients for death and progression, $\beta_{D}$ and $\beta_{P}$, and error variances, $\sigma^2_{D}$ and $\sigma^2_{P}$ for each upper cluster $k$.
          \item  Treatment‐effect coefficient, $\beta_Z$ for each upper cluster $k$.
          \item Covariate distribution parameters corresponding to each upper cluster \(k\) and lower cluster \(j\), 
          including \(\lambda_{jk}\) and \(\tau_{jk}\) for continuous covariates, and \(\psi_{jk}\) for binary covariates.
          \end{itemize}
\item
For each posterior sample, perform $n_{\text{MC}}$ Monte Carlo replicates as follows: Draw an upper cluster \(k\)  and a lower cluster $j \mid k$ using the posterior sample of the weights, 
\begin{align*}
 k \;&\sim\;\mathrm{Categorical}(\gamma_1,\ldots,\gamma_N)\\ 
  j\mid k \;& \sim\;\mathrm{Categorical}(\gamma_{1\mid k},\ldots,\gamma_{M\mid k})  
\end{align*}

\item For the selected mixture component indexed by $(k,j)$, sample the subject’s covariates $X$.
Each continuous covariate is drawn from a Log‑Normal distribution whose parameters depend on $(j,k)$, while each binary covariate is drawn from a Bernoulli distribution:
\begin{align*}
  X_{\mathrm{cont}} 
    &\sim \mathrm{Lognormal}\bigl(\lambda_{jk},\,\sqrt{\tau_{jk}}\bigr),
    &&\text{for each continuous predictor,}\\
  X_{\mathrm{bin}}
    &\sim \mathrm{Bernoulli}\bigl(\psi_{jk}\bigr),
    &&\text{for each binary covariate.}
\end{align*}
We collect all covariates (including the intercept) into a vector
$$X = \begin{pmatrix} 1, & X_{\text{AGE}}, & X_{\text{SBP}}, & X_{\text{CHL}}, & X_{\text{HDL}}, & X_{\text{BMI}}, & X_{\text{SMOKER}}, & X_{\text{GENDER}}, & X_{\text{DIAB}} \end{pmatrix}^\top,$$

\item For each treatment $z=0,1$, compute the normalized weights
$$
w_k(X,z)
=\frac{\gamma_k \sum_{j=1}^M \gamma_{j\mid k}\,P\bigl(X,z\mid\omega_{j\mid k}\bigr)}
{\sum_{h=1}^N \gamma_h \sum_{j=1}^M \gamma_{j\mid h}\,P\bigl(X,z\mid\omega_{j\mid h}\bigr)},
\quad k=1,\dots,N.
$$

\item Simulate \((Y_D^1,Y_D^0)\) from the Gaussian copula $G_\mathbf{x}$, with marginal CDFs $G_\mathbf{x}^1$ and $G_\mathbf{x}^0$,
\begin{equation*}
 G_\mathbf{x}(t,w ;\rho)= \Phi_{2,\rho}\Big[\Phi^{-1}\left\{G_\mathbf{x}^1(t)\right\}, \Phi^{-1}\left\{G_\mathbf{x}^0(w)\right\}\Big]   
\end{equation*}
\noindent In the steps that follow, we begin by sampling on the observed log-survival distribution, but we subsequently transform the outcomes to the standard normal latent scale and remain there throughout the procedure. In particular, we do not transform back to the original outcome scale. 

\begin{enumerate}
\item First, draw a cluster $k'(X,1)$
$$k'(X,1) \sim \mathrm{Categorical}\bigl(w_1(X,1), \dots, w_N(X,1)\bigr).$$ 

\item Extract the regression coefficients $\beta^{(k'(X,1))}_{D}$, $\beta_Z^{(k'(X,1))}$, and error variance $\sigma^{2(k'(X,1))}_{D}$,  and compute  the conditional mean:
\begin{align}
\mu^{(k')}_{D}(X,1) &= X\,\beta_{D}^{(k'(X,1))} + \beta_{Z}^{(k'(X,1))}.
\end{align}
Conditional on this selected component \(k'\), draw the log-survival outcome
$$Y_D^1\sim \mathcal{N}(\mu^{(k')}_{D}(X,1),\; \sigma^{2(k')}_{D}(X,1)),$$ 
 and denote the realized value by $t = Y_D^1$. 

\vspace{6pt}  
\noindent This two‐step procedure  produces the mixture CDF
$$
G_\mathbf{x}^1(t)=\Pr\bigl(Y_D^1\le t\mid X\bigr)
=\sum_{k=1}^N w_k(X,1)\,
\Phi\!\Bigl(\tfrac{t - \mu_{D}^{(k)}(X,1)}{\sigma_{D}^{(k)}}\Bigr)\,. 
$$

where $ w_k(X,1)
=\Pr\bigl(k\mid X,Z=1\bigr)$,
\quad $\mu_D^{(k)}(X,1)=X\,\beta_{D}^{(k(X,1))} + \beta_{Z}^{(k(X,1))}$,
\; and \;
$\sigma_D^{(k)}$ is the standard deviation for death associated with the \,$k$th mixture component. 

\item For the realized value $t$ compute the latent Gaussian score \;    $v_D^1\;=\;\Phi^{-1}\bigl(G_\mathbf{x}^1(t)\bigr)$. \\

Under the Gaussian‐copula assumption sample the conditional latent variable $V_D^0 \mid V_D^1$   
 $$V_D^0 \mid V_D^1=v_D^1 \;\sim\; \mathcal{N}\bigl(\rho \,v_D^1,\; 1-\rho^2\bigr).$$
  \end{enumerate}

\item  Define the unconditional threshold \(u_D^1\),  such that $\Pr(V_D^1 \le u_D^1) \;=\; \Pr(Y_D^1\le \log(u))=G_\mathbf{x}^1(\log(u))$, 
$$u_D^1 \;=\; \Phi^{-1}\bigl(G_\mathbf{x}^1(\log(u))\bigr).$$

Define the threshold \(u_D^0\)
$$u_D^0 \;=\; \rho \, v_D^1 \,+\, \sqrt{1-\rho^2}\;\Phi^{-1}\bigl(G_\mathbf{x}^0(\log(u)\bigr).$$
where
$$ G_\mathbf{x}^0( \log(u))
\;=\;
\sum_{k=1}^{N} w_k(X,0) 
\;\Phi\!\Bigl(\frac{\log(u) -  \mu^{(k)}_{D}(X,0)}{\sigma^{(k)}_{D}(X,0)}\Bigr).$$

\item Test the event $\;Y_D^1 \geq \log(u) \; \text{and} \;  Y_D^0 \geq \log(u)$  by the equivalent copula conditions $\;V_D^1 \geq u_D^1$ and $ V_D^0 \geq u_D^0$.

 \item A simulated subject in step 5, survived if \; $V_D^1 \geq u_D^1 \quad \text{and} \quad V_D^0 \geq u_D^0$.\\

  \item Conditional on survival, the two latent progression outcomes (non-terminal HF) are simulated. The conditional joint distribution function of $(Y_P^z, Y_D^{1-z})$ given $(Y_D^z =t, X = x)$,  $H^z_x$ for $z=0,1$ follows a Gaussian
copula model, i.e.,
\begin{equation*}
 H_\mathbf{x}^z(s,r \mid t ;\rho^*_z)= \Phi_{2,\rho^*_z}\Big[\Phi^{-1}\left\{\Pr(Y_p^z \leq s \mid Y_D^z=t]\right\}, \Phi^{-1}\left\{\Pr(Y_D^{1-z} \leq r \mid Y_D^z = t]\right\}\Big].  
\end{equation*}

\noindent The joint distribution $H_\mathbf{x}^z$ (for $z=0,1$) involves the conditional distribution of \,$Y_D^{1-z} \mid Y_D^z$, which is modeled via the Gaussian copula (Assumption 4 in Section \ref{Assumptions One death}). Since the dependence is closed form in the latent space, we express this conditional distribution through the corresponding latent variables. From earlier steps, we know the conditional distribution of $V_D^{1-z} \mid V_D^z$, the first copula edge,
$$V_D^{1-z} \mid V_D^z=v_D^z \;\sim\; \mathcal{N}\bigl(\rho \, v_D^z,\; 1-\rho^2\bigr).$$
Given the realized pair $(v_D^z, v_D^{1-z})$, we compute the conditional standard normal score:
$$ v_{\text{std}}^{1-z}=\Phi^{-1}\bigl(\Pr(V_D^{1-z} \leq v_D^{1-z} \mid V_D^z = v_D^z)\bigr)
\;=\; \Phi^{-1}\!\Bigl(\Phi\!\Bigl(\frac{v_D^{1-z} - \rho\,v_D^z}{\sqrt{1-\rho^2}}\Bigr)\Bigr)=\frac{v_D^{1-z} - \rho\,v_D^z}{\sqrt{1-\rho^2}}.
$$
This transformed score $v_{\text{std}}^{1-z}$ is then used as the conditioning value to sample the latent variable of the second copula edge  $V_P^z \mid V_D^z$,
$$V_P^z \mid V_D^z  \sim \mathcal{N}\left(\rho_z^*\; v_{\text{std}}^{1-z},\; \sqrt{1-(\rho_z^*)^2}\right).$$

\item  Define thresholds \(u_{P}^z\),  
$$ u_{P}^z \;=\; \rho^*_z \; v_{\text{std}}^{1-z}\; + \; \sqrt{1- (\rho^*_z)^2}\;\Phi^{-1}\bigl(\Pr(Y_P^z\le \log(u))\bigr), \quad z=0,1,$$
with the CDF calculated as 
 $$ \Pr(Y_P^z \leq \log(u)) \;=\;
\sum_{k=1}^{N} w_k(X,z) 
\;\Phi\!\Bigl(\frac{\log(u) -  \mu^{(k)}_{P}(X,z)}{\sigma^{(k)}_{P}(X,z)}\Bigr), 
$$
where $ w_k(X,z)
=\Pr\bigl(k\mid X,Z=z\bigr)$,
\quad $\mu_P^{(k)}(X,z)=X\,\beta_{P}^{(k(X,z))} + z\,\beta_{Z}^{(k(X,z))}$,
\; and \;
$\sigma_P^{(k)}$ is the standard deviation of progression associated with the \,$k$th mixture component. 

\item Test the event $ \;Y_P^z < \log(u)$ by the equivalent copula condition $\;V_P^z < u_P^z$.\\

\item Monte Carlo integration and estimand calculation:  
    \begin{itemize}
      \item For each valid simulation (i.e., when the survival criteria are met), event indicators are recorded:
     $$ I_1 = \mathbf{1}\{V_P^1 < u_P^1\} \quad \text{and} \quad I_0 = \mathbf{1}\{V_P^0 < u_P^0\}.
       $$
      \item The numerator and the denominator are defined as the summed counts of events, respectively:
$$\text{num} = \sum I_1, \quad \text{den} = \sum I_0.$$
      \item After obtaining $n_{MC}$ valid draws, the final estimand is computed as: 
    \begin{align*}
    \hat{\tau}(u) &= \frac{\text{num}}{\text{den}}= \frac{ \sum_{m=1}^{n_{\text{MC}}} \mathbf{1}\{{V_P^1 < u_P^1} \mid  V_D^1 \geq u_D^1 , \; V_D^0 \geq u_D^0 \} }{ \sum_{m=1}^{n_{\text{MC}}} \mathbf{1}\{ V_P^0 < u_P^0 \mid   V_D^1 \geq u_D^1 , \; V_D^0 \geq u_D^0  \}}.
\end{align*}
    \end{itemize}

 \item After computing $\hat{\tau}(u)$ for all $n_{\text{posterior}}=1000$ samples, we have 1000 posterior samples of the estimands. We obtain the final estimate as:
\begin{align*}
    \mathbb{E}[\tau(u)] \approx \frac{1}{n_{\text{posterior}}} \sum_{i=1}^{n_{\text{posterior}}} \hat{\tau}_i(u).
\end{align*}
\end{enumerate}
