\section*{Appendix B: Specifications for the Semi-Competing risks model with One Terminal Event}\label{appendix model specification}

\noindent We model the logarithm of the death time $Y_{D}$ and the HF time $Y_{P}$ with each mixture component of the EDPM using AFT models:
\begin{align*}
\log(Y_{D}) &= X\beta_{D} + \varepsilon_{D}, 
& \varepsilon_{D} &\overset{\text{iid}}{\sim} N(0,\sigma_{D}^{2}),\\
\log(Y_{P}) &= X\beta_{P} + \varepsilon_{P}, 
& \varepsilon_{P} &\overset{\text{iid}}{\sim} N(0,\sigma_{P}^{2}).
\end{align*}

\noindent where $X\in\mathbb{R}^{n\times p}$ is the design matrix (including intercept), containing both continuous and binary covariates.

\subsection{Priors}

\subsubsection{Regression and Scale Parameters (Death and HF)}  
Let $\hat\beta_D,\hat\sigma_D^2$ and $\hat\beta_{P},\hat\sigma_{P}^2$ be the maximum likelihood estimates and the error variance (scale) estimates. We assign
\begin{align*}
\beta_{D} &\sim N\!\Bigl(\hat\beta_{D},\;\frac{n_{\mathrm{death}}}{5}\,\mathrm{diag}(\hat\Sigma_{\beta_{D}})\Bigr), 
& 
\sigma_{D}^{2} &\sim \mathrm{Inv\text{-}Gamma}\bigl(3,\;\hat\sigma_{D}^{2}\bigr),\\[3pt]
\beta_{P} &\sim N\!\Bigl(\hat\beta_{P},\;\frac{n_{P}}{5}\,\mathrm{diag}(\hat\Sigma_{\beta_{P}})\Bigr), 
& 
\sigma_{P}^{2} &\sim \mathrm{Inv\text{-}Gamma}\bigl(3,\;\hat\sigma_{P}^{2}\bigr).
\end{align*}
Here $\hat\Sigma_{\beta}$ denotes the estimated covariance of $\hat\beta$, and $n_D,n_{P}$ are the numbers of uncensored events in each model.

\subsubsection{Covariates}  
For each continuous covariate $X_h$, let $\bar X_h$ and $\hat\sigma_{X_h}^2$ be its sample mean and variance.  We set
$$ X_h \;\sim\; N(\lambda_h,\tau_h),
\quad
\lambda_h\;\sim\;N\Bigl(\bar X_h,\;\frac{n}{5}\,\hat\sigma_{X_h}^2\Bigr),
\quad
\tau_h\;\sim\;\mathrm{Inv\text{-}Gamma}\bigl(3,\;2\,\hat\sigma_{X_h}^2\bigr).$$

For each binary covariate $X_k$, let $\bar X_k$ be its observed proportion.  We set
$$
X_k\;\sim\;\mathrm{Bernoulli}(\psi_k),
\quad
\psi_k\;\sim\;\mathrm{Beta}\bigl(10\,\bar X_k,\;10\,(1-\bar X_k)\bigr).
$$
