\item For the realized value $t$ compute the latent Gaussian score \;    $v_{D_2}^1\;=\;\Phi^{-1}\bigl(\Pr(Y_{D_2}^1 \leq t)\bigr)$.\\
Under the Gaussian‐copula assumption sample the corresponding conditional latent variable  
 $$V_{D_2}^0 \mid V_{D_2}^1=v_{D_2}^1 \;\sim\; \mathcal{N}\bigl(\rho \,v_{D_2}^1,\; 1-\rho^2\bigr).$$
  \end{enumerate}

  \item The conditional joint distribution function of $(Y_{D_1}^z, Y_{D_2}^{1-z})$ given $(Y_{D_2}^z =t, X = x)$,  $J^z_x$ for $z=0,1$ follows a Gaussian
copula model, i.e.,
\begin{equation*}
 J_\mathbf{x}^z(s,w \mid t ;\rho^*_z)= \Phi_{2,\rho^*_z}\Big[\Phi^{-1}\left\{\Pr(Y_{D_1}^z \leq s \mid Y_{D_2}^z=t]\right\}, \Phi^{-1}\left\{\Pr(Y_{D_2}^{1-z} \leq w \mid Y_{D_2}^z = t]\right\}\Big].  
\end{equation*}

\noindent The quantity $J_\mathbf{x}^z$ (for $z=0,1$) involves the conditional distribution of \,$Y_{D_2}^{1-z} \mid Y_{D_2}^z$, which was modeled via the Gaussian copula $H_\mathbf{x}$. Since the dependence is closed form in the latent space, we express this conditional distribution through the corresponding latent variables. From earlier steps sampling using $H_\mathbf{x}$, we know the conditional distribution of $V_{D_2}^{1-z} \mid V_{D_2}^z$, the first copula edge,
$$V_{D_2}^{1-z} \mid V_{D_2}^z=v_{D_2}^z \;\sim\; \mathcal{N}\bigl(\rho \, v_{D_2}^z,\; 1-\rho^2\bigr).$$
Given the realized pair $(v_{D_2}^z, v_{D_2}^{1-z})$, we compute the conditional standard normal scores:
$$ v_{\text{std}}^{1-z}=\Phi^{-1}\bigl(\Pr(V_{D_2}^{1-z} \leq v_{D_2}^{1-z} \mid V_{D_2}^z = v_{D_2}^z)\bigr)
\;=\; \Phi^{-1}\!\Bigl(\Phi\!\Bigl(\frac{v_{D_2}^{1-z} - \rho\,v_{D_2}^z}{\sqrt{1-\rho^2}}\Bigr)\Bigr)=\frac{v_{D_2}^{1-z} - \rho\,v_{D_2}^z}{\sqrt{1-\rho^2}}.
$$
Therefore, $V_{D_1}^z \mid V_{D_2}^z$  using the transformed score $v_{\text{std}}^{1-z}$ in the Gaussian copula $J_\mathbf{x}^z$ sequence:
$$V_{D_1}^z \mid V_{D_2}^z  \sim \mathcal{N}\left(\rho^*_z\; v_{\text{std}}^{1-z},\; \sqrt{1-\rho_2^2}\right).$$

For $z=1$ we sample $V_{D_1}^1 \mid V_{D_2}^1 \sim \mathcal{N}\left(\rho_z^*\; v_{\text{std}}^0,\; \sqrt{1-(\rho_z^*)^2}\right)$  and denote the realized value by $v_{D_1}^1$.\\

%Thus, sequentially we have gotten realizations $(v_{D_2}^1,\; v_{D_2}^0, \; v_{D_1}^1)$ of $$(V_{D_2}^1,\quad V_{D_2}^0 \mid V_{D_2}^1, \quad V_{D_1}^1 \mid V_{D_2}^0,\,V_{D_2}^1).$$

\item To sample $V_{D_1}^0 \mid V_{D_2}^0,\,V_{D_2}^1$ we use the copula $L_\mathbf{x}$. The conditional joint distribution function of $(Y_{D_1}^1, Y_{D_1}^0)$ given $(Y_{D_2}^1=t, Y_{D_2}^0=w, \mathbf{X}=\mathbf{x})$, $L_\mathbf{x}$, follows the copula model
\small{
\begin{equation*}
 L_\mathbf{x}(s,v \mid t, w)= \Phi_{2,\rho^{**}}\Big[\Phi^{-1}\left\{ \Pr(Y_{D_1}^1 \leq s \mid Y_{D_2}^1=t, Y_{D_2}^0=w)\right\}, \Phi^{-1}\left\{ \Pr(Y_{D_1}^0 \leq v  \mid Y_{D_2}^1=t, Y_{D_2}^0=w)\right\}\Big].  
\end{equation*}}
Specifically, we draw
$$ V_{D_1}^0 \mid V_{D_1}^0, V_{D_1}^0
\;\sim\;
\mathcal{N}\Bigl(
\rho^{**}\;v_{\text{std}}^{1}\,,\; 1-(\rho^{**})^{2}
\Bigr).$$

\item Define the thresholds $u_{D_1}^z$, $z=0,1$ 
\begin{align*}
u_{D_1}^1 \;&=\; \rho^*_z \; v_{\text{std}}^{0}\; + \; \sqrt{1- (\rho^*_z)^2}\;\Phi^{-1}\bigl(\Pr(Y_{D_1}^1\le \log(u))\bigr),\\
u_{D_1}^0 \;&=\; \rho^{**} \; v_{\text{std}}^{1}\; + \; \sqrt{1- (\rho^{**})^2}\;\Phi^{-1}\bigl(\Pr(Y_{D_1}^0\le \log(u))\bigr),
\end{align*}

with the CDF calculated as 
 $$ \Pr(Y_{D_1}^z \leq \log(u)) \;=\;
\sum_{k=1}^{N} w_k(X,z) 
\;\Phi\!\Bigl(\frac{\log(u) -  \mu^{(k)}_{D_1}(X,z)}{\sigma^{(k)}_{D_1}(X,z)}\Bigr), \quad z=0,1, 
$$
where $ w_k(X,z)
=\Pr\bigl(k\mid X,Z=z\bigr)$,
\quad $\mu_{D_1}^{(k)}(X,z)=X\,\beta_{D_1}^{(k(X,z))} + z\,\beta_{Z}^{(k(X,z))}$,
\; and \;
$\sigma_{D_1}^{(k)}$ is the standard deviation of death due to CVD associated with the \,$k$th mixture component. 

Test the event \( \;Y_{D_1}^z \geq \log(u)\) by the equivalent copula condition \(\;v_{D_1}^z \geq u_{D_1}^z\), for $z=0,1$.\\

\item Consider simulated subject who survive beyond time $u$ and under either medication status $z\in\{0,1\}$, experience death due to CVD ``before" death due to other causes. Formally, \;  $V_{D_2}^1 \geq V_{D_1}^1 \geq u_{D_1}^1$ and $\quad V_{D_2}^0 \geq V_{D_1}^0 \geq u_{D_1}^0$.

\item For each treatment $z=0,1$, sample the latent log-times for HF

\begin{enumerate}
    \item First, conditional on the selected component $k'(X,z)$,  extract the  regression coefficients $\beta_{P}^{(k'(X,z))}$ and error variances $\sigma^2_P(X,z))$. Compute the mean
    $$\mu^{(k')}_{P}(X,z) = X\,\beta_{P}^{(k'(X,z))} + z\,\beta_{Z}^{(k'(X,z))}.$$

    \item Sample $$ Y_P^z \, \sim \mathcal{N} (\mu^{(k')}_P(X,z), \sigma^{2(k')}_P(X,z)),$$ 
    and denote the realized value by $r^z=Y_P^z$.

\noindent This two‐step procedure  produces the mixture CDF
$$
\Pr\bigl(Y_{P}^z\le t\mid X\bigr)
=\sum_{k=1}^N w_k(X,z)\,
\Phi\!\Bigl(\tfrac{t - \mu_{P}^{(k)}(X,z)}{\sigma_{P}^{(k)}}\Bigr), 
$$
where $ w_k(X,1)
=\Pr\bigl(k\mid X,Z=1\bigr)$,
\quad $\mu_{P}^{(k)}(X,1)=X\,\beta_{P}^{(k(X,1))} + z \, \beta_{Z}^{(k(X,1))}$,
\; and \;
$\sigma_{P}^{(k)}$ is the standard deviation for progression time associated to the \,$k$th mixture component. 
\item Let $V_P^z$ be the latent Gaussian variable for $Y_P^z$ and for the realized value $r^z$ compute the corresponding latent Gaussian scores $v_P^z =\Phi^{-1}(\Pr(Y_P^z \leq r^z))$, $z=0,1$.
\end{enumerate} 

\item For $z=0,1$ define thresholds $u_P^z$
$$u_P^z= \Phi^{-1}(\Pr(Y_P^z \leq \log(u) )).$$

Test the event $\;Y_P^z < \log(u)$ by the equivalent copula condition $\;V_P^z < u_P^z$.\\


\item Monte Carlo integration and estimand calculation:  
    \begin{itemize}
      \item For each valid simulation (i.e, when the simulated subject survive beyond time $u$ and under either medication status $z\in\{0,1\}$, experience death due to CVD ``before" death due to other causes), event indicators are recorded:
     $$ I_1 = \mathbf{1}\{V_P^1 < u_P^1\} \quad \text{and} \quad I_0 = \mathbf{1}\{V_P^0 < u_P^0\}.
       $$
      \item The numerator and the denominator are defined as the summed counts of events, respectively:
$$\text{num} = \sum I_1, \quad \text{den} = \sum I_0.$$
      \item After obtaining $n_{MC}$ valid draws, the final estimand is computed as: 

    \begin{align*}
    \hat{\tau}(u) &= \frac{\text{num}}{\text{den}}= \frac{ \sum_{m=1}^{n_{\text{MC}}} \mathbf{1}\{{V_P^1 < u_P^1} \mid  V_{D_2}^1 \geq V_{D_1}^1 \geq u_{D_1}^1 , \; V_{D_2}^0 \geq V_{D_1}^0 \geq u_{D_1}^0 \} }{ \sum_{m=1}^{n_{\text{MC}}} \mathbf{1}\{ V_P^0 < u_P^0 \mid  V_{D_2}^1 \geq V_{D_1}^1 \geq u_{D_1}^1 , \; V_{D_2}^0 \geq V_{D_1}^0 \geq u_{D_1}^0  \}}.
\end{align*}
    \end{itemize}

 \item After computing $\hat{\tau}(u)$ for all $n_{\text{posterior}}=1000$ samples, we have 1000 posterior samples of the estimands. We obtain the final estimate as:
\begin{align*}
    \mathbb{E}[\tau(u)] \approx \frac{1}{n_{\text{posterior}}} \sum_{i=1}^{n_{\text{posterior}}} \hat{\tau}_i(u).
\end{align*}
\end{enumerate}


