\begin{abstract}
We investigate weak-type $(1, 1)$  boundedness of sparse operators with respect to Lebesgue measure. Specifically, we find the Bellman function maximizing level sets of sparse operators (localized to an interval) and use this to find the exact weak-$(1,1)$ norm of these sparse operators.
\end{abstract}



%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%\section{Introduction}

\vspace{0.3in}

Let $I$ be a real interval -- where by ``interval'' we always mean one of the form $[a,b)$. We work with binary sequences $\alpha$ adapted to $I$, i.e. indexed by the dyadic subintervals of $I$:
$$\alpha = \{\alpha_J\}_{J\in\mcd(I)}; \:\: \alpha_J \in \{0,1\}, \text{ for all } J \in \mcd(I),$$
where the dyadic lattice $\mcd(I)$ is the collection of subintervals of $I$ defined inductively:
    $$
    \mcd(I) := \bigcup_{k=0}^\infty \mcd_k(I), \text{ where } 
    \mcd_0(I):=\{I\} \text{ and } \mcd_{k+1}(I) := \{J_-, J_+ :\: J\in\mcd_k(I)\} \text{ for } k\geq 0,
    $$
where $J_-$ and $J_+$ denote the left and right halves of $J$, respectively. We can think of $\alpha$ as a selection procedure, and denote:
   $$
    \scs_\alpha := \{K\in \mcd(I): \: \alpha_K = 1\},
    $$
the collection of dyadic subintervals of $I$ ``selected'' by $\alpha$.
For every $J\in\mcd(I)$, define:
    $$
    A(\alpha; \: J) := \frac{1}{|J|}\sum_{K\in\mcd(J)}\alpha_K |K|. 
    %= \frac{1}{|J|}\sum_{\substack{K\in\scs_\alpha:\\ K \subset J}} |K|.
    $$
This is an averaging quantity, measuring ``how much'' of $\alpha$ is packed within $J$, relative to the size of $J$. It is analogous to averaging a function $f$ over $J$, which we denote by:
   $$
    \La f\Ra_J := \frac{1}{|J|} \int_J f(t)\,dt.
    $$


For some $C>1$, we say $\alpha$ is \textbf{$C$-Carleson} if and only if
    $
    \sup_{J\in\mcd(I)} A(\alpha; \: J) \leq C.
    $
Equivalently, the collection $\scs_\alpha$ is  $\sfrac{1}{C}$-sparse (see \cite{LNBook} for details). Let $\mfs_C(I)$ denote the set of all $C$-Carleson binary sequences adapted to $I$. In practical applications, the specific constant $C$ typically does not matter, as one can run equivalent sparse domination arguments with any $C>1$; so, in this paper we work exclusively with $2$-Carleson sequences $\alpha \in \mfs_2(I)$.

\vspace{0.2in}

For  $r>0$ and $\alpha \in \mfs_2(I)$, define the (localized) sparse operator:
$$
\mca_{\alpha, r}f(t):= \left(\sum_{J\in\mcd(I)} \alpha_J \: \langle |f|\rangle_J^r \: \unit_J(t)\right)^{1/r}.
$$
Some notable examples include the classical sparse operator (for $r=1$), used in domination arguments for many linear operators, and the square-sparse operator (for $r=2$), which dominates the dyadic square function.

We will also consider the closely-related power-mean sparse operator 
$$
\mcq_{\alpha, p}f(t) := \sum_{J\in\mcd(I)} \alpha_J \La |f|^p\Ra_J^{\sfrac{1}{p}} \unit_J(t),
$$
for $p\geq 1$ (see Section \ref{sS:power-mean}).

\begin{center}
  {\Large\ding{167}} 
\end{center}

We investigate 
weak-type $(1,1)$ boundedness of $\mca_{\alpha, r}$, with respect to Lebesgue measure. If there is a $C_{\alpha, r}>0$ such that
\begin{equation}
    \label{e:W11}
|\{t\in I: \mca_{\alpha,r}f(t)\geq\lambda\}| \leq \frac{C_{\alpha, r}}{\lambda} \int_I |f(t)|\,dt, \text{ for all } f\in L^1(I) \: \text{ and all } \: \lambda>0,  
\end{equation}
then the optimal constant $C_{\alpha, r}$ above is the operator norm 
    $$ \|\mca_{\alpha, r}\|_{(1,1)} :=  \|\mca_{\alpha, r} : L^1(I) \rightarrow L^{1,\infty}(I)\|.$$
Now, in \eqref{e:W11}, we have $|f|$ on the right-hand side, and the operator $\mca_{\alpha,r}$ also only sees $|f|$ -- so there is no loss of generality if we take $f\geq 0$ in \eqref{e:W11}. We also adjust for working instead with $\mca_{\alpha,r}^r$, and rewrite \eqref{e:W11} as
$$
\|\mca_{\alpha, r}\|_{(1,1)} = \sup_{f, \lambda} \:
\frac{\lambda^{\sfrac{1}{r}}}{\La f\Ra_I} \: \frac{1}{|I|} |\{t\in I: \mca^r_{\alpha,r}f(t)\geq\lambda\}|,
$$
where supremum is over all $f\geq 0$ on $I$ with $0<\La f\Ra_I <\infty$, and all $\lambda>0$. If we take supremum over all sequences $\alpha\in\mfs_2(I)$ on both sides of the previous equality, and index the functions $f$ by $x:=\La f\Ra_I \in (0,\infty)$, and the $\alpha$'s by $A:=A(\alpha; \: I) \in [0,2]$, we obtain:
    \begin{equation}
        \label{e:W11-withB}
        \sup_{\alpha \in \mfs_2(I)} \|\mca_{\alpha, r}\|_{(1,1)} = \sup_{\substack{x>0, \: \lambda>0;\\ A\in [0,2]}} 
        \: \frac{\lambda^{\sfrac{1}{r}}}{x} \mbb_r(x,A,\lambda),
    \end{equation}
where for every $x\geq 0$, $A\in [0,2]$, and $\lambda\in\mbr$, we define the \textbf{Bellman function}:
\begin{equation} \label{E:B-def1}
\mbb_r (x,A,\lambda) := \sup_{f, \alpha} \frac{1}{|I|} |\{t\in I: \mca_{\alpha,r}^r f(t) \geq\lambda\}|,
\end{equation}
where supremum is over all:
\begin{itemize}
\item non-negative functions $f\geq 0$ in $L^1(I)$ with fixed average 
    $    \langle f \rangle_I = x;   $
\item sequences $\alpha\in\mfs_2(I)$ with 
    $    A(\alpha; I) = A.    $
\end{itemize}
%We say any such pair $(f,\alpha)$ is an \textit{admissible pair} for $\mbb_r(x,A,\lambda)$.
\noindent In this paper we find $\mbb_r$, and the quantity in \eqref{e:W11-withB}.
As shown in Section \ref{sS:power-mean}, this immediately gives us weak-type $(p,p)$ norms for the power-mean sparse operators $\mcq_{\alpha,p}$.
