 %   \left(\frac{\lambda^p}{y} \mbb_{\sfrac{1}{p}}(y,A,\lambda)\right)^{\sfrac{1}{p}}.
 %   $$

\vspace{0.2in}
\begin{minipage}[c]{0.5\linewidth}
    \begin{proposition}
        \label{prop:bound}
    For $r>0$,
    $$
         \sup_{\alpha \in \mfs_2(I)} \|\mca_{\alpha, r}\|_{(1,1)} = C(r) := \left(
    \frac{2^{r+1}-1}{2^r-1}
    \right)^{\sfrac{1}{r}}.
    $$
    \end{proposition}

    \begin{corollary}
        \label{cor:power-mean}
        For $p\geq 1$:
        $$
        \sup_{\alpha \in \mfs_2(I)} \|\mcq_{\alpha, p}\|_{(p,p)} = C(\sfrac{1}{p})^{\sfrac{1}{p}} = 
        \frac{2 \cdot 2^{\sfrac{1}{p}}-1}{2^{\sfrac{1}{p}}-1}.
        $$
    \end{corollary}
