        \mbm_{\infty}(\omega, A) := \lim_{r\rightarrow \infty} \mbm_r(\omega, A)  
        = \inf_{r>0} \:\mbm_r(\omega, A)
        = \min(1, \: A, \: \omega).
    \end{equation}

