\subsection{Weak-type $(p,p)$ bounds for $\mcq_{\alpha, p}$ operators}
\label{sS:power-mean}

Let $p\geq 1$. By H\"{o}lder's inequality 
    \begin{equation}
        \label{e:comparison}
        \mca_{\alpha, p} f \leq \left(\mca_{\alpha, 1}(|f|^p)\right)^{\sfrac{1}{p}}
        \leq \mcq_{\alpha, p}f,
    \end{equation}
with all operators coinciding at $p=1$. For $\alpha\in \mfs_2(I)$:
%If we look at $\mcq_{\alpha,p} : L^p(I) \rightarrow L^{p,\infty}(I)$, %we need the best constant $C_p$ such that
%    $$
%    |\{t\in I: \mcq_{\alpha, p} f(t) \geq \lambda\}| \leq \frac{C_p^p}{\lambda^p}\int_I |f|^p\,dx.
%    $$
