    $$
    \|\mcq_{\alpha, p}\|_{(p,p)} := \|\mcq_{\alpha, p} : L^p(I) \rightarrow L^{p,\infty}(I)\| =
    \sup_{f, \lambda} \left(\frac{\lambda^p}{\La f^p\Ra_I} \frac{1}{|I|} |\{t\in I: \mcq_{\alpha, p}f(t) \geq \lambda\}|\right)^{\sfrac{1}{p}}
    $$
where the supremum is over all $f\geq 0$ in $L^p(I)$, and all $\lambda>0$. But observe that
    $$
    \mcq_{\alpha, p}f = \left(\mca_{\alpha, \sfrac{1}{p}}(f^p)\right)^{\sfrac{1}{p}},
    $$
so
    $$
    \sup_{\alpha\in\mfs_2(I)} \: \|\mcq_{\alpha, p}\|_{(p,p)} = \sup_{\substack{y>0, \: \lambda>0;\\ A\in [0,2]}} \left(\frac{\lambda^p}{y} \mbb_{\sfrac{1}{p}} (y, A, \lambda) \right)^{\sfrac{1}{p}}
    = \sup_{A\in [0,2]} \: \sup_{\omega>0} \left(\frac{\mbm_{\sfrac{1}{p}}(\omega, A)}{\omega}\right)^{\sfrac{1}{p}} = C(\sfrac{1}{p})^{\sfrac{1}{p}},
    $$
proving Corollary \ref{cor:power-mean}.

