\section{Bellman Function Properties}
\label{S:Bellman}

Let $r>0$, and recall our Bellman function:
\begin{equation} \label{E:B-def}
\mbb_r (x,A,\lambda) := \sup_{f, \alpha} \frac{1}{|I|} |\{t\in I: \mca_{\alpha, r}^r f(t) \geq\lambda\}|,
\end{equation} 
where
    $$
    \mca^r_{\alpha, r}f(t) = \sum_{J\in\mcd(I)} \alpha_J \: \langle |f|\rangle_J^r \: \unit_J(t),
    $$
and supremum is over all
\begin{itemize}
\item non-negative functions $f\geq 0$ in $L^1(I)$ with fixed average 
    $    \langle f \rangle_I = x;   $
\item sequences $\alpha\in\mfs_2(I)$ with 
    $    A(\alpha; I) = A.    $
\end{itemize}
We say any such pair $(f,\alpha)$ is an \textit{admissible pair} for $\mbb_r(x,A,\lambda)$. For the rest of this paper, we assume $r>0$ is fixed and suppress the $r$-subscript.


\vspace{0.1in}
We usually define the domain of a Bellman function to be the set of all points where $\mbb>-\infty$ (i.e. we are not taking supremum over the empty set). In this case, 
the domain is%we need:
%\begin{itemize}
%    \item $x\in\mbr$ for which there exists a non-negative function $f\geq 0$ on some interval $I$ with average $\La f\Ra_I=x$, and
 %   \item $A\in\mbr$ for which there exists an $\alpha\in\mfs_2(I)$ with $A(\alpha; I)=A$. 
%\end{itemize} 
%So we define the domain:
    $$
    \Omega_\mbb:=[0,\infty) \times [0,2] \times \mbr.
    $$
It is obvious from the definition that
    $$
    0 \leq \mbb(x,A,\lambda)\leq 1.
    $$
The next theorem lists the basic properties of $\mbb$. 

\begin{theorem}%[Basic Properties of $\mbb$]
    \label{T:Bellman-Props}
    The function $\mbb:\Omega_\mbb\rightarrow [0,1]$ defined above satisfies the following:

    \begin{enumerate}[label=\textnormal{(\roman*)}, itemsep=0.6em, leftmargin=2.2em]
        \item \textbf{Interval Independence:} $\mbb$ is independent of the choice of main interval $I$.

        \item \textbf{Obstacle Condition:} For all $\lambda \leq 0$,
        \begin{equation}
            \label{e:mbb-OC}
            \mbb(x,A,\lambda) = 1.
        \end{equation}

        \item \textbf{Initial Conditions:} For all $\lambda > 0$,
        \[
        \mbb(0,A,\lambda) = 0 \quad \text{and} \quad \mbb(x,0,\lambda) = 0.
        \]

        \item \textbf{Homogeneity:} For all $c > 0$,
        \begin{equation}
            \label{e:mbb-Hom}
            \mbb(x,A,\lambda) = \mbb(cx, A, c^r \lambda).
        \end{equation}

        \item \textbf{Main Inequality:} For all points in the domain,
        \begin{equation}
            \label{e:mbb-MI}
            \mbb(x, A+\gamma, \lambda + \gamma \cdot x^r) \geq \frac{1}{2}\bigg(\mbb(x_1,A_1,\lambda) + \mbb(x_2,A_2,\lambda)\bigg),
        \end{equation}
        where
        \[
        x = \La x_i \Ra := \frac{x_1 + x_2}{2}, \quad
        A = \La A_i \Ra := \frac{A_1 + A_2}{2}, \quad
        \gamma \in \{0,1\}, \quad
        A + \gamma \leq 2.
        \]
    \end{enumerate}
\end{theorem}

\vspace{10pt}

\begin{proof}%[Proof of Theorem \ref{T:Bellman-Props}]

    {\noindent\em (i)} If $f\in L^1([a_0,b_0))$, define $g\in L^1([a_1,b_1))$ as $g(x):=f(a_0+\frac{b_0-a_0}{b_1-a_1}(x-a_1))$. Then clearly 
    $\langle g\rangle_{[a_1,b_1)} = \langle f\rangle_{[a_0,b_0)} $, and
    \begin{equation*}
        \frac{1}{b_0-a_0}|\{t\in [a_0,b_0): \mca_{\alpha,r}^r f(t) \geq\lambda\}|=\frac{1}{b_1-a_1}|\{t\in [a_1,b_1): \mca_{\alpha,r}^r g(t) \geq\lambda\}|.
    \end{equation*}

    \vspace{0.1in}

    {\noindent\em (ii)} This is an immediate consequence of the fact that $f\geq 0$.

    \vspace{0.1in}

    {\noindent\em (iii)} The first equality follows from the realization that a nonnegative function with average $\langle f\rangle = 0$ must satisfy $f\equiv0$ a.e. The second equality is obvious: if $A=0$, then $\alpha_J=0$ for all $J\in\mathcal{D}(I)$ and $\mca_{\alpha,r}^rf(t)=0$ for all $t$.

    \vspace{0.1in}

    {\noindent\em (iv)} Let $(f, \: \alpha)$ be an admissible pair for $\mbb(x,A,\lambda)$. Then, for every $c>0$, the function $c f$ satisfies $\langle cf\rangle_I = c\langle f\rangle_I = cx$. Therefore $(cf, \: \alpha)$ is an admissible pair for $\mathbb{B}(cx,A,c^r\lambda)$, so
        $$
        \mathbb{B}(cx,A,c^r\lambda) \geq \frac{1}{|I|} \left|\left\{ t\in I: \mca_{\alpha,r}^r (cf) (t) \geq c^r\lambda \right\}\right| = 
        \frac{1}{|I|}\left|\left\{ t\in I: \mca_{\alpha,r}^r (f) (t) \geq \lambda \right\}\right|.
        $$
    Since this holds for all pairs $(f,\alpha)$ admissible for $\mbb(x,A,\lambda)$, we have
        $$
        \mbb(x,A,\lambda) \leq \mbb(cx, A, c^r \lambda), \:\text{ for all } c>0.
        $$
    We can replace $c$ with $\sfrac{1}{c}$ above and obtain the equality in \eqref{e:mbb-Hom}.

       \vspace{0.1in}


    {\noindent\em (v)} Let $\epsilon>0$ and $(x_i, A_i, \lambda)$, $i=1,2$ be two points in the domain of $\mbb$. Let $I$ be an interval, and denote its left and right halves by $I_1=I_-$ and $I_2=I_+$, respectively. For each $i=1,2$, let
        $(f_i, \: \alpha_i)$ be an admissible pair for $\mbb(x_i, A_i, \lambda)$, where
            \begin{align*}
                & f_i \in L^1(I_i); \: f_i \geq 0; \: \La f_i\Ra_{I_i}=x_i\\
                & \alpha_i \in \mfs_2(I_i); \: A_i=A(\alpha_i;I_i).
            \end{align*}
    Moreover, we can assume $(f_i, \: \alpha_i)$ were chosen in such a way that they ``almost give the supremum:''
        \begin{equation}
            \label{e:MIbla}
        \frac{1}{|I_i|}|\{t\in I_i: \mathcal{A}_{\alpha_i, r}^rf_i\geq\lambda\}|\geq \mathbb{B}(x_i,A_i,\lambda) - \epsilon.
        \end{equation}
    Now, concatenate $f_1$ and $f_2$ to obtain:
    \begin{equation*}
        f(t)=f_1(t)\unit_{I_1}(t) + f_2(t)\unit_{I_2}(t),
    \end{equation*}
   a function in $L^1(I)$ with 
    $$
    \La f\Ra_I = x := \La x_i \Ra.
    $$

When concatenating the sparse collections $\alpha_1$ and $\alpha_2$, to obtain a new sparse collection $\alpha$ \textit{adapted to $I$}, we have two choices for assigning $\alpha_I$: either $\alpha_I :=0 $, or $\alpha_I := 1$ (in  \eqref{e:mbb-MI}, the parameter $\gamma$ plays the role of $\alpha_I$). Then
    \begin{equation*}       
        \mca_{\alpha,r}^rf(t)=\alpha_Ix^r\unit(t) + \sum\limits_{J\in\mathcal{D}(I_1)}\alpha_J\langle |f|\rangle^r\unit(t)+\sum\limits_{J\in\mathcal{D}(I_2)}\alpha_J\langle |f|\rangle^r\unit(t).
    \end{equation*}
The new collection $\alpha$ has total mass
    $$
    A(\alpha,I)=A+\alpha_I, \text{ where } A := \La A_i\Ra.
    $$
Assuming $A+\alpha_I \leq 2$, the pair $(f, \alpha)$ is then admissible for $\mbb(x, A+\gamma, \lambda + \gamma x^r)$, where $\gamma := \alpha_I$. Then
    \begin{align*}
    \mbb(x, A+\gamma, \lambda + \gamma x^r)  & \geq
    \frac{1}{|I|} \left|\left\{t\in I: \mca_{\alpha,r}^rf(t) \geq \lambda+\gamma x^r\right\}\right|
     = \frac{1}{2} \sum_{i=1}^2 \frac{1}{|I_i|} \left|\left\{
    t \in I_i: \mca_{\alpha_i, r}^r f_i(t) \geq \lambda
    \right\}\right|
    \end{align*}
By our assumption in \eqref{e:MIbla}, after taking $\epsilon \rightarrow 0$, we obtain exactly \eqref{e:mbb-MI}.
\end{proof}





