\subsection{The family of supersolutions}
\label{subS:supersolutions}

Let $\mathscr{B}$ denote the collection of all functions  $$
    B(x,A,\lambda) : \Omega_\mbb \rightarrow [0,1]
    $$
 which satisfy the Obstacle Condition:
        \begin{equation}
            \label{e:B-OC}
            B(x,A,\lambda)=1, \: \text{ for all } \lambda\leq 0,
        \end{equation}
 and the Main Inequality:           
 \begin{equation}
                \label{e:B-MI}
                B(x, \: A+\gamma,\: \lambda+\gamma \cdot x^r) \geq \frac{1}{2}\bigg(B(x_1,A_1,\lambda) + B(x_2,A_2,\lambda)\bigg),
            \end{equation}
for all points in the domain with
            $
            x=\La x_i\Ra; A=\La A_i\Ra; \gamma \in \{0,1\}; A+\gamma \leq 2.
            $



\begin{theorem}[Least Supersolution Property of $\mbb$]
    \label{T:LS}
    For all points $(x,A,\lambda)\in\Omega_\mbb$, we have:
    $$
    \mbb(x,A,\lambda) \leq B(x,A,\lambda),
    $$
    for all $B\in\scb$.
\end{theorem}

\begin{proof}%[Proof of Theorem \ref{T:LS}]

Fix a supersolution function $B\in \scb$ and a point $(x,A,\lambda)$ in the domain. We will show that
    \begin{equation}
        \label{E:LSstar}
    \frac{1}{|I|} \left|\left\{t \in I: \mca_{\alpha,r}^r f(t) \geq \lambda\right\}\right|
    \leq B(x,A,\lambda)
    \end{equation}
holds for all pairs $(f,\alpha)$ admissible for $\mbb(x,A,\lambda)$. 

By a standard limiting argument, it is enough to show that \eqref{E:LSstar} holds for sequences $\alpha$ with finitely many non-zero terms. Assume there is some dyadic level $N\in\mbn$ such that
    $$
    \alpha_J =0, \text{ for all } J \in \mcd(I) \text{ with } \frac{|J|}{|I|} \leq \frac{1}{2^N}.
    $$
For such $\alpha$, the quantity $\mca_{\alpha,r}^r f$ is constant on each of these ``terminal'' intervals $J\in\mcd_N(I)$: 
    $$
    \mca_{\alpha, r}^r f(t) = \sum_{K \in \mcd(I): \: K \supsetneq J} \alpha_K \La f\Ra_K^r, 
    \text{ for all } t \in J, \: J \in \mcd_N(I).
    $$
To every $J\in\mcd(I)$ we associate the \textit{Bellman point} 
    $$
    p_J : = (x_J, A_J, \lambda_J),
    $$
where 
    $$
    x_J := \La f\Ra_J; \:\:\:\:\:\:\:
    A_J := A(\alpha; \: J); \:\:\:\:\:\:\:
    \lambda_J := \lambda - \sum_{K \in \mcd(I): \: K \supsetneq J} \alpha_K \La f\Ra_K^r.
    $$
%    \begin{align*}
%        x_J & := \La f\Ra_J;\\
%        A_J & := A(\alpha; \: J);\\
%        % = \frac{1}{|J|}\sum_{K\in\mcd(I): \: K \subseteq J} \alpha_K |K|;\\
 %       \lambda_J & := \lambda - \sum_{K \in \mcd(I): \: K \supsetneq J} \alpha_K \La f\Ra_K^r.
 %   \end{align*}
Remark that these always satisfy
    $$
    x_J = \frac{x_{J_-} + x_{J_+}}{2}; \:\:\:
    A_J = \frac{A_{J_-}+A_{J_+}}{2} + \alpha_J; \:\:\:
    \lambda_{J_-} = \lambda_{J_{+}} = \lambda_J - \alpha_J x_J^r,
    $$
for all $J\in\mcd(I)$.

Begin with $p_I=(x_I, A_I, \lambda_I) = (x,A,\lambda)$, and apply the Main Inequality \eqref{e:B-MI} recursively for $B$:
    \begin{align*}
    B(x,A,\lambda) = B(p_I) & \geq 
    \frac{1}{2}\sum_{i=1}^2 \left(B(p_{I_-}) + B(p_{I_+})\right) 
    = \frac{1}{2} \sum_{J\in\mcd_1(I)} B(p_J)\\
    & \geq \frac{1}{2} \sum_{J \in \mcd_1(I)} \frac{1}{2}
    \left( B(p_{J_-}) + B(p_{J_+}) \right) = 
    \frac{1}{2^2} \sum_{J \in \mcd_2(I)} B(p_J)\\
    & \vdots\\
    & \geq \frac{1}{2^{N}} \sum_{J \in \mcd_{N}(I)} B(x_J, A_J, \lambda_J).
    \end{align*}
Now, observe that the level set $\{t\in I: \mca_{\alpha, r}^r f(t) \geq \lambda\}$ is a disjoint union of intervals $J\in\mcd_N(I)$, namely those for which $\lambda_J \leq 0$. 
Finally, by non-negativity of $B$ and the Obstacle Condition:
    $$
    B(x,A,\lambda) \geq \frac{1}{2^{N}} \sum_{J \in \mcd_{N}(I): \: \lambda_J \leq 0} B(x_J, A_J, \lambda_J) 
    = \frac{1}{2^{N}} \#\{J\in\mcd_N(I): \: \lambda_J \leq 0\},
    $$
which proves \eqref{E:LSstar}.



