\alpha_K & \quad \text{if } \frac{|K|}{|I|}\geq\frac{1}{2^N}, \\
0 & \quad \text{otherwise}.
\end{cases}$$

And we take the notation $\mca^r_N:=\mca^r_{\alpha^{(N)}}$.

Let $(f,\alpha)$ be any admissible pair for $\mbb(x, A, \lambda)$, then


    \begin{align*}
        \mca^r_\alpha f(t)&=\sum_{K\in\mcd(I)}\alpha_Kf(t)\\
        &=\lim_{N\rightarrow \infty}\sum^N_{m=0}\sum_{K\in\mcd_m(I)}\alpha_Kf(t)\\
        &=\lim_{N\rightarrow\infty}\mca^r_Nf(t)\\
        &=\sup_N\mca_N^rf(t)
    \end{align*}
Here we need to show that, for any adissible pair $(f,\alpha)$ for $\mbb(x, A, \lambda)$,

     \begin{equation}
            \label{e:Claim2}
            |\{t\in I: \mca^r\alpha f(t)\geq\lambda\}|=\lim_{N\rightarrow \infty}|{t\in I:\mca^r_{N}f(t)\geq\lambda}|
    \end{equation}

Denote the sets 
$$S:=\{t\in I:\mca^r_{\alpha} f(t)\geq\lambda\}=\{\bigcup^{\infty}_{N=0}\mca^r_{N}f(t)\geq\lambda\}$$
$$S_>:=\{t\in I:\mca^r_{\alpha} f(t)>\lambda\}$$
$$S_=:=\{t\in I:\mca^r_{\alpha} f(t)=\lambda\}.$$

For $S_>$, if $t\in S_>$, then by properties of suprema there exists a positive integer $N$ such that $\mca^r_Nf(t)>\lambda$, so
$$S_>\subseteq \bigcup^{\infty}_{N=0}\{t\in I:\mca_N^rf(t)>\lambda\}$$

and, clearly,
$$S_>\supseteq \bigcup\limits^{\infty}_{N=0}\{t\in I:\mca_N^rf(t)>\lambda\}$$ by the definition. Therefore, $$S_>=\bigcup^{\infty}_{N=0}\{t\in I:\mca^r_Nf(t)\geq\lambda\}$$

 For any $t\in S_=$, $\mca^r_{\alpha}f(t)=\sup_N \mca^r_{\alpha}f(t)$. If there exists some positive integer $N$ such that $A_N^rf(t)=\lambda$, then $S_==\bigcup^{\infty}_{N=0}\{\mca^r_Nf(t)=\lambda\}$. If there does not exist such $N$, $\mca^r_Nf(t)<\lambda$ for all $N$ and thus $|S_=|=0$.
 In summary, 
     \begin{align*}
        |S|&=|S_>|+|S_=|\\
        &=|\bigcup^{\infty}_{N=0}\{t\in I:\mca^r_Nf(t)>\lambda\}|+|\{t\in S_=:\exists N \textrm{ such that } \mca^r_Nf(t)=\lambda\}|\\
        &+|\{t\in S_=:\exists N \textrm{ such that }\mca^r_Nf(t)>\lambda\}|\\
        &=|\bigcup^{\infty}_{N=0}\{t\in I: \mca^r_Nf(t)\geq\lambda\}|.
    \end{align*}


Together with (19), $\mca^r_{\alpha}f(t)=\sup_N\mca_N^rf(t)$ implies that

    \begin{align*}
        \frac{1}{|I|}|\{t\in I:\mca_N^rf\geq \lambda\}|&=\frac{1}{|I|}\bigcup^{\infty}_{N=0}|\{t\in I:\mca_N^rf(t)\geq \lambda\}|
 \\
        &=\lim_{N\rightarrow\infty}\frac{1}{|I|}|\{t\in I:\mca_N^rf(t)\geq\lambda\}|\\
        &\leq\lim_{N\rightarrow\infty}B(x, A,\lambda),
    \end{align*}
    and thus $\mbb(x,A,\lambda)\leq B(x,A,\lambda)$ on $\Omega$.

\end{comment}
\end{proof}



