Before we proceed, let us note that \eqref{e:B-MI} can be simplified as follows:

\begin{lemma}
    A function $B$ satisfies \eqref{e:B-MI} if and only if $B$ satisfies the following two conditions:
     \begin{enumerate}[label=\textnormal{(\roman*)}, itemsep=0.6em, leftmargin=2.2em]
        \item \textbf{Concavity in the first two variables:}  
        \begin{equation}
        \label{e:B-C}
        B(x,A,\lambda) \geq \frac{1}{2}\sum_{i=1}^2 B(x_i, A_i, \lambda), \text{ for all }
        x=\La x_i\Ra; \: A=\La A_i\Ra.
        \end{equation}

    \item \textbf{Jump Inequality:}
        \begin{equation}
        \label{e:B-J}
        B(x,A+1,\lambda+x^r) \geq B(x,A,\lambda), \text{ for all } A\in [0,1].
    \end{equation}
    \end{enumerate}
\end{lemma}

\begin{proof}
    First suppose a function $B$ satisfies \eqref{e:B-MI}. Let $\gamma=0$ to obtain condition \eqref{e:B-C}, and let $\gamma=1$, $A=A_1=A_2$, and $x=x_1=x_2$ to obtain condition \eqref{e:B-J}.

    Conversely, suppose $B$ satisfies \eqref{e:B-C} and \eqref{e:B-J}, and let $\gamma\in\{0,1\}$. For $\gamma=0$, \eqref{e:B-MI} is precisely \eqref{e:B-C}. To obtain \eqref{e:B-MI} for the $\gamma=1$ case, we apply both \eqref{e:B-C} and \eqref{e:B-J}:
    $$
    B(x,A+1,\lambda + x^r) \geq B(x,A,\lambda) \geq \frac{1}{2}\sum\limits_{i=1}^2B(x_i,A_i,\lambda).
    $$
