\noindent Then, since $f$ is concave, it must lie above the line segments determined by the points $(\omega_n, 2^{-1/n})$. We denote this by
    $$
    f(\omega) \geq \Lint\bigg[(\omega_0, 1); \: (\omega_1, 2^{-1}); \: \ldots ;\: (\omega_n, 2^{-n}); \ldots\bigg],
    $$
for all $\omega\in(0,\omega_0)$. We therefore arrive at the function defined in \eqref{e:f-def-r}:
    \begin{equation}
        \label{e:f-def}
    \mathfrak{f}: [0,\infty) \rightarrow [0,1]; \:\:\:
    \mathfrak{f}(\omega) := \begin{cases}
        0, & \:\text{ if }\: \omega=0\\
        \Lint[(\omega_n, 2^{-n}); \: n\in \mbz_{\geq 0}], & \:\text{ if }\: 0<\omega<\omega_0\\
        1, & \:\text{ if }\: \omega \geq \omega_0.
    \end{cases}
    \end{equation}
Explicitly, for $0<\omega<\omega_0$:
    \begin{equation}
    \label{e:f-explicit}
        \text{If }\:\: \omega_{n}\leq \omega< \omega_{n-1}, \:\text{ for } n\geq 1, \text{ then: }\:\: \mathfrak{f}(\omega):= \frac{1}{2^n} \left(1+\frac{\omega-\omega_{n}}{\omega_{n-1} -\omega_{n}}\right).
    \end{equation}




Define $\bfm: \Omega_\mbm \rightarrow [0,1]$ by  
\begin{equation}
\label{e:M-def}
	\bfm(\omega,A):=\begin{cases}
	\frac{A}{2}\mathfrak{f}\left(\frac{2\omega}{A}\right), & \text{ if } (\omega, A) \in \Delta;\\[7pt]
        \frac{\omega+(1-\omega_0)A}{2-\omega_0}, & \text{ if } (\omega, A) \in \Delta_0; \\[7pt]
       % &\\
        A, & \text{ if } (\omega, A) \in \Sigma_1; \\[7pt]
       % &\\
        1, & \text{ if } (\omega, A) \in \Sigma_0.
	\end{cases}
\end{equation}

\noindent We have proved:

\begin{theorem}
\label{T:bff-minimizes}
    The function $\bfm$ defined in \eqref{e:M-def} is a minimizer of the collection $\scm$, that is
        $$
        \bfm(\omega, A) \leq M(\omega, A),
        $$
    for all $(\omega,A)\in\Omega_\mbm$ and all $M\in\scm$.
\end{theorem}



