%-----------Jump------------%

We are only left to show that $\bfm$ satisfies the Jump Inequality \eqref{e:M-J}. 
We will rely on properties of the $\varphi(\omega) := \varphi_r(\omega)$ function defined in \eqref{e:varphi-def}.
It is easy to see that 
$\varphi$ is strictly increasing, strictly concave, and satisfies 
    $$ \varphi(0)=0; \:\:\:\: \lim_{\omega\rightarrow\infty} \varphi(\omega) = 1;
    \:\:\:\: \varphi(\omega) \leq \omega.$$

\begin{proposition}
        \label{P:Jump1}
The candidate defined in \eqref{e:M-def} satisfies:
    \begin{equation}
        \label{e:Jump-bfm}
    \bfm\big(\varphi(\omega), A+1\big) \geq \bfm(\omega, A),
    \end{equation}
for all $\omega \geq 0$ and $A\in [0,1]$.
\end{proposition}

\begin{proof}
Note that \eqref{e:Jump-bfm} holds trivially for $\omega=0$ and $A=0$, so assume below that $\omega >0$ and $A\in (0,1]$.
First, we prove \eqref{e:Jump-bfm} holds at the endpoint $A=1$, namely 
    \begin{equation}
        \label{e:Jump-bfm-1}
        \mathfrak{f}\bigg( \varphi(\omega)\bigg) \geq \bfg(\omega) := \bfm(\omega, 1),
        \:\:\: \text{ for all } \omega \geq 0.
    \end{equation}
Recall that $\mathfrak{f}$ is defined in \eqref{e:f-def}. We include here  for completeness the expression for $\bfg$:
 \begin{equation}
        \label{e:g-def}
    \bfg: [0,\infty) \rightarrow [0,1]; \:\:\:
    \bfg(\omega) := \begin{cases}
        \frac{1}{2}\mathfrak{f}(2\omega), & \:\text{ if }\: 0 \leq \omega < \frac{\omega_0}{2}\\[7pt]
        \frac{\omega+1-\omega_0}{2-\omega_0}, & \:\text{ if }\: \frac{\omega_0}{2} \leq \omega<1\\[7pt]
        1, & \:\text{ if }\: \omega \geq 1.
    \end{cases}
    \end{equation}
Note that, for $\omega <1$, the function $\bfg$ is just linear interpolation between the points 
    $$
    \left(1,1\right); \:\:
    \left(\frac{\omega_0}{2},\frac{1}{2}\right); \:\:
     \left(\frac{\omega_1}{2},\frac{1}{2^2}\right); \:\:
     \ldots
      \left(\frac{\omega_{n-1}}{2},\frac{1}{2^{n}}\right); \:\:
      \ldots
    $$
Moreover, $\varphi$ maps the $\omega$-coordinates of these points exactly to the $\omega$-coordinates of the critical points on the graph of $\mathfrak{f}$:
    $$
    \left(\omega_0, 1\right), \:\:
    \left(\omega_1, \frac{1}{2}\right), \:\:
    \left(\omega_2, \frac{1}{2^2} \right), \:\:
    \ldots
        \left(\omega_n, \frac{1}{2^n} \right), \:\:
    \ldots.
    $$

To prove \eqref{e:Jump-bfm-1}, consider the function:
       $$
        h(\omega) := \mathfrak{f}\big( \: \varphi(\omega) \: \big) - \bfg(\omega); \:\:\:\: \omega>0.
        $$

\begin{itemize}
    \item If $\omega\geq 1$, then $\varphi(\omega) \geq \varphi(1)=\omega_0$, so both sides of  \eqref{e:Jump-bfm-1} are equal to $1$.

    \item For $\frac{\omega_0}{2} \leq \omega \leq 1$, we have $\omega_1 \leq \varphi(\omega) \leq \omega_0$, and from \eqref{e:f-explicit} and \eqref{e:g-def}, $h$ takes the explicit form
        $$
        h(\omega) = \frac{1}{2} \left(1 + \frac{\varphi(\omega) - \omega_1}{\omega_0-\omega_1}\right) - \frac{\omega+1-\omega_0}{2-\omega_0}.
        $$
    Then for all $\omega \in (\omega_0/2, \: 1)$:
        $$
        h''(\omega) = \frac{1}{2(\omega_0-\omega_1)} \varphi''(\omega) <0,
        $$
    so $h$ is concave on this interval. Moreover, $h$ is $0$ at the endpoints:
        $$
        h\left(\frac{\omega_0}{2}\right) = \mathfrak{f}(\omega_1) - \bfg\left(\frac{\omega_0}{2}\right) = \frac{1}{2} - \frac{1}{2} = 0; 
        \:\:\:\:\:\:\:
        h(1) = \mathfrak{f}(\omega_0)-\bfg(1) = 1-1=0,
        $$
    so $h(\omega) \geq 0$ for all $\omega \in [\omega_0/2, \: 1]$.


    \item Finally, let $\omega \in (0, \tfrac{\omega_0}{2})$. Let $n\geq 1$ be such that
        $$
        \frac{\omega_n}{2} \leq \omega < \frac{\omega_{n-1}}{2}.
        $$
    Then
        $$
        h(\omega) = \frac{1}{2^{n+1}}\left(1 + \frac{\varphi(\omega)-\omega_{n+1}}{\omega_n - \omega_{n+1}}\right) -
        \frac{1}{2^{n+1}}\left(1 + \frac{2\omega-\omega_{n}}{\omega_{n-1} - \omega_{n}}\right).
        $$
    Similarly, $h''(\omega) <0$ for all $\omega\in (\omega_n/2, \: \omega_{n-1}/2)$, so $h$ is concave on this interval. Once again, it is $0$ at the endpoints: 
        $$
        h\left(\frac{\omega_n}{2}\right) = h\left(\frac{\omega_n}{2}\right) = 0,
        $$
    so $h\geq 0$ on each interval of the form $[\omega_n/2, \: \omega_{n-1}/2)$, and thus throughout $(0, \omega_0/2)$.
\end{itemize}


Lastly, we show that \eqref{e:Jump-bfm} holds for any $\omega>0$ and  $A\in (0,1)$:
    $\bfm(\: J(\omega, A)\:)\geq \bfm(\omega, A),$
where $J$ denotes the ``jump transformation''
    $$
    J(\omega, A) := (\varphi(\omega), \: A+1).
    $$
As shown in Figure \ref{fig:Jregs}, we split the lower half of the domain into three regions, depending on where in the upper half $J(\omega, A)$ lands.

\begin{figure}[h]
\begin{center}
\includegraphics[scale=0.42]{Figure7.jpg}
\end{center}
\caption{Jump regions}
\label{fig:Jregs}
\end{figure}

\vspace{0.2in}
\textbf{Region 1:} 
    $$
    (\omega, A): \:\: \omega>0; \:\: \frac{1-\varphi(\omega)}{1-\omega_0} \leq A <1.
    $$
Then $J(\omega, A)$ lands in $\Sigma_0$ and \eqref{e:Jump-bfm} becomes $1 \geq A$, which is certainly true.

\vspace{0.2in}

\textbf{Region 2:} 
    $$
    (\omega, A): \:\: \omega>0; \:\:
    0< A \leq \min\left(\frac{2\varphi(\omega)}{\omega_0}-1, \: \frac{1-\varphi(\omega)}{1-\omega_0}\right).
    $$
Then $J(\omega, A)$ lands in $\Delta_0$, so
    $$
    \bfm(\: J(\omega, A)\:) = \frac{\varphi(\omega) +(1-\omega_0)(A+1)}{2-\omega_0},
    $$
and \eqref{e:Jump-bfm} becomes equivalent to
    \begin{equation}
        \label{e:temp1}
    A \leq \varphi(\omega) + 1 - \omega_0.
    \end{equation}
But remember that $A$ is bounded by the minimum between two curves.
If $\varphi(\omega) \leq \omega_0$, then
    $$
    \varphi(\omega) + 1 - \omega_0 \geq \frac{2\varphi(\omega)}{\omega_0}-1,
    $$    
otherwise 
    $$
    \varphi(\omega) + 1 - \omega_0 \geq \frac{1-\varphi(\omega)}{1-\omega_0}.
    $$
Either way, \eqref{e:temp1} holds.


\vspace{0.2in}
\textbf{Region 3:} 
    $$
    (\omega, A): \:\: 0 < \omega < \varphi^{-1}\left(\frac{A+1}{2}\omega_0\right); \:\: 0<A<1.
    $$
Then $J(\omega, A)$ lands in $\Delta$, so
    $$
    \bfm(\: J(\omega, A)\:) = \frac{A+1}{2} \cdot \mathfrak{f}\left( \frac{2\varphi(\omega)}{A+1} \right).
    $$
Observe now that we can also express $\bfm(\omega, A)$ in terms of $\bfg$:
    $$
    \bfm(\omega, A) = A \cdot \bfg\left(\frac{\omega}{A}\right).
    $$
Therefore \eqref{e:Jump-bfm} becomes equivalent to
     \begin{equation}
         \label{e:temp2}
         \mathfrak{f}\left( \frac{2\varphi(\omega)}{A+1} \right) \geq \frac{2A}{A+1} \cdot \bfg\left(\frac{\omega}{A}\right).
     \end{equation}

Recall that for a concave function $h:[0,\infty)\rightarrow\mbr$ with $h(0)\geq 0$, we have
    $$
    h(\theta x) \geq \theta \cdot h(x), \text{ for all } \theta \in [0,1].
    $$
Since $\varphi \geq 0$ is concave and $A\in(0,1)$, 
    $$
    \varphi(\omega) = \varphi\left(A \cdot \frac{\omega}{A}\right) \geq A \cdot \varphi\left(\frac{\omega}{A}\right).
    $$
Then, because $\mathfrak{f}$ is non-decreasing,
    \begin{align*}
        \mathfrak{f}\left( \frac{2\varphi(\omega)}{A+1} \right) &\geq 
    \mathfrak{f}\left( \frac{2A}{A+1} \cdot \varphi\left(\frac{\omega}{A}\right)\right)\\
        & \geq \frac{2A}{A+1} \cdot \mathfrak{f}\left(
        \varphi\left(\frac{\omega}{A}\right)\right)\\
        & \geq \frac{2A}{A+1} \cdot \bfg\left(\frac{\omega}{A}\right),
    \end{align*}
where the second inequality follows by concavity of $\mathfrak{f}$ and $\tfrac{2A}{A+1}<1$, and the third inequality follows from \eqref{e:Jump-bfm-1}. This proves \eqref{e:temp2}, and we are done.
\end{proof}

