The asymptotic distributions of the MLE of the model parameters and leaf probabilities are derived next. 
Let $\mathcal{M}$ be a   one-floret model  (\ref{DefOneFloret}) parameterized by $\boldsymbol \theta = (\theta_1,  \dots, \theta_{J})\tr$.   By the model definition,  the sum-to-one constraint, $\boldsymbol 1\tr\boldsymbol \theta = 1$, is the only restriction on model parameters and, therefore,  by setting $\theta_J =  1 - \theta_1 - \dots - \theta_{J-1}$,  the model can be expressed  in terms of $J-1$ non-redundant parameters, $\tilde{\boldsymbol \theta} \coloneqq(\theta_1,  \dots, \theta_{J-1})\tr$. The parameter space is therefore $\boldsymbol \Omega = \{\tilde{\boldsymbol \theta} \in (0,1)^{J-1}: \,\,\boldsymbol 1\tr\tilde{\boldsymbol \theta} < 1 \}$. 
Let $\boldsymbol \theta_0 = (\tilde{\boldsymbol \theta}_0, {\theta}_{J0})\tr$ denote the corresponding true values. The simplify the notation,   the value  of the matrix of the first derivatives of $ \boldsymbol p$ with respect to  $\tilde{\boldsymbol \theta}$, $(\partial \boldsymbol p /\, \partial \tilde{\boldsymbol \theta})$,  at $\boldsymbol \theta_0$ will be denoted by  $(\partial \boldsymbol p / \, \partial \boldsymbol \theta_0)$. Finally, let $\mathbf{A} = diag(\boldsymbol p_0)^{-1/2}(\partial \boldsymbol p /\, \partial \boldsymbol \theta_0)$.  


\begin{theorem}\label{theoremAgrestiAsymptotic}
Let $\mathcal{M}$ be a one-floret model and assume that the true value $\boldsymbol p_0  = \boldsymbol p(\boldsymbol \theta_0) \in \mathcal{M}$.  Given data $\boldsymbol y \sim Mult(N, \boldsymbol p_0)$, if the MLE $\hat{\tilde{\boldsymbol \theta}}$ of $\tilde{\boldsymbol \theta}_0$ and $\hat{\boldsymbol p} =  \boldsymbol p (\hat{\boldsymbol \theta})$ of $\boldsymbol p_0$ exist,  the asymptotic distributions of $\hat{\tilde{\boldsymbol \theta}}$ and $\hat{\boldsymbol p}$ are, respectively: 
$$\sqrt{N}(\hat{\tilde{\boldsymbol \theta}} - \tilde{\boldsymbol \theta}_0) \overset{d}{\rightarrow} \mathcal{N}(\boldsymbol 0, \boldsymbol{\Phi}_{{\tilde{\boldsymbol{\theta}}}}),$$
$$\sqrt{N}(\hat{\boldsymbol p} - \boldsymbol p_0) \overset{d}{\rightarrow} \mathcal{N}(\boldsymbol 0, \boldsymbol{\Phi}_{{\boldsymbol{p}}} ),$$
\noindent where $\overset{d}{\rightarrow}$ denotes convergence in distribution, and the corresponding asymptotic covariance matrices  are equal to:  
\begin{equation}\label{AsCovProbOneFloret}
\boldsymbol{\Phi}_{{\tilde{\boldsymbol{\theta}}}} =(\mathbf{A}\tr \mathbf{A})^{-1}\quad \mbox{ and } \quad \boldsymbol{\Phi}_{{\boldsymbol{p}}} =\frac{\partial \boldsymbol p}{\partial \boldsymbol \theta_0}(\mathbf{A}\tr \mathbf{A})^{-1}\frac{\partial \boldsymbol p\tr}{\partial \boldsymbol \theta_0}.
\end{equation}
\end{theorem}
%Although these asymptotic results hold for the whole class of general log-linear models, it turns out that in the case of  (\ref{PMmatr}),  the matrix $\boldsymbol{\Phi}_{\hat{\boldsymbol{\theta}}}$  can be found in closed form.  

The statements follow from \cite{Birch64proof}, see also Theorem 14.8-4 in \cite{BFH}, among others, and the proof is omitted.  For a one-floret model a simpler expression for $\boldsymbol{\Phi}_{\tilde{\boldsymbol{\theta}}}$  can be obtained. 

\begin{theorem}\label{theoremMatrixProbOneFloret}
For a one-floret model $\mathcal{M}$ the following holds:
\begin{enumerate}[(i)]
\item 
\begin{equation}\label{OneFloretMxA}
\mathbf{A}\tr \mathbf{A} = \mathcal{S}(\boldsymbol p(\boldsymbol{\theta}_0))\cdot( diag(\tilde{\boldsymbol \theta}_0^{-1})  + \boldsymbol 1 \cdot \boldsymbol 1\tr  \theta_{J0}^{-1}),
\end{equation}
where $\mathcal{S}(\boldsymbol p(\boldsymbol{\theta}_0)) =  \boldsymbol{1} \tr  \mathbf{M} \boldsymbol{p}(\boldsymbol{\theta}_0)$ is the exposure total evaluated at $\boldsymbol p(\boldsymbol \theta_0)$.
\item The asymptotic covariance matrix of $\sqrt{N}\hat{\tilde{\boldsymbol \theta}}$ is equal to:  
\begin{equation}\label{AsCovMultiOneFloret}
\boldsymbol{\Phi}_{\tilde{\boldsymbol{\theta}}} =\frac{1}{ {\mathcal{S}(p(\boldsymbol{\theta}_0))}} \cdot (diag(\tilde{\boldsymbol \theta}_0)  - \boldsymbol 1 \cdot \boldsymbol 1\tr  \theta_{J0}). \end{equation}
\end{enumerate}
\end{theorem}

\begin{proof}
The proof of (\textit{i}) is given in  the Appendix. The statement (\textit{ii}) follows from (\ref{AsCovProbOneFloret}) and  from the equation 
$$\left(diag(\tilde{\boldsymbol{\theta}}_0^{-1}) + \boldsymbol 1 \cdot \boldsymbol 1\tr \theta_{J0}^{-1}\right)^{-1} = 
diag(\tilde{\boldsymbol \theta}_0)  - \boldsymbol 1 \cdot \boldsymbol 1\tr  \theta_{J0}.
$$
\end{proof}

\vspace{3mm}
Notice that the matrix $\boldsymbol{\Sigma}_{\tilde{\boldsymbol{\theta}}} = diag(\tilde{\boldsymbol{\theta}}_0) - \boldsymbol 1 \cdot \boldsymbol 1\tr \theta_{J0}$ that appears in (\ref{AsCovMultiOneFloret}) is the covariance matrix of ${\tilde{\boldsymbol{\theta}}}_0$.
Then,  $\boldsymbol{\Phi}_{\tilde{\boldsymbol{\theta}}}$ can be rewritten as a product:
$$\boldsymbol{\Phi}_{\tilde{\boldsymbol{\theta}}} = \frac{N}{ {\mathcal{S}(Np(\boldsymbol{\theta}_0))}} \cdot \boldsymbol{\Sigma}_{\tilde{\boldsymbol{\theta}}}.$$ 
Here, the factor $\frac{N}{ {\mathcal{S}(Np(\boldsymbol{\theta}_0))}} $ is the reciprocal of the ratio between the true value of the exposure size, ${\mathcal{S}(Np(\boldsymbol{\theta}_0))}$, and the sample size, $N$.  In the remainder of the paper this ratio will be referred to as \textit{exposure rate}.

