\section{Multi-floret sequential designs}\label{SectionMultiple}


Consider an experimental design of tree structure as described at the beginning of Section \ref{sectionOneTrt}.   The tree nodes $X_1, \dots, X_K$ correspond to the experiments or interventions whose outcomes are random variables parameterized by strictly positive $\boldsymbol \theta^{(1)} $, $\dots$, $\boldsymbol \theta^{(K)}$, where $\boldsymbol \theta^{(k)} =  (\theta_{kl})_{l = 1}^{I_k}$, $k = 1, \dots, K$. This section focuses on testing a hypothesis stating that some of the responses to some interventions are identically distributed, that is, there exists a partition $\mathcal{F} = \{S_1, \dots, S_F \}$ of the nodes $\{X_1, \dots, X_K \}$ into subsets $S_f$, such that  for any $s, t \in \{1, \dots, K\}, \, s\neq t$, and $f = 1, \dots, F$,

\begin{align*}
%&\{X_1, \dots, X_K \} = \cup_{f = 1}^FS_f, \\
&X_s, X_t \in S_f \iff \boldsymbol \theta^{(s)} = \boldsymbol \theta^{(t)}. 
\end{align*}
Recall that the subsets of nodes with the same edge probabilities are called \textit{florets}. Denote by $\boldsymbol \theta_f$ the common edge parameters of the distributions in $S_f$ and then $\boldsymbol \theta = (\boldsymbol \theta_f)_{S_f \in \mathcal{F}}$. Let $J_f =|\boldsymbol \theta_f|$ and $J =|\boldsymbol \theta|$ stand for the lengths of $\boldsymbol \theta_f$ and $\boldsymbol \theta$, respectively. Further, from the root $X_1$ there leads a unique path to a leaf $i$, where $i = 1, \dots, I$.  Let $\mu_{fji}$ denote the number of times the edge parameter $\theta_{fj}$ appears on this path.  Then $\mathbf{M}_f = (\mu_{fji})$ is $J_f \times I$  matrix. Finally, let $\mathbf{M}$ be the $J \times I$ block matrix with blocks $\mathbf{M}_f$. In the sequel, to simplify the notation, a floret $S_f$ is referred to by its index, $f$.  A floret $f$ is called complete if the row space of $\mathbf{M}_f$ contains a row of $1$'s.



\begin{definition} The multi-floret tree model $\mathcal{M}$ generated by a set of florets $\mathcal{F} = \{S_1, \dots, S_F \}$ is the set of positive distributions on $\mathcal{I}$ that satisfy: 
\begin{equation} \label{PMmatr}
\mathcal{M} = \left \{ \boldsymbol p \in \mathcal{P}:  \,\,{\boldsymbol p} = \prod_{f \in \mathcal{F}} ({\boldsymbol \theta}_f)^{\mathbf{M}_f\tr} \, \mbox{for some } \, \boldsymbol \theta = (\boldsymbol \theta_f)_{f \in \mathcal{F}} \right\}.
\end{equation} 
\end{definition}




 Let $\boldsymbol y$  be the observed data obtained from a sample of size $N$ using a generating procedure of a tree structure with nodes $\boldsymbol{X}_1, \dots, \boldsymbol{X}_K$.   As noted in the previous section,   $\boldsymbol y$ is a realization of a random variable $\boldsymbol Y$ which has a multinomial distribution $Mult(N, \boldsymbol p)$ where $\boldsymbol p$ is the vector of leaf probabilities.   Notice that that under the model (\ref{PMmatr}), the kernel of the multinomial log-likelihood function ${L}(\boldsymbol p(\boldsymbol{\theta}), \boldsymbol y) $ can  be partitioned into floret-specific terms, namely:
\begin{equation}\label{LLmultiF}
{L}(\boldsymbol p(\boldsymbol{\theta}), \boldsymbol y) = \boldsymbol y \tr \mbox{log } \boldsymbol p(\boldsymbol{\theta}) = \sum_{f \in \mathcal{F} }(\mathbf{M}_f\boldsymbol y)\tr \cdot  \mbox{log } \boldsymbol \theta_f =  \sum_{f \in \mathcal{F} } {L}_f(\boldsymbol p(\boldsymbol{\theta}), \boldsymbol y).
\end{equation} 
(The logarithm is applied component-wise.)  Here, each  ${L}_f(\boldsymbol p(\boldsymbol{\theta}), \boldsymbol y)  = \mathbf{M}_f\boldsymbol y \tr \mbox{log } \boldsymbol \theta_f$ is the kernel of the floret-specific multinomial log-likelihood function.
Because the floret parameters $\boldsymbol \theta_f$ mutually variation independent, Theorem 4.6 of \cite{TRbook2018} implies that the MLE   of $\boldsymbol{\theta} = (\boldsymbol \theta_f)_{f \in \mathcal{F}}$ can be found by separately maximizing the floret-specific log-likelihood functions.  
Consequently, the MLE $\hat{\boldsymbol{\theta}}$ and its properties can be obtained by extending Theorems \ref{theoremMatrixOneFloret}  to the multi-floret case, as shown next. In the sequel, $\mathcal{S}_f({\boldsymbol{y}}) = \boldsymbol 1_f\tr \mathbf{M}_f \boldsymbol y$ is the exposure size in the floret $f$. Here $\boldsymbol 1_f$ is the vector of $1's$ of length $J_f$.   



\begin{theorem}\label{theoremMatrixMultiFloret}
Let $\mathcal{M}$ be a multi-floret tree model (\ref{PMmatr}).   Assume that  the MLEs $\hat{\boldsymbol \theta}$ and $\hat{\boldsymbol p}$   given $\boldsymbol y$  exist.  Then, the following holds:
\begin{enumerate}[(i)]
\item The MLE of the edge probabilities and leaf probabilities are equal to, respectively:
\begin{equation}\label{MLEclosed1}
\hat{\boldsymbol \theta}_{f} =  \frac{1}{\mathcal{S}_f({\boldsymbol{y}})} \cdot \mathbf{M}_f \boldsymbol y, \, \mbox{ for each } f \in \mathcal{F},  \quad \mbox{and} \quad \hat{\boldsymbol p} = \prod_{f \in \mathcal{F}} (\hat{\boldsymbol \theta}_f)^{\mathbf{M}_f\tr}.
\end{equation}
\item For each $f = 1 \dots, F$ and $\hat{\boldsymbol y} = N\hat{\boldsymbol p}$,
\begin{equation}\label{adjFmultiFloretJ}
 \frac{1}{\mathcal{S}_f(\hat{\boldsymbol{y}})} \cdot \mathbf{M}_f \hat{\boldsymbol y} =  \frac{1}{\mathcal{S}_f({\boldsymbol{y}})} \cdot \mathbf{M}_f {\boldsymbol y} .
\end{equation}
\item For each $f \in \mathcal{F}$, the floret exposure ratio,
\begin{equation}\label{adjMultiFloretGamma} {\gamma}_f = 
\frac{\mathcal{S}_f(\hat{\boldsymbol y})}{\mathcal{S}_f({\boldsymbol{y}})},
\end{equation}
is equal to $1$  if and only if the row space of $\mathbf{M}_f$ contains a row of $1$'s. 
\end{enumerate}
\end{theorem}

\begin{proof}

For each  $f \in \mathcal{F}$, if the MLE  $\hat{\boldsymbol \theta}_f$ exists, then by Theorem \ref{theoremMatrixOneFloret},  it is equal to
\begin{equation*}%\label{MLEclosed1}
\hat{\boldsymbol \theta}_{f} =   \frac{1}{\mathcal{S}_f({\boldsymbol{y}})} \cdot \mathbf{M}_f \boldsymbol y, 
\end{equation*}
and therefore, $\hat{\boldsymbol p} = \prod_{f \in \mathcal{F}} (\hat{\boldsymbol \theta}_f)^{\mathbf{M}_f\tr}$.  The statement (ii) follows from (ii) of Theorem \ref{theoremMatrixOneFloret} and, finally, (iii) follows from the same theorem, part (iv),  applied floret-wise.


\end{proof}




\vspace{5mm}

Notice that if the row space of a floret submatrix $\mathbf{M}_f$ contains a row of $1$'s then the corresponding floret has the overall effect (OE), which happens, for example, when the floret is complete.  A multi-floret model can include both florets with and without the OE. 




The asymptotic results for the MLE of $\boldsymbol{\theta}$  and of $\boldsymbol{p}$ in a multi-floret case are presented next.   Firstly, because within each floret $\theta_{f,J_f} =  1 - \theta_{f1} - \dots - \theta_{f,J_f-1}$, the multi-floret model can be expressed  in terms of $J-f$ non-redundant parameters, $\tilde{\boldsymbol \theta} = (\tilde{\boldsymbol \theta}_f)_{f \in \mathcal{F}}$, where $\tilde{\boldsymbol \theta}_f \coloneqq(\theta_{f1},  \dots, \theta_{f,J_f-1})\tr$.   For each $f = 1, \dots, F$,  $\boldsymbol{\theta}_{f0} = (\tilde{\boldsymbol \theta}_{f0}, {\theta}_{f,J_f,0})\tr$ denote the corresponding true values of the floret-specific components.  Similarly to the previous section, let $(\partial \boldsymbol p / \, \partial \boldsymbol \theta_0)$ denote the value of the matrix of first derivatives $(\partial \boldsymbol p /\, \partial \tilde{\boldsymbol \theta})$ of $\boldsymbol p$ with respect  to $\tilde{\boldsymbol \theta}$ at $\boldsymbol \theta_0$, and the matrix $\mathbf{A} = diag(\boldsymbol p_0)^{-1/2}(\partial \boldsymbol p /\, \partial \boldsymbol \theta_0)$.  


\begin{theorem}\label{theoremAgrestiAsymptoticMulti}
Let $\mathcal{M}$ be a multi-floret model with a set of florets $\mathcal{F}$ and assume that the true parameter value $\boldsymbol p_0  = \boldsymbol p(\boldsymbol \theta_0) \in \mathcal{M}$.  Assume that given data $\boldsymbol y \sim Mult(N, \boldsymbol p_0)$ the MLE $\hat{\tilde{\boldsymbol \theta}}$ and $\hat{\boldsymbol p} =  \boldsymbol p (\hat{\boldsymbol \theta})$ exist.  As $N \to \infty$,  the  asymptotic distributions of $\hat{\tilde{\boldsymbol \theta}}$ and $\hat{\boldsymbol p}$ are, respectively: 
\begin{align}\label{systemPnewMatrix_estimate_M1}  
&\sqrt{N}(\hat{\tilde{\boldsymbol \theta}} - \tilde{\boldsymbol \theta}_0) \overset{d}{\rightarrow} \mathcal{N}(\boldsymbol 0, \boldsymbol{\Phi}_{{\tilde{\boldsymbol{\theta}}}}); \\
&\sqrt{N}(\hat{\boldsymbol p} - \boldsymbol p_0) \overset{d}{\rightarrow} \mathcal{N}(\boldsymbol 0, \boldsymbol{\Phi}_{{{\boldsymbol{p}}}}), \nonumber
\end{align}
\noindent where $\overset{d}{\rightarrow}$ denotes convergence in distribution, and  
\begin{equation}\label{AsCovProbMultiFloret}
\boldsymbol{\Phi}_{{\tilde{\boldsymbol{\theta}}}} =(\mathbf{A}\tr \mathbf{A})^{-1}\quad \mbox{ and } \quad \boldsymbol{\Phi}_{{\boldsymbol{p}}} =\frac{\partial \boldsymbol p}{\partial \boldsymbol \theta_0}(\mathbf{A}\tr \mathbf{A})^{-1}\frac{\partial \boldsymbol p\tr}{\partial \boldsymbol \theta_0}.
\end{equation}
\end{theorem}

The statements (\ref{systemPnewMatrix_estimate_M1}) and (\ref{AsCovProbMultiFloret}) follow from the asymptotic theory for general parametric models for discrete data \citep{Birch64proof, BFH}. The proof is omitted.  As in the one-floret case,  a simpler expression for $\boldsymbol{\Phi}_{\hat{\boldsymbol{\theta}}}$  can be derived. 

\begin{theorem}\label{theoremMatrixProbMultiFloret}
For a multi-floret model $\mathcal{M}$,
\begin{enumerate}[(i)]
\item The matrix $\mathbf{A}\tr \mathbf{A} $ is block-diagonal, constructed from floret-specific blocks:
\begin{equation}\label{MultiFloretMxA}
\mathbf{A}\tr \mathbf{A} = diag\left\{\mathcal{S}_f(\boldsymbol p(\boldsymbol{\theta}_0))\cdot( diag(\tilde{\boldsymbol \theta}_{f0}^{-1})  + \boldsymbol 1 \cdot \boldsymbol 1\tr  \theta_{f,J_f0}^{-1})\right \}_{f = 1}^{F},
\end{equation}
where for each $f = 1, \dots, F$,  $\mathcal{S}_f(\boldsymbol p(\boldsymbol{\theta}_0)) =  \boldsymbol{1} \tr  \mathbf{M} \boldsymbol{p}(\boldsymbol{\theta}_0)$ is the exposure size at block $f$.
\item The asymptotic covariance matrix  $\boldsymbol{\Phi}_{\tilde{\boldsymbol{\theta}}}$ of $\sqrt{N}\hat{\tilde{\boldsymbol{\theta}}}$ is  block-diagonal, with blocks $\boldsymbol{\Phi}_{\tilde{\boldsymbol{\theta}}_{f}}$,  where for each for $f = 1, \dots, F$, 
\begin{equation}\label{AsCovMultiFloret}
\boldsymbol{\Phi}_{\tilde{\boldsymbol{\theta}}_f} =\frac{1}{ {\mathcal{S}_f(p(\boldsymbol{\theta}_0))}} \cdot (diag(\tilde{\boldsymbol \theta}_{f0})  - \boldsymbol 1 \cdot \boldsymbol 1\tr  \theta_{f,J_f,0}). 
\end{equation}
\end{enumerate}
\end{theorem}

\begin{proof}

The statement (\textit{i}) is verified in  the Appendix. 

To show (\textit{ii}) recall that the inverse of a non-singular block-diagonal matrix is also block-diagonal,  obtained by inverting the original blocks.  It is straightforward to check that each block of $\mathbf{A}\tr \mathbf{A}$ is non-singular,  with inverse equal to:
$$
(\mathcal{S}_f(\boldsymbol p(\boldsymbol{\theta}_0))\cdot( diag(\tilde{\boldsymbol \theta}_{f0}^{-1})  + \boldsymbol 1 \cdot \boldsymbol 1\tr  \theta_{f,J_f0}^{-1}))^{-1} = \frac{1}{ {\mathcal{S}(p(\boldsymbol{\theta}_0))}} \cdot (diag(\tilde{\boldsymbol \theta}_{f0})  - \boldsymbol 1 \cdot \boldsymbol 1\tr  \theta_{f,J_f,0}),$$
for $f = 1, \dots, F$.
\end{proof}

Similarly to the one-floret case,  each $\boldsymbol{\Phi}_{\tilde{\boldsymbol{\theta}}_f}$ in (\ref{AsCovMultiFloret}) can be written as a product 
$$\boldsymbol{\Phi}_{\tilde{\boldsymbol{\theta}}_f} = \frac{N}{ {\mathcal{S}_f(Np(\boldsymbol{\theta}_0))}} \cdot \boldsymbol{\Sigma}_{\tilde{\boldsymbol{\theta}}_f},$$ 
of the covariance matrix of ${\tilde{\boldsymbol{\theta}}}_f$,  $\boldsymbol{\Sigma}_{\tilde{\boldsymbol{\theta}}_f} = diag(\tilde{\boldsymbol{\theta}}_f) - \boldsymbol 1 \cdot \boldsymbol 1\tr \theta_{f,J_f}$,   
and the reciprocal of the floret-specific exposure rate,  $\frac{N}{ {\mathcal{S}_f(Np(\boldsymbol{\theta}_0))}} $.  

\vspace{4mm}

\noindent \textit{Comment}:
The asymptotic covariance matrix $\boldsymbol{\Phi}_{\tilde{\boldsymbol{\theta}}}$ can be derived using the  approach of  \cite{AitchSilvey60} for the maximum likelihood maximization under constraints.  Applying their method, one first arrives to the expression for the asymptotic covariance matrix of $\hat{\boldsymbol \theta} = ((\hat{\tilde{\boldsymbol \theta}}_f, \hat{\theta}_{f, J_f}))_{f \in \mathcal{F}}$, as
\begin{equation}\label{AsCovMulti0}
 \boldsymbol{\Phi}_{\boldsymbol{\theta}}  = \mathbf{B}_{\boldsymbol{\theta}_0}^{-1} - \mathbf{B}_{\boldsymbol{\theta}_0}^{-1}  \boldsymbol 1 (\boldsymbol 1\tr\mathbf{B}_{\boldsymbol{\theta}_0}^{-1} \boldsymbol 1)^{-1} \boldsymbol 1\tr\mathbf{B}_{\boldsymbol{\theta}_0}^{-1},
\end{equation}
where $\mathbf{B}_{\boldsymbol{\theta}_0}$ is a block-diagonal matrix consisting of floret-specific blocks  $ {\mathcal{S}_f(p(\boldsymbol{\theta}_{0}))} diag (\boldsymbol{\theta}_{f0}^{-1})$.
Then, a direct substitution of the expression for $\mathbf{B}_{\boldsymbol{\theta}_0}$  into (\ref{AsCovMulti0}) yields  that $\boldsymbol{\Phi}_{{\boldsymbol{\theta}}}$ is  a block-diagonal matrix, with blocks $\boldsymbol{\Phi}_{{\boldsymbol{\theta}}_{f}}$, for $f = 1, \dots, F$, 
$$\boldsymbol{\Phi}_{{\boldsymbol{\theta}}_f} = \frac{N}{ {\mathcal{S}_f(Np(\boldsymbol{\theta}_0))}} \cdot \boldsymbol{\Sigma}_{{\boldsymbol{\theta}}_f},$$ 
where $\boldsymbol{\Sigma}_{{\boldsymbol{\theta}}_f} = diag({\boldsymbol{\theta}}_f{0}) - \boldsymbol \theta_{f0} \cdot \boldsymbol \theta_{f0}\tr$ is the covariance matrix of $\boldsymbol \theta_{f0}$.
Finally,  using the definition of $\tilde{\boldsymbol{\theta}}_{f0}$ in terms of ${\boldsymbol{\theta}}_{f}$, the delta method yields the expression (\ref{AsCovMultiFloret}). \qed

\vspace{4mm}



Notice that for a multi-floret model,   the true  exposure rates and their expected values are floret-specific,  equal to the ratio between the  exposure  size (number of subjects involved in the experiment) and the number of times the floret treatment is (or expected to be) applied,  as illustrated next.



\begin{example} \label{ExTwoFlorets1}
Consider a hypothetical clinical study in which the efficacy of a therapy consisting of treatments $T_1$ and $T_2$ is investigated.  First, the treatment $T_1$ is administered to all patients.  Then, the patients who had a positive response to it, received $T_1$ for the second time.  The patients who either had a negative response to the first round of $T_1$ or  a positive response to the second round of $T_1$ are treated with $T_2$.  The data-generating procedure is sequential and under the assumption that neither the efficacy of $T_1$ nor the efficacy of $T_2$  depend on how many times $T_1$ was  received by an individual can be described using the tree in Figure \ref{TreeTwoFlorets}. Let $p_{i}$, $i = 1, \dots, 5$, denote the leaf probabilities corresponding to the five resulting therapy paths.  The non-leaf nodes are partitioned in two equivalence classes, the first one parameterized by  
$(\zeta_1,\zeta_2)$ and the second one by $(\eta_1, \eta_2)$, where each $\zeta_1,\zeta_2, \eta_1, \eta_2 \in (0,1)$ and satisfy $\zeta_1 + \zeta_2 = 1$,  $\eta_1 +\eta_2 = 1$.   The corresponding model  $\mathcal{M}$ has two florets and states that:
\begin{equation}\label{modelTwoFlorets1}
p_{1}= \zeta_1^2\eta_1, \,\,p_{2}=\zeta_1^2\eta_2, \,\,p_{3}= \zeta_1\zeta_2, \,\,p_{4}=\zeta_2\eta_1, \,\, p_{5} =\zeta_2\eta_2.
\end{equation} 
 The model matrix consists of two floret-specific blocks:
$$\mathbf{M} = \left(\begin{array}{rrrrrr}   2 & 2 & 1 & 0 & 0\\ 
                                                             0 & 0 & 1 & 1 & 1 \\
                                                             &  &  &  &  \\[-6pt]
                                                             1 & 0 & 0 & 1 & 0 \\
                                                             0 & 1 & 0 & 0 & 1 \\
                                \end{array} \right).
$$
Notice that the row space of the matrix block corresponding to the second floret does not contain the row $(1,1,1,1,1)$, so the floret is incomplete and the exposure ratio in this floret depends on the observed data. 
By Theorem \ref{theoremMatrixProbMultiFloret}, the asymptotic covariance matrix of the non-redundant $\sqrt{N}\hat{\zeta}_1$ and $\sqrt{N}\hat{\eta}_1$  consists of two blocks and is equal to
\begin{equation} \label{MxFinal}
\boldsymbol{\Phi}_{\zeta_1, \eta_1}= 
 \left(\begin{array}{cc} \frac{\zeta_1(1-\zeta_1)}{\zeta_1 +1} & 0\\
                                 0 & \frac{\eta_1(1-\eta_1)}{\zeta_1^2 - \zeta_1 +1}\\                                
        \end{array}\right).\end{equation}
Indeed, in expectation, the $T_1$-exposure size is $N(\zeta_1 +1)$, because $N$ patients receive $T_1$ at the beginning and  another $N\zeta_1$ are expected to receive $T_1$ at the second round. And the expected $T_2$-exposure size is  $N(\zeta_1^2 + (1- \zeta_1))$, where  $N(1-\zeta_1)$ patients are expected to have had a negative response to the first round of $T_1$ and $N\zeta_1^2$ patients are expected to have had two positive responses to $T_1$.    \qed
\end{example}



