\section*{Appendix}

\subsection{Proof of Theorem \ref{theoremMatrixProbOneFloret}}

\begin{proof}

Part $(i)$: 

For simplicity of presentation, the subscript $0$ in $\boldsymbol p_0$ and $\boldsymbol \theta_0$ is omitted. The derivatives are with respect to $\tilde{\boldsymbol \theta}$, although the notation $\boldsymbol \theta$ is used instead.

Firstly, because $\mathbf{A} = diag(\boldsymbol p)^{-1/2 } \frac{\partial \boldsymbol p}{\partial \boldsymbol{\theta}}$, one has:
$$\mathbf{A}\tr \mathbf{A} = \frac{\partial \boldsymbol p\tr}{\partial \boldsymbol{\theta}} diag(\boldsymbol p^{-1 }) \frac{\partial \boldsymbol p}{\partial \boldsymbol{\theta}}.$$
Thus, to prove (\ref{OneFloretMxA}), one needs to verify that 
\begin{equation}\label{EqProof}
\frac{\partial \boldsymbol p\tr}{\partial \boldsymbol{\theta}} diag(\boldsymbol p^{-1 }) \frac{\partial \boldsymbol p}{\partial \boldsymbol{\theta}}= {\mathcal{S}(\boldsymbol p(\boldsymbol{\theta}))}\cdot(diag(\tilde{\boldsymbol\theta}^{-1} ) + \boldsymbol 1 \cdot \boldsymbol 1\tr \theta_{J}^{-1}).
\end{equation}

The proof presented next is based on the fact that if $\boldsymbol p \in \mathcal{M}$, the derivative  $\frac{\partial \boldsymbol p}{\partial \boldsymbol{\theta}}$ can be obtained either by explicit differentiation of 
$\boldsymbol p (\boldsymbol \theta) = \boldsymbol \theta^{\mathbf{M}\tr}$, or using implicit differentiation of $\boldsymbol \theta = \frac{1}{\mathcal{S}(\boldsymbol p(\boldsymbol{\theta}))}\mathbf{M}\boldsymbol p(\boldsymbol \theta)$. By bringing the two approaches together, the result in (\ref{EqProof}) and thus in (\ref{OneFloretMxA}) will be achieved.  

Let $\boldsymbol p$ denote the observed probability distribution, and  $\hat{\boldsymbol p} = (\hat{p}_{i})_{i = 1}^I$ the MLE having observed $\boldsymbol p$ under $\mathcal{M}$. Then, because $\mathcal{M}$ is a one-floret tree model,  
\begin{equation}\label{MLEproof}
\hat{p}_i  =  \prod_{j = 1 } ^J \left(\frac{\sum_{i = 1}^I \mu_{ji} p_i}{\sum_{l = 1 }^J \sum_{i = 1}^I \mu_{li} p_i}\right)^{ \mu_{ji}}, \quad \mbox{for } \quad i = 1, \dots, I. \tag{*}
\end{equation}
Here $(\mu_{ji})_{j,i}$ are the corresponding entries of the model matrix $\mathbf{M}$. Letting 
$z_j = \sum_{i = 1}^I \mu_{ji} p_i$, for each $j = 1, \dots, J$, $\boldsymbol z = (z_1, \dots, z_J)\tr $, $z_{J + 1} = z_{1} + \dots + z_{J}$, and $\theta_j = z_{j} / z_{J + 1}$, for $j = 1, \dots, J$, one obtains that 
\begin{equation}\label{thetaproof}
\hat{p}_{i} = \prod_{j = 1}^J \left(\frac{z_{j}}{z_{J + 1}}\right)^{\mu_{ji}} = \prod_{j = 1}^J \theta_j^{\mu_{ji}},  \quad \mbox{for } i = 1, \dots, I.
\end{equation}


Define
\begin{equation}\label{Qproof1}
Q_p = \sum_{i = 1}^I p_i \log \hat{p}_i. 
\end{equation}
The function $Q_p$ has the following properties. Firstly, by Proposition 2.5 in \cite{Kapranov1991},  for functions of the form (\ref{MLEproof}) one has:
\begin{equation} \nonumber
\log {\hat{p}}_k = \frac{\partial Q_p(\boldsymbol \theta)}{\partial p_k}, \quad \mbox{for } k = 1, \dots, I.
\end{equation}
Secondly, after substituting into $Q_p$, the expression for $\hat{p}_i$ in terms of $z_j$'s from (\ref{thetaproof}) one has:
\begin{align*}
Q_p &= \sum_{i = 1}^I p_i \log \prod_{j = 1}^J\left(\frac{z_{j}}{z_{J + 1}}\right)^{\mu_{ji}} 
= \sum_{i = 1}^I p_i \sum_{j = 1}^J {\mu_{ji}}  \log \left(\frac{z_{j}}{z_{J + 1}}\right) \\
&= \sum_{i = 1}^I \sum_{j = 1}^J {\mu_{ji}}  p_i \log {z_{j}} -   \sum_{i = 1}^I  \sum_{j = 1}^J p_i {\mu_{ji}} \log {z_{J + 1}}\\
&=  \sum_{j = 1}^J  \log {z_{j}}\sum_{i = 1}^I{\mu_{ji}}  p_i -  \log {z_{J + 1}} \sum_{j = 1}^J \sum_{i = 1}^I  p_i {\mu_{ji}} \\
&=  \sum_{j = 1}^J z_{j}  \log {z_{j}}-  \log {z_{J + 1}} \sum_{j = 1}^J z_{j}  \\
&=  \sum_{j = 1}^J z_{j}  \log {z_{j}}- {z_{J + 1}} \log {z_{J + 1}}.
\end{align*}
Denote the final expression by 
\begin{equation}\label{Qproof2}
W_z = \sum_{j = 1}^J z_j \log z_j - z_{J+1} \log z_{J + 1}.
\end{equation}

Therefore, for a $\boldsymbol p \in \mathcal{M}$,
\begin{equation}\label{qbothproof}
Q_p(\boldsymbol \theta) = W_z(\boldsymbol \theta).%  
\end{equation}
Next, both sides of the equality (\ref{qbothproof}) will be differentiated twice with respect to $\boldsymbol \theta$,  the resulting second derivatives will be set equal to each other, and then the latter will allow to determine the expression for $\frac{\partial \boldsymbol p\tr}{\partial \boldsymbol{\theta}} diag(\boldsymbol p^{-1 }) \frac{\partial \boldsymbol p}{\partial \boldsymbol{\theta}}$.




First, differentiate $Q_p$ with respect to $\boldsymbol \theta$:

\begin{align*}
\frac{\partial Q_p}{\partial \boldsymbol{\theta}} &= \sum_{i = 1}^{I} \frac{\partial p_i}{\partial \boldsymbol{\theta}}  \log \hat{p}_i + \sum_{i = 1}^{I} p_i \frac{\partial p_i/ \partial \boldsymbol{\theta}}{  \hat{p}_i}
= \sum_{i = 1}^{I} \frac{\partial p_i}{\partial \boldsymbol{\theta}}  \log \hat{p}_i,
\end{align*}
because if $\boldsymbol p \in \mathcal{M}$,   $\boldsymbol p = \hat{\boldsymbol{p}}$ and $\sum_{i = 1}^{I}  {\partial p_i/ \partial \boldsymbol{\theta}} = 0$.

The second derivative of $Q_p$ with respect to $\boldsymbol \theta$ is, therefore,
\begin{align*}
\frac{\partial^2 Q_p}{\partial \boldsymbol{\theta}^2} &= \sum_{i = 1}^{I} \frac{\partial^2 p_i}{\partial \boldsymbol{\theta}^2}  \log \hat{p}_i  + \sum_{i = 1}^{I}  \frac{\partial p_i}{\partial \boldsymbol{\theta}} \frac{\partial p_i/ \partial \boldsymbol{\theta}}{  \hat{p}_i},
\end{align*}
or, written in the matrix form,
\begin{align*}
\frac{\partial^2 Q_p}{\partial \boldsymbol{\theta}^2} &=  \frac{\partial^2 \boldsymbol p\tr}{\partial \boldsymbol{\theta}^2}  \log \hat{\boldsymbol p}  + \frac{\partial \boldsymbol p\tr}{\partial \boldsymbol{\theta}} diag(\hat{\boldsymbol p}^{-1 }) \frac{\partial \boldsymbol p}{\partial \boldsymbol{\theta}},
\end{align*}
and, finally, after recalling that $\boldsymbol p = \hat{\boldsymbol p}$:
\begin{align*}
\frac{\partial^2 Q_p}{\partial \boldsymbol{\theta}^2} &= \frac{\partial^2 \boldsymbol p\tr}{\partial \boldsymbol{\theta}^2}  \log \boldsymbol p  + \frac{\partial \boldsymbol p\tr}{\partial \boldsymbol{\theta}} diag(\boldsymbol p^{-1 }) \frac{\partial \boldsymbol p}{\partial \boldsymbol{\theta}}.
\end{align*}

Next, differentiate $W_z$ with respect to $\theta_k$, for $k = 1, \dots, J-1$:
\begin{align*}
\frac{\partial W_z}{\partial {\theta_k}} &= \sum_{j = 1}^{J} \frac{\partial z_j}{\partial {\theta_k}}  \log z_j + \sum_{j = 1}^{J} z_j \frac{\partial z_j/ \partial {\theta_k}}{  z_j} - \frac{\partial z_{J+1}}{\partial {\theta_k}}  \log z_{J+1} - z_{J+1}\frac{\partial z_{J+1}/ \partial {\theta_k}}{  z_{J+1}}% \\
%&= \sum_{j = 1}^{J} \frac{\partial z_j}{\partial {\theta_k}}  \log z_j  - \frac{\partial z_{J+1}}{\partial {\theta_k}}  \log z_{J+1},
\end{align*}
Because $z_{J + 1} = \sum_{j = 1}^{J} z_{j}$ and thus, $\sum_{j = 1}^{J}  {\partial z_j/ \partial \boldsymbol{\theta}} - \partial z_{J+1}/ \partial \boldsymbol{\theta}= 0$, the expression for the derivative simplifies to:
\begin{align*}
\frac{\partial W_z}{\partial {\theta_k}} &= \sum_{j = 1}^{J} \frac{\partial z_j}{\partial {\theta_k}}  \log z_j  - \frac{\partial z_{J+1}}{\partial {\theta_k}}  \log z_{J+1}.
\end{align*}

Compute the second derivatives of $W_z$ and rearrange the terms:
\begin{align*}
\frac{\partial^2 W_z}{\partial {\theta_k \theta_m}} &= \sum_{j = 1}^{J} \frac{\partial^2 z_j}{\partial {\theta_k \theta_m}}  \log z_j  + \sum_{j = 1}^{J}  \frac{\partial z_j}{\partial{\theta_k}} \frac{\partial z_j/ \partial {\theta_m}}{ z_j} -  \frac{\partial^2 z_{J+1}}{\partial {\theta_k \theta_m}}  \log z_{J +1} - \frac{\partial z_{J +1}}{\partial {\theta_k}} \frac{\partial z_{J +1}/ \partial {\theta_m}}{ z_{J +1}}  \\
&=\sum_{j = 1}^{J} \frac{\partial^2 z_j}{\partial {\theta_k \theta_m}}  \log z_j   -  \frac{\partial^2 z_{J+1}}{\partial {\theta_k \theta_m}}  \log z_{J +1} + \sum_{j = 1}^{J}  \frac{\partial z_j}{\partial {\theta_k}} \frac{\partial z_j/ \partial {\theta_m}}{ z_j} - \frac{\partial z_{J +1}}{\partial {\theta_k}} \frac{\partial z_{J +1}/ \partial {\theta_m}}{ z_{J +1}},  \\
&=\sum_{j = 1}^{J} \frac{\partial^2 z_j}{\partial {\theta_k}^2}  \log (z_j/z_{J +1})  + \sum_{j = 1}^{J}  \frac{\partial z_j}{\partial {\theta_k}} \frac{\partial z_j/ \partial {\theta_k}}{ z_j} - \frac{\partial z_{J +1}}{\partial {\theta_k}} \frac{\partial z_{J +1}/ \partial {\theta_k}}{ z_{J +1}}, \\
\end{align*}
for $ m = 1,\dots, J-1$. 
To simplify further, recall that $z_j = \theta_j z_{J+1}$, for $j = 1, \dots, J$ and $\theta_J = 1 - \sum_{j = 1}^{J-1} \theta_j$, and take into account that for $k = 1, \dots, J -1$, $$\partial z_{J +1}/ \partial {\theta_k} = \sum_{j = 1}^J \partial z_{j}/ \partial {\theta_k} = \partial z_{k}/ \partial {\theta_k} + \partial z_{J}/ \partial {\theta_k} = z_{J+1} - z_{J+1} = 0.$$

\noindent For $k = m$, one has:
\begin{align*}
\frac{\partial^2 W_z}{\partial {\theta_k}^2} &=\sum_{j = 1}^{J} \frac{\partial^2 z_j}{\partial {\theta_k}^2}  \log (z_j/z_{J +1})  + \sum_{j = 1}^{J}  \frac{\partial z_j}{\partial {\theta_k}} \frac{\partial z_j/ \partial {\theta_k}}{ z_j} - \frac{\partial z_{J +1}}{\partial {\theta_k}} \frac{\partial z_{J +1}/ \partial {\theta_k}}{ z_{J +1}}  \\
&=\sum_{j = 1}^{J} \frac{\partial^2 z_j}{\partial {\theta_k}^2}  \log (z_j/z_{J +1}) + \frac{\partial z_k}{\partial {\theta_k}} \frac{\partial z_k/ \partial {\theta_k}}{ z_k}  + \frac{\partial z_{J}}{\partial {\theta_k}} \frac{\partial z_J/ \partial {\theta_k}}{ z_J} - \frac{\partial z_{J +1}}{\partial {\theta_k}} \frac{\partial z_{J +1}/ \partial {\theta_k}}{ z_{J +1}}  \\
&=\sum_{j = 1}^{J} \frac{\partial^2 z_j}{\partial {\theta_k}^2} \log (z_j/z_{J +1})  + \frac{ z_{J +1}^2}{ z_{J+1}\theta_k}  + (-z_{J +1}) \frac{-z_{J +1}}{ z_{J +1}\theta_J} - \frac{\partial z_{J +1}}{\partial {\theta_k}} \frac{\partial z_{J +1}/ \partial {\theta_k}}{ z_{J +1}}  \\
&=\sum_{j = 1}^{J} \frac{\partial^2 z_j}{\partial {\theta_k}^2}  \log (z_j/z_{J +1})  + z_{J +1}(\frac{1}{\theta_k}  + \frac{1}{\theta_J}).% - \frac{\partial z_{J +1}}{\partial {\theta_k}} \frac{\partial z_{J +1}/ \partial {\theta_k}}{ z_{J +1}}  \\
\end{align*}
\noindent For $k \neq m$:
\begin{align*}
\frac{\partial^2 W_z}{\partial {\theta_k\theta_m}} &=\sum_{j = 1}^{J} \frac{\partial^2 z_j}{\partial {\theta_k \theta_m}} \log (z_j/z_{J +1}) + \sum_{j = 1}^{J}  \frac{\partial z_j}{\partial {\theta_k}} \frac{\partial z_j/ \partial {\theta_m}}{ z_j} - \frac{\partial z_{J +1}}{\partial {\theta_k}} \frac{\partial z_{J +1}/ \partial {\theta_m}}{ z_{J +1}}  \\
&=\sum_{j = 1}^{J} \frac{\partial^2 z_j}{\partial {\theta_k \theta_m}}  \log (z_j/z_{J +1})  + \frac{\partial z_J}{\partial {\theta_k}} \frac{\partial z_J/ \partial {\theta_m}}{ z_j}  - \frac{\partial z_{J +1}}{\partial {\theta_k}} \frac{\partial z_{J +1}/ \partial {\theta_m}}{ z_{J +1}}  \\
&=\sum_{j = 1}^{J} \frac{\partial^2 z_j}{\partial {\theta_k \theta_m}}  \log (z_j/z_{J +1})  + (-z_{J +1}) \frac{-z_{J +1}}{ z_{J +1}\theta_J}  - \frac{\partial z_{J +1}}{\partial {\theta_k}} \frac{\partial z_{J +1}/ \partial {\theta_m}}{ z_{J +1}}  \\
&=\sum_{j = 1}^{J} \frac{\partial^2 z_j}{\partial {\theta_k\theta_m}}  \log (z_j/z_{J +1})  + z_{J +1}(\frac{1}{\theta_J}).% - \frac{\partial z_{J +1}}{\partial {\theta_k}} \frac{\partial z_{J +1}/ \partial {\theta_k}}{ z_{J +1}}  \\
\end{align*}
Finally,
\begin{equation}\label{secondDerivativesOneFloret}
\frac{\partial^2 W_z}{\partial {\theta_k\theta_m}} = \left\{ \begin{array}{l} 
\sum_{j = 1}^{J} \frac{\partial^2 z_j}{\partial {\theta_k}^2}  \log (z_j/z_{J +1})   + z_{J +1}(\frac{1}{\theta_k}  + \frac{1}{\theta_J}), \, \mbox{for }  k = m,\\
{}\\
\sum_{j = 1}^{J} \frac{\partial^2 z_j}{\partial {\theta_k\theta_m}}  \log (z_j/z_{J +1}) + z_{J +1}(\frac{1}{\theta_J}), \, \mbox{for }  k    \neq m.  \\
                                                                                      \end{array}  \right.
\end{equation}

Equivalently, in the matrix form,
\begin{equation*}
\frac{\partial^2 W_z}{\partial \tilde{\boldsymbol\theta}^2} =  \frac{\partial^2 {\boldsymbol z}}{\partial {\tilde{\boldsymbol \theta}}^2} \log ({\boldsymbol z}/z_{J+1}) + z_{J +1}(diag(\tilde{\boldsymbol\theta}^{-1} ) + \boldsymbol 1 \cdot \boldsymbol 1\tr \theta_{J}^{-1}).
\end{equation*}

To complete the proof, we need to show that 
$$ \frac{\partial^2 {\boldsymbol z}}{\partial {\tilde{\boldsymbol \theta}^2}} \log ({\boldsymbol z}/z_{J+1}) = 
\frac{\partial^2 \boldsymbol p\tr}{\partial \boldsymbol{\theta}^2}  \log \hat{\boldsymbol p}.$$

Because $z_j = \sum_{i = 1}^I \mu_{ij} p_i$,  $$ \frac{\partial^2 z_j }{\partial \theta_k \theta_m }  = 
\sum_{i = 1}^I \mu_{ij} \frac{\partial^2 p_i }{\partial \theta_k \theta_m } $$


Recall that $\hat{p}_{i} = \prod_{j = 1}^J \theta_j^{\mu_{ji}} =  \prod_{j = 1}^J (z_j/z_{J+1})^{\mu_{ji}} $. Hence, 
\begin{align*}
\sum_{i = 1}^I \frac{\partial^2 p_i}{\partial \theta_k \theta_m}\log \hat{p}_{i} &= \sum_{i = 1}^I \frac{\partial^2 p_i}{\partial \theta_k \theta_m }\sum_{j = 1}^J{\mu_{ji}} \log (z_j/z_{J+1}) = 
\sum_{j = 1}^J  \log (z_j/z_{J+1}) \sum_{i = 1}^I{\mu_{ji}} \frac{\partial^2 p_i}{\partial \theta_k \theta_m}\\
& = \sum_{j = 1}^{J} \log (z_j/z_{J+1}) \frac{\partial^2 z_j}{\partial \theta_k \theta_m}.
\end{align*}

Therefore,
$$ \frac{\partial \boldsymbol p\tr}{\partial \boldsymbol{\theta}} diag(\boldsymbol p^{-1 }) \frac{\partial \boldsymbol p}{\partial \boldsymbol{\theta}} = z_{J + 1}(diag(\tilde{\boldsymbol\theta}^{-1} ) + \boldsymbol 1 \cdot \boldsymbol 1\tr \theta_{J}^{-1}) = {\mathcal{S}(p(\boldsymbol{\theta}))}\cdot(diag(\tilde{\boldsymbol\theta}^{-1} ) + \boldsymbol 1 \cdot \boldsymbol 1\tr \theta_{J}^{-1}),$$
which completes the proof.
\end{proof}


\subsection{Proof of Theorem \ref{theoremMatrixProbMultiFloret}} %{theoremMatrixProbMultiFloret}

\begin{proof}

The procedure generalizes  the proof of Theorem \ref{theoremMatrixProbOneFloret}.
The subscript $0$ in $\boldsymbol p_0$ and $\boldsymbol \theta_0$ is also omitted. The derivatives are with respect to $\tilde{\boldsymbol \theta}$, although the notation $\boldsymbol \theta$ is used instead.

Let $\mathbf{A} = diag(\boldsymbol p)^{-1/2 } \frac{\partial \boldsymbol p}{\partial \boldsymbol{\theta}}$. It will be shown first that the matrix 
$$\mathbf{A}\tr \mathbf{A} = \frac{\partial \boldsymbol p\tr}{\partial \boldsymbol{\theta}} diag(\boldsymbol p^{-1 }) \frac{\partial \boldsymbol p}{\partial \boldsymbol{\theta}}$$
is block-diagonal with floret-specific blocks equal to:
\begin{equation}\label{MultiFloretMxA}
\mathbf{B}_f = \mathcal{S}_f(\boldsymbol p(\boldsymbol{\theta}))\cdot( diag(\tilde{\boldsymbol \theta_f}^{-1})  + \boldsymbol 1 \cdot \boldsymbol 1\tr  \theta_{J}^{-1}), \mbox{ for each } f \in \mathcal{F}.
\end{equation}

Let $\boldsymbol p$ denote the observed probability distribution, and  $\hat{\boldsymbol p} = (\hat{p}_{i})_{i = 1}^I$ the MLE having observed $\boldsymbol p$ under $\mathcal{M}$. 
Because $\mathcal{M}$ is a multi-floret tree model,  for each $i = 1, \dots, I$, 
\begin{equation}\label{MLEproofMulti}
\hat{p}_i  =   \prod_{f = 1 } ^F\prod_{j = 1 } ^{J_f} \left(\frac{\sum_{i = 1}^I \mu_{fji} p_i}{\sum_{l = 1 }^{J_f} \sum_{i = 1}^I \mu_{fli} p_i}\right)^{ \mu_{fji}}. \tag{**}
\end{equation}
Here $(\mu_{fji})_{f,j,i}$ are the corresponding entries of the model matrix $\mathbf{M}$. For each $f \in \mathcal{F}$, letting 
$z_{fj} = \sum_{i = 1}^I \mu_{fji} p_i$, for each $j = 1, \dots, J_f$, $\boldsymbol z_f = (z_{f1}, \dots, z_{f,J_f})\tr $, $z_{f,J_f + 1} = z_{f1} + \dots + z_{f,J_f}$, and $\theta_{fj} = z_{fj} / z_{f,J_f + 1}$, for $j = 1, \dots, J_f$,  one obtains that 
\begin{equation}\label{thetaproofMulti}
\hat{p}_{i} =\prod_{f = 1 } ^F \prod_{j = 1}^{J_f} \left(\frac{z_{fj}}{z_{f,J_f + 1}}\right)^{\mu_{fji}} = \prod_{f = 1 } ^F\prod_{j = 1}^{J_f} \theta_{fj}^{\mu_{fji}},  \quad \mbox{for } i = 1, \dots, I.
\end{equation}


As in the proof of Theorem \ref{theoremMatrixProbOneFloret}, define
\begin{equation}\label{QproofF}
Q_p = \sum_{i = 1}^I p_i \log \hat{p}_i. 
\end{equation}
Generalizing Proposition 2.5 in \cite{Kapranov1991}  for functions of the form (\ref{MLEproofMulti}), one has:
\begin{equation} \nonumber
\log {\hat{p}}_k = \frac{\partial Q_p(\boldsymbol \theta)}{\partial p_k}, \quad \mbox{for } k = 1, \dots, I.
\end{equation}
Next, let for $f \in \mathcal{F}$, 
\begin{equation}\nonumber
W_{fz} = \sum_{j = 1}^{J_f} z_{fj} \log z_{fj} - z_{f,J_f+1} \log z_{f,J_f + 1}, \quad 
\mbox{and} \quad W_z = \sum_{f = 1}^F W_z.
\end{equation}
After substituting into $Q_p$ the expression for $\hat{p}_i$ from (\ref{thetaproofMulti}) and rearranging terms one obtains that for a $\boldsymbol p \in \mathcal{M}$,
\begin{equation}\label{qbothproofMulti}
Q_p(\boldsymbol \theta) = W_z(\boldsymbol \theta) = \sum_{f = 1}^F W_{fz}.%  \coloneqq \sum_{j = 1}^J z_j \log z_j - z_{J+1} \log z_{J + 1}. % \sum_{j = 1}^J z_j \log z_j - z_{J+1} \log z_{J + 1}.
\end{equation}


Following the idea that was used in the proof of Theorem  \ref{theoremMatrixProbOneFloret}, the second derivatives with respect to $\boldsymbol \theta$ of the right hand and left hand sides of the equality (\ref{qbothproofMulti}) will be set equal to each other, which would allow to determine the expression for $\frac{\partial \boldsymbol p\tr}{\partial \boldsymbol{\theta}} diag(\boldsymbol p^{-1 }) \frac{\partial \boldsymbol p}{\partial \boldsymbol{\theta}}$.



One can verify that the first and second derivatives of $Q_p$ with respect to $\boldsymbol \theta$ have the same form as in the one-floret case, namely,
\begin{align*}
\frac{\partial Q_p}{\partial \boldsymbol{\theta}} &= \sum_{i = 1}^{I} \frac{\partial p_i}{\partial \boldsymbol{\theta}}  \log \hat{p}_i,\\
\frac{\partial^2 Q_p}{\partial \boldsymbol{\theta}^2} &= \sum_{i = 1}^{I} \frac{\partial^2 p_i}{\partial \boldsymbol{\theta}^2}  \log \hat{p}_i  + \sum_{i = 1}^{I}  \frac{\partial p_i}{\partial \boldsymbol{\theta}} \frac{\partial p_i/ \partial \boldsymbol{\theta}}{  \hat{p}_i}.
\end{align*}
After recalling that if $\boldsymbol p \in \mathcal{M}$ then $\boldsymbol p = \hat{\boldsymbol p}$, one has in the matrix form:
\begin{align*}
\frac{\partial^2 Q_p}{\partial \boldsymbol{\theta}^2} &= \frac{\partial^2 \boldsymbol p\tr}{\partial \boldsymbol{\theta}^2}  \log \boldsymbol p  + \frac{\partial \boldsymbol p\tr}{\partial \boldsymbol{\theta}} diag(\boldsymbol p^{-1 }) \frac{\partial \boldsymbol p}{\partial \boldsymbol{\theta}}.
\end{align*}



Next, notice that for $f, g \in \mathcal{F}$,  for $k = 1, \dots, J_g-1$, one has:
\begin{align*}
\frac{\partial W_{fz}}{\partial {\theta_{gk}}} &= \left \{\begin{array}{ll}
 \sum_{j = 1}^{J_f} \frac{\partial z_{fj}}{\partial {\theta_{fk}}}  \log z_{fj}  - \frac{\partial z_{f,J_f+1}}{\partial {\theta_{fk}}}  \log z_{J_f+1}, & \mbox{ if } \,\, f = g, \\
 0 & \mbox{ if } \,\, f \neq g.\\
 \end{array} \right.
\end{align*}
Therefore,
\begin{align*}
\frac{\partial W_{z}}{\partial {\theta_{fk}}} &= \sum_{g = 1}^F \frac{\partial W_{gz}}{\partial {\theta_{fk}}}  =   \frac{\partial W_{fz}}{\partial {\theta_{fk}}}  = \sum_{j = 1}^{J_f} \frac{\partial z_{fj}}{\partial {\theta_{fk}}}  \log z_{fj}  - \frac{\partial z_{f,J_f+1}}{\partial {\theta_{fk}}}  \log z_{J_f+1}.
\end{align*}

Further, because for the second derivatives,
\begin{align*}
\frac{\partial^2 W_{z}}{\partial {\theta_{fk}}\partial {\theta_{gm}}} &= \frac{\partial^2 W_{fz}}{\partial {\theta_{fk}}\partial {\theta_{fm}}},
\end{align*}
where $k, m = 1, \dots, J_f - 1$, one has:
\begin{equation*}
\frac{\partial^2 W_{z}}{\partial \tilde{\boldsymbol\theta}_f \partial \tilde{\boldsymbol\theta}_g} =
 \left \{\begin{array}{ll}
 \frac{\partial^2 W_{fz}}{\partial \tilde{\boldsymbol\theta}_f^2}& \mbox{ if } \,\, f = g, \\
 \mathbf{0} & \mbox{ if } \,\, f \neq g.\\
 \end{array} \right.
\end{equation*}
As can be verified using the derivation used in the proof of Theorem  \ref{theoremMatrixProbOneFloret},
\begin{align*}
\frac{\partial^2 W_{fz}}{\partial \tilde{\boldsymbol\theta}_f^2} &=  \frac{\partial^2 {\boldsymbol z}_f}{\partial {\tilde{\boldsymbol \theta}}_f^2} \log ({\boldsymbol z_f}/z_{f,J_f+1}) + z_{f,J_f +1}(diag(\tilde{\boldsymbol\theta_f}^{-1} ) + \boldsymbol 1 \cdot \boldsymbol 1\tr \theta_{f,J_f}^{-1}) \\ 
&= \frac{\partial^2 \boldsymbol p\tr}{\partial \boldsymbol{\theta}^2}  \log \hat{\boldsymbol p} + z_{f,J_f +1}(diag(\tilde{\boldsymbol\theta_f}^{-1} ) + \boldsymbol 1 \cdot \boldsymbol 1\tr \theta_{f,J_f}^{-1}).
\end{align*}

Therefore,
\begin{align*}
\frac{\partial \boldsymbol p\tr}{\partial \boldsymbol{\theta}} diag(\boldsymbol p^{-1 }) \frac{\partial \boldsymbol p}{\partial \boldsymbol{\theta}} &= diag\left\{z_{f,J_f + 1}(diag(\tilde{\boldsymbol\theta}_f^{-1} ) + \boldsymbol 1 \cdot \boldsymbol 1\tr \theta_{f,J_f}^{-1})\right \}_{f = 1}^F \\
&= diag\left\{ {\mathcal{S}_f(p(\boldsymbol{\theta}))}\cdot(diag(\tilde{\boldsymbol\theta}_f^{-1} ) + \boldsymbol 1 \cdot \boldsymbol 1\tr \theta_{f,J_f}^{-1})\right \}_{f = 1}^F,
\end{align*}

which completes the proof.


\end{proof}

