# Initialisation
for each entity i:
    mu_i <- exp_0(normalize(E(i)) * tanh(norm(E(i))))
    r_i <- log(1 + exp(w_i))
    kappa_i ~ Uniform(-5, -0.01)

# Training loop
for each minibatch (u, v_pos):
    sample v_neg
    for each v in {v_pos, v_neg}:
        initialise beam B_0 = {[u]}
        for h = 1 to k:
            expand each path P in B_{h-1} by appending tags t in T
                with score log K(e_{h-1}, t)
        keep top-b paths ending at v
        s(u, v) <- max_P prod_{(e_i, e_{i+1}) in P}
                     K(e_i, e_{i+1})
    L_rank <- max(0, gamma - s(u, v_pos) + s(u, v_neg))
    L_curv <- lambda * sum_i max(0, kappa_i + delta)^2
    update parameters via Riemannian Adam
\end{lstlisting}
\caption{Training pseudocode for ManifoldMind using beam-based semantic path reasoning.}
\label{fig:pseudocode}
\end{figure}

\section{Results}
We evaluate \textbf{ManifoldMind} on four real-world datasets,GoodBooks, MIND, Avicenna, and Book-Crossing, using standard metrics for classification (NDCG @ 10, Recall @ 10), calibration (ECE), diversity (Diversity @ 10, T-ILS) and interpretability. Baselines include NeuMF++, LightGCN++, Poincaré, CSRec, HSR, and FineRec. All results are averaged over five seeds.

\subsection{Comparison to Baselines}
\textbf{ManifoldMind achieves the best overall performance} across all core metrics. Table~\ref{tab:main-results} shows that it exceeds FineRec by +4. 5\% in NDCG@10 and achieves the lowest ECE (11.6\% lower). These improvements derive from adaptive curvature and symbolic path-based reasoning over hyperbolic space.

