\section{Introduction}
Let $X$ be a Euclidean space with inner product $\innp{x,y}$ and induced norm $\norm{x}:=\sqrt{\innp{x,x}}$. Our goal is to solve the optimization problem
\begin{equation*}
	\min_{x\in X} f(x):=\frac{1}{N}\sum_{i=1}^{N} f_i(x),
\end{equation*}
where each $f_i$ is convex, $L_i-$smooth, and bounded below. We denote $\ds L_{\max}:=\max_{i=1,\dots,N}L_{i}$. We use the notation $\ds\mu:=\inf f(X)$ for the infimum of any function $f$ throughout this paper. 

A popular algorithm for this setting, especially when $N$ is large, is the \emph{Stochastic Gradient Descent \cref{SGD}} algorithm
\begin{equation}
	x_{k+1}:=x_k-\gamma_k\nabla f_{B_k}(x_k),\label{SGD}\tag{SGD}
\end{equation}
where $\gamma_k>0$ is the stepsize, $B_k\subseteq\left\{1,\dots,N\right\}$ is a random batch with fixed size $b\geq1$, sampled independently and uniformly at each iteration, and $f_{B_k}:=\frac{1}{b}\sum_{i\in B_k} f_i$.

In \cite{Loizou2021}, Loizou, Vaswani, Hadj Laradji, and Lacoste-Julien proposed the following \textit{Stochastic Polyak's stepsize} \cref{SPS} for the \cref{SGD} when $b=1$:
\begin{equation}
	\gamma_k:=\lambda\min\left\{\frac{f_{i_k}(x_k)-\mu_{i_k}}{\norm{\nabla f_{i_k}(x_k)}^2},\frac{\gamma_{-1}}{\lambda}\right\},\label{SPS}\tag{SPS}
\end{equation}
where $\mu_i:=\inf f_i(X)$, and where $\gamma_{-1},\lambda>0$ are user-defined constants. However, \cref{SPS} requires the exact knowledge of $\mu_{i_k}$. The authors proved the following result:

\begin{fact}[{\cite[Theorem 3.4]{Loizou2021}}]\label{fact1.1}
	Let $f_i:X\to\mathbb{R}$ be convex, $L_i-$smooth, and bounded below for all $i=1,\dots,N$. Suppose that $f:=\frac{1}{N}\sum_{i=1}^Nf_i$ has a minimizer $x^*\in X$. Let $x_0\in X$, $\gamma_{-1}>0$ and $\lambda=1$. Then, the sequence $\left(x_k\right)_{k\in\mathbb{N}}$ generated by \cref{SGD} with \cref{SPS} satisfies
	\begin{equation*}
		\mathbb{E}\left[f(\bar{x}_k)-\mu\right]\leq\frac{\norm{x_0-x^*}^2}{\alpha k}+\frac{2\sigma^2\gamma_{-1}}{\alpha},
	\end{equation*}
	where $\alpha:=\min\big\{\frac{1}{2L_{\max}},\gamma_{-1}\big\}$, $\sigma^2:=\mu-\mathbb{E}\left[\mu_i\right]$, and $\bar{x}_k:=\frac{1}{k}\sum\limits_{i=0}^{k-1}x_i$.
\end{fact}

\begin{remark}
	\cref{fact1.1} implies that when $k\to\infty$, we get 
	\begin{equation*}
		\lim\limits_{k\to\infty}\mathbb{E}\left[f(\bar{x}_k)\right]\leq\mu+\frac{2\sigma^2\gamma_{-1}}{\alpha},
	\end{equation*}
	which the authors call ``convergence to a neighborhood of the solution''.
\end{remark}

In \cite{Orvieto2022}, Orvieto, Lacoste-Julien, and Loizou introduced the \textit{Decreasing Stochastic Polyak's Stepsize} \cref{DecSPS}
\begin{equation}
	\gamma_k:=\lambda_k\min\left\{\frac{f_{B_k}(x_k)-\underline{\mu_{B_k}}}{\norm{\nabla f_{B_k}(x_k)}^2},\frac{\gamma_{k-1}}{\lambda_{k-1}}\right\},\label{DecSPS}\tag{DecSPS}
\end{equation}
where $\underline{\mu_{B}}$ is a lower bound of $f_{B}$,  $\left(\lambda_k\right)_{k\in\mathbb{N}}$ is a decreasing sequence in $\mathbb{R}_{++}$, $\lambda_{-1}:=\lambda_0$ and $\gamma_{-1}>0$. Observe that for this stepsize, one does not need precise information about the optimal value of the batch objective function $f_{B_k}$ at each step but only a lower bound of $f_{B_k}$.

\begin{remark}[{\cite[Lemma 1]{Orvieto2022}}]
	From the definition of \cref{DecSPS} and the fact that $\left(\lambda_k\right)_{k\in\mathbb{N}}$ is a decreasing sequence, we have
	\begin{equation*}
			\left(\forall k\in\mathbb{N}\right)\quad \gamma_{k}\leq\lambda_k\frac{\gamma_{k-1}}{\lambda_{k-1}}\leq\gamma_{k-1},
		\end{equation*}
	i.e., $\left(\gamma_{k}\right)_{k\in\mathbb{N}}$ is indeed a decreasing stepsize.
\end{remark}

The main result for \cref{SGD} with \cref{DecSPS} is as follows:

\begin{fact}[{\cite[Theorem 3]{Orvieto2022}}]\label{fact1.4}
	Let $f_i:X\to\mathbb{R}$ be convex, $L_i-$smooth, and bounded below for all $i=1,\dots,N$. Suppose that $f:=\frac{1}{N}\sum_{i=1}^Nf_i$ has a minimizer $x^*\in X$. Let $\left(\lambda_k\right)_{k\in\mathbb{N}}$ be a decreasing sequence such that $\lambda_k\leq1$ for all $k\in\mathbb{N}$ and let $\lambda_{-1}:=\lambda_{0}$, $\gamma_{-1}>0$, $x_0\in X$. Let $\left(x_k\right)_{k\in\mathbb{N}}$ be a sequence generated by \cref{SGD} with \cref{DecSPS}. Assume that $M:=\sup_{k\in\mathbb{N}} \norm{x_k-x^*}^2<\infty$. Then we have for all $k\in\mathbb{N}$,
	\begin{equation*}
		\mathbb{E}\left[f(\bar{x}_k)\right]-\mu\leq\frac{M}{\alpha}\frac{1}{\lambda_{k-1}k}+\sigma_b^2\frac{\sum_{i=0}^{k-1}\lambda_{i}}{k},
	\end{equation*}
	where $\alpha:=\min\big\{\frac{1}{2L_{\max}},\frac{\gamma_{-1}}{\lambda_0}\big\}$ and $\bar{x}_k:=\frac{1}{k}\sum_{i=0}^{k-1}x_i$.
\end{fact}

\begin{fact}[Ces\`aro means]\label{fact1.5}
	If $\left(\lambda_k\right)_{k\in\mathbb{N}}$ lies in $\mathbb{R}$ and $\lambda_{k}\to\lambda$, then $\frac{1}{k}\sum_{i=0}^{k-1}\lambda_i\to\lambda$.
\end{fact}

\begin{remark}
	In light of \cref{fact1.4} and \cref{fact1.5}, if $k\lambda_{k-1}\to\infty$, and $\lambda_{k}\to0$ ($\Rightarrow\frac{1}{k}\sum_{i=0}^{k-1}\lambda_i\to0$), then $\lim_{k\to\infty}\mathbb{E}\left[f(\bar{x}_k)\right]=\mu$. A standard choice for $\left(\lambda_{k}\right)_{k\in\mathbb{N}}$ that satisfies these assumptions is $\lambda_k:=\frac{1}{(k+1)^\theta}$ with $\theta\in(0,1)$, or $\lambda_k:=\frac{\ln(k+2)}{(k+2)^\theta}$ with $\theta\in(0,1]$.
\end{remark}

\cref{fact1.4} relies on a crucial assumption that the sequence $(x_k)_{k\in\mathbb{N}}$ is bounded, which the author only verified when $\lambda_{k}:=\frac{1}{\sqrt{k+1}}$ and under the rather restrictive assumption that each $f_i$ is strongly convex (see \cite[Proposition 1]{Orvieto2022}). In fact, many recent variants of \cref{SGD} with \cref{DecSPS} still use this assumption (see \cite[Theorem 5]{Islamov2024}, \cite[Corollary 5]{Jiang2023}, \cite[Theorem 3.6]{Oikonomou2024}).

In this paper, we provide the following new results on \cref{fact1.4}:
\begin{itemize}
    \item We present a scheme in which the sequence generated by \cref{SGD} with \cref{DecSPS} can be unbounded (see \cref{theorem3.4}).
    \item We then relax the condition of \cite[Proposition 1]{Orvieto2022} from strong convexity to a broader class of functions whose lower level sets, with the minimizers removed, are bounded (e.g., coercive functions), and extend the result to both constant and diminishing step sizes (see \cref{theorem3.8}).
    \item Finally, we discuss cases not covered by the above results.
\end{itemize}

The rest of the paper is organized as follows: \cref{s:prelim} introduces preliminary results. \cref{s:counterex} presents an example in which the sequence generated by \cref{SGD} with \cref{DecSPS} blows up to infinity. \cref{s:main} establishes our main boundedness result. \cref{s:discussion} discusses scenarios not covered by our assumptions.

The notation we employ is standard and largely follows, e.g., \cite{Bauschke2017} and \cite{Garrigos2024}.

\section{Preliminary results}
\label{s:prelim}
In this section, we introduce definitions, facts, and lemmas from convex analysis that will be useful in the subsequent sections.

\begin{definition}[{\cite[Definition 5.1]{Beck2017}}]
	Let $L\geq0$.  A function $f: X\to\mathbb{R}$ is said to be {\rm$L$-smooth} if it is differentiable and satisfies
	\begin{equation*}
		\left(\forall x,y\in X\right)\quad\norm{\nabla f(x)-\nabla f(y)}\leq L\norm{x-y}.
	\end{equation*}
\end{definition}

\begin{remark}\label{remark2.2}
	In the finite sum setting, if $f:=\frac{1}{N}\sum^{N}_{i=1}f_i$ and each $f_i$ is $L_i$-smooth, then every batch function $f_B$ is $L_{\max}$-smooth.
\end{remark}

\begin{definition}[{\cite[Equation (2.5)]{Beck2017}}]
	A function $f:X\to\mathbb{R}$ is said to be {\rm convex} if
	\begin{equation*}
		\left(\forall x,y\in X\right)\left(\forall \lambda\in(0,1)\right)\quad f\big((1-\lambda)x+\lambda y\big)\leq\left(1-\lambda\right)f(x)+\lambda f(y).
	\end{equation*}
\end{definition}

\begin{remark}\label{remark2.4}
	In the finite sum setting, if $f:=\frac{1}{N}\sum^{N}_{i=1}f_i$ and each $f_i$ is convex, then every batch function $f_B$ is also convex.
\end{remark}

\begin{fact}[{\cite[Theorem 5.8]{Beck2017}}]\label{fact2.5}
	Let $L>0$ and let $f: X\to\mathbb{R}$ be convex and differentiable. Then $f$ is $L$-smooth if and only if
	\begin{equation*}
		\left(\forall x,y\in X\right)\quad f(y)\leq f(x)+\innp{\nabla f(x),y-x}+\frac{L}{2}\norm{y-x}^2.
	\end{equation*}
\end{fact}

\begin{lemma}[{\cite[Lemma 2.28]{Garrigos2024}}]\label{lemma2.6}
	Let $L>0$ and let $f: X\to\mathbb{R}$ be convex, $L$-smooth and bounded below. Then
	\begin{equation*}
		\left(\forall x\in X\right)\quad f(x)-\mu\geq\frac{1}{2L}\norm{\nabla f(x)}^2.
	\end{equation*}
	Note that $f$ does not need to have a minimizer.
\end{lemma}

