\begin{definition}[{\cite[Definition 11.11]{Bauschke2017}}]
	Let $f:X\to\mathbb{R}$. Then $f$ is {\rm coercive} if
	\begin{equation*}
		\lim_{\norm{x}\to\infty}f(x)=\infty.
	\end{equation*}
\end{definition}

\begin{definition}[{\cite[Definition 1.4]{Bauschke2017}}]
	Let $f:X\to\mathbb{R}$. The {\rm lower level set} of $f$ at height $\xi\in\mathbb{R}$ is
	\begin{equation*}
		\lev{\xi}f:=\left\{x\in X\mid f(x)\leq\xi\right\}.
	\end{equation*}
\end{definition}

\begin{fact}[{\cite[Proposition 11.12]{Bauschke2017}}]\label{fact2.9}
	Let $f:X\to\mathbb{R}$. Then $f$ is coercive if and only if its lower level sets $\left(\lev{\xi}f\right)_{\xi\in\mathbb{R}}$ are bounded.
\end{fact}

\begin{fact}[{\cite[Proposition 11.13]{Bauschke2017}}]\label{fact2.10}
	Let $f:X\to\mathbb{R}$ be convex. Then $f$ is coercive if and only if there exists $\xi\in\mathbb{R}$ such that $\lev{\xi}f$ is nonempty and bounded.
\end{fact}

\begin{fact}[{\cite[Proposition 1.2.3]{Bertsekas2016}}]\label{fact2.11}
	Assume that $f$ is $L$-smooth and bounded below. Suppose also that $\gamma_{k}\to0$, $\sum_{k\in\mathbb{N}}\gamma_{k}=\infty$, and $\gamma_k>0$ for all $k\in\mathbb{N}$. Let $\left(x_k\right)_{k\in\mathbb{N}}$ be a sequence generated by a gradient method $x_{k+1}=x_k-\gamma_{k}\nabla f(x_k)$. Then, $\left(f(x_k)\right)_{k\in\mathbb{N}}$ converges to a finite value and $\nabla f(x_k)\to0$. Furthermore, every limit point of $\left(x_k\right)_{k\in\mathbb{N}}$ is a stationary point of $f$.
\end{fact}

\section{Main results}
Recall the \cref{SGD} algorithm with fixed batch size $b\geq1$:
\begin{equation*}
	x_{k+1}:=x_k-\gamma_k\nabla f_{B_k}(x_k),
\end{equation*}
where $\gamma_k>0$. We consider 3 cases:

\begin{enumerate}[label=(C\arabic*)]
	\item $\left(\exists B\subseteq\left\{1,\dots,N\right\},|B|=b\right)\quad\argmin f_B=\varnothing$.\label{C1}
	\item $\left(\forall B\subseteq\left\{1,\dots,N\right\},|B|=b\right)\quad\argmin f_B\neq\varnothing$ and $\lev{\xi}f_B\setminus\argmin f_B$ is bounded for all $\xi\in\mathbb{R}$.\label{C2}
	\item $\left(\forall B\subseteq\left\{1,\dots,N\right\},|B|=b\right)\quad\argmin f_B\neq\varnothing$, but there exists a batch $\hat{B}$ and a constant $\hat{\xi}\in\mathbb{R}$ such that $\lev{\hat{\xi}}f_{\hat{B}}\setminus\argmin f_{\hat{B}}$ is unbounded.\label{C3}
\end{enumerate}

\begin{remark}
	A sufficient condition for \ref{C2} is that the number of coercive functions satisfies
	\begin{equation*}
		\#\left\{i\in\left\{1,\dots,N\right\}\mid f_i\text{ is coercive}\right\}\geq N-b+1;
	\end{equation*}
	indeed, in this case, every batch function is the average of at least one coercive function and several bounded below functions, and is therefore coercive. The conclusion then follows from \cref{remark2.4}, \cref{fact2.9} and \cref{fact2.10}.
\end{remark}

\begin{remark}
	When $X=\mathbb{R}$, \ref{C3} will never happen: indeed, if $\argmin f_{\hat{B}}$ were bounded, \cref{fact2.9} and \cref{fact2.10} would lead to a contradiction. WLOG, assume $\argmin f_{\hat{B}}=(-\infty,a]$. Since $\lev{\hat{\xi}}f_{\hat{B}}\setminus\argmin f_{\hat{B}}$ is unbounded and $\argmin f_{\hat{B}}\subseteq\lev{\hat{\xi}}f_{\hat{B}}$, it follows that $\lev{\hat{\xi}}f_{\hat{B}}=\mathbb{R}$; that is, $f_{\hat{B}}$ is bounded above. This, combined with \cref{remark2.4} and \cite[Corollary 8.6.2]{Rockafellar1997}, implies that $f_{\hat{B}}$ is a constant function. However, this would mean $\lev{\hat{\xi}}f_{\hat{B}}\setminus\argmin f_{\hat{B}}=\varnothing$, which is a contradiction.
\end{remark}

\begin{fact}[{\cite[Lemma 1]{Orvieto2022}}]\label{fact3.3}
	Let $f_i:X\to\mathbb{R}$ be convex, $L_i-$smooth, and bounded below for all $i=1,\dots,N$. Let $\left(\lambda_k\right)_{k\in\mathbb{N}}$ be a decreasing sequence in $\mathbb{R}_{++}$. Let $\lambda_{-1}:=\lambda_0$, $\gamma_{-1}>0$ and let $\left(\gamma_k\right)_{k\in\mathbb{N}}$ be the stepsize sequence generated by \cref{SGD} with \cref{DecSPS}. Then,
	\begin{equation*}
		\left(\forall k\in\mathbb{N}\right)\quad\min\left\{\frac{1}{2L_{\max}},\frac{\gamma_{-1}}{\lambda_0}\right\}\lambda_k\leq\gamma_k\leq \frac{\gamma_{-1}}{\lambda_0}\lambda_k.
	\end{equation*}
\end{fact}

\subsection{Case \ref{C1}}
\label{s:counterex}
\begin{theorem}\label{theorem3.4}
	Let $f_i:X\to\mathbb{R}$ be convex, $L_i-$smooth, and bounded below for all $i=1,\dots,N$. Suppose that \ref{C1} is satisfied. Let $\left(\lambda_k\right)_{k\in\mathbb{N}}$ be a decreasing sequence such that $\lambda_{k}\to0$, $\sum_{k\in\mathbb{N}}\lambda_{k}=\infty$ and $0<\lambda_0\leq1$. Let $\lambda_{-1}:=\lambda_{0}$, $\gamma_{-1}>0$, $x_0\in X$. Then, there exists a sequence of batches $\left(B_k\right)_{k\in\mathbb{N}}$ such that the corresponding sequence $\left(x_k\right)_{k\in\mathbb{N}}$ generated by \cref{SGD} with \cref{DecSPS} satisfies $\lim_{k\to\infty} \norm{x_k}=\infty$.
\end{theorem}

\begin{proof}
	Let $\hat{B}$ be the batch where $\argmin f_{\hat{B}}(X)=\varnothing$. Consider the sequence $\left(y_k\right)_{k\in\mathbb{N}}$ generated by the gradient method applied to the problem $\min_{x\in X}f_{\hat{B}}(x)$, using the stepsize defined in \cref{DecSPS} but restricted only to the batch $\hat{B}$, that is,
	\begin{equation*}
		\gamma_{k,\hat{B}}:=\lambda_k\min\left\{\frac{f_{\hat{B}}(x_k)-\underline{\mu_{\hat{B}}}}{\norm{\nabla f_{\hat{B}}(x_k)}^2},\frac{\gamma_{k-1,\hat{B}}}{\lambda_{k-1}}\right\}.
	\end{equation*}
	Then, $(\gamma_{k,\hat{B}})_{k\in\mathbb{N}}$ is a deterministic sequence and it is bounded: indeed, by \cref{fact3.3},
	\begin{equation*}
		\left(\forall k\in\mathbb{N}\right)\quad\min\left\{\frac{1}{2L_{\max}},\frac{\gamma_{-1,\hat{B}}}{\lambda_0}\right\}\lambda_k\leq\gamma_{k,\hat{B}}\leq \frac{\gamma_{-1,\hat{B}}}{\lambda_0}\lambda_k.
	\end{equation*}
	Because $\lambda_{k}\to0$ and $\sum_{k\in\mathbb{N}}\lambda_{k}=\infty$, we have $\gamma_{k,\hat{B}}\to0$ and $\sum_{k\in\mathbb{N}}\gamma_{k,\hat{B}}=\infty$. By \cref{remark2.2} and \cref{fact2.11}, every limit point of $\left(y_k\right)_{k\in\mathbb{N}}$ is a stationary point of $f_{\hat{B}}$. However, since $f_{\hat{B}}$ is convex (see \cref{remark2.4}) and has no minimizer, it cannot have a stationary point. Thus, $\norm{y_k}\to\infty$ as $k\to\infty$. Moreover, if we were to sample the same batch $\hat{B}$ at every step, then $\left(x_k\right)_{k\in\mathbb{N}}$ would coincide with $\left(y_k\right)_{k\in\mathbb{N}}$, which implies $\lim_{k\to\infty} \norm{x_k}=\infty$.
\end{proof}

\subsection{Case \ref{C2}}
\label{s:main}
Assume that there exists $m\in\mathbb{R}_+$ such that for every batch $B\subseteq\left\{1,\dots,N\right\}$ with $|B|=b$, there exists a lower bound $\underline{\mu_{B}}$ of $f_B$ such that the stepsize sequence $\left(\gamma_{k}\right)_{k\in\mathbb{N}}$ of \cref{SGD} satisfies
\begin{equation}
	\left(\forall k\in\mathbb{N}\right)\quad\gamma_k\norm{\nabla f_{B_k}(x_k)}^2\leq m \big(f_{B_k}(x_k)-\underline{\mu_{B_k}}\big).\label{3.1}
\end{equation}

\begin{remark}\label{remark3.5}
	If $f_i:X\to\mathbb{R}$ is convex, $L_i-$smooth, and bounded below for all $i=1,\dots,N$, then \cref{remark2.2} , \cref{remark2.4}, and \cref{lemma2.6} imply that any sequence $\left(\gamma_{k}\right)_{k\in\mathbb{N}}$ that is bounded above by some $\gamma\in\mathbb{R}_+$ satisfies \cref{3.1} with $m=2L_{\max}\gamma$.
\end{remark}

\begin{remark}\label{remark3.6}
	From the definition of \cref{DecSPS}, we have
	\begin{equation*}
		\gamma_k\overset{\text{def}}{=}\lambda_k\min\left\{\frac{f_{B_k}(x_k)-\underline{\mu_{B_k}}}{\norm{\nabla f_{B_k}(x_k)}^2},\frac{\gamma_{k-1}}{\lambda_{k-1}}\right\}\leq\lambda_{k}\frac{f_{B_k}(x_k)-\underline{\mu_{B_k}}}{\norm{\nabla f_{B_k}(x_k)}^2},
	\end{equation*}
	and so,
	\begin{equation*}
		\gamma_{k}\norm{\nabla f_{B_k}(x_k)}^2\leq\lambda_{k}\big(f_{B_k}(x_k)-\underline{\mu_{B_k}}\big).
	\end{equation*}
	Since $\left(\lambda_{k}\right)_{k\in\mathbb{N}}$ is a decreasing sequence, \cref{3.1} is satisfied with $m=\lambda_0$.
\end{remark}

It is discussed in \cite[Remark 1]{Orvieto2022} that for \cref{DecSPS}, if at the $k$th step we get $\nabla f_{B_k}(x_k)=0$, we simply resample a different batch, as the update direction in \cref{SGD} would otherwise be zero, making the choice of stepsize irrelevant. Moreover, the authors stated that this event never occurred in their experiments. Therefore, we will assume that this situation never happens; that is, $x_k\notin\argmin f_{B_k}$ for all $k\in\mathbb{N}$.

\begin{proposition}\label{proposition3.7}
	Let $f_i:X\to\mathbb{R}$ be convex, differentiable, and bounded below for all $i=~1,\dots,N$. Let $x_0\in X$ and let $\left(x_k\right)_{k\in\mathbb{N}}$ be a sequence generated by \cref{SGD} with stepsize $\left(\gamma_{k}\right)_{k\in\mathbb{N}}$ satisfying \cref{3.1}. Then,
	\begin{equation*}
		\left(\forall k\in\mathbb{N}\right)\quad\norm{x_{k+1}}^2\leq\norm{x_k}^2-\left(2-m\right)\gamma_k\big(f_{B_k}(x_k)-\underline{\mu_{B_k}}\big)+2\gamma_{k}\big(f_{B_k}(0)-\underline{\mu_{B_k}}\big).
	\end{equation*}
\end{proposition}

\begin{proof}\belowdisplayskip=-13pt
	From \cref{SGD}, \cref{3.1} and convexity of the batch function $f_{B_k}$ (see \cref{remark2.4}), we obtain
        \begin{align}
		\norm{x_{k+1}}^2\overset{\cref{SGD}}{=}\, \ \ &\norm{x_k-\gamma_{k}\nabla f_{B_k}(x_k)}^2\notag\\
		=\ \ \ \ \ &\norm{x_k}^2-2\gamma_{k}\innp{\nabla f_{B_k}(x_k),x_k}+\gamma_{k}^2\norm{\nabla f_{B_k}(x_k)}^2\notag\\
		\overset{\cref{3.1}}{\leq}\ \ \ \ \ &\norm{x_k}^2-2\gamma_{k}\innp{\nabla f_{B_k}(x_k),x_k}+m\gamma_{k}\big(f_{B_k}(x_k)-\underline{\mu_{B_k}}\big)\notag\\
		\overset{\text{convexity}}{\leq}&\norm{x_k}^2-2\gamma_{k}\big(f_{B_k}(x_k)-f_{B_k}(0)\big)+m\gamma_{k}\big(f_{B_k}(x_k)-\underline{\mu_{B_k}}\big)\notag\\
		=\ \ \ \ \ &\norm{x_k}^2-2\gamma_{k}\big(f_{B_k}(x_k)-\underline{\mu_{B_k}}+\underline{\mu_{B_k}}-f_{B_k}(0)\big)\notag\\
		&+m\gamma_{k}\big(f_{B_k}(x_k)-\underline{\mu_{B_k}}\big)\notag\\
		=\ \ \ \ \ &\norm{x_k}^2-\left(2-m\right)\gamma_{k}\big(f_{B_k}(x_k)-\underline{\mu_{B_k}}\big)+2\gamma_{k}\big(f_{B_k}(0)-\underline{\mu_{B_k}}\big).\notag\qedhere
	\end{align}
\end{proof}

\begin{theorem}\label{theorem3.8}
	Let $f_i:X\to\mathbb{R}$ be convex, $L_i-$smooth, and bounded below for all $i=~1,\dots,N$. Suppose that \ref{C2} is satisfied. Let $x_0\in X$. Let $\left(x_k\right)_{k\in\mathbb{N}}$ be a sequence generated by \cref{SGD} with stepsize $\left(\gamma_{k}\right)_{k\in\mathbb{N}}$ satisfying \cref{3.1} with $m<2$ and $0<\gamma_k\leq\gamma$. Then $\left(x_k\right)_{k\in\mathbb{N}}$ is bounded.
\end{theorem}

\begin{proof}
	Let 
	\begin{equation*}
		D:=\max_{\substack {B\subseteq\left\{1,\dots,N\right\}\\ |B|=b}}\big(f_{B}(0)-\underline{\mu_{B}}\big).
	\end{equation*}
	Let $I$ be the list of batches $B$ with $|B|=b$ such that $\lev{\underline{\mu_B}+\frac{2D}{2-m}}f_B\setminus\argmin f_B$ is nonempty. Assumption \ref{C2} implies
	\begin{equation}
		\left(\forall B\in I\right)\left(\exists M_B>0\right)\left(\forall x\in\lev{\underline{\mu_B}+\frac{2D}{2-m}}f_B\setminus\argmin f_B\right)\quad \norm{x}\leq M_B.\label{3.2}
	\end{equation}
	Let $M:=\max_{B\in {I}}M_B$, and let $x^*_B$ denote a minimizer for each batch function $f_B$. Define 
	\begin{equation*}
		c:=\max\left\{M,\frac{\gamma L_{\max}}{1+\gamma L_{\max}}\max_{\substack {B\subseteq\left\{1,\dots,N\right\}\\ |B|=b}}\norm{x_B^*}\right\}.
	\end{equation*}

	We will prove by induction that
	\begin{equation*}
		\left(\forall k\in\mathbb{N}\right)\quad\norm{x_k}^2\leq\max\left\{4c^2\left(1+\gamma L_{\max}\right)^2,\norm{x_0}^2\right\}.
	\end{equation*}
	The base case $k=0$ clearly holds. For the induction step, assume the induction hypothesis
	\begin{equation}
		\norm{x_k}^2\leq\max\left\{4c^2\left(1+\gamma L_{\max}\right)^2,\norm{x_0}^2\right\},\label{3.3}
	\end{equation}
	holds for some $k\in\mathbb{N}$. If
	\begin{equation*}
		\norm{x_{k+1}}\leq2c\left(1+\gamma L_{\max}\right),
	\end{equation*}
	then \cref{3.3} holds for $k+1$, and we are done. So, we consider the case where
	\begin{equation}
		\norm{x_{k+1}}>2c\left(1+\gamma L_{\max}\right).\label{3.4}
	\end{equation}

	By the triangle inequality, $L_{\max}$-smoothness of $f_{B_k}$ (see \cref{remark2.2}), and $\gamma_k\leq\gamma$, we get that
	\begin{align*}
		\norm{x_k}&\geq\norm{x_{k+1}}-\norm{x_{k+1}-x_k}\\
		&=\norm{x_{k+1}}-\gamma_k\norm{\nabla f_{B_k}(x_k)}\\
		&\geq\norm{x_{k+1}}-\gamma L_{\max}\norm{x_k-x^*_{B_k}}\\
		&\geq\norm{x_{k+1}}-\gamma L_{\max}\left(\norm{x_k}+\norm{x^*_{B_k}}\right).
	\end{align*}
	Rearrange and divide both sides by $1+\gamma L_{\max}$, we obtain
	\begin{equation}
		\norm{x_k}\geq\frac{\norm{x_{k+1}}}{1+\gamma L_{\max}}-\frac{\gamma L_{\max}}{1+\gamma L_{\max}}\norm{x_{B_k}^*}.\label{3.5}
	\end{equation}

	From the definition of $c$, we get that
	\begin{equation}
		\frac{\gamma L_{\max}}{1+\gamma L_{\max}}\norm{x_{B_k}^*}\leq c.\label{3.6}
	\end{equation}
	Combining \cref{3.5}, \cref{3.4}, \cref{3.6} and the definition of $c$, we obtain
	\begin{equation*}
		\norm{x_k}>2c-c=c\geq {M}.
	\end{equation*}
	Hence,
	\begin{equation*}
		\norm{x_k}>M.
	\end{equation*}
	This combined with \cref{3.2} and the definition of $M$ yields
	\begin{equation}
		\left(\forall B\in I\right)\quad x_k\notin \lev{\underline{\mu_B}+\frac{2D}{2-m}}f_B\setminus\argmin f_B.\label{3.7}
	\end{equation}

	From \cref{3.7} and the definition of $I$, we obtain
	\begin{equation*}
		\left(\forall B\subseteq\left\{1,\dots,N\right\},|B|=b\right)\quad x_k\notin \lev{\underline{\mu_B}+\frac{2D}{2-m}}f_B\setminus\argmin f_B,
	\end{equation*}
	which implies
	\begin{equation*}
		f_{B_k}(x_k)=\mu_{B_k}\text{ or }f_{B_k}(x_k)>\underline{\mu_{B_k}}+\frac{2D}{2-m}.
	\end{equation*}
	Since we assumed $x_k\notin\argmin f_{B_k}$ for all $k\in\mathbb{N}$, we deduce that
	\begin{equation}
		f_{B_k}(x_k)>\underline{\mu_{B_k}}+\frac{2D}{2-m}.\label{3.8}
	\end{equation}

	From Proposition \ref{proposition3.7}, \cref{3.3}, \cref{3.8} and the definition of $D$, we obtain
	\begin{align*}
		\norm{x^{k+1}}^2&\leq\norm{x^k}^2-(2-m)\gamma_{k}\big(f_{B_k}(x_k)-\underline{\mu_{B_k}}\big)+2\gamma_{k}\big(f_{B_k}(0)-\underline{\mu_{B_k}}\big)\\
		&< \max\left\{4c^2\left(1+\gamma L_{\max}\right)^2,\norm{x_0}^2\right\}-(2-m)\gamma_{k}\frac{2D}{2-m}+2\gamma_{k}D\\
		&=\max\left\{4c^2\left(1+\gamma L_{\max}\right)^2,\norm{x_0}^2\right\}.
	\end{align*}
	This conclude the proof.
\end{proof}

\begin{corollary}
	Let $f_i:X\to\mathbb{R}$ be convex, $L_i-$smooth, and bounded below for all $i=~1,\dots,N$. Suppose that \ref{C2} is satisfied. Let $\left(\gamma_k\right)_{k\in\mathbb{N}}$ be a sequence such that $0<\gamma_k\leq\gamma<\frac{1}{L_{\max}}$ for all $k\in\mathbb{N}$. Let $x_0\in X$ and let $\left(x_k\right)_{k\in\mathbb{N}}$ be a sequence generated by \cref{SGD}. Then $(x_k)_{k\in\mathbb{N}}$ is bounded.
\end{corollary}

\begin{proof}
	From \cref{remark3.5} and $0<\gamma_k\leq\gamma<\frac{1}{L_{\max}}$ for all $k\in\mathbb{N}$, it follows that the sequence $\left(\gamma_{k}\right)_{k\in\mathbb{N}}$ satisfies \cref{3.1} with $m=2L_{\max}\gamma<2$. Therefore, \cref{theorem3.8} applies and yields the conclusion.
\end{proof}

\begin{corollary}
	Let $f_i:X\to\mathbb{R}$ be convex, $L_i-$smooth, and bounded below for all $i=~1,\dots,N$. Suppose that \ref{C2} is satisfied. Let $\left(\lambda_k\right)_{k\in\mathbb{N}}$ be a decreasing sequence such that $0<\lambda_0<2$ and let $\lambda_{-1}:=\lambda_{0}$, $\gamma_{-1}>0$, $x_0\in X$. Let $\left(x_k\right)_{k\in\mathbb{N}}$ be a sequence generated by \cref{SGD} with \cref{DecSPS}. Then $(x_k)_{k\in\mathbb{N}}$ is bounded.
\end{corollary}

\begin{proof}
	From \cref{remark3.6} and $0<\lambda_0<2$, it follows that the sequence $\left(\gamma_{k}\right)_{k\in\mathbb{N}}$ satisfies \cref{3.1} with $m=\lambda_0<2$. Moreover, since $\left(\lambda_k\right)_{k\in\mathbb{N}}$ is a decreasing sequence, \cref{fact3.3} implies that $\gamma_k\leq\frac{\gamma_{-1}}{\lambda_0}\lambda_k\leq\gamma_{-1}$ for all $k\in\mathbb{N}$. Therefore, Theorem \ref{theorem3.8} applies and yields the conclusion.
\end{proof}

\subsection{Case \ref{C3}}
\label{s:discussion}
Let $f_i:=\frac{1}{2}d_{C_i}^2$ where $C_i$ is a nonempty closed convex subsets of $X$ and $d_{C}:=\inf_{c\in C}\norm{\cdot-c}$ for all $i=1,\dots,N$. Then each $f_i$ is convex, bounded below, and $1-$smooth with $\nabla f_i=\Id-P_{C_i}$ where $P_C$ is the orthogonal projector onto C and $\Id$ is the identity mapping on $X$.

In the case where $b=1$ and $\underline{\mu_i}=\mu_i=0$ for all $i=1,\dots,N$, \cref{DecSPS} implies
\begin{align*}
    \gamma_k&\overset{\text{def}}{=}\lambda_k\min\left\{\frac{f_{i_k}(x_k)-\mu_{i_k}}{\norm{\nabla f_{i_k}(x_k)}^2},\frac{\gamma_{k-1}}{\lambda_{k-1}}\right\}\\&=\lambda_k\min\left\{\frac{1}{2},\frac{\gamma_{k-1}}{\lambda_{k-1}}\right\}\\
    &\overset{\text{def}}{=}\lambda_k\min\left\{\frac{1}{2},\frac{\lambda_{k-1}\min\left\{\frac{1}{2},\frac{\gamma_{k-2}}{\lambda_{k-2}}\right\}}{\lambda_{k-1}}\right\}\\
    &=\lambda_k\min\left\{\frac{1}{2},\frac{\gamma_{k-2}}{\lambda_{k-2}}\right\}\\
    &\ \ \vdots\\
    &=\lambda_k\min\left\{\frac{1}{2},\frac{\gamma_{-1}}{\lambda_{0}}\right\}.
\end{align*}
Hence, \cref{SGD} with \cref{DecSPS} is equivalent to the relaxed random projection algorithm:
\begin{equation}
    x_{k+1}=x_k-\gamma_k\nabla f_{i_k}(x_k)=\left(1-\lambda_k\min\left\{\frac{1}{2},\frac{\gamma_{-1}}{\lambda_{0}}\right\}\right)x_k+\lambda_k\min\left\{\frac{1}{2},\frac{\gamma_{-1}}{\lambda_{0}}\right\}P_{C_{i_k}}x_k.\label{3.9}
\end{equation}

If each $C_i\subseteq X$ is an unbounded polyhedral set\footnote{Recall that a subset $C$ of $X$ is a polyhedral set if it is the intersection of finitely many closed halfspaces.}, then \cref{C3} is satisfied. By \cite[Theorem~2.5]{Bauschke2025}, if $\min\left\{\lambda_0,2\gamma_{-1}\right\}<4$, then the sequence $(x_k)_{k\in\mathbb{N}}$ generated by \cref{3.9} is bounded.

If we drop polyhedrality and let $\lambda_k=\gamma_{-1}=2$ for all $k\in\mathbb{N}$, then one can construct two sets $C_1,C_2$ such that \cref{C3} is satisfied and there exists a sampling of sets such that the sequence $(x_k)_{k\in\mathbb{N}}$ generated by \cref{3.9} blow up to infinity (see \cite[Example~4.1]{Bauschke2025}).

Even in this special case, we've seen that the sequence of iterates generated by \cref{SGD} with \cref{DecSPS} can either be bounded or unbounded. Thus, we leave the analysis of \cref{C3} in more settings as future work.

