\subsection*{Properties of nilpotentisers}
\bigskip

If $x\in L$, then $\nil_L(x)$ is the union of all maximal nilpotent subalgebras containing $x$.

\begin{lemma} 
For any Lie algebra $L$ and any $x\in L$, the following are equivalent:
\begin{itemize}
\item[(i)]  $\nil_L(x)$ is a subspace of $L$;
\item[(ii)]  $ \nil_L(x)$  is a maximal nilpotent subalgebra of $L$;
\item[(iii)]  $x$ is contained in just one maximal nilpotent subalgebra.
\end{itemize}
\end{lemma}

\begin{proof} 
Simply note that if $U$, $V$ are subspaces of $L$, then $U\cup V$ is a subspace if and only if $U\subseteq V$ or $V\subseteq U$.
\end{proof}

\begin{lemma} Let $L$ be a Lie algebra, $J$ an ideal of $L$ and $x,y\in L$. Then
\begin{itemize}
\item[(i)] $\nil(L)\subseteq \nil_L(x)$;
\item[(ii)] $\frac{\nil_L(x)+J}{J}\subseteq \nil_L(x+J)$;
\item[(iii)] $\nil_{L/J}(x+J)=\frac{\nil_L(x)}{J}$ whenever $J\subseteq Z^*(L)$;
\item[(iv)] the nilpotentiser of every element of $L$ is a subalgebra if and only if the same is true for $L/J$ for some ideal $J$ of $L$ with $J\subseteq Z^*(L)$;
\item[(v)] if $\nil_L(x)$ is a subalgebra of $L$ and $y\in \nil_L(x)$, then $\nil_L(y)=\nil_L(x)$;
\item[(vi)] if $\theta$ is an automorphism of $L$, then $\theta(\nil_L(x))=\nil_L(\theta(x))$.
\end{itemize}
\end{lemma}

\begin{proof} 
These are straightforward.
\end{proof}


