\begin{remark}
Let $L$ be a reductive Lie algebra over a field $F$ of characteristic zero. Then $L$ decomposes as:
\[L = S \oplus Z(L),\]
where $S = [L, L]$ is semisimple and $Z(L)$ is the center of $L$.
\end{remark}

\begin{lemma}
Let $L$ be a reductive Lie algebra over a field $F$ of characteristic zero. Then $\nil(L) = Z(L)$.
\end{lemma}

\begin{proof} 
Let $x \in Z(L)$. Then for any $y \in L$, we have $[x, y] = 0$, so $\langle x, y\rangle$ is abelian, hence nilpotent. Thus, $x \in \nil(L)$.

Reciprocally, let $x \in \nil(L)$. Write $x = s + z$ with $s \in S$, and $z \in Z(L)$. Suppose $s \neq 0$. 


Since $S$ is semisimple and the field has characteristic zero, there exists $y \in S \subseteq L$ such that the subalgebra $\langle s, y \rangle$ is not nilpotent. But $z \in Z(L)$, so for all $y \in L$, we have:
\[[x, y] = [s + z, y] = [s, y] + [z, y] = [s, y].\]
Hence \( \langle x, y \rangle = \langle s, y \rangle \), which is not nilpotent, a contradiction. Therefore, $s = 0$, and $x = z \in Z(L)$. Since $S$ is semisimple and the field has characteristic zero, there exists \( y \in S \subseteq L \) such that the subalgebra \( \langle s, y \rangle \) is not nilpotent.
\end{proof}



\section{The nilpotent graph of a Lie algebra}

\begin{definition}
Let $L$ be a finite-dimensional non-nilpotent Lie algebra. The nilpotent graph of $L$, denoted by $\Gamma_{\mathfrak{N}}(L)$, is a simple undirected graph whose vertex set is $L\setminus \nil(L)$, and two vertices $x$ and $y$ are adjacent if and only if $\langle x, y\rangle$ is a nilpotent subalgebra of $L$.    
\end{definition}

