\begin{lemma}
Let $U$ be a nilpotent subalgebra of a finite-dimensional Lie algebra $L$, such that $U\not\subseteq \nil(G)$. Then the set 
$U\setminus (U\cap \nil(L))$ forms a clique in $\Gamma_\mathfrak{N}(L)$.
\end{lemma}


\begin{proof}
For all $x,y\in U\setminus (U\cap \nil(L))$ we have that $\langle x,y\rangle$ is nilpotent. Thus, the subgraph of $\Gamma_\mathfrak{N}(L)$  having $U- (U\cap \nil(L))$ as its set of vertices is a clique. 
\end{proof}

\section{Direct Sums}


\begin{lemma}\label{ComponentsNilAdjacency}
Let $L_1$ and $L_2$ be Lie algebras over a field $F$, $a_1, a_2\in L_1$ and $b_1, b_2\in L_2$, Then $\langle (a_1, b_1), (a_2, b_2) \rangle$ is a nilpotent Lie subalgebra of $L_1\oplus L_2$ if and only if $\langle a_1, a_2 \rangle$ and $\langle b_1, b_2 \rangle$ are nilpotent Lie subalgebras of $L_1$ and $L_2$ respectively.
\end{lemma}

\begin{proof}
It is clear that if $(x,y) \in \langle(a,b),(c,d)\rangle$ then $x \in \langle a,c\rangle$ and $y \in \langle b,d\rangle$ (a simple induction would give a formal proof), so $\langle(a,b),(c,d)\rangle \subseteq \langle a,c\rangle \oplus \langle b,d\rangle$. Hence $\langle a,c\rangle$ and $\langle b,d\rangle$ nilpotent implies that $\langle(a,b),(c,d)\rangle$ is nilpotent. For the converse, note that there must be an n such that every product of n elements of $\langle(a,b),(c,d)\rangle$ must be zero. But every product of n elements of $\langle a,c\rangle$ occurs as the first coordinate of such a product, and so is zero. Similarly, for $\langle b,d\rangle$.
\end{proof}

