\begin{theorem}
\label{KappaProductNilpotent}
Let $L_1$ be a finite dimensional non-nilpotent Lie algebra. For every finite dimensional nilpotent Lie algebra $L$, it holds $ \kappa(L_1\oplus L) = \kappa(L_1)$. In particular, $\Gamma_{\mathfrak{N}}(L_1)$ is connected if and only if $\Gamma_{\mathfrak{N}}(L_1\oplus L)$ is connected for every finite dimenional nilpotent  Lie algebra $L$.
\end{theorem}

\begin{proof}
Let $L$ be any finite dimensional nilpotent Lie algebra. Then $\nil(L) = L$ and $\nil(L_1\oplus L) = \nil(L_1)\oplus L$. Thus, by Lemma \ref{ComponentsNilAdjacency},  
$(z,w), (x,y)$ are adjacent in $\Gamma_{\mathfrak{N}}(L_1\oplus L)$ if and only if $z$ and $x$ are adjacent in $\Gamma_{\mathfrak{N}}(L_1)$. Then, there is no path from $z$ to $x$ if and only if there is no path from $(z,w)$ to $(x,y)$, for all $w, y \in L$. This implies that $\kappa(L_1\oplus L) = \kappa(L_1)$.
\end{proof}

\par

%In group theory, the existence of strongly self-centralizing subgroups guarantees the nonconnectedness of the nilpotent graph of a group $G$.
\section{Strongly self-centralising subalgebras}

\begin{definition}
A subalgebra $U$ of $L$ is said to be strongly self-centralizing if $C_L(x) = U$ for all $0\neq x\in U$.
\end{definition}

\begin{example}
Let $L$ be the two-dimensional non-abelian Lie algebra. The $L$ has basis $\{x, y\}$ with $[x,y]=-[y,x]=y$. Put $U = Fx$. Then $U$ is a strongly self-centralising Lie subalgebra of $L$. 
\end{example}


\begin{example}
Let $L$ be three-dimensional with basis $\{e, f, g\}$ and products $[e,f] = 0, [e,g] = e, [f,g] = f$. Then $U := Fe + Ff$ is strongly self-centralising Lie subalgebra of $L$. 
\end{example}


\begin{example}
Let $L=\mathfrak{sl}_n(F_q)$ be the Lie algebra of $n\times n$ traceless matrices over the finite field $F_q$, and let $U$ be the subalgebra of all diagonal matrices in $\mathfrak{sl}_n(F_q)$, with $q= p^a$ and $p\nmid n$. Then $C_L(x)=U$ for all $0\neq x\in U$. 
\end{example}

\par

\begin{lemma}\label{omega}
 Let $U$ be a nilpotent subalgebra of $L$ such that $U \not \subseteq \nil(L)$. Then
 $U\setminus (U\cap \nil(L))$ is the set of vertices of a clique of $\Gamma_\mathfrak{N}(L)$. Moreover, if $N$ is a nilpotent ideal of $L$ and $L$ is finite, $|N\setminus (N\cap \nil(L))| \leq \omega(\Gamma_\mathfrak{N} (L))$. In
 particular, $|N(L) \setminus (N(L)\cap \nil(L))|\leq \omega(\Gamma_\mathfrak{N} (L))$.
\end{lemma}

\begin{proof}
Since any subalgebra of a nilpotent Lie algebra is nilpotent, $\langle x,y\rangle$ is nilpotent for all $x, y \in U \setminus (U \cap \nil(L))$. Thus the subgraph of $\Gamma_\mathfrak{N} (L)$ having $U \setminus (U\cap \nil(L))$ as its set of vertices is a clique. Moreover, if $N$ is a nilpotent ideal of $L$, then
 \begin{align*}
 |N\setminus(N\cap \nil(L))| &\leq \max\{|U \setminus(U\cap \nil(L))| : U \hbox{ is a nilpotent ideal of } L\} \\
 &\leq \max\{|U \setminus(U\cap \nil(L))| : U \hbox{ is a nilpotent subalgebra of } L\} \\
 &\leq \omega(\Gamma_\mathfrak{N}(L)).
\end{align*}

The rest follows from the fact that the nilradical $N(L)$ is the largest  nilpotent subgroup of $L$.  
\end{proof}

\par


\begin{theorem}
\label{ProperCentralizer2}
 If there exists a strongly self-centralizing subalgebra $U$ of $L$, then:
 \begin{enumerate}
     \item $\nil_L(x) = U$ for all $0\neq x\in U$.

     \item $\Gamma_\mathfrak{N} (L)$ is a disconnected graph.

    \item  if $L$ is finite, $|\mathrm{N}(L)|-1\leq \omega(\Gamma_\mathfrak{N} (L))$.
 \end{enumerate}
\end{theorem}
\begin{proof}
(1) Let $0\neq x\in U$. Clearly, $U=C_L(x)\subseteq \nil_L(x)$. So let $y\in \nil_L(x)$. Then there exists $z\in Z(\langle x,y\rangle)$ and so $z\in C_L(x)=U$. It follows that $y\in C_L(z)=U$, whence $\nil_L(x)\subseteq U$ and equality results.

(2) As in (1), for every $y\in L\setminus U$, $y\notin \nil_L(x)$, so $\langle x,y\rangle$ is not nilpotent and there is no edge from $y$ to $x$.

(3) By part (1) and Theorem \ref{z*},  $\nil(L) = Z^*(L) = 0$. Therefore $|N(L)|-1 \leq \omega(\Gamma_\mathfrak{N} (L))$ (by Lemma \ref{omega}).
\end{proof}


%\section{The non-nilpotent graph of a Lie algebra}

Finally, we present the complement of the nilpotent graph and an example of it.  This complement condition immediately implies that such a graph is connected. 

\begin{definition}
Let $L$ be a finite-dimensional non-nilpotent Lie algebra. The non-nilpotent graph of $L$, denoted by $\Gamma_{\mathfrak{N}}(L)^c$, is a simple undirected graph whose vertex set is $L\setminus \nil(L)$, and two vertices $x$ and $y$ are adjacent if and only if $\langle x, y\rangle$ is a non-nilpotent subalgebra of $L$.    
\end{definition}

