\section{Algorithms}

\begin{algorithm}[H]
\caption{An algorithm to generate the nilpotent and non-nilpotent graphs of a finite  matrix Lie algebra $L$}
    \begin{algorithmic}
        \State $n \gets \text{Any positive integer}$
        \State $F \gets \text{Any finite Field}$
        \State $L \gets gap(f'MatrixLieAlgebra(\{F\},\{n\})')$
        \Statex
        \State $elements \gets L.\text{AsList}()$
        \State $Nilpotentizer \gets Nilpotentizer(L)$ 

        \State $nodes \gets [x \in elements \mid x \notin Nilpotentizer]$

        \Statex \# nilpotent and non-nilpotent graph respectively
        \State $G \gets \text{Graph}()$
        \State $H \gets \text{Graph}()$
        \State $G.\text{add\_vertices}(nodes)$
        \Statex

        \For{$i \gets 0$ to $\text{length}(nodes)$}

            \For{$j \gets i + 1$ to $\text{length}(nodes)$}

                \State $S \gets L.\text{Subalgebra}([nodes[i], nodes[j]])$

                \If{$S.\text{IsLieNilpotent}()$}

                    \State $G.\text{add\_edge}(nodes[i], nodes[j])$

                \Else

                    \State $H.\text{add\_edge}(nodes[i], nodes[j])$

                \EndIf
            \EndFor
        \EndFor
        \Statex \# Nilpotent Graph
        \State $G.\text{show}(\text{figsize}=[10, 10])$
        \Statex \# Non-Nilpotent Graph
        \State $H.\text{show}(\text{figsize}=[10, 10])$

    \end{algorithmic}
\end{algorithm}




