\section{The multiway Dowker theorem}
\label{sec:multiway}

In this section we construct the main result.
%
In section~\ref{subsec:revisited}, we revisit Dowker's theorem in the light of section~\ref{sec:prod}.
%
This motivates a `cellular Dowker lemma' for arbitrary cell complexes, in section~\ref{subsec:cellular}. In section~\ref{subsec:multiway-prod}, we state and prove the multiway Dowker theorem for prod-complexes. This is primarily an assertion that certain Dowkerian quotient maps are homotopy equivalences.
%
In section~\ref{subsec:iterated}, we briefly discuss iterated Dowkerian quotients.

%------------------------------------------------
\subsection{Dowker's theorem revisited}
\label{subsec:revisited}

Let $R \subseteq I \times J$ be a binary relation.
%
The definitions
%
\begin{align*}
    \Dowker_I(R) &=
    \{ \sigma \in \Delta I
    \mid
    \text{there exists $j \in J$ such that
    $\sigma \times \{j\} \subseteq R$}
    \}
    \\
    \Dowker_J(R) &=
    \{ \tau \in \Delta J
    \mid
    \text{there exists $i \in I$ such that
    $\{i\} \times \tau \subseteq R$}
    \}
    \end{align*}
%
of the two classic Dowker complexes suggest two additional relations:
%
\begin{alignat*}{2}
    R_I
    &=
    \{ (\sigma, j) \mid
    \sigma \times \{j\} \subseteq R
    \}
    &&\; \subseteq \; \Delta I \times J
    \\
    R_J
    &=
    \{ (i, \tau) \mid
    \{i\} \times \tau \subseteq R
    \}
    &&
    \; \subseteq \; I \times \Delta J
\end{alignat*}
%
These are downwardly closed, in the following sense:
\begin{alignat*}{3}
(\sigma, j) \in R_I
&\;\; \text{and} \;\;
\sigma' \subseteq \sigma
&\;\; \text{implies} \;\;
(\sigma', j) \in R_I
\\
(i, \tau) \in R_J
&\;\; \text{and} \;\;
\tau' \subseteq \tau
&\;\; \text{implies} \;\;
(i, \tau') \in R_J
\end{alignat*}
%
This means that the `slices' of these relations
\begin{align*}
R_{I,j}
&= \{ \sigma \in \Delta I \mid (\sigma, j) \in R_I \}
\\
R_{i,J}
&= \{ \tau \in \Delta J \mid (i, \tau) \in R_J \}
\end{align*}
%
are simplicial complexes for each $j$ and each $i$. Moreover
\[
\Dowker_I(R) = \bigcup_{j \in J} R_{I,j}
\quad \text{and} \quad
\Dowker_J(R) = \bigcup_{i \in I} R_{i,J}
\]
so we recover the two Dowker complexes from these relation slices.

We can repeat the process that gave us $R_I$ and $R_J$ to obtain one more downwardly closed relation. This one we interpret geometrically:

\begin{definition}
    \label{def:relational-product}
    The \emph{Dowker relational product} \cite{Yoon_2024} is the prod-complex on $I,J$ defined:
    \[
    \dowker(R)
    =
    R_{IJ}
    =
    \{
    (\sigma, \tau) \mid \sigma \times \tau \subseteq R
    \}
    \; \subseteq \;
    \Delta I \times \Delta J
    \]
%
It is the largest prod-complex on $I, J$ whose vertex set is equal to~$R$.
\end{definition}

\begin{proposition}
    \label{prop:DI=D/I}
    The Dowker complexes of~$R$ are equal to the Dowkerian quotients of the Dowker relational product:
    \[
    \Dowker_I(R) = \dowker(R)/J
    \quad \text{and} \quad
    \Dowker_J(R) = \dowker(R)/I   
    \]
\end{proposition}

\begin{proof}
If $\sigma \in \Dowker_I(R)$ then there exists $j \in J$ with $\sigma \times \{j\} \subseteq R$.
%
Then $(\sigma,\{j\}) \in \dowker(R)$ so $\sigma \in \dowker(R)/J$.
%
Conversely if $\sigma \in \dowker(R)/J$ then some $\sigma \times \tau \subseteq R$. Taking $j \in \tau$ we have $\sigma \times \{j\} \subseteq R$ and therefore $\sigma \in \Dowker_I(R)$. The second statement is similar.
\end{proof}

\begin{theorem}[Dowker's theorem revisited]
\label{thm:dowker-revisited}
The geometric Dowkerian quotient maps
\[
\xymatrix{
|\Dowker_I(R)| = |\dowker(R)/J|
&&
|\dowker(R)|
    \ar@{>>}[ll]_-{|\psi_2|}
    \ar@{>>}[rr]^-{|\psi_1|}
&&
|\dowker(R)/I| = |\Dowker_J(R)|
}
\]
are homotopy equivalences.
\end{theorem}

This statement can be thought of as a prod-simplicial `squashing' of Brun and Salbu's formulation~\cite{Brun_Salbu_2022}.
%
We deduce it in the next section from the cellular Dowker lemma \ref{lem:cellular}.

%------------------------------------------------
\subsection{The cellular Dowker lemma}
\label{subsec:cellular}

We mimic some of the steps that led to the statement of Theorem~\ref{thm:dowker-revisited} in a more general setting.

%
Let $X$ be a CW-complex indexed by a set $A$, let $J$ be a set, and let $R \subseteq A \times J$ be a relation that is downwardly closed with respect to the CW-complex partial order on~$A$ and the trivial partial order on~$J$. Thus
\[
(\alpha,j) \in R
\;\; \text{and} \;\;
\alpha' \leq \alpha
\;\; \text{implies} \;\;
(\alpha',j) \in R
\]
for all $\alpha, \alpha' \in A$ and $j \in J$.
%

We have two types of slice:
%
\begin{align*}
    R_\alpha &= \{ j \in J \mid (\alpha, j) \in R \}
    \\
    R_j &= \{ \alpha \in A \mid (\alpha, j) \in R \}
\end{align*}
%
Since $R$ is downwardly closed, the function $\alpha \mapsto R_\alpha$ is order-reversing and each slice $R_j$ is a down-set that defines a subcomplex $X_{R_j}$ of~$X$.
%
We write
\[
X_R
=
\bigcup_{j \in J} X_{R_j}
=
\bigcup
\,
(
\overline{e}_\alpha 
\mid
\text{there exists $j \in J$ such that $(\alpha,j) \in R$}
)
\]
for the union of these subcomplexes. This is the subcomplex of~$X$ actively involved in~$R$.

The next step is to define a relation between $A$  and $\Delta J$:
\[
R_J
    =
    \{ (\alpha,\tau) \mid
    \{ \alpha \} \times \tau \subseteq R
    \}
    \leq A \times \Delta J
\]
Being a down-set, it defines a subcomplex of $X \times |\Delta J|$
\[
X \times_R |\Delta J|
=
\bigcup
\,(
\overline{e}_\alpha \times |\tau| 
\mid
(\alpha,\tau) \in R_J
)
\]
which we may call the `cellular Dowker relational product' of~$R$.
%
See Figure~\ref{fig:saucepan}.


\begin{proposition}
\label{prop:cellular-map}
The projection map $X \times |\Delta J| \to X$ restricts to a surjective map:
%
\[
\xymatrix{
X \times_R |\Delta J|
    \ar[r]
&
X_R
}
\]
%
\end{proposition}

\begin{proof}
    The image of the map is the union of the closed cells $\overline{e}_\alpha$ for which there exists a simplex~$\tau$ with $(\alpha,\tau) \in R_J$. This condition is equivalent to the existence of a single element~$j$ with $(\alpha,j) \in R$; this is satisfied precisely by the cells of $X_R$.
\end{proof}

\begin{lemma}[cellular Dowker lemma]
    \label{lem:cellular}
    Let $X$ be a CW-complex index by a set~$A$, let $J$ be a set, and let $R \subseteq A \times J$ be a downwardly closed relation, as above. Then the map
    \[
    \xymatrix{
    X \times_R |\Delta J|
        \ar[r]
    &
    X_R
    }
    \]
    of Proposition~\ref{prop:cellular-map} is a homotopy equivalence.
\end{lemma}

