\begin{proof}[Proof of Lemma~\ref{lem:cellular} when $X,J$ are finite]
%
In the finite case, each nonempty $R_\alpha$ is a simplex and we have
\[
X \times_R |\Delta J|
=
\bigcup_{\alpha \in A}
\overline{e}_\alpha \times |R_\alpha|
\]
because $(\alpha,\tau) \in R_J$ iff $\tau \subseteq R_\alpha$.
%
Let $x \in X_R$.
%
Then the fiber at~$x$ is
\[
\bigcup_{\alpha \in A_x}
\{x\} \times |R_\alpha|
\]
where $A_x = \{ \alpha \in A \mid x \in \overline{e}_\alpha \}$. Let $e_\beta$ be the carrier of~$x$. Then $x \in \overline{e}_\beta$ so the fiber contains $\{x\} \times |R_\beta|$.
%
From the definition of the partial order on~$A$, the condition $\alpha \in A_x$ implies $\alpha \geq \beta$, which in turn implies $R_\alpha \subseteq R_\beta$. Thus the fiber is equal to $\{x\} \times |R_\beta|$. 
%
This is nonempty by Proposition~\ref{prop:cellular-map}, so it is a closed geometric simplex; hence it is contractible and locally contractible.
%
The Smale mapping theorem~\ref{thm:smale-v2} for finite CW-complexes implies that the map is a homotopy equivalence.
\end{proof}

Readers interested primarily in the finite case may skip the following.

\begin{proof}[Proof of Lemma~\ref{lem:cellular} in full generality]
    We use Proposition~\ref{prop:finite-to-infinite} to extend the result from the finite case.
    %
    Our task is to show that the map
    \[
    \xymatrix{
        X \times_R |\Delta J|
        \ar[r]
        &
        X_R
    }
    \]
    is a homotopy equivalence.
    %
    For each pair $(Y,K)$ where $Y \subseteq X$ is a finite subcomplex and $K \subseteq J$ is a finite subset, we write $S = R \cap (Y \times K)$. We have a diagram
    \[
    \xymatrix{
    X \times_R |\Delta J|
        \ar[rr]
    &&
     X_R
    \\
    Y \times_S | \Delta K|
        \ar[rr]^-{\simeq}
        \ar[u]
    &&
    Y_S
        \ar[u]
    }
    \]
    where the vertical maps are inclusions of finite subcomplexes and the lower map is a homotopy equivalence by the finite case of Lemma~\ref{lem:cellular}.

    Suppose $F \subseteq X \times_R |\Delta J|$ and
    $G \subseteq X_R$
    are finite subcomplexes. The product cells that constitute $F$ involve finitely many cells of $X$, and finitely many simplices of $|\Delta J|$ therefore finitely many elements of $J$. Meanwhile $G$ contains finitely many cells of~$X$; for each cell~$\sigma$ we select $j$ such that $(\sigma,j) \in R$. Choose a finite subcomplex $Y \subseteq X$ and a finite set $K \subseteq J$ that include the finitely many cells of~$X$ and finitely many elements of~$J$ mentioned above. Then $Y \times_S |\Delta K|$ contains~$F$ while
    $Y_S$ contains~$G$.

    The conditions of Proposition~\ref{prop:finite-to-infinite} being satisfied, the map is a homotopy equivalence.    
\end{proof}

The `revisited' Dowker theorem is a special case of the cellular Dowker lemma.

\begin{proof}[Proof of Theorem~\ref{thm:dowker-revisited}]
%
Let $R, I, J, R_I$ be as in the statement of~\ref{thm:dowker-revisited}.
%
Apply the cellular Dowker lemma \ref{lem:cellular} to the CW-complex $|\Delta I|$ indexed by $\Delta I$, the set~$J$, and the relation $R_I \subseteq \Delta I \times J$.
%
The resulting homotopy equivalence is the upper arrow of a commutative diagram
\[
\xymatrix{
|\Delta I|_{R_I}
    \ar@{=}[d]
&&
|\Delta I| \times_{R_I} |\Delta J|
    \ar@{=}[d]
    \ar[ll]_{\simeq}
\\
|\dowker(R)/J|
&&
|\dowker(R)|
    \ar@{>>}[ll]_-{|\psi_2|}
}
\]
where the vertical sides are equalities.
%
Thus $|\psi_2|$ is a homotopy equivalence. Similarly $|\psi_1|$ is a homotopy equivalence.
\end{proof}

\begin{remark}
\label{rem:classical-functoriality}
Functoriality is immediate.
%
Let $R \subseteq I_1 \times I_2$ and $S \subseteq J_1 \times J_2$ be relations. Suppose $f = (f_1, f_2)$ where
%
$f_1 : I_1 \to J_1$,
and
$f_2 : I_2 \to J_2$
%
are functions with the property that $(i_1, i_2) \in R$ implies $(f_1(i_1), f_2(i_2)) \in S$. Then we have a diagram
\[
\xymatrix{
|\dowker(R)/I_2|
    \ar[d]_{|f_1|}
&&
|\dowker(R)|
    \ar@{>>}[ll]_{|\psi_2|}
    \ar@{>>}[rr]^{|\psi_1|}
    \ar[d]^{|f|}
&&
|\dowker(R)/I_1|
    \ar[d]^{|f_2|}
\\
|\dowker(S)/J_2|
&&
|\dowker(S)|
    \ar@{>>}[ll]_{|\psi_2|}
    \ar@{>>}[rr]^{|\psi_1|}
&&
|\dowker(S)/J_1|
}
\]
where the two squares commute by \eqref{eq:dowkerian-naturality}.
%
The four corner spaces are geometric simplicial complexes, while the two mediating spaces are geometric prod-complexes of order~2.
\end{remark}


%------------------------------------------------
\subsection{Multiway Dowker for prod-complexes}
\label{subsec:multiway-prod}

Here is the main object of our attention.

\begin{definition}[Dowker relational product]
%
Let $R \subseteq I_1 \times \dots \times I_m$ be a multiway relation. The multiway {Dowker relational product} of~$R$ is the prod-complex on $I_1, \dots, I_m$ defined:
\[
\dowker(R)
=
\{
(\sigma_1, \dots, \sigma_m)
\mid
\sigma_1 \times \dots \times \sigma_m \subseteq R
\}
\leq
\Delta I_1 \times \dots \times \Delta I_m
\]
It is the largest prod-complex on $I_1, \dots, I_m$ whose vertex set is~$R$.
\end{definition}

\begin{theorem}[multiway Dowker theorem]
    \label{thm:multiway-main-theorem}
    Let $R \subseteq I_1 \times \dots \times I_m$ be a multiway relation. Then the geometric Dowkerian quotient map
    $
    \xymatrix{
    |\psi_k| :
    |\dowker(R)| 
        \ar@{>>}[r]
    &
    |\dowker(R)/I_k|
    }
    $
    is a homotopy equivalence for all~$k$.
\end{theorem}

Thus we have a diagram of $m$ homotopy equivalences
    \begin{equation}
    \label{eq:hub-diagram}
    \xymatrix{
    &&& |\dowker(R)|
        \ar@{>>}[llld]_{|\psi_1|}
        \ar@{>>}[ld]^(0.4){|\psi_2|}
        \ar@{>>}[rrrd]^{|\psi_m|}
    \\
    |\dowker(R)/I_1|
    &&
    |\dowker(R)/I_2|
    &&
    \dots
    &&
   |\dowker(R)/I_m|
    }
    \end{equation}
through which the spaces $|\dowker(R)/I_k|$ are canonically homotopy equivalent. See Figures \ref{fig:rco-iterated-all}, \ref{fig:rco}.

