\begin{proof}
We may assume $k=m$.
%
Apply the cellular Dowker lemma \ref{lem:cellular} with:
%
\begin{align*}
    X &=
    |\Delta I_1| \times \dots \times |\Delta I_{m-1}|
    \\
    A &=
    \Delta_1 \times \dots \times \Delta_{m-1}
    \\
    J &= I_m
    \\
    \tilde{R} &=
    \{
    ((\sigma_1, \dots, \sigma_{m-1}), j)
    \mid
    \sigma_1 \times \dots \times \sigma_{m-1} \times \{j\}
    \subseteq R
    \}
\end{align*}
%
The resulting homotopy equivalence is the upper arrow in the commutative diagram
\[
\xymatrix{
\big( 
|\Delta I_1| \times \dots \times |\Delta I_{m-1}| 
\big)
\times_{\tilde{R}} |\Delta I_m|
    \ar[d]_{\cong}
    \ar[rr]^-{\simeq}
&&
\big( |\Delta I_1| \times \dots \times|\Delta I_{m-1}| \big)_{\tilde{R}}
    \ar@{=}[d]
\\
|\dowker(R)|
    \ar[rr]^{|\psi_m|}
&&
|\dowker(R)/I_m|
}
\]
where the right-hand side is an equality and the left-hand arrow is the homeomorphism defined by the following tautological formula:
\[
\xymatrix{
((x_1, \dots, x_{m-1}), x_m)
    \ar@{|->}[r]
&
(x_1, \dots, x_{m-1}, x_m)
}
\]
It follows that $|\psi_m|$ is a homotopy equivalence as claimed.
\end{proof}

\begin{remark}
    \label{rem:multiway-naturality}
    For functoriality, let $S \subseteq J_1 \times \dots \times J_m$ and suppose
    \[
    f = (f_1, \dots, f_m)
    \quad
    \text{where}
    \quad 
    \text{$f_k : I_k \to J_k$ for all $k$}
    \]
    satisfies the condition
    \[
    (i_1, \dots, i_m) \in R
    \; \Rightarrow \;
    (f_1(i_1), \dots, f_m(i_m)) \in S
    \]
    for all $i_1, \dots, i_m$.
    %
    Equation~\eqref{eq:dowkerian-naturality} provides commutative diagrams for all~$k$:
    \[
    \xymatrix{
    |\dowker(R)| 
        \ar@{>>}[rr]^{|\psi_k|}
        \ar[d]_-{|f|}
    &&
    |\dowker(R)/I_k|
        \ar[d]^-{|f_{/k}|}
    \\
    |\dowker(S)| 
        \ar@{>>}[rr]^{|\psi_k|}
    &&
    |\dowker(S)/J_k|    
    }
    \]
    %
    These squares can be combined, like pages in a book along the spine $|\dowker(R)| \stackrel{|f|}{\longrightarrow} |\dowker(S)|$, to confirm that the diagram \eqref{eq:hub-diagram} is functorial in $R$.
\end{remark}

%------------------------------------------------
\subsection{Iterated Dowkerian quotients}
\label{subsec:iterated}

The multiway Dowker theorem tells us that we can collapse any one of the factors of the Dowker relational product of a multiway relation without changing the homotopy type. %
%
What happens if we collapse two or more factors?

It is tempting to simply apply Theorem~\ref{thm:multiway-main-theorem} to each quotient, but we emphasize that this will not work: in most cases $\dowker(R)/I_k$ is not itself a multiway Dowker relational product, so its Dowkerian quotient maps need not be homotopy equivalences.
%
Figure~\ref{fig:hexagon} contains the simplest example: a square without its interior cannot be a Dowker relational product for any binary relation, and it is not homotopy equivalent to its Dowkerian quotients.

We introduce some notation.
%
Let $P$ be a prod-complex on $I_1, \dots, I_m$ and $k < \ell$. Defining
\[
P/(I_k, I_{\ell})
=
\{
(\sigma_1, \dots, \widehat{\sigma}_k, \dots, \widehat{\sigma}_{\ell}, \dots, \sigma_m)
\mid
(\sigma_1, \dots, \sigma_m) \in P
\}
\]
it follows that
\[
P/(I_k, I_\ell)
=
(P/I_k)/I_{\ell}
=
(P/I_{\ell})/I_{k}
\]
by iterating \eqref{eq:dowkerian-quotient}.
%
Higher-order iterated quotients are handled similarly.
%
See Figure~\ref{fig:rco-iterated} for a trio of examples.

\begin{figure}
\centering
\includegraphics[scale=1]{fig-iterated-quotients}
%     \[
%    \xymatrix @R=-10ex {
%    \includegraphics[scale=0.4]{rco_V.pdf}
%    &
%    \includegraphics[scale=0.4]{rco_E.pdf}
%    &
%    \includegraphics[scale=0.4]{rco_F.pdf}
%    \\
%    \dowker(R)/(E,F)   
%    &
%    \dowker(R)/(V,F)
%    &
%    \dowker(R)/(V,E)
%    }
%    \]
    \caption{Continuing from Figure~\ref{fig:rco}, the three iterated Dowkerian quotients are respectively the 1-skeleton of a cube, the 1-skeleton of a cuboctahedron, and the 1-skeleton of an octahedron.}
    \label{fig:rco-iterated}
\end{figure}

`Complementary' iterated quotients can be made independent of one another:

\begin{example}
    \label{ex:two-factor-collapse}
    Let $R_1 \subseteq I_1 \times J_1$ and $R_2 \subseteq I_2 \times J_2$ be binary relations. Combining them to obtain a 4-way relation
    \[
    R_1 \times R_2
    \subseteq
    I_1 \times J_1 \times I_2 \times J_2
    \]
    we get
    \[
    \dowker(R_1 \times R_2)/(I_2, J_2)
     =
    \dowker(R_1)
    \quad \text{and} \quad
    \dowker(R_1 \times R_2)/(I_1, J_1)    
    =
    \dowker(R_2).
    \qedhere\]
    %
    Since we can assign arbitrary simplicial complex homotopy types to these two spaces,\footnote{%
    Let $S$ be an arbitrary simplicial complex on~$I$, let $J = S$, and let
    $
    R = \{ 
    (i,\sigma) \in I \times J
    \mid
    %\text{\rm $i$ is a vertex of $\sigma$}
    i \in \sigma
    \}
    $.
    Then $\dowker(R)/J = S$ and hence $|\dowker(R)| \simeq |\dowker(R)/J| = |S|$.
    }
    %
    there can be no general relation between these iterated quotients.
\end{example}

We have more to say about iterated quotients of \emph{ternary} relations in section~\ref{sec:ternary}.

