\section{Simplexification}
\label{sec:simplexification}

We are ready to transfer our results to simplicial complexes.
%
In section~\ref{subsec:simplexification}, we describe a `simplexification' operation that converts a prod-complex to a simplicial complex, along with a `squashing map' that gives a homotopy equivalence from the simplexification to the prod-complex.
%
In section~\ref{subsec:simp-squash-fun-natural}, we discuss the functoriality of these constructions and their relationship with Dowkerian quotients. This sets up a clean treatment of the simplicial multiway Dowker theorem in section~\ref{subsec:multiway-simplicial}.

Before we begin, we comment on what simplexification \emph{isn't}.
%
One way to convert a prod-complex into a simplicial complex is to construct its barycentric subdivision;
%
its simplices are the finite nonempty chains in the prod-complex viewed as a poset. One advantage is that it is homeomorphic to the original prod-complex when geometrically realized. The main disadvantage is that it has many more low-dimensional cells, making it computationally more expensive. This is true even in the order~1 case where the prod-complex is a simplicial complex, which ideally should not need conversion.
%
In contrast, simplexification retains the same vertex set and leaves simplicial complexes unchanged.

%------------------------------------------------
\subsection{Simplexification and squashing}
\label{subsec:simplexification}

Let $P$ be a prod-complex on $I_1, \dots, I_m$. To each prod-simplex $\sigma = (\sigma_1, \dots, \sigma_m)$ we assign a simplex\footnote{%
We can think of $\simp(\sigma)$ as a geometrically `thickened' version of $\sigma$ with the same vertex set $\sigma_1 \times \dots \times \sigma_m$.
}
\[
\simp((\sigma_1, \dots, \sigma_m))
= 
\sigma_1 \times \dots \times \sigma_m
\; \in \; \Delta(I_1 \times \dots \times I_m).
\]
%

\begin{definition}[simplexification]  
\label{def:simplexification}
The simplexification of~$P$ is the simplicial complex on $I_1 \times \dots \times I_m$ defined as follows:
\[
\simp(P)
=
\bigcup_{\sigma \in P} \Delta(\simp(\sigma))
\]
Its simplices are characterized by the following property:
\[
\rho \in \simp(P)
\; \Leftrightarrow \;
\text{there exists $(\sigma_1, \dots, \sigma_m) \in P$ such that $\rho \subseteq \sigma_1 \times \dots \times \sigma_m$}
\]
\end{definition}

%
Note that $\simp(P) = P$ when $m=1$.
%
We must go to $m=2$ for the archetypal example:

\begin{example}[simplexification of a square]
    Recall that $\Delta^n = \Delta{\{0,\dots,n\}}$ denotes the standard n-simplex.
    %
    Then    
    \[
    Q = \Delta^{1} \times \Delta^{1}
    \]
    is a prod-complex on $\{0,1\}, \{0,1\}$ with geometric realization 
    \[
    |Q| = |\Delta^{1}| \times |\Delta^{1}|
    \]
    homeomorphic to a square;
    %
    whereas
    \[
    \simp(Q) = \Delta(\{0,1\} \times \{0,1\})
    \]
    is a complete simplex on four vertices, with geometric realization
    \[
    |\simp(Q)| \cong |\Delta^{3}|
    \]
    homeomorphic to a tetrahedron.
\end{example}

A tetrahedron viewed from a particular angle has the silhouette of a square.
%
A photograph of such a view implicitly `squashes' the tetrahedron onto the square $\boxtimes \to \square$.
%
Guided by this, we give a general definition of squashing map
\[
\xi_P :
\xymatrix{|\simp(P)| \ar[r] & |P|}
\]
in the following way.
%
Each projection $\pi_k : I_1 \times \dots \times I_m \to I_k$ induces a linear map
%
\[
\xymatrix{
\R_{I_1 \times \dots \times I_m}
    \ar[rrr]^-{\xi_k = \R_{\pi_k}}
&&&
\R_{I_k}
}
\]
We combine these into a single map $\xi = (\xi_1, \dots, \xi_m)$
%
and define $\xi_P$ to be the retriction of~$\xi$ indicated in the following diagram (the vertical arrows being the inclusion maps):
\[
\xymatrix{
\R_{I_1 \times \dots \times I_m}
    \ar[rrr]^-{\xi = (\xi_1, \dots, \xi_m)}
&&&
\R_{I_1} \times \dots \times \R_{I_m}
\\
|\simp(P)|
    \ar[u]
    \ar@{>>}[rrr]^-{\xi_P}
&&&
|P|
    \ar[u]
}
\]
%
Later (but not right now) we may write $\xi$ instead of $\xi_P$ to avoid cumbersome notation.

\begin{proposition}
    \label{prop:squash-well-defined}
    The squashing map $\xi_P$ is well-defined and surjective.
\end{proposition}

\begin{proposition}
    \label{prop:squash-sigma}
    We have $\xi(|\simp(\sigma|) = |\sigma|$ for all $\sigma \in \Delta I_1 \times \dots \times \Delta I_m$.
\end{proposition}

\begin{proof}
    From the formula
    \[
    \xymatrix{
    \basis((i_1, \dots, i_m))
        \ar@{|->}[r]^-{\xi}
    &
    (\basis(i_1), \dots, \basis(i_m))
    }
    \]
    it follows that $\xi$ carries the vertices of $|\simp(\sigma)|$ bijectively onto the vertices of $|\sigma|$. Convex hulls are preserved by linear maps, so $\xi$ carries $|\simp(\sigma)|$ onto $|\sigma|$.
\end{proof}

\begin{proof}[Proof of Proposition~\ref{prop:squash-well-defined}]
    Take the union of Proposition~\ref{prop:squash-sigma} over $\sigma \in P$.
\end{proof}

As a step towards understanding the fibers of $\xi_P$, we identify the preimage of each~$|\sigma|$.

\begin{proposition}
    \label{prop:squash-preimage}
    For each $\sigma \in P$ we have $\xi_P^{-1} |\sigma| = |\simp(\sigma)|$.
\end{proposition}

\begin{lemma}
    \label{lem:squash-carriers}
    Suppose $x \in |\Delta(I_1 \times \dots \times I_m)|$ has carrier $\rho$. Then $\xi(x) \in |\Delta I_1| \times \dots \times |\Delta I_m|$ has carrier $(\pi_1(\rho), \dots, \pi_m(\rho))$.
\end{lemma}

\begin{proof}
Equivalently, $\xi_k(x) \in |\Delta I_k|$ has carrier $\pi_k(\rho)$ for all~$k$. Let $i = (i_1, \dots, i_m)$ denote a typical element of $I_1 \times \dots \times I_n$.
Writing $x$ as a convex combination
\[
x =
\sum_{i \in \rho} \lambda_i \basis((i_1, \dots, i_m)) 
\]
with positive coefficients, we have
\[
\xi_k(x)
=
\sum_{i \in \rho} \lambda_i \basis(i_k)
%
=
\sum_{j \in I_k}
\mu_j \basis(j)
\quad
\text{where} \;
\mu_j = \sum\big( \lambda_i \mid i \in \rho,\, i_k = j \big)
\]
so the positive coefficients occur precisely at the vertices of $\pi_k(\rho)$.
\end{proof}


\begin{proof}[Proof of Proposition~\ref{prop:squash-preimage}]
%
By Proposition~\ref{prop:squash-sigma} it suffices to show that $\xi_P^{-1}|\sigma| \subseteq |\simp(\sigma)|$.
%
Suppose $x \in \xi_P^{-1}|\sigma|$. Let $\rho$ denote its carrier. By the lemma, $(\pi_1(\rho), \dots, \pi_m(\rho))$ is the carrier of $\xi(x)$. Since $\xi(x) \in |\sigma| = |\sigma_1| \times \dots \times |\sigma_m|$ it follows that $\pi_k(\rho) \subseteq \sigma_k$ for all~$k$, therefore $\rho \subseteq \sigma_1 \times \dots \times \sigma_m = \simp(\sigma)$. It follows that $x \in |\simp(\sigma)|$.
%
\end{proof}

\begin{theorem}
    \label{thm:squashing-HE}
    The squashing map $\xi_P : |\simp(P)| \to |P|$ is a homotopy equivalence.
\end{theorem}

\begin{proof}
    We consider the point fibers of $\xi_P$. Let $y \in |P|$ and take $\sigma \in P$ such that $y \in |\sigma|$. Proposition~\ref{prop:squash-preimage} implies:
    \[
    \xi_P^{-1}(y) = \xi^{-1}(y) \cap |\simp(\sigma)|
    \]
    This is convex because $\xi$ is linear and $|\simp(\sigma)|$ convex; and nonempty by Proposition~\ref{prop:squash-sigma}. Thus $\xi_P^{-1}(y)$ is contractible and locally contractible.
    %
    This proves the result when $I_1, \dots, I_m$ are finite, by the Smale mapping theorem~\ref{thm:smale-v2}.

    In general, $\xi_P$ restricts to homotopy equivalences
    \[
    \xymatrix{
    |\simp(P(J_1, \dots, J_m))|
        \ar[r]
    &
    |P(J_1, \dots, J_m)|
    }
    \]
    where
    \[
    P(J_1, \dots, J_m)
    =
    P \cap (\Delta J_1 \times \dots \times \Delta J_m)
    \]
    whenever we have finite subsets $J_1 \subseteq I_1$, \dots, $J_m \subseteq I_m$.
    %
    Let $F \subseteq |\simp(P)|$ and $G \subseteq |P|$ be finite subcomplexes. Each cell, and therefore $F$ and $G$ themselves, involves only finitely many elements of the sets $I_1, \dots, I_m$. Thus we have finite subsets $J_1, \dots, J_m$ such that
    \[
    F \subseteq |\simp(P(J_1, \dots, J_m))|
    \quad \text{and} \quad
    G \subseteq |P(J_1, \dots, J_m)|.
    \]
    The conditions of Proposition~\ref{prop:finite-to-infinite} are satisfied, so $\xi_P$ is a homotopy equivalence.
\end{proof}

%------------------------------------------------
\subsection{Functoriality and naturality}
\label{subsec:simp-squash-fun-natural}

The constructions of section~\ref{subsec:simplexification} are categorically well-behaved: simplexification is a functor and the squashing map is a natural transformation.

\begin{proposition}[simplexification is functorial]
\label{prop:simp-functorial}
Let $P$ and $Q$ be prod-complexes on $I_1, \dots, I_m$ and $J_1, \dots, J_m$ and let $f = (f_1, \dots, f_m)$
be a prod-map $P \to Q$. Then the product map
\[
\xymatrix{
I_1 \times \dots \times I_m
    \ar[rr]^-{f_1 \times \dots \times f_m}
&&
J_1 \times \dots \times J_m
}
\]
induces a simplicial map
$
\simp(f) : \simp(P) \to \simp(Q)
$.
This makes $\simp$ a functor from the category of prod-complexes and prod-maps (of fixed order~$m$) to the category of simplicial complexes and simplicial maps.
%
\end{proposition}

\begin{proof}
Each $\rho \in \simp(P)$ is a subset of some $\sigma_1 \times \dots \times \sigma_m$ where $(\sigma_1, \dots, \sigma_m) \in P$. Then
\[
(f_1 \times \dots \times f_m)
(\sigma_1 \times \dots \times \sigma_m)
=
f_1(\sigma_1) \times \dots \times f_m(\sigma_m)
\]
which is a simplex of $\simp(Q)$ because
\[
(f_1(\sigma_1), \dots, f_m(\sigma_m))
=
f(\sigma_1, \dots, \sigma_m)
\]
is a prod-simplex of~$Q$.
%
It is readily verified that $\simp(gf) = \simp(g) \circ \simp(f)$ and $\simp(1_P) = 1_{\simp(P)}$ so $\simp$ is a functor.
\end{proof}

\begin{proposition}
\label{prop:epi}
    The functor $\simp$ preserves epimorphisms: if a prod-map $f : P \to Q$ is surjective, then $\simp(f) : \simp(P) \to \simp(Q)$ is surjective.
\end{proposition}

\begin{proof}
    For $\tau \in Q$, take $\sigma \in P$ with $f(\sigma) = \tau$. Then $\simp(f)$ carries $\simp(\sigma)$ onto $\simp(\tau)$, so $\Delta(\simp(\tau))$ is contained in the image of $\simp(f)$. Now take the union over $\tau \in Q$.
\end{proof}

\begin{proposition}[squashing is natural]
    \label{prop:squash-natural}
    Let $P$ and $Q$ be prod-complexes on $I_1, \dots, I_m$ and $J_1, \dots, J_m$ and let
    $
    f = (f_1, \dots, f_m) : P \to Q
    $
    be a prod-map. Then the diagram of spaces
    %
    \begin{equation}
    \label{eq:squash-natural}
    \xymatrix{
    |\simp(P)|
        \ar[rr]^{\simp(f)}
        \ar[d]_{\xi_P}
    &&
    |\simp(Q)|
        \ar[d]^{\xi_Q}
    \\
    |P|
        \ar[rr]^{f}
    &&
    |Q|
    }         
    \end{equation}
    %
    commutes. In other words, the squashing map is a natural transformation.
\end{proposition}

\begin{proof}
The diagram is the restriction of a diagram of vector spaces:
\[
\xymatrix{
\R_{I_1 \times \dots \times I_m}
    \ar[d]_{\xi}
    \ar[rrr]^{\R_{f_1 \times \dots \times f_m}}
&&&
\R_{J_1 \times \dots \times J_m}
    \ar[d]^{\xi}
\\
\R_{I_1} \times \dots \times \R_{I_m}
    \ar[rrr]^{\R_{f_1} \times \dots \times \R_{f_m}}
&&&
\R_{J_1} \times \dots \times \R_{J_m}
}
\]
To see that this commutes, observe that a typical basis element $\basis((i_1,\dots,i_m))$ on the top left is mapped by either path to $(\basis(f_1(i_1)), \dots, \basis(f_m(i_m)))$ on the bottom right.
\end{proof}

\begin{corollary}[squashing respects Dowkerian quotients]
    \label{cor:squash-dowkerian}
    Let $P$ be a prod-complex on $I_1, \dots, I_m$ and let $\psi_k : P \to P/I_k$ denote its $k$-th Dowkerian quotient map.
    %
    Then $\simp(\psi_k)$ is surjective and the diagram of spaces
    \[
    \xymatrix{
    |\simp(P)|
        \ar[rr]^-{|\simp(\psi_k)|}
        \ar[d]_{\xi_P}
    &&
    |\simp(P/I_k)|
        \ar[d]^{\xi_{P/I_k}}
    \\
    |P|
        \ar[rr]^{|\psi_k|}
    &&
    |P/I_k|
    }
    \]
    commutes.
\end{corollary}

\begin{proof}
    Apply Propositions \ref{prop:epi} and~\ref{prop:squash-natural} to $\psi_k$ interpreted according to Remark~\ref{rem:dowkerian-*}.
\end{proof}

%------------------------------------------------
\subsection{Multiway Dowker for simplicial complexes}
\label{subsec:multiway-simplicial}

The simplicial version of our main theorem relates a `{cuboid complex}' to its associated {multiway Dowker complexes}. We define these terms now.
%
Let $R \subseteq I_1 \times \dots \times I_m$ be a multiway relation, and let
\[
    R_{i_k}
    =
    \{
    (i_1, \dots, \widehat{i_k}, \dots, i_m)
    \mid
    (i_1, \dots, i_k, \dots, i_m) \in R
    \}
    \subseteq
    I_1 \times \dots \times \widehat{I_k}
    \times \dots \times I_m
\]
%
denote the `slice' of~$R$ at $i_k \in I_k$.

\begin{definition}[cuboid complex]
\label{def:cuboid}
    The cuboid complex of~$R$ is the simplicial complex on $I_1 \times \dots \times I_m$ defined
    %
    \begin{align*}
    \cuboid(R)
    &=
    \{
    \rho
    \mid
    \rho_1 \times \dots \times \rho_m \subseteq R \}
    \\
    &=
    \{
    \rho
    \mid
    \text{$\exists\; \sigma_1, \dots, \sigma_m$ such that $\rho \subseteq \sigma_1 \times \dots \times \sigma_m \subseteq R$}
    \}
    \\
    &=
    \simp(\dowker(R))
    \end{align*}
    %
    where $\rho_k = \proj_{I_k}(\rho) \subseteq I_k$.
    %
    When $m=2$, this is the rectangle complex of Brun and Salbu~\cite{Brun_Salbu_2022}. We sometimes write $\rect(R)$ instead of $\cuboid(R)$ as a reminder that $m=2$.
\end{definition}

\begin{definition}[multiway Dowker complex]
\label{def:multiway-Dowker-complex}
    The $k$-th multiway Dowker complex of~$R$ is the simplicial complex on $I_1 \times \dots \times \widehat{I_k} \times \dots \times I_m$ defined as follows:
    \[
    \Dowker_{/I_k}(R)
    =
    \bigcup_{i_k \in I_k} \cuboid(R_{i_k})
    =
    \bigcup_{i_k \in I_k} \simp(\dowker(R_{i_k}))
    =
    \simp(\dowker(R)/I_k)
    \]
\end{definition}

\begin{definition}[simplicial Dowkerian quotient]
\label{def:simplicial-dowkerian-quotient}
    The $k$-th simplicial Dowkerian quotient map is the simplicial map $\varphi_k$ defined by the diagram
    %
    \begin{equation}
    \label{eq:cuboid-dowker-square}
        \xymatrix{
        \cuboid(R)
            \ar[rr]^-{\varphi_k}
            \ar@{=}[d]
        &&
        \Dowker_{/I_k}(R)
            \ar@{=}[d]
        \\
        \simp(\dowker(R))
            \ar[rr]^-{\simp(\psi_k)}
        &&
        \simp(\dowker(R)/I_k)    
        }
    \end{equation}
    %
    and induced by the projection map
    \[
    \xymatrix{
    I_1 \times \dots \times I_m
        \ar[rr]^-{\proj_{/I_k}}
    &&   
    I_1 \times \dots \times \widehat{I_k}
    \times \dots \times I_m
    }
    \]
    on vertices.
    %
    In fact $\Dowker_{/I_k}(R)$ is the smallest simplicial complex to which $\proj_{/I_k}$ defines a simplicial map from $\cuboid(R)$, since $\varphi_k = \simp(\psi_k)$ is surjective (Corollary~\ref{cor:squash-dowkerian}).
\end{definition}

\begin{remark}
    In the classical case of a relation $R \subseteq I \times J$, we have
    \[
    \Dowker_I(R) = \Dowker_{/J}(R) 
    \quad \text{and} \quad
    \Dowker_J(R) = \Dowker_{/I}(R)
    \]
    so we caution the reader to be careful with the subscripts.
    %
    In the case of a ternary relation between $I, J, K$ one may wish to write
    \[
    \Dowker_{JK} = \Dowker_{/I},
    \quad
    \Dowker_{IK} = \Dowker_{/J},
    \quad
    \Dowker_{IJ} = \Dowker_{/K}
    \]
    as we have done in the caption to Figure~\ref{fig:hexagon}.
\end{remark}

The simplicial version of our main theorem now follows quickly.

\begin{theorem}[simplicial multiway Dowker]
\label{thm:multiway-simplicial}
    Let $R \subseteq I_1 \times \dots \times I_k$ be a multiway relation. Then
    \[
    \xymatrix{
    |\cuboid(R)|
    \ar[r]^-{|\varphi_k|}
    &
    |\Dowker_{/I_k}(R)|    
    }
    \]
    is a homotopy equivalence for all~$k$.
\end{theorem}

\begin{proof}
    Corollary~\ref{cor:squash-dowkerian} applied to $P = \dowker(R)$ yields a commutative diagram of spaces
    \[
    \xymatrix{
    |\simp(\dowker(R))|
        \ar[rr]^-{|\simp(\psi_k)|}
        \ar[d]_{\xi}
    &&
    |\simp(\dowker(R)/I_k)|
        \ar[d]^{\xi}
    \\
    |\dowker(R)|
        \ar[rr]^{|\psi_k|}
    &&
    |\dowker(R)/I_k|
    }
    \]
    where the lower three sides are homotopy equivalences.
%    
    Thus $|\simp(\psi_k)| = |\varphi_k|$ is a homotopy equivalence.
\end{proof}

\begin{corollary}
    \label{cor:multiway-square}
    We have a commutative square of homotopy equivalences
    \[
    \xymatrix{
    |\cuboid(R)|
        \ar[rr]^-{|\varphi_k|}
        \ar[d]_{\xi}
    &&
    |\Dowker_{/I_k}(R)|
        \ar[d]^{\xi}
    \\
    |\dowker(R)|
        \ar[rr]^-{|\psi_k|}
    &&
    |\dowker(R)/I_k|
    }
    \]
    combining \eqref{eq:cuboid-dowker-square} with the diagram in the proof of Theorem~\ref{thm:multiway-simplicial}.
    \qed
\end{corollary}

\begin{proposition}[naturality of $\varphi_k$]
\label{prop:multiway-simplicial-functoriality}
Let $R \subseteq I_1 \times \dots \times I_m$ and $S \subseteq J_1 \times \dots \times J_m$. Let
\[
f = (f_1, \dots, f_m)
\quad
\text{where $f_k : I_k \to J_k$}
\]
satisfy $(f_1 \times \dots \times f_m)(R) \subseteq S$. Then we have a commutative diagram
\[
\xymatrix{
    \cuboid(R)
        \ar[rr]^-{\varphi_k}
        \ar[d]_{f_1 \times \dots \times f_m}
    &&
    \Dowker_{/I_k}(R)
        \ar[d]^{f_1 \times \dots \times \widehat{f_k} \times \dots \times f_m}
    \\
    \cuboid(S)
    \ar[rr]^-{\varphi_k}
    &&
    \Dowker_{/J_k}(S)
}
\]
of simplicial maps.
\end{proposition}

\begin{proof}
    The left vertical map is simplicial because of the condition on $f_1 \times \dots \times f_m$. The right vertical map is simplicial because it is the union of the simplicial maps
    \[
    \xymatrix{
    \cuboid(R_{i_k})
        \ar[rrr]^-{f_1 \times \dots \times \widehat{f_k} \times \dots \times f_m}
    &&&
    \cuboid(S_{f_k(i_k)})
    }
    \]
    over $i_k \in I_k$.
    The diagram commutes because the vertices of $\cuboid(R)$ are mapped
    \[
    \xymatrix{
    (i_1, \dots, i_m)
        \ar@{|->}[r]
    &
    (f_1(i_1), \dots, \widehat{f_k(i_k)}, \dots f_m(i_m))
    }
    \]
    by either path through the diagram.
\end{proof}

We combine Theorem \ref{thm:multiway-simplicial} and Proposition~\ref{prop:multiway-simplicial-functoriality} into a single statement.

\begin{theorem}
\label{thm:multiway-simplicial-final}
Let $R \subseteq I_1 \times \dots \times I_m$ be a multiway relation. Then we have a functorially defined diagram
\[
    \xymatrix@C=1.8pc{
    &&& \cuboid(R)
        \ar@{>>}[llld]_-{\varphi_1}
        \ar@{>>}[ld]^(0.4){\varphi_2}
        \ar@{>>}[rrrd]^-{\varphi_m}
    \\
    \Dowker_{/I_1}(R)
    &&
    \Dowker_{/I_2}(R)
    &&
    \dots
    &&
    \Dowker_{/I_m}(R)
    }
    \]
of simplicial maps whose geometric realizations are homotopy equivalences.
\qed
\end{theorem}

