Of the ten homotopy types, only seven are distinct:

\begin{proposition}
    \label{prop:seven-of-ten}
    Let $R \subseteq I \times J \times K$ be a ternary relation. Then:
    %
    \begin{alignat*}{2} 
    &\dowker(R)/(J,K) &&= \Dowker_I(R_{(JK)})
    \\
    &\dowker(R)/(I,K) &&= \Dowker_J(R_{(IK)})
    \\
    &\dowker(R)/(I,J) &&= \Dowker_K(R_{(IJ)})
    \end{alignat*}
\end{proposition}

\begin{proof}
    We prove the first of these (the other two being similar):
    %
    \begin{align*}
    \dowker(R)/(J,K)
    &=
    \{
    \sigma \in \Delta I
    \mid
    \text{there exist $j \in J$, $k \in K$}
    \text{\;such that\;}
    (\sigma, \{j\}, \{k\}) \in \dowker(R)
    \}
    \\
    &=
    \{
    \sigma \in \Delta I
    \mid
    \text{there exist $j \in J$, $k \in K$}
    \text{\;such that\;}
    \sigma \times \{j\} \times \{k\} \subseteq R
    \}
    \\
    &=
    \{
    \sigma \in \Delta I
    \mid
    \text{there exists $(j,k) \in J \times K$}
    \text{\;such that\;}
    \sigma \times \{(j,k)\} \subseteq R_{(JK)}
    \}
    \\
    &=
    \Dowker_I(R_{(JK)})
    \qedhere
    \end{align*}
\end{proof}

