\section{Introduction: symmetry-integrable equations and \\
  multipotentialisations}

Assume that the following is an $n$th-order symmetry-integrable evolution equation
\begin{gather}
  \label{gen-ee-n}
  E:=u_t-F(x,u,u_x,u_{xx},\ldots,u_{nx})=0.
\end{gather}  
Throughout this paper subscripts $t$ and $x$
    denote partial derivatives. That is, for the dependent variable $u=u(x,t)$, we have
\begin{gather*}
  u_t=\pde{u}{t},\quad u_x=\pde{u}{x},\quad u_{xx}=\pdd{u}{x},\quad  u_{xxx}=\frac{\p^3u}{\p x^3},\quad  u_{qx}=\frac{\p^q u}{\p x^q}
  \quad  \mbox{for}\quad q\geq 4.  
\end{gather*}
For the dependent variable $u_1=u_1(x,t)$ we use the notation $u_{1,x},\ u_{1,xx},\ u_{1,xxx},\  u_{1,qx}$ for $q\geq 4$.
By a symmetry-integrable evolution equation of the form (\ref{gen-ee-n}), we mean an equation that admits a recursion operator $R_u$
that generates an infinite set of commuting
Lie-B\"acklund symmetries
\begin{gather}
    \label{gen-eta_j}
Z_j=\eta_j\pde{\ }{u},\qquad j=1,2,\ldots
\end{gather}
with
\begin{gather}
    \label{gen-Z_j}
\eta_j=R^j_u\,u_t\quad \mbox{or}\quad \eta_k=R_u^k\,u_x\qquad j=1,2,\ldots,\quad k=1,2,\ldots\ .
\end{gather}
Here $\eta_j$ satisfies the symmetry condition
\begin{gather}
  \left.\vphantom{\frac{DA}{DB}}
  L_E[u]\eta_j\right|_{E=0}=0
\end{gather}
for every $j$ for (\ref{gen-ee-n}), where $L_E[u]$ is the linear operator
\begin{gather}
  L_E[u]=\pde{E}{u}+\pde{E}{u_t}D_t+\pde{E}{u_x}D_x+\pde{E}{u_{xx}}D^2_x+\cdots +
  \pde{E}{u_{nx}}D^n_x.
\end{gather}
Here and below, $D_x$ denotes the total $x$-derivative and $D_t$ the total
$t$-derivative. For an extensive list of symmetry-integrable evolution equations we refer to \cite{M}.
%%%
We use integro-differential recursion operators of the form
\begin{gather}
\label{RO-GEN-into}
R_u=\sum_{j=0}^mG_jD_x^j+\sum_{i=1}^3I_i(u_x,u_t)D_x^{-1}\circ \Lambda_i,
\end{gather}
where $G_j$ are functions of $u$ and $x$-derivatives of $u$,
$D_x^{-1}$ is the integral
operator and $\Lambda_i$ are integrating factors of the
equation. 
%%%
The condition for a recursion operator $R_u$ of (\ref{gen-ee-n}) is
\begin{gather}
  \label{Gen-Cond-R}
  \left[L_E[u],\ R_u\right] =D_t R_u,
\end{gather}  
where $[\ ,\ ]$ is the standard Lie bracket $[A,B]:=AB-BA$.
A hierarchy of symmetry-integrable equations then follow for (\ref{gen-ee-n}), namely the hierarchy of evolution equations 
\begin{gather}
  u_{t_j}= R^j_u\,F,\qquad u_{\tau_j}=R^j_u u_x    \qquad j=1,2,\ldots
\end{gather}  
where every equation in the hierarchy admits the infinite set of commuting symmetries (\ref{gen-eta_j}) generated by $R_u^j$.
%\end{document}
Assume that (\ref{gen-ee-n}) admits a conservation law with conserved current $\Phi^t$ and flux $\Phi^x$. That is
\begin{gather}
  \left.\vphantom{\frac{DA}{DB}}
  \left(D_t\Phi^t+D_x\Phi^x\right)\right|_{u_t=F}=0.
\end{gather}
Then $\Phi^t$ must satisfy the relation (see, for example, \cite{Fokas-Fuchssteiner} and \cite{Anco-Bluman})
\begin{gather}
  \label{Phi-t}
  \Lambda=\hat E[u]\,\Phi^t,
\end{gather}
where $\Lambda$ is the corresponding integrating factor (or multiplier) of (\ref{gen-ee-n}) and
$\hat E[u]$ is the Euler operator
\begin{gather}
  \hat E[u]=\pde{\ }{u}-D_x\circ \pde{\ }{u_x}-D_t\circ \pde{\ }{u_t}+D_x^2\circ \pde{\ }{u_{xx}}
  -D_{x}^3\circ \pde{\ }{u_{xxx}}+\cdots\ .
  %\nn\\[0.3cm]
  %\qquad
%  +(-1)^{k}D_x^k\circ \pde{\ }{u_{kx}}.  
\end{gather}
The necessary and sufficient condition on $\Lambda$ is
\begin{gather}
    \hat E[u]\left(\Lambda E\right)=0,
\end{gather}  
or, equivalently, the conditions
\begin{gather}
  \label{alt-cond-Lambda}
  \left.\vphantom{\frac{DA}{DB}}
  L_E^*\Lambda\right|_{E=0}=0\quad
  \mbox{and}\quad
  L_\Lambda E=L^*_\Lambda E,
\end{gather}
where $L^*_E$ is the adjoint operator of $L_E$, namely
\begin{gather}
  \label{L-star}
  L^*_E=\pde{E}{u}-D_x\circ \pde{E}{u_x}-D_t\circ \pde{E}{u_t}
  +D_x^2\circ \pde{E}{u_{xx}}-D_{x}^3\circ \pde{E}{u_{xxx}}+\cdots \nn\\[0.3cm]
  \qquad
  +(-1)^{k}D_x^k\circ \pde{E}{u_{kx}}.  
\end{gather}  
Note that the first condition in (\ref{alt-cond-Lambda}) is the necessary and sufficient condition for an adjoint symmetry $\Lambda$ for
(\ref{gen-ee-n}) (see \cite{Anco-Bluman} for details on adjoint symmetries).

Following the description above, we can calculate
a conservation law of (\ref{gen-ee-n}) by first calculating $\Lambda$ by conditions (\ref{alt-cond-Lambda}) and then
$\Phi^t$ by condition (\ref{Phi-t}). The flux then follows from
\begin{gather}
\label{Phi-x-gen}
  \Phi^x=
\left.\vphantom{\frac{DA}{DB}}
-D_x^{-1}\left(
\vphantom{\frac{DA}{DB}}
D_t\Phi^t\right|_{E=0}\right).
\end{gather}
Using integration by parts, (\ref{Phi-x-gen}) results in the following useful formula for $\Phi^x$:

\begin{proposition}
  \label{Prop-Phi-x-formula}
  Assume that $u_t=F(x,u,u_x,\ldots,u_{nx})$ admits an integrating factor $\Lambda$ and a conserved current
  $\Phi^t=\Phi^t(x,y,u_x,\ldots,u_{mx})$, such that $\Lambda=\hat E[u] \Phi^t$. Then the corresponding flux $\Phi^x$ is given by
\begin{gather}
\label{formula-Phi-x}
  \Phi^x=-D_x^{-1}\left(\Lambda F\right)
  +\sum_{k=1}^m\sum_{j=0}^{m-k} (-1)^k \left(D_x^j F\right)\,D_x^{k-1}\left(
  \pde{\Phi^t}{u_{(j+k)x}}\right).
\end{gather}
\end{proposition}  

\strut\hfill

\noindent
As an example for Proposition \ref{Prop-Phi-x-formula}, consider $\Phi^t=\Phi^t(x,u,u_x,u_{xx},u_{xxx})$.
Then (\ref{Phi-x-gen}) takes the form
\begin{gather}
  \Phi^x=-D_x^{-1}\left(\Lambda F\right)
  -\pde{\Phi^t}{u_x}\,F
  -\pde{\Phi^t}{u_{xx}}\,D_xF
  -\pde{\Phi^t}{u_{xxx}}\, D_x^2 F\\[0.3cm]
  \qquad
  +FD_x\left(\pde{\Phi^t}{u_{xx}}\right)
  -FD_x^2\left(\pde{\Phi^t}{u_{xxx}}\right)
  +(D_x F)\,D_x\left(\pde{\Phi^t}{u_{xxx}}\right).
\end{gather}


\noindent
    {\bf Example:} Consider the Schwarzian Korteweg-de Vries equation (SKdV) 
\begin{gather}
  \label{SKdV}
u_t=u_{xxx}-\frac{3}{2}\frac{u_{xx}^2}{u_x}
\equiv u_x\{u,x\},
\end{gather}
where $\{u,x\}$ it the Schwarzian derivative defined by
\begin{gather*}
  \{u,x\}:=\frac{u_{xxx}}{u_x}-\frac{3}{2}\left(\frac{u_{xx}}{u_x}\right)^2
  \equiv \left(\frac{u_{xx}}{u_x}\right)_x-\frac{1}{2}\left(\frac{u_{xx}}{u_x}\right)^2.
\end{gather*}
%Ref: John Weiss in 1982 (Painlev\'e Property). \n\n
(See \cite{Weiss-1983} where (\ref{SKdV}) was introduced as well as  \cite{Steeb-Euler} and \cite{Conte-1999}
    for more details on its applications in view of the Painlev\'e Test).
Using condition (\ref{alt-cond-Lambda}) we calculate all integrating factors for (\ref{SKdV}) up to order 4 and obtain 
\begin{gather*}
  \Lambda_1=-\frac{2u_{xx}}{u_x^3},\quad \Lambda_2=-\frac{2u^2u_{xx}}{u_x^3}+\frac{4u}{u_x},\quad
  \Lambda_3=\alpha\left(\frac{u_{4x}}{u_x^2}-\frac{4u_{xx}u_{xxx}}{u_x^3}+\frac{3u_{xx}^3}{u_x^4}\right)\\[0.3cm]
  \Lambda_4=\alpha\left(\frac{uu_{xx}}{u_x^3}-\frac{1}{u_x}\right),
\end{gather*}
where $\alpha$ is an arbitrary non-zero constant. Then, using condition (\ref{Phi-t}) and (\ref{formula-Phi-x}), the 
corresponding conserved current and flux for each integrating factor take the following form: 
\begin{gather*}
\Phi_1^t=\frac{1}{u_x},\qquad \Phi_2^t=\frac{u^2}{u_x},\qquad
\Phi_3^t=\frac{\alpha}{2}\left(\frac{u_{xx}}{u_x}\right)^2,\qquad
\Phi_4^t=-\frac{\alpha}{2}\frac{u}{u_x}\\[0.3cm]
\Phi_1^x=\frac{u_{xxx}}{u_x^2}-\frac{1}{2}\frac{u_{xx}^2}{u_x^3},\qquad
\Phi_2^x=\frac{u^2u_{xxx}}{u_x^2}-\frac{1}{2}\frac{u^2u_{xx}^2}{u_x^3}
-4\frac{uu_{xx}}{u_x}+4u_x\\[0.3cm]
\Phi_3^x=\alpha\left(
-\frac{u_{xx}u_{4x}}{u_x^2}
+\frac{1}{2}\frac{u_{xxx}^2}{u_x^2}+\frac{2u_{xx}^2u_{xxx}}{u_x^3}
-\frac{9}{8}\frac{u_{xx}^4}{u_x^4}\right)\\[0.3cm]
\Phi_4^x=
\alpha\left(-\frac{1}{2}\frac{uu_{xxx}}{u_x^2}+\frac{1}{4}\frac{uu_{xx}^2}{u_x^3}+\frac{u_{xx}}{u_x}\right).
\end{gather*}
By the recursion operator Ansatz (\ref{RO-GEN-into}) with $m=2$, condition (\ref{Gen-Cond-R}) results in the following recursion operator for
(\ref{SKdV}) (\cite{Sanders-Wang-2001},  \cite{EE-R-2007}):
%Furthermore, $\Lambda_3$ is needed for the recursion operator of (\ref{SKdV}), which takes the following form:
\begin{gather*}
  R_u=D_x^2-\left(\frac{2u_{xx}}{u_x}\right)D_x+\frac{u_{xxx}}{u_x}-\left(\frac{u_{xx}}{u_x}\right)^2
      -u_xD_x^{-1}\circ \textcolor{black}{\Lambda_3},
\end{gather*}
where $\Lambda_3$ is the integrating factor given above with $\alpha=1$. Now
\begin{gather*}
  \eta_1=R_u \,u_x=u_{xxx}-\frac{3}{2}\frac{u_{xx}^2}{u_x}\\[0.3cm]
  \eta_2=R^2_u\,u_x=u_{5x}-\frac{5u_{xx}u_{4x}}{u_x}-\frac{5}{2}\frac{u_{xxx}^2}{u_x}
  +\frac{25}{2}\frac{u_{xx}^2u_{xxx}}{u_x^2}
  -\frac{45}{8}\frac{u_{xx}^4}{u_x^3},
\end{gather*}
which are two commuting symmetries $Z_1=\eta_1\pde{\ }{u}$ and  $Z_2=\eta_2\pde{\ }{u}$ of (\ref{SKdV}), i.e.
$[Z_1,\ Z_2]=0$. This provides the first two
members of the symmetry-integrable Schwarzian Korteweg-de Vries hierarchy (in terms of the ``time''
variables $t_1$ and $t_2$), namely
\begin{subequations}
\begin{gather*}
  u_{t_1}=u_{xxx}-\frac{3}{2}\frac{u_{xx}^2}{u_x},\ \ 
  u_{t_2}=u_{5x}-\frac{5u_{xx}u_{4x}}{u_x}-\frac{5}{2}\frac{u_{xxx}^2}{u_x}
  +\frac{25}{2}\frac{u_{xx}^2u_{xxx}}{u_x^2}
  -\frac{45}{8}\frac{u_{xx}^4}{u_x^3}.
\end{gather*}
\end{subequations}

\strut\hfill

In the current paper we are interested in the potentialisation of equations. To potentialise equation (\ref{gen-ee-n}) we need to introduce a new variable
$v(x,t)$ such that (\ref{gen-ee-n}) maps to a new equation,
\begin{gather}
  \label{1st-pot-G}
v_t=G(x,v_x,v_{xx},\ldots,v_{\textcolor{black}{n}x}),
\end{gather}
called the potential equation of (\ref{gen-ee-n}). This may be achieved by using an appropriate
conserved current $\Phi_1^t$ and flux $\Phi_1^x$ of (\ref{gen-ee-n}), whereby we let
\begin{gather*}
v_x=\Phi_1^t(x,t,u,u_x,\ldots, u_{qx}),\qquad 
v_t=-\Phi_1^x(x,t,u,u_x,\ldots, u_{qx}).
%\left.\vphantom{\frac{DA}{DB}}
%D_t\Phi^t+D_x\Phi^x\right|_{E=0}=0
\end{gather*}
This is illustrated in Diagram 1.
