D_x^{-1}\circ u\notag\\[0.3cm]
%\label{recursion_IS}
\qquad -2ue^{-2\int u^2\,dx}D_x^{-1}\circ
\textcolor{black}{
\left[
\left(u_{xx}+2u^2u_x\right)e^{2\int u^2\,dx}
+2u\int \left(e^{2\int u^2\,dx}\,u_x^2\right)\,dx\right]
}
\nonumber
\end{gather*}
