and back again to the 2nd potential Kupershmidt equation; in both cases this is achieved by two different potentialisations as indicated
in Diagram 7.
This leads to

\strut\hfill

\begin{proposition}
  \label{Prop-2nd-pot-invariance}
   \cite{ME-NE-Triangular-2012}
  The 2nd potential Kupershmidt equation (\ref{2nd-pot-kuper}), i.e.
\begin{gather*}
  u_t=u_{5x}-5\frac{u_{xx}u_{4x}}{u_x}-\frac{15}{4}\frac{u_{xxx}^2}{u_x}
  +\frac{65}{4}\frac{u_{xx}^2u_{xxx}}{u_x^2}
  -\frac{135}{16}\frac{u_{xx}^4}{u_x^3},
\end{gather*}  
  is invariant under the transformation $u(x,t)\mapsto \bar u(x,t)$,
  where
  \begin{subequations}
  \begin{gather}
\label{relation-u_1-u_3}
   \bar u=u+c_1\quad\mbox{or}\\[0.3cm]
\label{relation-u2-u3}
   \bar u=-\frac{1}{u}+c_2\quad{or}\\[0.3cm]
\label{relation-u1-u4}
\bar u=\int u_x\left[
\vphantom{\frac{DA}{DB}}
\int u_x^{-1/2}\,dx+f_1(t)\right]^4\,dx+f_2(t).
  \end{gather}
  \end{subequations}
  Here $c_1$ and $c_2$ are arbitrary constants, whereas $f_1$ and $f_2$ have to be determined such that $\bar u$ of (\ref{relation-u1-u4}) satisfies
  (\ref{2nd-pot-kuper}).
\end{proposition}




\noindent
{\bf Proof}: We refer to Diagram 7. Using relations between $u_1$ and $u_3$, we obtain (\ref{relation-u_1-u_3}) with $\bar u=u_3$ and $u=u_1$.
Using relations between $u_2$ and $u_3$, we obtain (\ref{relation-u2-u3}) by eliminating $v_x$ with $\bar u=u_3$
and $u=u_2$. Similarly,
by the given relations between $u_1$ and $u_4$ we eliminate $v$ by differentiation to obtain
\begin{gather}
\label{relation-Bernoulli}
   \bar u_{xx}=\left(\frac{u_{xx}}{u_{x}}\right)\bar u_{x}+4\left(u_{x}^{-1/4}\right)\bar u_{x}^{3/4}.  
  \end{gather}
where $\bar u=u_4$ and $u=u_1$. Equation (\ref{relation-u1-u4}) is a first-order Bernoulli equation of the form
\begin{gather*}
  Y_x=\left(\frac{u_{xx}}{u_{x}}\right)Y+4\left(u_{x}^{-1/4}\right)Y^{3/4},
\end{gather*}
where $Y(x,t)=\bar u_x(x,t)$, which can easily be linearised by the substitution $Z(x,t)=Y^{1/4}(x,t)$. The general solution
is (\ref{relation-u1-u4}).
Note that the condition that results when we make use of the relations between $u_2$ and $u_4$ is the same as the condition which results if we insert
(\ref{relation-u2-u3}) in (\ref{relation-u1-u4}). \qquad $\Box$

\strut\hfill

\noindent
    {\bf Example:} We start with the seed solution
    \begin{gather*}
      u_{1}=-\frac{1}{x}
     \end{gather*} 
 of (\ref{2nd-pot-kuper}). Applying now (\ref{relation-u1-u4}) we obtain
    \begin{gather*}
      \bar u_{1}=
      \frac{1}{112}x^7+\frac{1}{10}f_1(t)x^5+\frac{1}{2}f_1^2(t)x^3+2f_1^3(t)x-f_1^4(t)\left(\frac{1}{x}\right)+f_2(t)
\end{gather*} 
    and insering this $\bar u_{1}$ into (\ref{2nd-pot-kuper}) we obtain
    \begin{gather*}
      f_1(t)=c_{01},\quad f_2(t)=72 c_{01} \,t+c_{02},
     \end{gather*} 
    where $c_{01}$ and $c_{02}$ are arbitrary constants. We could then continue by applying, for example, (\ref{relation-u2-u3}), i.e.
    \begin{gather*}
      \bar u_{2}=-\frac{1}{\bar u_{1}}+c_{03}
    \end{gather*}
    and use the solution $\bar u_{2}$ in (\ref{relation-u1-u4}) to obtain yet another solution $\bar u_{3}$, etc.

