\section{Invariance of the Kupershmidt equation and its chain of potentialisations}

Using Proposition \ref{Prop-2nd-pot-invariance} and Proposition \ref{Prop-3rd-pot-invariance} we obtain nonlocal invariance relations for
all the equations depicted in Diagram 6.

\strut\hfill

\begin{proposition}
\label{Prop-Invariance-Diagram}
\strut\hfill

\begin{itemize}

\item[a)]
  The Kupershmidt equation (\ref{kupershmidt}) is invariant under $K(x,t)\mapsto \bar K(x,t)$, in which
\begin{gather}
\label{Prop-a}
  \bar K=K+2\left[\ln(v)\right]_x\quad \mbox{and}\quad  K=-\left[\ln(v_x)\right]_x,
\end{gather}
where $v$ is a solution of (\ref{3rd-pot-kuper}) such that $v_x\neq 0$, which can be iterated by the relations in Proposition \ref{Prop-3rd-pot-invariance}.

\item[b)]
  The 1st potential Kupershmidt equation (\ref{1st-a-pot-kuper}) is invariant under $U(x,t)\mapsto \bar U(x,t)$, in which
  \begin{gather}
    \label{Prop-b}
  \bar U=U+2\ln(v)\quad \mbox{and}\quad U=\ln\sqrt{2}-\ln(v_x),
\end{gather}
where $v$ is any solution of (\ref{3rd-pot-kuper}) such that $v_x\neq 0$, which can be iterated by the relations in Proposition \ref{Prop-3rd-pot-invariance}.

\item[c)]
The 2nd potential Kupershmidt equation (\ref{2nd-pot-kuper}) is invariant under $u(x,t)\mapsto \bar u(x,t)$, in which  
\begin{gather}
  \label{Prop-c}
   \bar u=v^4u-4\int uv^3v_x\,dx+f_2(t)
   \quad \mbox{and}\quad
   u=\int \left(\frac{1}{v_x^{2}}\right)\,dx+f_1(t),
\end{gather} 
where $f_1$ and $f_2$ must be determined such that $u$ and $\bar u$ satisfy (\ref{2nd-pot-kuper}).
Here $v$ is any solution of (\ref{3rd-pot-kuper}) such that $v_x\neq 0$, which can be iterated by the relations in Proposition \ref{Prop-3rd-pot-invariance}.


\item[d)]
The 3rd potential Kupershmidt equation (\ref{3rd-pot-kuper}) is invariant under $v(x,t)\mapsto \bar v(x,t)$, in which  
\begin{gather}
  \label{Prop-d}
   \bar v=uv-\int \left(\frac{v}{v_x^{2}}\right)\,dx +f_2(t)
   \quad \mbox{and}\quad
   v=\int u_x^{-1/2}\,dx+f_1(t),
\end{gather} 
where $f_1$ must be determined such that $v$ satisfies (\ref{3rd-pot-kuper}) and $f_2$ such that $\bar v$ satisfies (\ref{3rd-pot-kuper}).
Here $u$ is any solution of (\ref{2nd-pot-kuper}) such that $u_x\neq 0$, which can be iterated by the relations in Proposition \ref{Prop-2nd-pot-invariance}.



\item[e)]
The 4th potential Kupershmidt equation (\ref{4th-pot-kuper}) is invariant under $w(x,t)\mapsto \bar w(x,t)$, in which  
\begin{subequations}
  \begin{gather}
    \label{Prop-e-1}
    \bar w=\left(\frac{\bar v}{uv}\right)^2 w
    -\int w\left[\left(\frac{\bar v}{uv}\right)^2\right]_x\,dx + f_4(t)\\[0.3cm]
    \label{Prop-e-2}
    w=-\frac{\beta}{6}uv^2+\frac{\beta}{3}\int uvv_x\,dx+f_3(t)\\[0.3cm]
    \label{Prop-e-3}
    u=\int \left(\frac{1}{v_x^{2}}\right)\,dx+f_1(t)\\[0.3cm]
    \label{Prop-e-4}
    \mbox{and}\quad
    %\bar v=v\int \left(\frac{1}{v_x^{2}}\right)\,dx -\int \left(\frac{v}{v_x^{2}}\right)\,dx +f_1(t),
    \bar v=\int uu_x^{-1/2}\,dx+f_2(t)
\end{gather}
\end{subequations}
where $f_1$ must be determined such that $u$ satisfies (\ref{2nd-pot-kuper}), $f_2$ such that $\bar v$ satisfies (\ref{3rd-pot-kuper}),
$f_3$ such that
$w$ satisfies (\ref{4th-pot-kuper}), and $f_4$ such that $\bar w$ satisfies (\ref{4th-pot-kuper}). Here $v$ is any solution of (\ref{3rd-pot-kuper})
such that $v_x\neq 0$,
which can be iterated by the relations in Proposition \ref{Prop-3rd-pot-invariance}.

\item[f)]  
The 5th potential Kupershmidt equation (\ref{5th-pot-kuper}) is invariant under $q(x,t)\mapsto \bar q(x,t)$, in which  
\begin{subequations}
  \begin{gather}
    \label{Prop-f-1}
\bar q=q\left(\frac{uv}{\bar v}\right)-\int q \left(\frac{uv}{\bar v}\right)_x\,dx+f_3(t),\quad
q=-\frac{4}{3}\left(\frac{-6}{\beta}\right)^{1/2}\ln (v)\\[0,3cm]
\label{Prop-f-2}
%\bar v=\int uv_x\,dx+f_2(t),\quad \mbox{and}\quad u=\int \left(\frac{1}{v_{x}^{2}}\right)\,dx+f_1(t),
 u=\int \left(\frac{1}{v_x^{2}}\right)\,dx+f_1(t)\quad \mbox{and}\quad
    \bar v=\int uu_x^{-1/2}\,dx+f_2(t)
  \end{gather}
\end{subequations}
where $f_1$ must be determined such that $u$ satisfies (\ref{2nd-pot-kuper}), $f_2$ such that $\bar v$ satisfies (\ref{3rd-pot-kuper}), and $f_3$ such that
$q$ satisfies (\ref{5th-pot-kuper}). Here $\beta<0$ and $v$ is any solution of (\ref{3rd-pot-kuper}) such that $v_x\neq 0$, which
can be iterated by the relations in
Proposition \ref{Prop-3rd-pot-invariance}.

\item[g)] \cite{E-E-Reyes}  
The Sawada-Kotera equation (\ref{Sawada-Kotera})  is invariant under $S(x,t)\mapsto \bar S(x,t)$, in which  
\begin{gather}
  \label{Prop-g}
   \bar S=S+6\left[\ln(v)\right]_{xx}
   \quad \mbox{and}\quad
   S=-\frac{v_{xxx}}{v_x},
\end{gather}
where $v$ is any solution of (\ref{3rd-pot-kuper}) such that $v_x\neq 0$, which can be iterated by the relations in Proposition \ref{Prop-3rd-pot-invariance}.

\item[h)]
    The $k$-equation (\ref{private-Kuper}) is invariant under $k(x,t)\mapsto \bar k(x,t)$, in which 
    \begin{subequations}
      \begin{gather}
        \label{Prop-h-1}
  \bar k=k+\frac{3}{2}\left[\ln(u)\right]_{xx}\\[0.3cm]
\label{Prop-h-2}
  \mbox{and}\quad k=\frac{3}{2}\left[\ln(u)\right]_{xx}
  -\frac{1}{2}\left[\ln(u_x)\right]_{xx}
  -\frac{1}{8}\left[\ln(u_x)\right]_x^2,
\end{gather}
    \end{subequations}
where $u$ is any solution of (\ref{2nd-pot-kuper}) such that $u_x\neq 0$, which can be iterated by the relations in Proposition \ref{Prop-2nd-pot-invariance}.

  \end{itemize}

\end{proposition}

