\noindent
    {\bf Proof:} We start with the statement (\ref{Prop-b}) for the 1st potential Kupershmidt equation (\ref{1st-a-pot-kuper}). Following the
    potentialisations as depicted in
Diagram 6, we consider
\begin{gather*}
  \label{Prop-Proof-u1x-u2x}
  u_{1,x}=\frac{1}{2}e^{2U_1},\qquad  u_{2,x}=\frac{1}{2}e^{2U_2},
\end{gather*}
with
\begin{gather*}
  \label{Prop-Proof-u1-u2}
  u_{1,x}=v_x^{-2},\qquad u_{2,x}=v^4v_x^{-2}.
\end{gather*}
This leads to
\begin{gather*}
  \label{Prop-Proof-U1-U2}
  U_2=\ln\left(\sqrt{2}v^2v_x^{-1}\right),\qquad U_1=\ln\left(\sqrt{2}v_x^{-1}\right),
\end{gather*}
so that
\begin{gather*}
  U_2=U_1+\ln(v^2),\qquad   U_1=\ln\sqrt{2}-\ln(v_x).
\end{gather*}  
With $U_2\equiv \bar U$ and $U_1\equiv U$ we obtain (\ref{Prop-b}). Since $U_x=K$, we differentiate (\ref{Prop-b}) to obtain (\ref{Prop-a}).
%By (\ref{Prop-Proof-u1-u2}) we have
Also
\begin{gather*}
  u_{2,x}=u_{1,x}v^4,\qquad u_{1,x}=v_x^{-2}
\end{gather*}
which becomes (\ref{Prop-c}) after integration. Integrating the relations
\begin{gather*}
  v_{1,x}=u_x^{-1/2},\qquad v_{3,x}=uu_x^{-1/2}
\end{gather*}
we obtain
\begin{gather*}
  v_1=\int u_x^{-1/2}\,dx+f_1(t)\\[0.3cm]
  v_3=\int u v_{1,x}\,dx+f_2(t)=\int uv_1\,dx-\int v v_x^{-2}\,dx+f_2(t).
\end{gather*}
With $v_3\equiv \bar v$ and $v_1\equiv v$ we obtain (\ref{Prop-d}).
For the 4th potential Kupershmidt equation (\ref{4th-pot-kuper}) we consider
\begin{gather*}
  w_{1,x}=-\frac{\beta}{6}v_1^2v_{1,x}^{-2},\qquad
  w_{2,x}=-\frac{\beta}{6}v_3^2v_{3,x}^{-2}\\[0.3cm]
  v_{1,x}=u_x^{-1/2},\qquad v_{3,x}=uu_x^{-1/2},
\end{gather*}  
which leads to
\begin{gather*}
  w_{2,x}=w_{1,x}v_1^{-2}v_3^2u^{-2},\qquad
  w_{1,x}=-\frac{\beta}{6}v_1^2u_x. 
\end{gather*}
Integrating the above expressions for $w_{2,x}$ and $w_{1,x}$ leads to (\ref{Prop-e-1}) -- (\ref{Prop-e-4}), where $w_2\equiv \bar w$, $w_1\equiv w$, $v_3\equiv \bar v$ and $v_1\equiv v$.
For the 5th potential Kupershmidt equation (\ref{5th-pot-kuper}) we consider
\begin{gather*}
  q_{1,x}=-\frac{4}{3}w_{1,x}^{-1/2},\qquad q_{2,x}=-\frac{4}{3}w_{2,x}^{-1/2}\\
  w_{1,x}=-\frac{\beta}{6}v_1^2v_{1,x}^{-2},\qquad w_{2,x}=-\frac{\beta}{6}v_3^2v_{3,x}^{-2}\\
  v_{1,x}=u_x^{-1/2},\qquad\quad v_{3,x}=uu_x^{-1/2}.
 \end{gather*}
Combining the above relations, we obtain
\begin{gather*}
  q_{1,x}=A v_1^{-1}u_x^{-1/2},\qquad q_{2,x}=Av_3^{-1}uu_x^{-1/2},\qquad
  A=-\frac{4}{3}\left(-\frac{\beta}{6}\right)^{-1/2},
\end{gather*}  
so that
\begin{gather*}
  q_{2,x}=uv_1v_3^{-1}q_{1,x}\quad \mbox{where}\quad q_{1,x}=Av_1^{-1}v_{1,x}.
\end{gather*}
Integrating the above expressions for $q_{2,x}$ and $q_{1,x}$, we obtain (\ref{Prop-f-1}) -- (\ref{Prop-f-2}), where $q_2\equiv \bar q$, $q_1\equiv q$, $v_3\equiv \bar v$ and $v_1\equiv v$. For the Sawada-Kotera equation
(\ref{Sawada-Kotera}) we consider
\begin{gather*}
  S_1=K_{1,x}-K_1^2,\qquad S_2=K_{2,x}-K_2^2
\end{gather*}
with
\begin{gather*}
  K_2=K_1+6\left[\ln(v)\right]_x,\qquad K_1=-\left[\ln(v_x)\right]_x.
\end{gather*}
This leads to
\begin{gather*}
  S_2=S_1+6\left[\ln(v)\right]_{xx},\qquad S_1=-\frac{v_{xxx}}{v_x},
\end{gather*}  
which is (\ref{Prop-g}) where $S_2\equiv \bar S$ and $S_1\equiv S$. Finally, for the $k$-equation (\ref{private-Kuper})
we have
\begin{gather*}
  k=-K_x-\frac{1}{2}K^2,\qquad
  K=-\left[\ln(v_x)\right]_x.
\end{gather*}
This leads to
\begin{gather*}
  k=\frac{v_{xxx}}{v_x}-\frac{3}{2}\left(\frac{v_{xx}}{v_x}\right)^2\equiv \{v,\,x\},
\end{gather*}
where $\{v,\,x\}$ is the Schwarzian derivative. We now consider
\begin{gather*}
  k_1=\{v_1,\,x\},\qquad
  k_2=\{v_2,\,x\}\\
  v_{1,x}=uu_x^{-1/2},\qquad v_{2,x}=u_x^{-1/2},
\end{gather*}
which leads to (\ref{Prop-h-1}) -- (\ref{Prop-h-2}), where $k_2\equiv \bar k$ and $k_1\equiv k$.\qquad $\Box$


