\begin{proof} (Lemma \ref{l:analytic})
Define $T:= \sup \{t \geq 0 | h(t)=0 \}.$ Clearly, $0<T_0 \leq T$. Indirectly assume $T<\infty.$ 
For all $0 \leq t<T$ we have $h(t)=0$, which means all the left derivatives of $h$ are $0$ at $T$, hence, the Taylor series expansion is $0$ around $T$. Then there exists an $\varepsilon>0$ such that $h(t)=0 \, \forall t \in [T,T+\varepsilon].$ This would imply $T +\varepsilon \leq T $, resulting in a contradiction.
\end{proof}

Next, we prove Lemma \ref{l:H1_graphon} which directly implies Lemma \ref{l:H1}.

\begin{proof} (Lemma \ref{l:H1_graphon})
\begin{align*}
u(t,x)=& \, u(0,x)+\int_{0}^{t} \left(1-u(\tau,x) \right)\W u(t,x)-\gamma(x) u(\tau,x) \d \tau \\
\left |u(t,x)-\hat{u}(t,x) \right| \leq & \left |u(0,x)-\hat{u}(0,x) \right| +\int_{0}^{t} \underbrace{\left| \W u(\tau,x)  \right|}_{\leq M} \cdot \left |u(\tau,x)-\hat{u}(\tau,x) \right| \d \tau+\\
&\int_{0}^{t} \underbrace{\left|1-\hat{u}(\tau,x) \right|}_{\leq 1} \cdot \left| \W u(\tau,x)- \hat{\W}\hat{u}(\tau,x) \right| \d \tau+ \\
&\int_{0}^{t} \underbrace{\gamma(x)}_{ \leq M} \left | u(\tau,x)-\hat{u}(\tau,x) \right | \d \tau+ \int_{0}^{t} \underbrace{\hat{u}(\tau,x)}_{ \leq 1} \left | \gamma(x)-\hat{\gamma}(x)\right| \d \tau \\
\left |u(t,x)-\hat{u}(t,x) \right| \leq & \left |u(0,x)-\hat{u}(0,x) \right| +T \left| \gamma(x)-\hat{\gamma}(x) \right| \\
&+\int_{0}^{t} \underbrace{\left | \hat{\W} \left[u(\tau,x)-\hat{u}(\tau,x) \right]  \right|}_{ \leq M \left \|u(\tau)-\hat{u}(\tau) \right \|_1} \d \tau+ \\
