 \right | \d \tau+2M \int_{0}^{t} \left |u(\tau,x)-\hat{u}(\tau,x)\right | \d \tau \\
 \|u(t)-\hat{u}(t) \|_{1} \leq& \|u(0)-\hat{u}(0) \|_{1}+T \|\gamma-\hat{\gamma} \|_{1}+\underbrace{\int_{0}^{t} \left \| \left(\W-\hat{\W} \right)u(t)\right \|_{1}}_{=H_{1,t} \leq H_{1,T} } + \\
