\begin{proof}(Theorem \ref{t:reconstruction_characterisation})
Since the nullspace of $G(T_0)$ is composed of vectors $v \in \mathbb{R}$ such that \begin{align*}
    \int_{0}^{T_0} \langle v, z(t) \rangle^2 \d t =0, 
\end{align*} 
\ref{condreconb} $\iff$ \ref{condreconc} is trivial.


Now assume there exists a vector $0 \neq v \in \mathcal{N}.$

Set $u_i:= \frac{v_i}{\pi_i}$ and $\hat{w}_{ij}:=w_{ij}-\varepsilon u_iu_j.$ Clearly, $\hat{W}^{\intercal}=\hat{W}$ and we can choose $\varepsilon>0 $ to be small enough such that $m' \leq \hat{w}_{ij} \leq M'$ for any $0<m'<m \leq M <M'$ making $\hat{W} \sim \mathcal{P}_{m',M'}^{(n)}.$
\begin{align*}
  \eta^{(i)}_j=&\, \varepsilon u_i u_j \pi_j=\varepsilon u_i v_j  \Rightarrow \eta^{(i)}=\varepsilon u_i v ,\\
  \left\| \eta^{(i)} \right \|_{G(T_0)}^2=& \, \varepsilon^2 u_i^2 \underbrace{\|v \|_{G(T_0)}^2}_{=0}=0 \ \overset{\eqref{eq:H2_noice}}{\Rightarrow} H_{2,T_0}=0.
\end{align*}
$H_{2,T_0}=0$ and Lemma \ref{l:H1} implies $z(t)=\hat{z}(t)$ for all $0 \leq t \leq T_0$ while $\hat{W} \neq W,$ which means $W$ is not $q$-reconstructible.

Lastly, assume $\mathcal{N}= \{0 \}$ making $\| \cdot \|_{G(T_0)}^2$ a norm. Let $\hat{W}$ a network such that $\hat{z}(t)=z(t)$ on $t \in [0,T_0].$ 

Due to  \eqref{eq:A_observe} for $t \in [0,T_0]$ we also have $\mathcal{A}z(t)=\hat{\mathcal{A}}\hat{z}(t)= \hat{\mathcal{A}}z(t)$, implying $H_{2,T_0}=0.$ Consequently, \eqref{eq:H2_noice} yields
\begin{align*}
  \forall i \in V \ \|\eta^{(i)} \|_{G(T_0)}^2=0 \quad \Rightarrow \quad \forall i \in V \ \eta^{(i)}=0  \quad\Rightarrow \quad \hat{\mathcal{A}}=\mathcal{A} \quad \Rightarrow \quad \hat{W}=W,  
\end{align*}
making $W$ $q$-reconstructible.
\end{proof}

\begin{proof} (Theorem \ref{t:different_d})

Fix any parameter $q \in \mathcal{Q}_{m,M}^{(n)}$ with $\gamma=0$. We will use the notation $z^c(t):=1-z(t)$ for short.
\begin{align*}
 \frac{\d}{\d t}z_{i}^{c}(t)=&-\frac{\d}{\d t}z_i(t)=-z_i^c(t) \left(\mathcal{A}z(t) \right)_{i} \\
 z_{i}^c(t)=&\exp \left(-\int_{0}^{t} \left(  \mathcal{A} z(\tau)\right)_{i} \d \tau \right)z_{i}^{c}(0)
\end{align*}

We give a uniform upper bound on $z_{i}^c(t)$ first. As there is no recovery in the SI model, $z_{i}(t)$ is monotone increasing, so $z_{i}(t) \geq z_{i}(0) \geq m.$ Then
\begin{align*}
\left(\mathcal{A}z(t) \right)_i =&\sum_{j \in V} w_{ij} \pi_{j} z_{j}(t) \geq m^2 \sum_{j \in V} \pi_j=m^2,
\end{align*}
so
\begin{align}
\label{eq:ziexp}
z_{i}^{c}(t) \leq& e^{-m^2 t}.
\end{align}

Next,
\begin{align*}
\int_{0}^{t} \left(\mathcal{A} z(t)\right)_{i} \d \tau=&\int_{0}^{t} \left(\mathcal{A} \mathds{1} \right)_i \d \tau +\int_{0}^{t} \left(\mathcal{A} z^c(t)\right)_{i} \d \tau=d_it+O(1), \\
z_{i}^{c}(t)=&\, e^{-d_it+O(1)}z_{i}^{c}(0).
\end{align*}
($\mathds{1}$ denotes the all $1$ vector.) 

Take a $v \in \mathbb{R}^n$ such that for all $t \in [0,T_0]$ we have $\langle v, z(t) \rangle=0$. From Lemma \ref{l:analytic}, $\langle v, z(t) \rangle=0$ actually holds for any $t \geq 0$.

In particular, since $z(t)=1-z^c(t) \to \mathds{1}$ as $t \to \infty$, we must have $\langle v, \mathds{1} \rangle=0 $, which yields $\langle v, z^c(t) \rangle=0. $

Without loss of generality, we assume $d_1<\dots <d_n.$

Define $\zeta_{k}(t):=\sum_{i \geq k}z_{i}^c(t).$ Due to \eqref{eq:ziexp}, the slowest exponential decay dominates $\zeta_k(t)$ making
\begin{align*}
   \lim_{t \to \infty} \frac{z_{i}^{c}(t)}{\zeta_{k}(t)} =0 
\end{align*}
for all $i>k$. Therefore,
\begin{align*}
0=\lim_{t \to \infty} \frac{1}{\zeta_{1}(t)} \langle u, z^c(t) \rangle=\lim_{t \to \infty} \sum_{i \in V} u_{i} \frac{z_{i}^c(t)}{\zeta_1(t)}=u_1.    
\end{align*}
Inductively, we may assume $u_i=0$ for all $i \leq k.$
\begin{align*}
 0=\lim_{t \to \infty} \frac{1}{\zeta_{k+1}(t)} \langle u, z^c(t) \rangle=\lim_{t \to \infty} \sum_{i \geq k+1} u_i \frac{z_{i}^c(t)}{\zeta_{k+1}(t)}=u_{k+1},   
\end{align*}
showing that $u=0$. 

This means $W$ is $q$-reversible.
\end{proof}

\begin{proof} (Theorem \ref{t:reconstruction_bad}.)

Let $p,p' \in \mathcal{P}_{m,M}^{(n)}$ with corresponding trajectories $z(t), z'(t)$. From Lemma \ref{l:H1_graphon} and Remark \ref{eq:cut_norm_conv} we know that for any $\varepsilon>0$ there is a $\delta>0$ such that $\|p-p'\|_{\square}<\delta$ implies
\begin{align*}
    \sup_{0 \leq t \leq T} \|z(t)-z'(t) \|_{1,\pi}<\frac{\varepsilon}{2}.
\end{align*}

From Lemmas \ref{l:H1_graphon} and \ref{l:Szemeredi} we know that there exists an $ n_0$ such that for any $n \geq n_0$ and $p=(W,q) \in \mathcal{P}_{m,M}^{(n)}$ there is a block homogeneous $p'=(W',q') \in \mathcal{P}^{(n)}_{m,M}$  with $1 \leq K \leq K_{\max}(\varepsilon)$ 
 blocks such that $\|p-p' \|_{\square}<\delta.$

Without loss of generality, we may assume  $\delta<\frac{1}{16}m$ and $n_0 \geq 4 K_{\max}(\varepsilon)$.

We will modify $W'$ into $W''$ in such a way that $p'':=(\hat{W},q')$ is still block regular with the same partition and $\bar{a}_{kl}$ values,  while $W'$ and $\hat{W}$ have a non-vanishing cut distance. This also means that the corresponding trajectory $z''(t)$ is identical to $z'(t).$

Informally, the idea is that we split vertices into odd and even labels and double the weights between vertices of the same parity and zero opposite ones.

Let the size of the block be $|V_k|:=2s_k+r_k$ where $r_{k} \in \{0,1 \}$ and $s_k \in \mathbb{N}.$ We can further divide the blocks into $V_{k,0}, V_{k,1},V_{k,2}$ where $|V_{k,0}|=r_{k}$ and $|V_{k,1}|=|V_{k,2}|=s_k.$

Take $i \in V_{k}, j \in V_l $ If $i \in V_{k,0}$, then set $\hat{w}_{ij}:=w'_{ij}.$ For $ i \in V_{k,1}$, 
\begin{equation*}
        \hat{w}_{ij} := \begin{cases}
                        w_{ij}' \text{ if $j \in V_{l,0} $} \\
                        2w_{ij}' \text{ if $j \in V_{l,1}$} \\
                        0, \textit{  if $j \in V_{l,2}$}
                    \end{cases}
\end{equation*}
then for $i \in V_{k,2}$, similarly take
\begin{equation*}
        \hat{w}_{ij} := \begin{cases}
                        w_{ij}' \text{ if $j \in V_{l,0} $} \\
                        0 \text{ if $j \in V_{l,1}$} \\
                        2w_{ij}' \text{ if $j \in V_{l,2}$.}
                    \end{cases}
\end{equation*}

Clearly, for any $k,l$ and $i \in V_k$,
$$\sum_{j \in V_l}\hat{w}_{ij} \frac{1}{n}=\sum_{j \in V_l}w'_{ij} \frac{1}{n},$$ and $\pi_i=\frac{1}{n}$, so indeed $p''$ is block regular and $z''(t)=z'(t).$

Furthermore, take the sets $S:=\bigcup_{k=1}^{K} V_{k,1}.$
\begin{align*}
    \|\hat{W}-W' \|_{\square} \geq & \frac{1}{n^2} \sum_{i,j \in S} \hat{w}_{ij}-w'_{ij}=\frac{1}{n^2} \sum_{i,j \in S} w_{ij}'=\frac{1}{n^2} \sum_{k,l=1}^{K} \bar{w}_{kl}s_{k}s_{l} \\
    \geq & \frac{1}{n^2}\sum_{k,l=1}^{K} \bar{w}_{kl} \frac{|V_k|-1}{2} \frac{|V_l|-1}{2} \geq \frac{m}{4n^2} \sum_{k,l=1}^{K} \left(|V_k|-1\right) \left(|V_l| -1\right) \\
    &=\frac{1}{4}m \frac{n^2-2Kn+K^2}{n^2}\geq \frac{1}{4}m \left(1-\frac{2K_{\max}(\varepsilon)}{n} \right) \geq \frac{1}{8}m .
\end{align*}
From $\|W-W' \|_{\square} \leq \|p-p'\|_{\square}<\delta<\frac{1}{16}m$ it follows that $\|W-\hat{W} \|_{\square}  \geq \frac{1}{16}m. $

Finally, set $\hat{p}:= (\hat{W},q)$ with trajectory $\hat{z}(t).$ Then
\begin{align*}
\|p''-\hat{p} \|_{\square}=\|z(0)-z'(0) \|_{1, \pi}+\|\gamma-\gamma' \|_{1, \pi} \leq d_{\square}(p,p')<\delta,
\end{align*}
resulting in
\begin{align*}
\sup_{0 \leq t \leq T} \|z(t)-\hat{z}(t) \|_{1, \pi} \leq &   \sup_{0 \leq t \leq T} \|z(t)-z'(t) \|_{1, \pi}+\sup_{0 \leq t \leq T} \|z'(t)-z''(t) \|_{1, \pi}  \\
& +\sup_{0 \leq t \leq T} \|z''(t)-\hat{z}(t) \|_{1, \pi}<  \frac{\varepsilon}{2}+0+\frac{\varepsilon}{2}=\varepsilon.
\end{align*}

\end{proof}
\subsection{Proofs for Section \ref{s:results_prediction}}

We will prove Theorem \ref{t:uniform_prediction} by showing that the following slightly stronger statement also holds:

\begin{theorem}
\label{t:uniform_prediction_stronger}
Assume $ 0 \leq \hat{W}(x,y)=\hat{W}(y,x) \leq M$ ($i,j \in V$) a.e. Then
\begin{align}
 \forall \varepsilon>0 \ \exists \delta>0 \ \forall  p \in  \mathcal{P}_{0,M}: \ H_{2,T_0}<\delta \Rightarrow H_{2,T}<\varepsilon .
\end{align}
\end{theorem}

Before proving Theorem \ref{t:uniform_prediction_stronger}, we make some preparations. Define
\begin{align*}
 G_T(x,y):=&\int_0^T u(t,x)u(t,y) \d t, \\
 \mathbb{G}_Tf(x):=& \int_{0}^1 G_T(x,y)f(y) \d y, \\
 \|f \|_{G_T}^2:=&\langle \mathbb{G}_Tf,f \rangle= \int_0^{T} \langle f, u(t) \rangle^2 \d t.
\end{align*}
Clearly $\|f \|_{G_T}^2 \leq T \|f \|_2^2.$ Due to Lemma \ref{l:analytic}, $\|f \|_{G_{T_0}}^2=0 \iff \|f \|_{G_T}^2=0$ $(0<T_0 \leq T).$

Similarly to \eqref{eq:H2_noice}, take $\eta(x)(y):=W(x,y)-\hat{W}(x,y)$ for which we have $\W u(t,x)-\hat{\W} u(t,x)= \langle \eta(x),u(t) \rangle$, and
\begin{align}
\label{eq:H2_noice_graphon}
H_{2,T}^2= \int_{0}^{T} \int_{0}^{1} \langle \eta(x),u(t) \rangle^2 \d x \d t=\int_{0}^{1} \| \eta(x) \|_{G_T}^2 \d x.
\end{align}

Throughout the rest of this section, $\rightharpoonup$ denotes weak convergence in $L^2([0,1]).$

\begin{lemma}
\label{l:GT_weak_cont}
 Assume $f_N \rightharpoonup f $ with $\|f_N \|_2^2 \leq 1$. Then $\|f_N \|_{G_T}^2 \to \| f\|_{G_T}^2$.   
\end{lemma}

\begin{proof}(Lemma \ref{l:GT_weak_cont})

$\langle f_N,u(t) \rangle^2 \leq \|f_N \|_2^2\cdot \|u(t) \|_2^2 \leq 1$, so dominated convergence applies to show
\begin{align*}
\lim_{N \to \infty} \|f_N \|_{G_T}^2=\int_{0}^{T} \lim_{N \to \infty} \langle f_N, u(t) \rangle ^2 \d t=\int_{0}^T \langle f,u(t) \rangle^2\d t=\|f \|_{G_T}^2.   
\end{align*}
\end{proof}

\begin{lemma}
\label{l:lambda_eigenish}
Define
\begin{align*}
\lambda_N:= \sup_{\|f \|_2^2 = 1} \frac{\|f \|_{G_T}^2}{\|f \|_{G_{T_0}^2}+\frac{1}{N}}
\end{align*}
There exists an $f \in L^2([0,1])$ such that $\|f\|_2^2 \leq 1$ and
\begin{align*}
\lambda_N=\frac{\|f \|_{G_T}^2}{\|f \|_{G_{T_0}^2}+\frac{1}{N}}
\end{align*}
\end{lemma}

\begin{proof} (Lemma \ref{l:lambda_eigenish})
Clearly $\lambda_N \leq NT.$

There must be a sequence $(f_n) \subset L^2([0,1])$ with $\|f_n \|_2^2= 1$ such that
\begin{align*}
 \lambda_N=\lim_{n \to \infty} \frac{\|f_n \|_{G_T}^2}{\|f_n \|_{G_{T_0}^2}+\frac{1}{N}} 
\end{align*}

Since the unit ball is weakly compact in $L^2([0,1])$, it must have a weakly convergent subsequence  $f_{n_k} \rightharpoonup f$  with $\|f \|_2^2 \leq 1$, resulting in
\begin{align*}
 \lambda_N=\lim_{k \to \infty} \frac{\|f_{n_k} \|_{G_T}^2}{\|f_{n_k} \|_{G_{T_0}}^2+\frac{1}{N}} = \frac{\|f \|_{G_T}^2}{\|f \|_{G_{T_0}}^2+\frac{1}{N}}.
\end{align*}
\end{proof}

Since the value of $p \in \mathcal{P}_{0,M}$ varies, we emphasize that $\lambda_N$ and $G_{T}$ depends on $p$, writing $\lambda_N(p)$ and $G_T(p)$ respectively.

\begin{remark}
\label{r:norm_relabel}
Based on Remark \ref{r:u_relabel}:
\begin{align*}
\langle f, u(t) \rangle=&\int_{0}^{1}f(x)u(t,x) \d x=\int_{0}^{1} f^{\phi}(x) u^{\phi}(t,x) \d x=\langle f^{\phi},(u(t))^{\phi} \rangle,\\
\|f \|_{G_T(p)}^2=&\int_{0}^{T} \langle f, u(t) \rangle^2 \d t =\int_{0}^{T} \langle f^{\phi},(u(t))^{\phi} \rangle^2 \d t= \left\|f^{\phi} \right\|_{G_T\left(p^{\phi}\right)}^2.
\end{align*}
\end{remark}

\begin{lemma}
\label{l:chi}
Define
\begin{align*}
    \chi_N:=\sup_{p \in \mathcal{P}_{0,M}} \frac{1}{N} \lambda_N(p).
\end{align*}
Then $\chi_N \to 0$ as $N \to \infty.$
\end{lemma}

\begin{proof} (Lemma \ref{l:chi}) Clearly $\chi_N \leq T.$

Define $\theta:=\limsup_{N \to \infty} \chi_N$.

Indirectly assume $\theta>0$. Then there must be a subsequence $(N_k)$ such that 
\begin{align*}
   \chi_{N_k} \geq \frac{1}{2}\theta>0 \quad  \forall \, k. 
\end{align*}
Therefore there must be a $p_{N_k} \in \tilde{\mathcal{P}}_{0,M}$ such that
\begin{align*}
    \bar{\lambda}_{N_k}:=\frac{1}{N_k}\lambda_{N_k}\left(p_{N_k} \right)=\frac{\|f_{N_k} \|_{G_T\left(p_{N_k} \right)}^2}{N_k \|f_{N_k} \|_{G_{T_0}\left(p_{N_k} \right)}^2+1} \geq \frac{1}{4} \theta >0
\end{align*}
for some $f_{N_k} \in L^2([0,1]).$

Due to Remark \ref{r:norm_relabel}, we may take an arbitrary $\phi_{N_k} \in \Phi,$ making
\begin{align*}
  \bar{\lambda}_{N_k}:=\frac{\left\|f_{N_k}^{\phi_{N_k}} \right\|_{G_T\left(p_{N_k}^{\phi_{N_k}} \right)}^2}{N_k \left\|f_{N_k}^{\phi_{N_k}} \right\|_{G_{T_0}\left(p_{N_k}^{\phi_{N_k}} \right)}^2+1} . 
\end{align*}

Since $\tilde{\mathcal{P}}_{0,M}$ is compact we can choose a suitable subsequence $(N_k')$ and $\phi_{N_k'} \in \Phi$ such that $ p_{N_k'}^{\phi_{N_K'}} \overset{\| \cdot \|_{\square}}{ \to}p \in \mathcal{P}_{0,M}$. Furthermore, the unit ball of $L^2([0,1])$ is weakly compact and $ \left\|f_{N_k'}^{\phi_{N_k'}} \right\|_2= \left \|f_{N_k'} \right \|_2 \leq 1$, thus, for some further subsequence $(N_k'')$ we also have  $f_{N_k'"}^{\phi_{N_k''}} \rightharpoonup f$ with $\|f \|_2^2 \leq 1.$
Let the solutions of \eqref{eq:u} with parameters $p_{N_k'}^{\phi_{N_k''}}, p$ be $u_{N_k''}, u.$ 
Then $u_{N_k''}(t) \overset{L^1([0,1])}{ \to} u(t)$ uniformly in $t \in [0,T]$ due to Remark \ref{eq:cut_norm_conv}.

Notice
\begin{align*}
 &\left | \left\|f_{N_k''}^{\phi_{N_k''}} \right \|_{G_{T} \left(p_{N_k''}^{\phi_{N_k''}} \right)}^2-\left\|f_{N_k''}^{\phi_{N_K''}} \right\|_{G_{T} \left(p \right)}^2 \right|\leq\\
 & \int_{0}^{T} \left| \left\langle f_{N_k''}^{\phi_{N_k''}},u_{N_k''}(t)  \right\rangle^2 -\left\langle f_{N_k''}^{\phi_{N_k''}},u(t)  \right\rangle^2 \right|  \ \d t  \leq \\
& \int_{0}^{T} \left |\left\langle f_{N_k''}^{\phi_{N_k''}},u_{N_k''}(t)-u(t)  \right\rangle \right| \cdot \left| \left\langle f_{N_k''}^{\phi_{N_k''}},u_{N_k''}(t)+u(t)  \right\rangle\right| \d t \leq \\
& 2 \int_{0}^{T} \|u_{N_k''}(t)-u(t) \|_2 \d t \leq 2 T \sup_{ 0 \leq t \leq T}  \|u_{N_k''}(t)-u(t) \|_2 \overset{|u_{N_k''}(t,x)-u(t,x)| \leq 1 }{\leq} \\
&2T \sqrt{\sup_{ 0 \leq t \leq T}  \|u_{N_k''}(t)-u(t) \|_1 } \to 0,
\end{align*}
 which implies
\begin{align*}
\lim_{k \to \infty} \left \|f_{N_k''}^{\phi_{N_{k}''}}  \right\|_{G_{T} \left(p_{N_k''} \right)}^2=\lim_{k \to \infty} \left\|f_{N_k''}^{\phi_{N_k''}}  \right\|_{G_{T} \left(p \right)}^2=\|f \|_{G_T(p)}^2.
\end{align*}

Define 
\begin{align*}
   \bar{\lambda}:=\lim_{k \to \infty} \bar{\lambda}_{N_k''} =\lim_{k \to \infty} \frac{\left\|f_{N_k''}^{\phi_{N_k''}} \right\|_{G_T\left(p_{N_k''}^{\phi_{N_k''}} \right)}^2}{N_k'' \|f_{N_k''}^{\phi_{N_k''}} \|_{G_{T_0}\left(p_{N_k''}^{\phi_{N_k''}} \right)}^2+1}=\lim_{k \to \infty} \frac{\|f \|_{G_T(p)}^2}{N_k''\|f \|_{G_{T_0}(p)}^2+1}.
\end{align*}
If $\| f\|_{G_{T_0}}^2>0$ then the limit is $\bar{\lambda}=0.$

If $\| f\|_{G_{T_0}}^2=0 \iff \|f \|_{G_T}^{2}=0$, then $\bar{\lambda}=\|f \|_{G_T}^{2}=0.$

This, however, contradicts $\bar{\lambda} \geq \frac{1}{4} \theta >0$.
\end{proof}

Finally we can prove Theorem \ref{t:uniform_prediction_stronger} which in turn proves Theorem \ref{t:uniform_prediction}.

\begin{proof}(Theorem \ref{t:uniform_prediction_stronger}.)

$ \|\eta(x) \|_2 \leq \|\eta(x) \|_{\infty}  \leq M. $ for almost every $x \in [0,1]$.
Furthermore, $H_{2,T}^2$ can be expressed as
\begin{align*}
H_{2,T}^2=&\int_{0}^1 \|\eta(x) \|_{G_T}^2 \d x \leq \int_{0}^{1} \lambda_N  \left(\|\eta(x) \|_{G_{T_0}^2}+\frac{1}{N}\|\eta(x) \|_2^2 \right) \d x \\  
 \leq &\lambda_{N}\underbrace{\int_{0}^T \| \eta(x) \|_{G_{T_0}}^2  \d x}_{=H_{2,T_0}^2}+M^2 \frac{\lambda_N}{N} \leq NTH_{2,T_0}^2+M^2 \chi_N.
\end{align*}

Fix $\varepsilon>0$. Based on Lemma \ref{l:chi} we can choose a large enough $N$ such that $M^2 \chi_N<\frac{\varepsilon^2}{2}.$ Set $\delta:=\frac{\varepsilon}{\sqrt{2NT}}.$

From this we can say that $H_{2,T_0}<\delta$ implies $H_{2,T}<\varepsilon.$ Note that the choice of $\delta$ only depends on $\varepsilon$ and it is independent of the choice of $p \in \mathcal{P}_{0,M}.$
\end{proof}

