\begin{subsection}{Outline}
 Section \ref{se:preliminaries} collects definitions and material required throughout the paper. This includes Riemann surfaces with border, spaces of functions and forms and their norms, boundary values of harmonic functions of finite Dirichlet energy, the overfare process and main theorems derived in \cite{Schippers_Staubach_scattering_I}, Green's function, and some basic results about the harmonic measures (one-forms which vanish on the boundary). 

 Section \ref{se:Schiffer_Cauchy} contains the foundational results about the Schiffer and Cauchy-Royden operators. 
 In Section \ref{subsec:defSchiffer} we define the Schiffer operators, and an associated integral operator which we call the Cauchy-Royden operator. We show that these are bounded, and derive a simple set of relations between the Schiffer and Cauchy-Royden operators. We derive a kind of Plemelj-Sokhotski jump formula which mixes overfare and the Cauchy-Royden operator. This is the main tool in investigating the effect of the operators on cohomology classes, as well as the investigation of their kernels and images.  In Section \ref{se:Schiffer_adjoint_identities} we derive a number of identities for the adjoints of these operators, which play a role in this paper and in the proof of the unitarity of the scattering operator {in part II}.  In Section \ref{se:Schiffer_on_harmonic_measures} we establish the action of the Schiffer operators on harmonic measures, which also plays a role in the determination of the kernels and images of the Schiffer and Cauchy-Royden operators in this paper, and in the scattering theory {in part II}. 

  Section \ref{se:index_cohomology} contains geometric and algebraic results about the Schiffer operators introduced in Subsection \ref{subsec:defSchiffer}.  We establish the isomorphism theorem generalizing those of Napalkov and Yulmukhametov \cite{Nap_Yulm} and Shirazi \cite{Shirazi_thesis}.  We give a characterization of the image and kernel of $\mathbf{T}_{1,2}$, and use this to prove an index theorem for this operator in the case that $\riem_1$ and $\riem_2$ are connected, and in the case that $\riem_2$ is of genus $g$ with $n$ boundary curves capped by $n$ simply connected domains.  This index theorem relates the conformally invariant index to purely topological quantities.

  We investigate the effect of the Schiffer operators $\mathbf{T}_{j,k}$ and $\mathbf{S}_k$ on cohomology in Section \ref{se:Schiffer_cohomology}. The main tool is the ``overfared'' jump formula, which is used to prove Theorem \ref{th:Schiffer_cohomology} which says that certain linear combinations of the Schiffer operators produce exact forms. Together with the fact that $\mathbf{S}_k \mathbf{R}_k$ is an isomorphism, this completely characterizes the effect of $\mathbf{T}_{j,k}$ on cohomology classes. We also prove the generalization of the aforementioned isomorphism theorem in the case of capped surfaces. In Section \ref{se:Schiffer_kernel_image} we determine the kernel and image of the operator $\mathbf{T}_{1,2}$ in greater generality. These results will also play a central role in in the construction of the generalized period matrix in {part II}. Once this is accomplished, we prove the index theorems in Section \ref{th:index_and_examples}, which relate the index of the Schiffer operators to topological invariants.  Although the cokernel and kernel are conformally invariant, it is open question whether the cokernel and kernel are topological invariants. We conclude with an example which might suggest a way to investigate this question.
\end{subsection}
\begin{subsection}{Assumptions throughout the paper}
 \label{se:assumptions_scattering_section} 
 In order to prevent needless repetition, we will use consistent notation throughout the paper for the Riemann surfaces. 
 The following assumptions
 will be in force throughout Section \ref{se:Schiffer_Cauchy}. Additional hypotheses are added to the statement of each theorem where necessary.
 \begin{enumerate}
     \item $\mathscr{R}$ is a compact Riemann surface;
     \item $\Gamma = \Gamma_1 \cup \cdots \cup \Gamma_n$ is a collection of quasicircles in $\mathscr{R}$, which have pair-wise empty intersection;
     \item $\Gamma$ separates $\mathscr{R}$ into Riemann surfaces $\riem_1$ and $\riem_2$.
 \end{enumerate} 
 By ``separates'', we mean that $\mathscr{R} \backslash \Gamma$ consists of two Riemann surfaces $\riem_1$ and $\riem_2$, where for any $\Gamma_k$ both $\riem_1$ and $\riem_2$ bound $\Gamma_k$. That is, $\riem_1$ and $\riem_2$ are on opposite sides of each curve $\Gamma_k$ for $k=1,\ldots,n$.
 The precise meaning of ``separates'' is given ahead in Definition \ref{de:separating_complex}.
 It is not assumed a priori that $\riem_1$ or $\riem_2$ is connected, although we will sometimes add the assumption as necessary.

  We will furthermore assume that the ordering of the connected components of $\partial \riem_1$ and $\partial \riem_2$ is such that $\partial_k \riem_1 = \partial_k \riem_2 = \Gamma_k$ as sets for $k=1,\ldots,n$.    
\end{subsection}
\end{section}
\begin{section}{Preliminaries} \label{se:preliminaries}

\begin{subsection}{Bordered surfaces and quasicircles}

 We first establish some notation and terminology regarding Riemann surfaces and curves within them. Details can be found in \cite{Schippers_Staubach_scattering_I}. 

In what follows we let $\mathbb{C}$ denote the complex plane, $\gls{annulus}$ denote the annulus $ \{ z;\, a<|z|<b \}$, and $\disk = \{ z \in \mathbb{C} : |z|<1 \}$ denote the unit disk in the plane. 


One of our main objects of study is a particular type of bordered Riemann surface which is defined as follows:
\begin{definition}\label{defn:gn-type surface}
We say that $\riem$ is a \emph{bordered Riemann surface of type} $(g,n),$ if it is bordered (see e.g. \cite{Ahlfors_Sario}), the border has $n$ connected components, each of which is homeomorphic to $\mathbb{S}^1$, and its double $\riem^d$ is a compact surface of genus $2g + n-1$.  
 \end{definition}
Visually, a bordered surface of type $(g,n)$ is a $g$-handled surface bounded by $n$ simple closed curves.  
 We order the connected components of the border and label them accordingly, so that $\partial \riem = \partial_1 \riem \cup \cdots \cup \partial_n \riem$.  The borders can be identified with analytic curves in the double $\riem^d$, and we denote the union $\riem\cup \partial \riem$ by $\text{cl}(\riem)$.  

 Finally, we observe that borders are conformally invariant.  That is, if $\riem_1$ and $\riem_2$ are bordered surfaces, then any biholomorphism $f:\riem_1 \rightarrow \riem_2$ extends to a homeomorphism of the borders.  In fact, $f$ extends to a biholomorphism between the doubles $\riem_1^d$ and $\riem_2^d$ which takes $\partial \riem_1$ to $\partial \riem_2$.  Finally, if only one of the two surfaces has a border, say $\riem_1$, then one can endow $\riem_2$ with a border using $f$. In particular, there is a unique maximal border structure.  
 \begin{remark}
  Note that if $\riem$ has type $(g,n)$, the border structure is maximal, since $\riem^d$ is a compact surface.  
 \end{remark}

 \begin{definition}
 We say that a homeomorphic image $\Gamma$ of $\mathbb{S}^1$ is a \emph{strip-cutting Jordan curve} if it is contained in an open set $U$ and there is a biholomorphism $\phi:U \rightarrow \mathbb{A}_{r,R} $ for some annulus 
 \[  \mathbb{A}_{r,R} \subset \mathbb{C}, \ \ \  r<1<R,  \] in such a way that $\phi(\Gamma)$ is isotopic to the circle $|z|=1.$  We call $U$ a doubly-connected neighbouhood of $\Gamma$ and $\phi$ a doubly-connected chart. 
 \end{definition}
 \begin{remark}
  If $\Gamma$ is a strip-cutting curve, by shrinking $\mathbb{A}_{r,R} $, we can assume that (1) $\phi$ extends biholomorphically to an open neighourhood of $\text{cl} \,(U)$, (2), that the boundary curves of $U$ are themselves strip cutting (in fact analytic), and  (3) that $\Gamma$ is isotopic to each of the boundary curves (using $\phi^{-1}$ to provide the isotopy).  
 \end{remark}

 \begin{definition}
     We say that a Jordan curve $\Gamma$ in in a Riemann surface is a {\it quasicircle} if it is contained in an open set $U$ and there is a biholomorphism $\phi:U \rightarrow V \subset \mathbb{C}$ such that $\phi(\Gamma)$ is a quasicircle in $\mathbb{C}$. 
 \end{definition}
 \begin{remark} \label{re:analytic_curve_stripcutting}
  A quasicircle (and in particular, an analytic Jordan curve), is by definition strip-cutting. 
 \end{remark}


 Throughout the paper we consider \emph{nested Riemann surfaces}.  That is, we are 
 given a type $(g,n)$ bordered surface $\riem$, another Riemann surface $\mathscr{R}$ which is compact, and a holomorphic inclusion map $\iota( \riem )\subset \mathscr{R}$.  Assume that the closure of $\riem$ is compact in $R$, and furthermore the boundary consists of $n$ closed strip-cutting Jordan curves, which do not intersect.  In that case, the inclusion map $\iota$ extends homeomorphically to a map from the border to the strip-cutting Jordan curves.  Thus $\partial \riem$ is in one-to-one correspondence with its image under the homeomorphic extension of $\iota$, and in fact the image is the boundary of $\iota (\riem)$
 in the ordinary topological sense.  For this reason, we will not notationally distinguish $\riem$ from $\iota (\riem)$.  We will also use the notation $\partial \riem$ for both the boundary of $\iota (\riem)$ in $\mathscr{R}$ and the abstract border of $\riem$, and denote both closures by $\text{cl}\, (\riem)$. 



 In fact, it is not necessary to assume that $\riem$ is bordered. That is, if $\riem \subseteq \mathscr{R}$ is bounded by strip-cutting Jordan curves in $\mathscr{R}$, then it can be shown that $\riem$ is bordered and the borders can be bijectively identified with the boundary curves as above (see \cite[Theorem 2.8]{Schippers_Staubach_scattering_I}).  

 \begin{remark}
   The embedding of the border $\partial \riem$ in $\mathscr{R}$ need not be regular.  That is, the inclusion map does not extend to a smooth or analytic map from $\partial \riem$ onto its image under inclusion $\iota$, unless the image consists of smooth or analytic curves. 
 \end{remark}

 By another application of \cite[Theorems 3.3, 3.4 Sect 15.3]{ConwayII}, it is easily shown that if $\riem_1\subset \mathscr{R}_1$ and $\riem_2 \subset \mathscr{R}_2$
 satisfy the conditions above, and $f:\riem_1 \rightarrow \riem_2$ is a biholomorphism, then $f$ extends continuously to a map taking each Jordan curve in $\partial \riem_1$ homeomorphically to one of the Jordan curves of $\partial \riem_2$. \\


 \end{subsection}

 \begin{subsection}{Function spaces and holomorphic and harmonic forms}
  In this paper, we will denote positive constants in the inequalities by $C$ whose 
value is not crucial to the problem at hand. The value of $C$ may differ
from line to line, but in each instance could be estimated if necessary.  Moreover, when the values of constants in our estimates are of no significance for our main purpose, then we use the notation $a\lesssim b$ as a shorthand for $a\leq Cb$. If $a\lesssim b$ and $b\lesssim a$ then we write $a\approx b.$  \\

 On any Riemann surface,  define the dual of the almost 
 complex structure,  $\ast$ in local coordinates $z=x+iy$,  by 
 \[  \ast (a\, dx + b \, dy) = a \,dy - b \,dx. \]
This is independent of the choice of coordinates.
It can also be computed in coordinates that for any complex function $h$ 
\begin{equation} \label{eq:Wirtinger_to_hodge}
    2 \partial_z h = dh + i \ast dh.
\end{equation}

\begin{definition}
 We say a complex-valued function $f$ on an open set $U$ is \emph{harmonic} if it is $C^2$ on $U$ and $d \ast d f =0$. We say that a complex one-form $\alpha$ is harmonic if it is $C^1$ and satisfies
 both $d\alpha =0$ and $d \ast \alpha =0$. 
\end{definition}
  Equivalently, harmonic one-forms are those which can be expressed locally as $df$ for some harmonic function $f$. Harmonic one-forms and functions must of course be $C^\infty$. \\

   Denote complex conjugation of functions and forms with a bar, e.g. $\overline{\alpha}$.
 A holomorphic one-form is one which can be written in coordinates as $h(z)\,dz$ for a holomorphic function $h$, while an anti-holomorphic one-form is one which can be locally written $\overline{h(z)}\, d\bar{z}$ for a holomorphic function $h$.  

Denote by $L^2(U)$ the set of one-forms $\omega$ on an open set $U$ which satisfy
\[   \iint_U \omega \wedge \ast \overline{\omega} < \infty  \]
(observe that the integrand is positive at every point, as can be seen by writing the expression in local coordinates).  
This is a Hilbert space with respect to the inner product
\begin{equation} \label{eq:form_inner_product}
 (\omega_1,\omega_2) =  \iint_U \omega_1 \wedge \ast \overline{\omega_2}.
\end{equation}

\begin{definition}\label{defn:bergman spaces}
The \emph{Bergman space of holomorphic one forms} is 
\begin{equation}
    \gls{bergman}(U) = \{ \alpha \in L^2(U) \,:\, \alpha \ \text{holomorphic} \}.
\end{equation} 
 The anti-holomorphic Bergman space is denoted $\overline{\mathcal{A}(U)}$.   We will also denote 
\begin{equation}
    \gls{Aharm}(U) =\{ \alpha \in L^2(U) \,:\, \alpha \ \text{harmonic} \}.
\end{equation}
\end{definition}


Observe that $\mathcal{A}(U)$ and $\overline{\mathcal{A}(U)}$ are orthogonal with respect to the inner product \eqref{eq:form_inner_product}.  In fact we have the direct sum decomposition
\begin{equation}\label{direct sum decomposition}
 \mathcal{A}_{\mathrm{harm}}(U) = \mathcal{A}(U) \oplus \overline{\mathcal{A}(U)}.    
\end{equation}      
If we restrict the inner product to 
 $\alpha, \beta \in \mathcal{A}(U)$ then since $\ast \overline{\beta} = i \overline{\beta}$, we have   
\[  (\alpha,\beta) = i \iint_U \alpha \wedge \overline{\beta}.      \]

Denote the projections induced by this decomposition by 
\begin{align}  \label{eq:hol_antihol_projections_Bergman}
  \mathbf{P}_U: \mathcal{A}_{\mathrm{harm}}(U) & \rightarrow \mathcal{A}(U) \nonumber \\
  \overline{\mathbf{P}}_U : \mathcal{A}_{\mathrm{harm}}(U) & \rightarrow  \overline{\mathcal{A}(U)}.
\end{align}

Let $f: U \rightarrow V$ be a biholomorphism. We denote the pull-back of $\alpha \in \mathcal{A}_{\mathrm{harm}}(V)$
under $f$ by $f^*\alpha.$ 
Explicitly, if $\alpha$ is given in local coordinates $w$ by $a(w)\, dw + \overline{b(w)} \, d\bar{w}$ and $w=f(z),$ then the pull-back is given by 
\[   f^* \left( a(w)\, dw + \overline{b(w)} \,d\bar{w} \right)= a(f(z)) f'(z)\, dz + \overline{b(f(z))} \overline{f'(z)}\, d\bar{z}.   \]
The Bergman spaces are all conformally invariant, in the sense that if $f:U \rightarrow V$ is a biholomorphism, then $f^*\mathcal{A}(V) = \mathcal{A}(U)$ and this preserves the inner product.  Similar statements hold for the anti-holomorphic and harmonic spaces.\\ 

\begin{definition}\label{def: exact holo and harm forms}
 We define the space $\gls{exactA}_{\mathrm{harm}}(U)$ as the subspace of exact elements of $\mathcal{A}_{\mathrm{harm}}(U)$, and similarly for $\mathcal{A}^\mathrm{e}(\riem)$ and $\overline{\mathcal{A}^\mathrm{e}(\riem)}$.  
\end{definition}

{We also consider one-forms which have zero boundary periods, which we call semi-exact.
\begin{definition} \label{de:semi_exact}
 Let $\riem$ be a bordered surface of type $(g,n)$. We say that an $L^2$ one-form $\alpha \in \mathcal{A}_{\mathrm{harm}}(\riem)$ is semi-exact if for any simple closed curve $\gamma$ homotopic to a boundary curve $\partial_k \riem$, 
 \[ \int_{\gamma}  \alpha =0. \]
 The class of semi-exact one-forms on $\riem$ is denoted $\mathcal{A}^{\mathrm{se}}_{\mathrm{harm}}(\riem)$. The holomorphic and anti-holomorphic semi-exact one-forms are denoted by $\gls{seform}(\riem)$  and 
 $\overline{\mathcal{A}^{\mathrm{se}}(\riem)}$ respectively.
\end{definition}}

The following spaces also play significant roles in this paper.
\begin{definition}\label{defn:dirichlet spaces}
The \emph{Dirichlet spaces of functions} are defined by 
\begin{align*}
   \gls{Dharm}(U)& = \{ f:U \rightarrow \mathbb{C}, f \in C^2(U), \,:\, 
   df\in L^2 (U)\,\,\,\mathrm{and}\,\, \, d\ast df =0 \},\\
   \gls{D}(U)& = \{ f:U \rightarrow \mathbb{C} \,:\, 
    df \in \mathcal{A}(U) \}, \ \text{and} \\
    \overline{\mathcal{D}(U)} & = \{ f:U \rightarrow \mathbb{C} \,:\, 
    df \in \overline{\mathcal{A}(U)} \}. \\
\end{align*}
\end{definition}
We also consider homogeneous Dirichlet spaces $\dot{\mathcal{D}}_{\mathrm{harm}}(U)$, $\dot{\mathcal{D}}(U)$, and $\dot{\overline{\mathcal{D}}}(U)$ obtained by quotienting by constants. More precisely, we say two functions $f,g \in \mathcal{D}(U)$ are equivalent if they differ by a locally constant function.  The homogeneous space $\dot{\mathcal{D}}(U)$ is the quotient of $\mathcal{D}(U)$ with respect to this equivalence relation. The same procedure can be applied to ${\overline{\mathcal{D}}}(U)$ and $\mathcal{D}_{\mathrm{harm}}(U)$ to obtain $\dot{\overline{\mathcal{D}}}(U)$ and $\dot{{\mathcal{D}}}_{\mathrm{harm}}(U)$.

We can define a degenerate inner product on $\mathcal{D}_{\mathrm{harm}}(U)$ by 
\[   (f,g)_{\mathcal{D}_{\mathrm{harm}}(U)} = (df,dg)_{\mathcal{A}_{\mathrm{harm}}(U)},   \] 
where the right hand side is the inner product (\ref{eq:form_inner_product}) restricted to elements of $\mathcal{A}_{\mathrm{harm}}(U)$.  The inner product can be used to define a seminorm on $\mathcal{D}_{\mathrm{harm}}(U)$, by letting $$\Vert f\Vert^2_{\mathcal{D}_{\mathrm{harm}}(U)}:=(df,df)_{\mathcal{A}_{\mathrm{harm}}(U)}.$$ 
This is a norm on the homogeneous spaces.



We note that if one defines the \emph{Wirtinger operators} via their local coordinate expressions
\[   \partial f = \frac{\partial f}{\partial z}\, dz,  \ \ \ 
   \overline{\partial} f =  \frac{\partial f}{\partial \bar{z}}\, d \bar{z}, \]
then the aforementioned inner product can be written as
\begin{equation} \label{eq:inner_product_with_dbar_and_d}
 (f,g)_{\mathcal{D}_{\mathrm{harm}}(U)} =i \iint_{U} \left[ \partial f \wedge \overline{\partial  g} -  \overline{\partial} f \wedge 
 \partial \overline{g} \right].    
\end{equation}
Although this implies that $\mathcal{D}(U)$ and $\overline{\mathcal{D}(U)}$ are orthogonal, there is no direct sum decomposition into $\mathcal{D}(U)$ and $\overline{\mathcal{D}(U)}$.  This is because in general there exist exact harmonic one-forms whose holomorphic and anti-holomorphic parts are not exact.  

Observe that the Dirichlet spaces are conformally invariant in the same sense as the Bergman spaces.  That is, if $f: U \rightarrow V$ is a biholomorphism then 
\begin{equation*}
 \gls{cf} h = h \circ f
\end{equation*} 
satisfies
\[  \mathbf{C}_f :\mathcal{D}(V) \rightarrow \mathcal{D}(U) \]
and this is a seminorm preserving bijection. On the homogeneous spaces it is an isometry. Similar statements hold for the anti-holomorphic and harmonic spaces. 

We also note that if $h \in \mathcal{D}(U)$ and $\tilde{h}(z) = h \circ \phi^{-1}(z)$ is the expression for $h$ in local coordinates $z= \phi(w)$ in an open set $\phi(U) \subseteq \mathbb{C}$,  then we have the local expression
\[  (h,h)_{\mathcal{D}(U)} = \iint_{\phi(U)}  |\tilde{h}'(z)|^2 dA_z   \] 
where $dA$ denotes Lebesgue measure in the plane. 
 Similar expressions hold for the other Dirichlet spaces.\\

\end{subsection}
\begin{subsection}{Harmonic measures} \label{ harmonic measures}
We start with the definition of harmonic measure in the context of bordered Riemann surfaces.
\begin{definition}\label{def:harmonic measure}
Let $\omega_k$, $k=1,\ldots,n$ be the unique harmonic function which is continuous 
 on the closure of $\riem$ and which satisfies
 \begin{equation*}
  \omega_k = \left\{ \begin{array}{ll} 
    1 & \mathrm{on}\,\,\, \partial_k \riem \\ 0 & \mathrm{on}\,\,\, \partial_j \riem, \ \  j \neq k.  \end{array}  \right.   
 \end{equation*}
 The one-forms $\gls{harmeasure}$ are the {\it harmonic measures}.  We denote the complex linear span of the harmonic measures by $\gls{Ahm}(\riem).$ Moreover we define $\ast \mathcal{A}_{\mathrm{hm}}(\riem) = \{ \ast \alpha : \alpha \in \mathcal{A}_{\mathrm{hm}}(\riem) \}.$
\end{definition}

By definition any element of $\mathcal{A}_{\mathrm{hm}}(\riem)$ is exact, and its anti-derivative $\omega$ is constant on each boundary curve. On the other hand, the elements of $\ast \mathcal{A}_{\mathrm{hm}}(\riem)$ are all closed but not necessarily exact. Elements of $\mathcal{A}_{\mathrm{hm}}(\riem)$ and $\ast \mathcal{A}_{\mathrm{hm}}(\riem)$ extend real analytically to the border, in the sense that they are restrictions to $\riem$ of harmonic one-forms on the double.  In particular they are square-integrable, which explains our choice of notation above. Thus to summarize:

\begin{proposition} \label{pr:harmonic_measures_L2}
 Let $\riem$ be a bordered surface of type $(g,n)$.  Then $\mathcal{A}_{\mathrm{hm}}(\riem) \subseteq \mathcal{A}_{\mathrm{harm}}^{\mathrm{e}}(\riem)$ and 
 $\ast \mathcal{A}_{\mathrm{hm}}(\riem) \subseteq \mathcal{A}_{\mathrm{harm}}(\riem)$.  
\end{proposition} 

 \begin{definition}\label{periodmatrix}
 The \emph{boundary period matrix} $\Pi_{jk}$ of a non-compact surface $\riem$ of type $(g,n)$ is defined by
 \[  \Pi_{jk} := \int_{\partial \riem} \omega_j  \ast d\omega_k = \int_{\partial_j \riem} \ast d \omega_k.   \]
\end{definition} 
 \begin{theorem} \label{th:period_matrix_invertible} If we let $j,k$ run from $1$ to $n$, omitting one fixed value $m$ say, then the resulting matrix
  $\Pi_{jk}$ is symmetric and positive definite.  
 \end{theorem}

 Thus $\Pi_{jk}$, $j,k = 1,\ldots\hat{m},\ldots,n$ is an invertible matrix, and we can specify $n-1$ of the boundary periods of elements of $\ast \mathcal{A}_{\mathrm{hm}}(\riem)$.
 \begin{corollary}  \label{co:boundary_periods_specified_starmeasure}
  Let $\riem$ be of type $(g,n)$ and $\lambda_1,\ldots,\lambda_n \in \mathbb{C}$ be such that $\lambda_1 + \cdots + \lambda_n =0$.  Then there is an $\alpha \in \ast \mathcal{A}_{\mathrm{hm}}(\riem)$ such that 
  \begin{equation}\label{periodjaveln}
    \int_{\partial_k \riem} \alpha = \lambda_k   
  \end{equation}   
  for all $k=1,\ldots,n$.  
 \end{corollary}
\end{subsection}
\begin{subsection}{Green's functions} 
Another basic notion which is of fundamental importance in our investigations is that of Green's functions.

 \begin{definition}\label{defn:greens function} Let $\riem$ be a type $(g,n)$ surface.
For fixed $z \in \riem$, we define \emph{Green's function of} $\riem$ to be a function $\gls{greenb}(w;z)$ such that 
 \begin{enumerate}
     \item for a local coordinate $\phi$ vanishing at $z$ the function $w\mapsto G_\Sigma(w;z) + \log|\phi(w)|$ is harmonic in an open neighbourhood
     of $z$;
     \item $\lim_{w \rightarrow \zeta} G_\Sigma (w;z) =0$ for any $\zeta \in \partial \riem$.   
 \end{enumerate}
 \end{definition}
  That such a function exists, follows from \cite[II.3 11H, III.1 4D]{Ahlfors_Sario}, considering $\riem$ to be a subset of its double $\riem^d$.\\  
\begin{definition}
 For compact surfaces $\mathscr{R}$, one defines the \emph{Green's function} $\gls{greenc}$ (see e.g. \cite{Royden}) as the unique function
 $\mathscr{G}(w,w_0;z,q)$ satisfying 
 \begin{enumerate}
  \item $\mathscr{G}$ is harmonic in $w$ on $\mathscr{R} \backslash \{z,q\}$;
  \item for a local coordinate $\phi$ on an open set $U$ containing $z$, $\mathscr{G}(w,w_0;z,q) + \log| \phi(w) -\phi(z) |$ is harmonic 
   for $w \in U$;
  \item for a local coordinate $\phi$ on an open set $U$ containing $q$, $\mathscr{G}(w,w_0;z,q) - \log| \phi(w) -\phi(q) |$ is harmonic 
   for $w \in U$;
  \item $\mathscr{G}(w_0,w_0;z,q)=0$ for all $z,q,w_0$.  
 \end{enumerate}
\end{definition}

 The existence of such a function is a standard fact about Riemann surfaces, see for example \cite{Royden}.  It satisfies the following identities:
 \begin{align}
  \mathscr{G}(w,w_1;z,q) & = \mathscr{G}(w,w_0;z,q) - \mathscr{G}(w_1,w_0;z,q) \label{eq:g_w_0_dependence} \\
  \mathscr{G}(w_0,w;z,q) & = - \mathscr{G}(w,w_0;z,q) \label{eq:g_interchange_w} \\
  \mathscr{G}(z,q;w,w_0) & = \mathscr{G}(w,w_0;z,q).  \label{eq:g_interchange_both}
 \end{align}
 In particular, $\mathscr{G}$ is also harmonic in $z$ where it is non-singular.

 \begin{remark}
  The condition (4) involving the point $w_0$ simply determines an arbitrary additive constant, and is not of any interest in the paper. 
 This is because by the property (\ref{eq:g_w_0_dependence}), $\partial_w \mathscr{G}$ is independent
 of $w_0$, and only such derivatives enter in the paper.  For this reason, we usually leave $w_0$ out of the expression for $\mathscr{G}$.
 \end{remark}





 Green's function is conformally invariant.  That is, if $\riem$ is of type $(g,n)$, and $f:\riem \rightarrow \riem'$ is conformal, then 
 {\begin{equation} \label{eq:Greens_conf_inv_gntype}
  G_{\riem'}(f(w);f(z)) = G_{\riem}(w;z). 
 \end{equation}}

 Similarly if $\mathscr{R}$ is compact and $f:\mathscr{R} \rightarrow \mathscr{R}'$ is a biholomorphism, then 
 \begin{equation} \label{eq:Greens_conf_inv_compact}
   \mathscr{G}_{\mathscr{R}'}(f(w),f(w_0);f(z);f(q)) = \mathscr{G}_{\mathscr{R}}(w,w_0;z,q). 
 \end{equation}



 These follow from uniqueness of Green's function; in the case of type $(g,n)$ surfaces, one also needs the fact that a biholomorphism extends to a homeomorphism of the boundary curves. 

 \end{subsection}
\begin{subsection}{ Sobolev spaces via harmonic measure and Green's functions}

     The harmonic measure and the Green's function can be used to define a conformally invariant Sobolev space that is of great significance in our investigations. 
 Let $d\omega_k$ be the harmonic measures given in Definition \ref{def:harmonic measure}. For a collar neighbourhood $U_k$ of $\partial_k \riem$ and $h_k \in \mathcal{D}_{\mathrm{harm}}(U_k)$, 
 we can fix a simple closed analytic curve $\gamma_k$ which is isotopic to $\partial_k \riem$, and define
 \begin{equation}\label{defn:integration over rough}
  \int_{\partial_k \riem}  h_k \ast d \omega_k: =  \iint_{V_k} dh_k \wedge \ast d\omega_k + \int_{\gamma_k} h_k \ast d \omega_k  
 \end{equation}   
 where $V_k$ is the region bounded by $\partial_k \riem$ and $\gamma_k$.  Here $\partial_k \riem$ is oriented positively with respect to $\riem$ and $\gamma_k$ has the same orientation as $\partial_k \riem$ (this is independent of $\gamma_k$).
 Equivalently, for a curves $\Gamma_r = \phi^{-1}(|z|=r)$ defined by a collar chart $\phi$, 
 \[   \int_{\partial_k \riem}  h_k \ast d \omega_k  = \lim_{r \nearrow 1} \int_{\Gamma_r}  h_k \ast d \omega_k.  \]
Now given $h_k \in \mathcal{D}_{\mathrm{harm}}(\riem)$ we set
   \begin{equation}\label{harmonisk matt}
    \mathscr{H}_k  := \int_{\partial_k \riem} h_k \ast d\omega_k.    
   \end{equation} 
\begin{definition}\label{def:norm on H1confU}
Let $\riem$ be a bordered surface of type $(g,n)$ and 
  let $U_k \subseteq \riem$ be collar neighbourhoods of $\partial_k \riem$ for $k=1,\ldots,n$. Set $U = U_1 \cup \cdots \cup U_n$. By ${H}^{1}_{\mathrm{conf}}(U)$ we denote the harmonic Dirichlet space $\mathcal{D}_{\mathrm{harm}}(U)$ endowed with the norm
  \begin{equation}\label{defn:Dconf norm}
 \| h \|_{H^1_{\mathrm{conf}}(U)} := \Big(\| h \|^2_{\mathcal{D}_{\mathrm{harm}}(U)} + 
  \sum_{k=1}^{n}   |\mathscr{H}_k |^2\Big)^{\frac{1}{2}} 
 \end{equation} 
 for $n>1$.  
 In the case that $n=1$,  fix a point $p\in \riem \setminus U_1$ and let $G_\Sigma$ be the Green function of $\Sigma$ given in Definition \ref{defn:greens function}. Then define instead 
  \begin{equation} \label{eq:constant_hk_definition_onecurve}
    \mathscr{H}_1 := \int_{\partial_1 \riem} h_1 \ast d G_{\riem}(w,p).
  \end{equation}


   For the Riemann surface $\riem$, assuming that $\riem$ is connected, we need only one boundary integral to obtain a norm.  If $n >1$, we can choose any fixed boundary curve $\partial_n \riem$ say, and define the norm 
 \begin{equation}\label{equivalent sobolev norm}  
     \| h \|_{{H}^1_{\mathrm{conf}}(\riem)} := \left( \| h \|^2_{\mathcal{D}_{\mathrm{harm}}(\riem)} + |\mathscr{H}_n |^2 \right)^{1/2},
 \end{equation}  
where any of the $\mathscr{H}_k$ could in fact be used in place of $\mathscr{H}_n$ and the result is an equivalent norm. In the case that $n=1$ we use (\ref{eq:constant_hk_definition_onecurve}) to define $\mathscr{H}_1$.
 \end{definition}
 \end{subsection}
\begin{subsection}{Boundary values and the bounce and the overfare operators}
We also consider a space of boundary values of Dirichet-bounded harmonic functions. In the following, let $\Gamma$ be a border of a Riemann surface $\riem$, which is homeomorphic to $\mathbb{S}^1$. For any such $\Gamma$ there is a biholomorphism 
 \[  \phi:U \rightarrow \mathbb{A}_{r,1} \]
 where $U$ is an open set in $\riem$ bounded by two Jordan curves, one of which is $\Gamma$, and $\mathbb{A}_{r,1}$ is an annulus $r<|z|<1$. We call this a collar chart of $\Gamma$. Such a $\phi$ extends homeomorphically to a map from $\Gamma$ onto $\mathbb{S}^1$; in fact, viewing $\Gamma$ as an analytic curve in the double of $\riem$, $\phi$ has a biholomorphic extension to an open neighbourhood of $\Gamma$. 

 Given any $h \in \mathcal{D}_{\mathrm{harm}}(\riem)$, $h$ has ``conformally non-tangential'' or ``CNT'' boundary values on $\Gamma$. That is, given a collar chart $\phi$ of $\Gamma$ , $h \circ \phi^{-1}$ has non-tangential boundary values except possibly on a Borel set of logarithmic capacity zero in $\mathbb{S}^1$; we define the CNT boundary value of $h$ at $p$ to be the non-tangential boundary value of $h \circ \phi^{-1}(p)$.  Define a null set on $\Gamma$ to be the image of a logarithmic set of capacity zero under $\phi^{-1}$. Let $\mathcal{H}(\Gamma)$ denote the set of functions on $\Gamma$ arising as CNT boundary values of elements of $\mathcal{D}_{\mathrm{harm}}(\riem)$, where we say two functions are the same if they agree except possibly on a null set.  
 It can be shown that $\mathcal{H}(\Gamma)$ is independent of the choice of collar chart.  The definition also extends immediately to finite collections of distinct borders $\Gamma = \Gamma_1 \cup \cdots \cup \Gamma_n$.  It can also be shown that $\mathcal{H}(\Gamma)$ is the set of CNT boundary values of elements of $\mathcal{D}_{\mathrm{harm}}(U)$ for any collar neighbourhood $U$ of $\Gamma$. 

 Treating $\Gamma$ as an analytic curve in the double, we can define the Sobolev space $H^{1/2}(\Gamma)$. Every element of $H^{1/2}(\Gamma)$ uniquely defines an element of $\mathcal{H}(\Gamma)$. 

 We also define the homogeneous space $\dot{\mathcal{H}}(\Gamma)$ of elements of $\mathcal{H}(\Gamma)$ mod functions which are constant on each connected component of $\Gamma$. Every element of the homogeneous Sobolev space $\dot{H}^{1/2}(\Gamma)$ defines a unique element of $\dot{\mathcal{H}}(\Gamma)$.  

 Finally, we will require a result regarding an operator we call the ``bounce operator''. This operator takes a Dirichlet bounded harmonic function defined in collars of the boundary to Dirichlet bounded functions on the surface with the same boundary values. 
  Let $\riem$ be a bordered surface of type $(g,n)$ as above, and
  let $U_k \subseteq \riem$ be collar neighbourhoods of $\partial_k \riem$ for $k=1,\ldots,n$. 
 \begin{definition}[Bounce operator] \label{defn:bounce op}
 Set $U = U_1 \cup \cdots \cup U_n$ and let $h:U \rightarrow \mathbb{C}$ be the function whose restriction to $U_k$ is $h_k$ for each $k=1,\ldots,n$.  We define 
  \begin{align*}
   \mathbf{G}_{U,\riem}: \mathcal{D}_{\mathrm{harm}}(U) & \rightarrow \mathcal{D}_{\mathrm{harm}}(\riem) \\ h & \mapsto H
  \end{align*}
  where $H$ is the element of $\mathcal{D}_{\mathrm{harm}}(\riem)$ with CNT boundary values agreeing with $h$ up to a null set, which exists and is unique by Theorem \cite[Theorem 3.10]{Schippers_Staubach_scattering_I}. 
 \end{definition}
  By conformal invariance of CNT limits, the bounce operator is conformally invariant, that is, if $f:\riem \rightarrow \riem'$ is a biholomorphism and $f(U)=U'$, then 

  \begin{equation} \label{eq:bounce_conformally_invariant}
   \gls{bounce} \mathbf{C}_f = \mathbf{C}_f \mathbf{G}_{U',\riem'}.
  \end{equation}


\begin{theorem}[Boundedness of bounce operator] \label{th:bounce_bounded} 
  Let $\riem$ and $U_k$ be as above for $k=1,\ldots,n$.
  Then $\mathbf{G}_{U,\riem}$ is bounded from ${H}^{1}_{\mathrm{conf}}(U)$ to ${H}^{1}_{\mathrm{conf}}(\riem)$.
 \end{theorem} 

\end{subsection}

\begin{subsection}{Overfare of functions}
 We will consider a compact Riemann surface $\mathscr{R}$ separated into two ``pieces'' $\riem_1$ and $\riem_2$ by a collection of quasicircles. It is possible for one or both of $\riem_1$ and $\riem_2$ to be disconnected. The precise definition of ``separating'' is the following.
  \begin{definition}  \label{de:separating_complex}
 Let $\mathscr{R}$ be a compact Riemann surface, and let $\Gamma_1,\ldots,\Gamma_m$ be a collection of  quasicircles in $\mathscr{R}$.  Denote $\Gamma = \Gamma_1 \cup \cdots \cup \Gamma_m$.  We say that $\Gamma$ \emph{separates} $\mathscr{R}$ into $\riem_1$ and $\riem_2$ if 
 \begin{enumerate}
     \item there are doubly-connected neighbourhoods $U_k$ of $\Gamma_k$ for $k=1,\ldots,n$   such that $U_k \cap U_j$ is empty for all $j \neq k$, 
     \item one of the two connected components of $U_k \backslash \Gamma_k$ is in $\riem_1$, while the other is in $\riem_2$; 
     \item $\mathscr{R} \backslash \Gamma = \riem_1 \cup \riem_2$;
     \item $\mathscr{R} \backslash \Gamma$ consists of finitely many connected components;
     \item $\riem_1$ and $\riem_2$ are disjoint.
 \end{enumerate}
 \end{definition}
 In this case we also call $\Gamma$ a separating complex of quasicircles. 

 As was shown in in \cite[Proposition 3.33]{Schippers_Staubach_scattering_I}, it turns out that one can identify the borders $\partial \riem_1$ and $\partial \riem_2$ pointwise with $\Gamma$. 

 Now fix a single quasicircle $\Gamma_k$ in the complex. Let $U_1$ and $U_2$ be collar neighbourhoods of $\Gamma_k$ in $\riem_1$ and $\riem_2$ respectively. In principle the set of CNT boundary values of harmonic functions in $\mathcal{D}_{harm}(U_1)$ might not agree with the set of boundary values of harmonic functions in $\mathcal{D}_{harm}(U_2)$.  In fact, it was shown in \cite{Schippers_Staubach_scattering_I} that they agree, so that we can denote this $\mathcal{H}(\Gamma_k)$.  

 More can be said.
  \begin{theorem}[Existence of overfare]\label{thm:bounded_overfare_existence}  Let $\mathscr{R}$ be a compact Riemann surface and let $\Gamma = \Gamma_1 \cup \cdots \cup \Gamma_m$ be a collection of  quasicircles separating $\mathscr{R}$ into $\riem_1$ and $\riem_2$. 
  Let $h_1 \in \mathcal{D}_{\mathrm{harm}}(\riem_1)$.  There is a $h_2 \in \mathcal{D}_{\mathrm{harm}}(\riem_2)$ whose \emph{CNT} boundary values agree with those of $h_1$ up to a null set, and this $h_2$ is unique.   
  \end{theorem}

    This theorem motivates the definition of the following operator which plays an important role in the scattering theory that is developed here.
  \begin{definition}\label{defn:overfare operator} 
Thus we can define the \emph{overfare operator} $\gls{overfare}_{\riem_1,\riem_2}$ by   
  \begin{align*}
   \mathbf{O}_{\riem_1,\riem_2} : \mathcal{D}_{\mathrm{harm}}(\riem_1) & \rightarrow 
   \mathcal{D}_{\mathrm{harm}}(\riem_2) \\
   h_1 & \mapsto h_2    
 \end{align*}
  \end{definition}
 One obviously has that
 \[  \mathbf{O}_{\riem_2,\riem_1} \mathbf{O}_{\riem_1,\riem_2} = \text{Id} \]
 and of course one can switch the roles of $\riem_1$ and $\riem_2$.  

 The overfare operator is conformally invariant.  That is, if $f:\mathscr{R} \rightarrow \mathscr{R}'$ is a biholomorphism and we set $f(\riem_k) = \riem_k'$ for $k=1,2$ then it follows immediately from conformal invariance of CNT limits that
 \begin{equation} \label{eq:overfare_conformally_invariant}
  \mathbf{O}_{\riem_1,\riem_2} \mathbf{C}_f = \mathbf{C}_f \mathbf{O}_{\riem_1',\riem_2'}.   
 \end{equation} 
 We use the abbreviated notation $\mathbf{O}_{1,2}$ and $\mathbf{O}_{2,1}$ when the underlying surfaces are clear from context.

 This operator is bounded under certain conditions \cite{Schippers_Staubach_scattering_I}. We summarize the main results here.one must assume that the originating surface is connected. 
 \begin{theorem}[Bounded overfare theorem for general quasicircles]\label{thm:bounded_overfare_Dirichlet} Let $\mathscr{R}$ be a compact Riemann surface and let $\Gamma = \Gamma_1 \cup \cdots \cup \Gamma_m$ be a collection of quasicircles separating $\mathscr{R}$ into $\riem_1$ and $\riem_2$.  Assume that $\riem_1$ is connected. 
  There is a constant $C$ such that 
     \[  \| \mathbf{O}_{1,2} h \|_{\mathcal{D}_{\mathrm{harm}}(\riem_2)}  \leq C \| h \|_{\mathcal{D}_{\mathrm{harm}}(\riem_1)}  \]
     for all $h \in \mathcal{D}_{\mathrm{harm}}(\riem_1)$.  
  \end{theorem}  


 If $\riem_1$ is connected and $c$ is a constant, then $\mathbf{O}_{\riem_1,\riem_2} c$ is also constant on $\riem_2$ so the operator
 \begin{equation} \label{eq:O_dot_definition}
 \gls{doto}_{\riem_1,\riem_2} : \dot{\mathcal{D}}_{\mathrm{harm}}(\riem_1) \rightarrow  \dot{\mathcal{D}}_{\mathrm{harm}}(\riem_2) 
 \end{equation}
 is well-defined.  

 \begin{remark}
 Note that it if the originating surface (say $\riem_1$) is not connected, this is not well-defined. For example, if $\riem_1$ consists of $n$ disks and $\riem_2$ is connected, then by choosing $h$ to be constant on the connected components of $\riem_1$, the overfare $\mathbf{O}_{1,2} h$ can be an arbitrary element of $\mathcal{A}_{\mathrm{harm}}(\riem_2)$.  
 \end{remark} 
 \begin{corollary}
  Let $\mathscr{R}$ be a compact Riemann surface, separated by quasicircles into $\riem_1$ and $\riem_2$.  Assume that $\riem_1$ is connected.  Then $\dot{\mathbf{O}}_{\riem_1,\riem_2}$ is bounded with respect to the Dirichlet norm.  
 \end{corollary}

 For more regular quasicircles, constants in the overfare process can be controlled.   
 A BZM (bounded zero mode) quasicircle $\gamma$ in $\mathscr{R}$ are quasicircles with the following property. Given an open neighbourhood $U$ of $\gamma$ and a conformal map $\phi:U \rightarrow V$ where $V$ is a doubly-connected domain in $\sphere$, let $\gamma'=\phi(\gamma)$ and denote the connected components of the complement by $\Omega_1$ and $\Omega_2$.  A BZM quasicircle is one such that overfare $\mathbf{O}_{\Omega_1,\Omega_2}$ is bounded from $H^1_{\mathrm{conf}}(\Omega_1)$ to $H^1_{\mathrm{conf}}(\Omega_2)$.  For such quasicircles one can remove the assumption of connectedness. 

 \begin{theorem}[Bounded overfare theorem for BZM quasicircles]\label{thm:bounded_overfare_conf}  Let $\mathscr{R}$ be a compact Riemann surface and let $\Gamma = \Gamma_1 \cup \cdots \cup \Gamma_m$ be a collection of \emph{BZM} quasicircles separating $\mathscr{R}$ into $\riem_1$ and $\riem_2$. 
  There is a constant $C$ such that 
     \[  \| \mathbf{O}_{1,2} h \|_{H^1_{\mathrm{conf}}(\riem_2)}  \leq C \| h \|_{H^1_{\mathrm{conf}}(\riem_1)}  \]
     for all $h \in \mathcal{D}_{\mathrm{harm}}(\riem_1)$.  
  \end{theorem}
\end{subsection}
\end{section}

\begin{section}{Schiffer and Cauchy-Royden operators} \label{se:Schiffer_Cauchy}
\begin{subsection}{Definitions of Schiffer and Cauchy operators}\label{subsec:defSchiffer} 
 In this section, we define the Schiffer and Cauchy-Royden operators, and prove their boundedness. We derive identities relating them, and demonstrate their bounedness. We also show that for quasicircles, the limiting integrals in the definition of the Cauchy-Royden operator are the same from either side, up to constants -- this point is analytically subtle, because quasicircles need not be rectifiable. This allows the formulation of a Plemelj-Sokhotski type result for quasicircles. 

Denote by $\mathscr{G}$ Green's function of $\mathscr{R}$, and let $G_{\Sigma_k}$ be Green's functions of $\riem_k$, $k=1,2$.   Here, if $\riem_k$ has more than one connected component, then $G_{\Sigma_k}$ stands for the function whose restriction to each connected component is the Green's function of that component.  


  First, we define the Schiffer operators.  
 To that end, we need to define certain bi-differentials, which will be the integral kernels of the Schiffer operators. 

 \begin{definition}
  For a compact Riemann surface $\mathscr{R}$ with Green's function $\mathscr{G}(w,w_0;z,q),$ the \emph{Schiffer kernel} is defined by
 \[  \gls{schifferk}_{\mathscr{R}}(z,w) =  \frac{1}{\pi i} \partial_z \partial_w \mathscr{G}(w,w_0;z,q),    \]
 and the \emph{Bergman kernel} is given by
 \[  \gls{bergmank}_{\mathscr{R}} (z,w) = - \frac{1}{\pi i} \partial_z \overline{\partial}_{{w}} \mathscr{G}(w,w_0;z,q).    \]


 For a non-compact surface $\riem$ of type $(g,n)$ with Green's function $g_\riem$, we define
 \[  L_\riem(z,w) =   \frac{1}{\pi i} \partial_z \partial_w G_\riem(w,z),  \]
 and 
 \[  K_\riem (z,w) = - \frac{1}{\pi i} \partial_z \overline{\partial}_{{w}}G_\riem(w,z).  \]
 \end{definition}


  The kernel functions satisfy the following:
 \begin{enumerate} 
  \item[$(1)$] $L_{\mathscr{R}}$ and $K_{\mathscr{R}}$ are independent of $q$ and $w_0$.  
  \item[$(2)$] $K_{\mathscr{R}}$ is holomorphic in $z$ for fixed $w$, and anti-holomorphic in $w$ for fixed $z$.
  \item[$(3)$] $L_{\mathscr{R}}$ is holomorphic in $w$ and $z$, except for a pole of order two when $w=z$.
\item[$(4)$] $L_{\mathscr{R}}(z,w)=L_{\mathscr{R}}(w,z)$.  
  \item[$(5)$] $K_{\mathscr{R}}(w,z)= - \overline{K_{\mathscr{R}}(z,w)}$.  
 \end{enumerate}

For non-compact Riemann surfaces $\riem$ with Green's function, $(2)-(5)$ hold with $L_{\mathscr{R}}$ and $K_{\mathscr{R}}$ replaced by $L_\riem$ and $K_\riem$. Moreover for any vector $v$ tangent to $\Gamma^{w}_{\varepsilon}$ at a point $z$, we have
  \begin{equation} \label{eq:level_curve_identity}
   \overline{K_\riem(z,w)}(\cdot,v) = -L_\riem(z,w)(\cdot,v).
  \end{equation} 
   Note that here we can treat the boundary as an analytic curve in the double, so that it makes sense to consider vectors tangent to the boundary.
 Also, the well-known reproducing property of the Bergman kernel holds, i.e.
 \begin{equation}  \label{eq:Bergman_reproducing}
  \iint_\riem K_\riem(z,w) \wedge h(w) = h(z),
 \end{equation}
 for $h \in A(\riem)$ \cite{Royden}.


Another basic fact about the kernels above is that they are conformally invariant.  That is, for a compact surface $\mathscr{R}$ and a biholomorphism $f:\mathscr{R} \rightarrow \mathscr{R}'$ we have 
 \begin{align} \label{eq:kernels_conformally_invariant_compact}
  (f^* \times f^*)  \; L_\mathscr{R'} & = L_{\mathscr{R}}  \nonumber \\
  (f^* \times f^*) \;  K_\mathscr{R'} & = K_{\mathscr{R}} 
 \end{align}
 and similarly, for surfaces $\riem$, $\riem'$ of type $(g,n)$ and a biholomorphism
 $f:\riem \rightarrow \riem'$, 
 \begin{align} \label{eq:kernels_conformally_invariant_gntype}
  (f^* \times f^*)  \; L_{\riem'} & = L_{{\riem}}  \nonumber \\
  (f^* \times f^*)\;  K_{\riem'} & = K_{{\riem}}.  
 \end{align}
 These follow immediately from conformal invariance of Green's function 
 (\ref{eq:Greens_conf_inv_compact},\ref{eq:Greens_conf_inv_gntype}).\\ 

 \begin{definition}\label{def: restriction ops}
For $k=1,2$ define the \emph{restriction operators}
 \begin{align*}
  \mathbf{R}_{\riem_k}:\mathcal{A}(\mathscr{R}) & \rightarrow \mathcal{A}(\riem_k) \\
  \alpha & \mapsto \left. \alpha \right|_{\riem_k}
 \end{align*}
 and 
 \begin{align*}
  \mathbf{R}^0_{\riem_k}: \mathcal{A}(\riem_1 \cup \riem_2) & \rightarrow \mathcal{A}(\riem_k) \\
    \alpha & \mapsto \left. \alpha \right|_{\riem_k}.
 \end{align*}
 \end{definition}

 It is obvious that these are bounded operators. In a similar way, we also define the restriction operator
 \[  \gls{harmrest}_{\riem_k} : \mathcal{A}_{\mathrm{harm}}(\mathscr{R}) \rightarrow \mathcal{A}_{\mathrm{harm}}(\riem_k).   \] 

Having the Bergman and Schiffer kernels and the restriction operators at hand, we can now define the Schiffer operators as follows.
\begin{definition}
For $k=1,2$, we define the {\it Schiffer comparison operators} by
 \begin{align*}
  \gls{T}_{\riem_k}: \overline{\mathcal{A}(\riem_k)} & \rightarrow \mathcal{A}(\riem_1 \cup \riem_2)  \\
  \overline{\alpha} & \mapsto \iint_{\riem_k} L_{\mathscr{R}}(\cdot,w) \wedge \overline{\alpha(w)}.
 \end{align*}
\\
and 
\begin{align*}
 \gls{S}_{\riem_k}: \mathcal{A}(\riem_k) & \rightarrow \mathcal{A}(\mathscr{R}) \\
  \alpha & \mapsto \iint_{\riem_k}  K_{\mathscr{R}}(\cdot,w) \wedge \alpha(w).
\end{align*}
The integral defining $\mathbf{T}_{\riem_k}$ is interpreted as a principal value integral whenever $z \in \riem_k$.  
Also, we define for $j,k \in \{1,2\}$
 \begin{equation}\label{defn: T sigmajsigmak}
     \gls{Tmix} = \mathbf{R}^0_{\riem_k} \mathbf{T}_{\riem_j}: \overline{\mathcal{A}(\riem_j)} \rightarrow \mathcal{A}(\riem_k). 
 \end{equation}   
\end{definition} 
 \begin{theorem} \label{th:Schiffer_operators_bounded}  $\mathbf{T}_{\riem_k}$, $\mathbf{T}_{\riem_j,\riem_k}$, and $\mathbf{S}_{\riem_k}$ are bounded for all $j,k =1,2$.  
 \end{theorem}
 \begin{proof}
The operator $\mathbf{T}_{\Sigma_k}$ is defined by integration against the $L_{\mathscr{R}}$-Kernel which in local coordinates $\zeta = f(z)$, $\eta = f(w)$ is given by 
\[  (f \times f)^*L_{\mathscr{R}}(\zeta,\eta) = \frac{d\zeta \, d \eta}{\pi(\zeta-\eta)^2} + \alpha(\zeta,\eta) \] where $\alpha$ is a holomorphic bi-differential. Since the singular part of the kernel is a Calder\'on-Zygmund kernel we can use the theory of singular integral operators to conclude that the operators with kernel $L_\mathscr{R}(z,w)$ are bounded on $L^2$.  The same proof applies to $L_{\riem}$. The boundedness of $\mathbf{T}_{\riem_j, \riem_k}$ follows from this and the fact that $\mathbf{R}
^0_{\riem_k}$ is also bounded.\\
That the operator $\mathbf{S}_{\Sigma_k}$ is bounded and its image is $\mathcal{A}(\mathscr{R}),$  can be seen from the fact that the kernel $K_{\mathscr{R}}(., w)$ is holomorphic in $w$ and $\mathscr{R}$ is compact.
 \end{proof}

{\bf{Notation.}} As in the case of the overfare operator $\mathbf{O}$, we will use the notations 
 \[  \mathbf{S}_k, \ \ \mathbf{T}_{j,k}, \ \ \mathbf{T}_k, \ \ \mathbf{R}_{k}, \ \  \mathbf{P}_k=\mathbf{P}_{\riem_k}, \]
 wherever the choice of surfaces $\riem_1$ and $\riem_2$ is clear from context.\\

For any operator $\mathbf{M}$, we define the complex conjugate operator by 
 \[  \overline{\mathbf{M}} \overline{\alpha} = \overline{\mathbf{M} \alpha}  \]
 So for example 
 \[   \overline{\mathbf{T}}_{1,2}:\mathcal{A}(\riem_1) \rightarrow \overline{\mathbf{A}(\riem_2)} \]
 and similarly for $\overline{\mathbf{R}}_{\riem_k}$, etc.  

 The restriction operator is conformally invariant by conformal invariance of Bergman space of one-forms. 
 By (\ref{eq:kernels_conformally_invariant_compact}), the operators $\mathbf{T}$ and $\mathbf{S}$ are also conformally invariant.  Explicitly, if $f:\mathscr{R} \rightarrow \mathscr{R}'$ is a biholomorphism between compact surfaces, and we denote
 $\riem_k'= f(\riem_k)$ for $k=1,2$, then 
 \begin{align}  \label{eq:Schiffer_operators_conformally_invariant}
   f^* \; \mathbf{R}_{\riem_k'} & = \mathbf{R}_{\riem_k} \; f^* \nonumber \\
   f^*  \; \mathbf{R}^0_{\riem_k'} & = \mathbf{R}^0_{\riem_k} \; f^* \nonumber \\
   f^* \; \mathbf{T}_{\riem_k'} & = \mathbf{T}_{\riem_k}\; f^* \\
   f^* \; \mathbf{T}_{\riem_j',\riem_k'} & = \mathbf{T}_{\riem_j,\riem_k} \; f^* \nonumber \\ 
   f^* \; \mathbf{S}_{\riem_k'} & = \mathbf{S}_{\riem_k} \; f^*. \nonumber
 \end{align}

 The following basic lemma which we will used frequently in this paper, is crucial in establishing some of the forthcoming identities concerning Schiffer and Bergman kernels.
\begin{lemma} \label{le:limiting_circle_Schiffer_identity}  Fix 
 a  point $z$ and local coordinates $\phi$ near $z$.  Let $\gamma_r$ be a curve such that $|\phi(w)-\phi(z)|=r$.  Then 
 for any holomorphic one-form $\alpha$ defined near $z$, and fixed $q$, we have 
 \[   \lim_{r \searrow 0} \int_{\gamma_r,w} \frac{1}{\pi i} \partial_z \mathscr{G}(w;z,q) \overline{\alpha(w)}=0    \]
 and
 \[   \lim_{r \searrow 0} \int_{\gamma_r,w} \frac{1}{\pi i} \partial_z \mathscr{G}(w;z,q)  {\alpha(w)}= \alpha(z).    \]
 Similarly for $z \in \riem_k$ we have 
 \[   \lim_{r \searrow 0} \int_{\gamma_r,w} \frac{1}{\pi i} \partial_z {G}_{\Sigma_k}(w;z) \overline{\alpha(w)}=0    \]
 and
 \[   \lim_{r \searrow 0} \int_{\gamma_r,w} \frac{1}{\pi i} \partial_z {G}_{\Sigma_k}(w;z)  {\alpha(w)}= \alpha(z).    \]
\end{lemma}
\begin{proof}
 In coordinates denote $\phi(w)=\zeta$ and $\phi(z)=\eta$.  We have, writing $\alpha(w) = h(\zeta)d\zeta$ (with $h$ holomorphic)
 and observing that  
 \[ \partial_z \mathscr{G}(w;z,q) = G_\eta(\zeta) d\eta  + \frac{1}{2}\frac{1}{\zeta-\eta}d\eta    \]
 where $G_\eta(\zeta)$ is non-singular at $\eta$, 
 \begin{align*}
  \lim_{r \searrow 0} \int_{\gamma_r,w} \frac{1}{\pi i} \partial_z \mathscr{G}(w;z,q)  {\alpha(w)} & = 
     \lim_{r \searrow 0} \int_{|\zeta-\eta|=r,\zeta} \frac{1}{2 \pi i} \frac{d\zeta}{\zeta-\eta} h(\zeta) d\eta = h(\eta) d\eta 
     \\ & = \alpha(z).
 \end{align*}
 Similarly 
 \begin{align*}
  \lim_{r \searrow 0} \int_{\gamma_r,w} \frac{1}{\pi i} \partial_z \mathscr{G}(w;z,q) \overline{\alpha(w)} & = 
     \lim_{r \searrow 0} \int_{|\zeta-\eta|=r,\zeta} \frac{1}{2 \pi i} \frac{d\overline{\zeta}}{\zeta-\eta} \overline{h(\zeta)} d {\eta} 
     \\ & = 0
 \end{align*}
 by writing a power series expansion of $h$ and integrating in polar coordinates.  The proof for $g_k$ is identical. 
\end{proof}


 We will frequently use the following identity, which we refer to as \emph{Schiffer's identity}.
 \begin{theorem}  \label{th:Schiffer_vanishing_identity}  Let $\riem$ be a bordered surface of type $(g,n)$.  
  For all $\overline{\alpha} \in \overline{\mathcal{A}(\riem)}$ 
  \[   \iint_{\riem,w}  L_\riem(z,w) \wedge \overline{\alpha(w)}=0. \]
 \end{theorem}
 \begin{proof} Let $\riem$ be embedded in its double $\riem^d$, so that the boundary is an analytic curve.  Fixing $z \in \riem$ and applying Stokes' theorem we then have
 \[ \iint_{\riem} L_\riem(z,w) \overline{\alpha(w)} = \int_{\partial \riem} \frac{1}{\pi i} \partial_z G_{\riem}(z;w) \overline{\alpha(w)} - \lim_{r \searrow 0}\int_{\gamma_{r,w}}
 \frac{1}{\pi i} \partial_z G_{\riem}(z;w) \overline{\alpha(w)}    \]
 with $\gamma_{r,w}$ as in Lemma \ref{le:limiting_circle_Schiffer_identity}. 
 The claim now follows from Lemma \ref{le:limiting_circle_Schiffer_identity} and the fact that for any fixed $z$, $\partial_z g_k(z;w)$ vanishes for all $w \in \partial \riem$.
 \end{proof} 
 This implies that  
 \begin{equation}  \label{eq:nonsingular_Schiffer}
  \mathbf{T}_{1,1} \alpha(z)= \iint_{\riem_1,w} \left(L_\mathscr{R}(z,w) - L_{\riem_1}(z,w) \right) 
  \wedge \overline{\alpha(w)}.  \end{equation}
 This desingularizes the kernel function, and will be useful below in some of the proofs. Incidentally, it also gives a direct way to see that the principal value integral defining $\mathbf{T}_{1,1}$ is independent of the choice of local coordinate, even though the omitted disks in the integral depend on this choice.  


\begin{example} \label{ex:sphere_kernels}
 If $\mathscr{R}$ is the Riemann sphere $\sphere$, we have
 \[  \mathscr{G}(w,\infty;z,q) = - \log{ \frac{|w-z|}{|w-q|}}.     \]
 Thus
 \[  K_{\sphere}(z,w) =0  \]
 and
 \[  L_{\sphere}(z,w) = - \frac{1}{2 \pi i} \frac{dw \,dz}{(w-z)^2}.  \]
 So the Schiffer operators are given by, for $\overline{\alpha(z)} = \overline{h(z)}d \bar{z}$,
 \[  \ \mathbf{T}_1  \, \overline{\alpha} (z) =
    \frac{1}{\pi} \iint_{\riem_1} \frac{\overline{h(w)}}{(w-z)^2} \frac{d\bar{w} 
    \wedge d w}{2i}  \cdot dz  \]
 and $\mathbf{S}_k=0$, $k=1,2$.    

 By the uniformization theorem, if $\mathscr{R}$ is a compact surface of genus zero, it is biholomorphic to $\sphere$.  Thus by conformal invariance of the Schiffer kernels \eqref{eq:kernels_conformally_invariant_compact} we see that $K_{\mathscr{R}}=0$ and $\mathbf{S}_k=0$.   
 \end{example}    
 \begin{example} \label{ex:disk_kernels}    
  For $\riem = \disk$, we have
 \[  \mathscr{G}(z,w) = - \log{\frac{|z-w|}{|1-\bar{w}z|}}.  \]
 So
 \[  L_{\disk}(z,w) = \frac{-1}{2\pi i} \frac{dw \, dz}{(w-z)^2}    \]
 and 
 \[  K_{\disk}(z,w) = \frac{1}{2\pi i}  \frac{d\overline{w} \, dz}{(1-\bar{w}z)^2}. \]

 For a M\"obius transformation $M$, we can verify the identities
 \[   \frac{M'(w) M'(z)}{(M(w)-M(z))^2} = \frac{1}{(z-w)^2}     \]
 and 
 \[  \frac{\overline{M'(w)} M'(z)}{(1-\overline{M(w)}M(z))^2} = \frac{1}{(1-\bar{w}z)^2}. \]
 By conformal invariance of the Schiffer kernels (\ref{eq:kernels_conformally_invariant_gntype}) we see that for any disk or half plane $U$
 \[  L_{U}(z,w) = \frac{-1}{2\pi i} \frac{dw \, dz}{(w-z)^2}    \]
 and 
 \[  K_{U}(z,w) = \frac{1}{2\pi i}  \frac{d\overline{w} \, dz}{(1-\bar{w}z)^2}. \]
\end{example}    

 Next we consider a kind of Cauchy operator defined using Green's function.  This operator involves integrals over the separating quasicircles, which are not in general rectifiable.  So we define the integral using limits along analytic curves which approach the quasicircle.  This is well-defined by the Anchor Lemmas \cite[Lemmas 3.14 and 3.15]{Schippers_Staubach_scattering_I}. Furthermore for quasicircles, up to constants, this limit does not depend on the side from which the curve is approached.  This significant fact, which depends on the bounded overfare theorem, is one of the motivations for the use of quasicircles throughout the paper.    
 We now define the Cauchy operators.

   \begin{definition}
   Let $A = A_1 \cup \cdots \cup A_n$ be a union of non-intersecting collar neighbourhoods of $\Gamma$ in $\riem_1$. For $q \in \mathscr{R} \backslash \Gamma$ and $h \in \mathcal{D}_{\mathrm{harm}}(A)$  define, for $z \in \mathscr{R} \backslash \Gamma$, the \emph{Cauchy-{Royden} operator} by
  \begin{align}  \label{eq:J_definition}
      \gls{crop}(\Gamma) h(z) = {-} {\frac{1}{\pi i}} \int_{\partial \riem_1} \partial_w \mathscr{G}(w;z,q) h(w) = {-} {\frac{1}{\pi i}} \sum_{k=1}^n 
      \int_{\partial_k \riem_1} \partial_w \mathscr{G}(w;z,q) h(w),
  \end{align} 

and the \emph{restricted Cauchy-Royden operators} by
\begin{equation}
    \gls{rcrop}(\Gamma)=\mathbf{J}_1^q(\Gamma) h |_{\riem_k}
\end{equation}
where, as will be shown later,  $\mathbf{J}_1^q(\Gamma):\mathcal{D}_{\mathrm{harm}}(\riem_1) \rightarrow \mathcal{D}_{\mathrm{harm}}(\riem_1 \cup \riem_2)$ and $\mathbf{J}_{1,k}^q(\Gamma): \mathcal{D}_{\mathrm{harm}}(\riem_1) \rightarrow \mathcal{D}_{\mathrm{harm}}(\riem_k).$

\end{definition} 
    Note that by Definition \ref{de:separating_complex} and \cite[Proposition 2.17]{Schippers_Staubach_scattering_I} non-intersecting collections of collar charts exist, and the integral exists by the first anchor lemma \cite[Lemma 3.14]{Schippers_Staubach_scattering_I}. 

 The Cauchy operator is closely related to the Schiffer operators, as the following theorem shows. 
 { \begin{theorem}  \label{th:jump_derivatives}  
  For all $h \in \mathcal{D}_{\mathrm{harm}}(\riem_1)$ and any $q \in \mathscr{R} \backslash \Gamma$, 
   \begin{align*}
    \partial \mathbf{J}_{1} ^q(\Gamma)h(z)   & = \mathbf{T}_{1,2} \overline{\partial} h(z),\, \, \, z\in \riem_2  \\
    \partial \mathbf{J}_{1}^q(\Gamma)  h(z) & = \partial h + \mathbf{T}_{1,1} \overline{\partial} h,\, \, \, z\in \riem_1   \\
    \overline{\partial} \mathbf{J}_{1}^q(\Gamma) h(z) & = \overline{\mathbf{S}}_1 \overline{\partial} h(z),\, \, \, z\in \riem_1 \cup \riem_2 
   \end{align*}
  \end{theorem}
  }
  \begin{remark}
   There is a sign error in \cite{Schippers_Staubach_Plemelj}, {which is corrected here.}
  \end{remark}
  \begin{proof}
    { Assume first that $q \in \riem_2$. The first claim follows from the application of the Stokes theorem to \eqref{eq:J_definition} and the fact that the integrand is non-singular.  Similarly for $q,z \in \riem_2$, the third claim follows 
    from the same reasoning.  

    The second claim also follows from Stokes theorem, namely if $\Gamma_\varepsilon$ are curves given by $|w-z|=\varepsilon$ in local coordinates, positively oriented with respect to $z$,
    \begin{align} \label{eq:add_q_temp}
     \partial \mathbf{J}_{1} ^q(\Gamma)h(z) & = \partial_z \left( - \frac{1}{\pi i} \lim_{\varepsilon \searrow 0}
     \int_{\Gamma_\varepsilon} (\partial_w \mathscr{G}(w;z,q) - \partial_w G_{\Sigma_1}(w,z) )\,h(w) \right) \nonumber \\
     & \ \ \ \   -   \partial_z \lim_{\varepsilon \searrow 0} \frac{1}{\pi i} \int_{\Gamma_\varepsilon}
     \partial_w G_{\Sigma_1} (w,z) \,h(w) \nonumber\\
     & = \partial_z \left(  \frac{1}{\pi i}  
     \iint_{\riem_1} (\partial_w \mathscr{G}(w;z,q) - \partial_w G_{\Sigma_1}(w,z) )\wedge_w \overline{\partial} h(w) \right) \nonumber \\
     & \ \ \ \  - \partial_z \lim_{\varepsilon \searrow 0} \frac{1}{\pi i} \int_{\Gamma_\varepsilon}
     \partial_w G_{\Sigma_1} (w,z) \,h(w) \nonumber\\
     & = \frac{1}{\pi i}  
     \iint_{\riem_1} (\partial_z \partial_w \mathscr{G}(w;z,q) - \partial_z \partial_w G_{\Sigma_1}(w,z) )
      \wedge_w \overline{\partial} h(w)  + \partial h(z) 
    \end{align}
    where we have used the harmonicity of $h$. Derivation under the integral sign in the first term is justified by the fact that the integrand
    of the first term is non-singular and holomorphic in $z$ for each $w\in \riem_1$, and that $$\iint_{\riem_1, w}|( \partial_w \mathscr{G}(w;z,q) - \partial_w G_{\Sigma_1}(w,z) ) \wedge_w \overline{\partial}_{{w}} h(w)|$$ is locally bounded in $z$. 

    Similarly removing the singularity using $\partial_w G_{\riem_1}$, and then using the harmonicity of $h$ and Stokes' theorem yield that
    \begin{align*}
      \overline{\partial} \mathbf{J}_{1} ^q(\Gamma) h(z) & = - \overline{\partial}_{{z}} \frac{1}{\pi i} \lim_{\varepsilon \searrow 0}
     \int_{\Gamma_\varepsilon} ( \partial_w \mathscr{G}(w;z,q) -  \partial_w G_{\Sigma_1}(w,z) )\,h(w)  + \overline{\partial} h(z) \\
     & =  \frac{1}{\pi i} \iint_{\riem_1}(\overline{\partial}_{{z}} \partial_w \mathscr{G}(w;z,q) - \overline{\partial}_{{z}} \partial_w G_{\Sigma_1}(w,z) ) \wedge_w \overline{\partial}_{{w}} h(w)  + \overline{\partial} h(z).
    \end{align*}
    The third claim now follows by observing that the second term in the integral is just $- \overline{\partial} h$ because the integrand is just the complex conjugate of the Bergman kernel.

    Now assume that $q \in \riem_1$.  We show the second claim in the theorem.  We argue as in equation (\ref{eq:add_q_temp}), except that we must also add 
    a term $\partial_w G_{\Sigma_1}(w;q) h(w)$.  We obtain instead
    \[ \partial \mathbf{J}_{1} ^q(\Gamma)h(z)=  \frac{1}{\pi i} 
     \iint_{\riem_1} (\partial_z \partial_w \mathscr{G}(w;z,q) - \partial_z \partial_w G_{\Sigma_1}(w;z) )
      \wedge_w \overline{\partial}_{{w}} h(w)  + \partial_z \left( h(z) + h(q) \right)  \]
     and the claim follows from $\partial_z h(q) =0$. The remaining claims follow similarly.} 
  \end{proof}

  Combining this with Theorem \ref{th:Schiffer_operators_bounded}, we obtain
  \begin{theorem}   \label{th:jump_bounded_Dirichlet}
   $\mathbf{J}_1^q(\Gamma):\mathcal{D}_{\mathrm{harm}}(\riem_1) \rightarrow \mathcal{D}_{\mathrm{harm}}(\riem_1 \cup \riem_2)$ 
   is bounded with respect to the Dirichlet seminorm. 
  \end{theorem}
  Of course, the roles of the surfaces $\riem_1$ and $\riem_2$ can be switched.\\  


  It follows from conformal invariance of Green's functions (\ref{eq:Greens_conf_inv_compact},\ref{eq:Greens_conf_inv_gntype}) and Dirichlet space that the Cauchy-Royden operator $\mathbf{J}$ is conformally invariant.  That is,
  if $f:\mathscr{R} \rightarrow \mathscr{R}'$ is a biholomorphism between compact surfaces, $\Gamma' = f(\Gamma)$, and $\riem_k' = f(\riem_k)$ for $k=1,2$, then 
  \begin{equation} 
    \mathbf{C}_f \mathbf{J}_k(\Gamma') = \mathbf{J}_k (\Gamma)  \mathbf{C}_f 
  \end{equation}
  which of course implies the same for $\mathbf{J}_{j,k}(\Gamma)$ and $\mathbf{J}_{j,k}(\Gamma')$ for $j,k=1,2$. 


  The operator $\mathbf{J}_1^q$ is in fact bounded with respect to the $H^1_{\text{conf}}$-norm.  
  \begin{theorem} \label{th:J_bounded_Hconf}
   $\mathbf{J}^q_{1,k}(\Gamma):H^1_{\mathrm{conf}}(\riem_1) \rightarrow H^1_{\mathrm{conf}}(\riem_k)$ is bounded for $k=1,2$. 
  \end{theorem}
  Note that strictly speaking, this is not stronger than Theorem \ref{th:jump_bounded_Dirichlet}, since that theorem shows that the $H^1_{\mathrm{conf}}$-norm is not necessary to control the Dirichlet norm of the output. 

  The proof requires a lemma.   
  \begin{lemma} \label{le:difference_Greens_in_Dirichlet} Let $g_1$ denote Green's function of $\riem_1$ 
   for  $k=1$ and $\mathscr{G}$ denote Green's function of $\mathscr{R}$.  Then for any fixed $p \in \riem_1$ and $q \in \riem_2$
   \[  \partial_w \mathscr{G}(w,w_0;p,q) - \partial_w G_{\Sigma_1}(w;p) \in \mathcal{A}_{\mathrm{harm}}(\riem_1).     \]
   If $q \in \riem_1$ then 
    \[  \partial_w \mathscr{G}(w,w_0;p,q) - \partial_w G_{\Sigma_1}(w;p) + \partial_w G_{\Sigma_1}(w;q) \in \mathcal{A}_{\mathrm{harm}}(\riem_1).     \]
   The same holds with $1$ and $2$ switched. 
  \end{lemma}
  \begin{proof}
   By definitions of $\mathscr{G}$ and $g_1$, this is a non-singular harmonic function on $\riem_1$.  So it suffices to show that the function is in $\mathcal{A}_{\mathrm{harm}}(A)$ for some collar neighbourhood of $A= A_1\cup \cdots \cup A_n$ of $\partial \riem_1$. 
   The first term $\partial_w \mathscr{G}(w,w_0;p,q)$ is obviously in $\mathcal{A}_{\mathrm{harm}}(A)$ since it is holomorphic on an open neighbourhood of the closure of $A$. By conformal invariance of Green's function and the Bergman norm, the second term can be evaluated on the double $\riem^d$, where the boundary $\partial \riem$ is then an analytic curve.  Assuming that the inner boundary of $A$ consists of $n$ analytic curves $\Gamma = \Gamma_1 \cup \cdots \cup \Gamma_n$ we get 
   \[ \iint_{A} \partial_{\bar{w}} G_{\Sigma_1}(w;p) \wedge_w \partial_w G_{\Sigma_1}(w;p) = - \int_{\Gamma} G_{\Sigma_1}(w;p)\,  \partial_w G_{\Sigma_1}(w;p) <\infty  \]
   where we have used Stokes' theorem and the fact that $g_1$ vanishes on $\partial \riem_1$.  The proof for $q \in \riem_1$ is similar.
  \end{proof}





  We can now prove Theorem \ref{th:J_bounded_Hconf}.
  \begin{proof}(of Theorem \ref{th:J_bounded_Hconf}.)  
   By Theorem \ref{th:jump_bounded_Dirichlet} and \cite[Lemma 3.21]{Schippers_Staubach_scattering_I}, to prove that $\mathbf{J}_{1,k}^q$ is bounded, it's enough to show that for a $p$ in one of the connected components of $\riem_k$, $|(\mathbf{J}_{1,k}^q h)(p)| \lesssim \| h \|_{H^1_{\mathrm{conf}}}.$ 

   We first do the case of $\mathbf{J}_{1,1}^q$. First assume that $q \in \riem_2$, and $p \in \riem_1$. Then, we have using the reproducing property of Green's function (see \cite[Proposition 3.19]{Schippers_Staubach_scattering_I} for the proof in this analytic setting) and Stokes' theorem 
   \begin{align*}
     \mathbf{J}_{11}^q h(p) & = - \lim_{\epsilon \searrow 0} \frac{1}{\pi i}  \int_{\Gamma_\epsilon} \partial_w \mathscr{G}(w;p,q)h(w) \\
     & =  \lim_{\epsilon \searrow 0} \frac{1}{\pi i}  \int_{\Gamma_\epsilon} \left( - \partial_w \mathscr{G}(w;p,q) 
     + \partial_w G_{\Sigma_1}(w;p) \right) h(w) + h(p) \\
     & =   \frac{1}{\pi i}  \iint_{\riem_1} \left( \partial_w \mathscr{G}(w;p,q) 
     - \partial_w G_{\Sigma_1}(w;p) \right) \wedge_w \overline{\partial} h(w) + h(p). \\
   \end{align*}
   By \cite[Lemma 3.21]{Schippers_Staubach_scattering_I} we have $|h(p)|\leq \| h \|_{H^1_{\mathrm{conf}}(\riem_1)}$, and by Cauchy-Schwarz and Lemma 
   \ref{le:difference_Greens_in_Dirichlet} we obtain
   \[  \left|  \frac{1}{\pi i}  \iint_{\riem_1} \left( \partial_w \mathscr{G}(w;p,q) 
     - \partial_w G_{\Sigma_1}(w;p) \right) \wedge_w \overline{\partial} h(w)\right| \leq C \| \overline{\partial} h \|_{\mathcal{A}_{\mathrm{harm}}(\riem_2)} \leq C \| h \|_{H^1_{\mathrm{conf}}(\riem_1)}.  \]
    If on the other hand $q \in \riem_1$, the claim follows similarly from the second part of Lemma \ref{le:difference_Greens_in_Dirichlet} and  
    \[  \mathbf{J}_{11}^q h(p) = \frac{1}{\pi i}  \iint_{\riem_1} \left( \partial_w \mathscr{G}(w;p,q) 
     - \partial_w G_{\Sigma_1}(w;p) + \partial_w G_{\Sigma_1}(w;q) \right) \wedge_w \overline{\partial} h(w) + h(p) - h(q).  \] 
     Because any point can be used in \cite[Lemma 3.21]{Schippers_Staubach_scattering_I} to obtain a norm equivalent to the $H^1_{\mathrm{conf}}$ norm, it holds that $|h(q)| \lesssim \| h \|_{H^1_{\mathrm{conf}(\riem_1)}}$ for the norm determined by $p$. 

     Now we estimate $\mathbf{J}_{12}^q$. If $q \in \riem_2$, then for $p \in \riem_2$ we have similarly by Stokes' theorem
     \[  \left| (\mathbf{J}_{11}^q h)(p) \right| = \left| 
       \lim_{\epsilon \searrow 0} \frac{1}{\pi i}  \iint_{\riem_1} \partial_w \mathscr{G}(w;p,q)\wedge_w \overline{\partial} h(w) \right|     \]
     so the claim follows once again by Cauchy-Schwarz and the fact that $\partial_w \mathscr{G}(w;p,q) \in \mathcal{D}(\riem_1)$ for $p,q \in \riem_2$.  
     The case that $q \in \riem_1$ can be dealt with as above.
  \end{proof}


  Like the Cauchy integral, this operator reproduces holomorphic functions (up to constants).
  \begin{theorem} \label{th:jump_on_holomorphic}
   Assume that $h \in \mathcal{D}(\riem_1)$.  If $q \in \riem_1$, 
   let $c_q(z)$ be the function which is equal to $h(q)$ in the connected component of $\riem_k$ containing $q$ and $0$ otherwise.  
   Then 
   \[   \mathbf{J}^q_{1,1} h (z) = \left\{  \begin{array}{ll} h(z) - c_q(z)  & q \in \riem_1 \\
      h(z)   & q \in \riem_2 \end{array} \right. \]
   and 
   \[  \mathbf{J}^q_{1,2} h (z) = \left\{  \begin{array}{ll} - c_q(z)  & q \in \riem_1 \\
      0  & q \in \riem_2 \end{array} \right.  \]
   This holds with the roles of $1$ and $2$ interchanged.
  \end{theorem}
  \begin{proof}  
   Since $h \in \mathcal{D}(\riem_1)$, the integrand of $\mathbf{J}^q_1 h$ is holomorphic, except for possible singularities at $z$ and $q$ depending on their locations. 
   If $z$ is contained in $\riem_1$, and $C_r$ are curves given by $|w-z|=r$ in local coordinates, positively oriented with respect to $z$, then 
   \[  - \frac{1}{\pi i} \lim_{r \searrow 0}  \int_{C_r} \partial_w \mathscr{G}(w;z,q) h(w) = h(z)    \]
   and if $q$ is in $\riem_1$ and $C_r$ are the curves $|w-q|=r$ then 
   \[   - \frac{1}{\pi i} \lim_{r \searrow 0}  \int_{C_r} \partial_w \mathscr{G}(w;z,q) h(w) = -h(q).    \]
   The claim follows from Stokes' theorem applied to the connected components of $\riem_1$.  
  \end{proof}
  In particular, for any $q \notin \Gamma$, and any locally constant function $c$,  $\mathbf{J}^q_1 c$ is also locally constant.  Thus we obtain a well-defined operator 
  \[  \gls{Jdot}: \dot{\mathcal{D}}_{\mathrm{harm}}(\riem_1) \rightarrow   \dot{\mathcal{D}}(\riem_1 \cup \riem_2).  \]
  The Dirichlet norm becomes a seminorm on the homogeneous space, and $\dot{\mathbf{J}}_1$ is bounded with respect to this norm. It is easily verified that $\dot{\mathbf{J}}_1$ is independent of $q$. 




   Next we will prove some results about the interaction with $\mathbf{J}_1^q$ with the bounce and overfare operators. 
  \begin{proposition} \label{prop:J_agrees_with_bounce} Let $A= A_1 \cup \cdots \cup A_n$ be a union of collar neighbourhoods $A_k$ of $\Gamma_k$ in $\riem$.  For $h \in \mathcal{D}_{\mathrm{harm}}(A)$ 
  \[   \mathbf{J}_1^q(\Gamma) h  = \mathbf{J}_1^q(\Gamma) \mathbf{G}_{A,\riem_1} h.     \]
  \end{proposition}
  \begin{proof}
    The kernel $\partial_w \mathscr{G}(w;z)$ is holomorphic in $w$ in an open neighbourhood of the boundary $\Gamma$, so $\partial_w \mathscr{G}(w;z) \in \mathcal{A}(A)$. The claim now follows from the second anchor lemma \cite[Lemma 3.15]{Schippers_Staubach_scattering_I}.
  \end{proof}
  \begin{remark} In fact, this applies for any collection of strip-cutting Jordan curves, but we do not require this here.
  \end{remark}
  A deeper result is that for quasicircles, the limiting integral is the same from both sides up to constants; for BZM quasicircles, they are the same. 
  \begin{theorem}  \label{th:J_same_both_sides} The following statements hold:\\
   \begin{enumerate} 
   \item [$(1)$] If $\Gamma$ consists of \emph{BZM} quasicircles, then 
   for any $h \in \mathcal{D}_{\mathrm{harm}}(\riem_1)$
    \[ \mathbf{J}_1^q(\Gamma) h = - \mathbf{J}_2^q(\Gamma) \mathbf{O}_{1,2} h.  \] 
  \item [$(2)$] If $\riem_1$ is connected and $\Gamma$ is an arbitrary complex of quasicircles, then for any $\dot{h} \in \dot{\mathcal{D}}_{\mathrm{harm}}(\riem_1)$
   \[ \dot{\mathbf{J}}_1(\Gamma) \dot{h} = - \dot{\mathbf{J}}_2(\Gamma) \dot{\mathbf{O}}_{1,2} \dot{h}.  \] 
  \end{enumerate}
  \end{theorem}
  \begin{proof} We prove first claim.
   Choose doubly-connected neighbourhoods $U_1,\ldots,U_n$ of the boundary curves $\Gamma$ with charts $\phi_m:U_m \rightarrow \mathbb{A}_m$, where each $\mathbb{A}_m = \{z : r_m < |z|<R_m \}$ is an annular region in the plane. For $k=1,2$ let $A_m^k = U_m \cap \riem_k$ be collar neighbourhoods of $\Gamma$ in $\riem_k$, and set $B_m^k=\phi_m(A_m^k)$.  We claim that $\mathcal{D}_{\text{harm}}(U_m)$ is dense in
   $\mathcal{D}_{\text{harm}}(A^k_m)$ for each $k=1,\ldots,n$ with respect to the $H^1_{\mathrm{conf}}$ norms. 
   By conformal invariance of the $H^1_{\mathrm{conf}}$-norm, it is enough to prove that $\mathcal{D}_{\mathrm{harm}}(\mathbb{A}_m)$ is dense in $\mathcal{D}_{\mathrm{harm}}(B_m^k)$. 
   This follows immediately from the fact that polynomials 
   \[ p(z) = \sum_{l=s}^t z^{l}, \ \ s,t \in \mathbb{Z}, t\geq s   \]
   are dense in both $\mathcal{D}(\mathbb{A}_m)$ and $\mathcal{D}(B_m^k)$.

   Now let $h \in \mathcal{D}_{\text{harm}}$, and let $\Gamma_\epsilon^k$ be the level sets of Green's function $g_k$ for $k=1,2$, which are analytic curves for $\epsilon$ sufficiently close to zero. Letting $E_\epsilon$ be the region enclosed by these analytic curves, we have 
   \[ - \frac{1}{\pi i} \int_{\Gamma^2_\epsilon} \partial_w \mathscr{G}(w;z,q) \,h(w) -  \frac{1}{\pi i} \int_{\Gamma^1_\epsilon} \partial_w \mathscr{G}(w;z,q) \,h(w)  =  \iint_{E_\epsilon} \partial_w \mathscr{G}(w;z,q) \wedge_w \overline{\partial} h(w)  \]
   (note that the reversal of orientation of the contour integrals is taken into account). 
   Applying the Cauchy-Schwarz inequality to the right hand side we get 
   \[ \left| \frac{1}{\pi i} \int_{\Gamma^2_\epsilon} \partial_w \mathscr{G}(w;z,q) \,h(w) +  \frac{1}{\pi i} \int_{\Gamma^1_\epsilon} \partial_w \mathscr{G}(w;z,q) \,h(w) \right| \leq   \|\partial_w \mathscr{G}(w;z,q) \|_{\mathcal{A}_{\mathrm{harm}}(E_\epsilon)}   \| \overline{\partial} h(w) \|_{\mathcal{A}_{\mathrm{harm}}(E_\epsilon)}.   \]
   Since quasicircles have measure zero and $\cap_\epsilon E_\epsilon = \Gamma$, the right hand side goes to zero as $\epsilon \searrow 0$.  Thus
   \[ - \lim_{\epsilon \searrow 0} \frac{1}{\pi i} \int_{\Gamma^2_\epsilon} \partial_w \mathscr{G}(w;z,q) \,h(w) = \lim_{\epsilon \searrow 0}  \frac{1}{\pi i} \int_{\Gamma^1_\epsilon} \partial_w \mathscr{G}(w;z,q) \,h(w). \]  
   Now set $U=U_1 \cup \cdots U_n$ and $A^k=A^k_1 \cup \cdots \cup A^k_n$ and assume that $h \in \mathcal{D}_{\mathrm{harm}}(U)$.
   Using the above, together with the second anchor lemma \cite[Lemma 3.15]{Schippers_Staubach_scattering_I} and the fact that $\mathbf{G}_{A^2,\riem_2} h = \mathbf{O}_{1,2}\mathbf{G}_{A^1,\riem_1} h$, we have
   \begin{align} \label{eq:thingy_temp}
       \mathbf{J}_1^q \mathbf{G}_{A^1,\riem_1} h & = \mathbf{J}_1^q h = - \mathbf{J}_2^q h \nonumber \\
       & = -\mathbf{J}_2^q \mathbf{G}_{A^2,\riem_2} h \nonumber \\
       & = -\mathbf{J}_2^q \mathbf{O}_{1,2} \mathbf{G}_{A^1,\riem_1} h.
   \end{align}
   The proof is completed by the density of $H^1_{\text{conf}}(U)$ in $H^1_{\text{conf}}(A^1)$, the density of $\mathbf{G}_{A^1,\riem_1} H^1_{\text{conf}}(A^1)$ in $H^1_{\text{conf}}(\riem_1)$ \cite[Theorem 3.29]{Schippers_Staubach_scattering_I}, and the boundedness of $\mathbf{J}^q_k$, $\mathbf{O}_{1,2}$, and $\mathbf{G}_{A^k,\riem_k}$ (Theorems \ref{th:J_bounded_Hconf}, \ref{thm:bounded_overfare_conf}, and \ref{th:bounce_bounded}).  

   {The proof of the second claim follows the same line, but requires a bit of care with the constants. First, observe that 
   \[  \mathbf{G}_{A^1,\riem_1} :\mathcal{D}_{\mathrm{harm}}(A^1) \rightarrow \dot{\mathcal{D}}_{\mathrm{harm}}(\riem_1)   \]
   is well-defined.  Furthermore, it is bounded with respect to the $H^1_{\mathrm{conf}}(A^1)$ and $\dot{\mathcal{D}}(\riem_1)$ norms, since the $H^1_{\mathrm{conf}}(\riem_1)$ norm dominates the Dirichlet seminorm. The image is dense.  

   By \eqref{eq:thingy_temp} we have 
   \[  \dot{\mathbf{J}}_1 \dot{H} = - \dot{\mathbf{J}}_2 \dot{\mathbf{O}}_{1,2} \dot{H}  \]
   for all $\dot{H}$ arising from $H \in \mathbf{G}_{A^1,\riem_1} \mathcal{D}_{\mathrm{harm}}(A^1)$.  The second claim now follows from boundedness of $\dot{J}$ (Theorem \ref{th:jump_bounded_Dirichlet}) and boundedness of $\dot{\mathbf{O}}_{1,2}$ (Theorem \ref{thm:bounded_overfare_Dirichlet}).}



  \end{proof}   
  {
  \begin{remark}
   On the other hand, $\mathbf{G}_{A^1,\riem_1} :\mathcal{D}_{\mathrm{harm}}(A^1) \rightarrow \dot{\mathcal{D}}_{\mathrm{harm}}(\riem_1)$ is not bounded with respect to the Dirichlet seminorms. To see this, let $\riem_1$ be the annulus $\{z : 1<|z|<4 \}$, and let $A^1 = \{ z: 1<|z|<2 \} \cup \{ z: 3<|z|<4 \}$.  The claim is falsified by considering the function which is $1$ on $\{ z: 1<|z|<2 \}$ and $N$ on $\{ z: 3<|z|<4 \}$, and letting $N \rightarrow \infty$.  
  \end{remark}}


  The operator $\mathbf{J}^q_k$ satisfies a Plemelj-Sokhotski jump formula. Although we will not emphasize this role in this paper, the following theorem represents this fact. 
    The following improvement of Theorem 4.13 in \cite{Schippers_Staubach_Plemelj}, can be viewed as a CNT version of the Plemelj-Sokhotski jump formula. However, rather than referring to a function on the curve, we express the result in terms of the extensions into $\riem_1$, with the help of the overfare operator.  
   \begin{theorem} \label{th:Overfare_with_correction_functions}  
    The following statements hold:\\
    \begin{enumerate}
        \item  [$(1)$] Assume that every curve in the complex $\Gamma$ is a \emph{BZM} quasicircle. 
    For any $h \in \mathcal{D}_{\mathrm{harm}}(\riem_1)$, 
    \[  \mathbf{O}_{2,1} \mathbf{J}^q_{1,2} h = \mathbf{J}^q_{1,1} h - h   \]
    and for all $h \in \mathcal{D}_{\mathrm{harm}}(\riem_2)$
    \[  \mathbf{O}_{2,1} \mathbf{J}^q_{2,2} h - \mathbf{J}^q_{2,1} h =\mathbf{O}_{2,1} h.   \]
    \item  [$(2)$] Assume that $\riem_2$ is connected and $\Gamma$ is an arbitrary complex of quasicircles. Then for any $\dot{h} \in \dot{\mathcal{D}}_{\mathrm{harm}}(\riem_1)$, 
    \[  \dot{\mathbf{O}}_{2,1} \dot{\mathbf{J}}_{1,2} \dot{h} = \dot{\mathbf{J}}_{1,1} \dot{h} - \dot{h} \]
    and 
    \[  \dot{\mathbf{O}}_{2,1} \dot{\mathbf{J}}_{2,2} \dot{h} - \dot{\mathbf{J}}_{2,1} \dot{h} = \dot{\mathbf{O}}_{2,1} \dot{h}.   \]
    \end{enumerate}
   \end{theorem}
   \begin{proof}  We prove (1). 
    Let $A_1$ be a collar neighbourhood of $\Gamma$ in $\riem_1$. 
     Assume that the boundary $\Gamma'$ is an analytic curve which is isotopic in the closure of $A_1$ to $\Gamma$.  Orient both curves positively with respect to $\riem_1$.    By shrinking $A$ and moving $\Gamma'$ we may assume that  $q$ is not in $A_1$. We assume that $z$ is in $A_1$.  Let $\gamma_r$ denote the curve $|w-z|=r$ in local coordinates, oriented positively with respect to $z$.

     Applying Stokes' theorem and assuming $h \in \mathcal{D}(A_1)$, for  $z \in A_1$ we have
    {\begin{equation*}
         - \frac{1}{\pi i}  \int_{\Gamma} \partial_w 
         \mathscr{G}(w;z,q) h(w) + \frac{1}{\pi i} \int_{\Gamma'} \partial_w \mathscr{G}(w;z,q) h(w)
          = - \frac{1}{\pi i} \lim_{r \searrow 0} \int_{\gamma_r}  \partial_w \mathscr{G}(w;z,q) h(w) = h(z).  
     \end{equation*}}
     The integrand of the second integral on the left hand side is holomorphic in $w$. Therefore the integral equals the limiting integral $-\mathbf{J}^q_{1,2} h$ for any $z \in \riem_2$, and furthermore, the integral over $\Gamma'$ is a harmonic function $H_2$ in $z$ extending $-\mathbf{J}^q_{1,2} h$ into $A_1 \cup \text{cl} (\riem_2)$. For $z \in A_1$ this function thus satisfies 
     \[  \mathbf{J}^q_{1,1} h(z) - H_2(z) = h(z).        \]
     Since the CNT boundary values of $\mathbf{J}^q_{1,2} h$ equal those of the extension $H_2$, we have proved that 
     \[  \mathbf{O}_{2,1} \mathbf{J}^q_{1,2} h(z) = \mathbf{G}_{A,\riem_1} H_2  =
      \mathbf{J}^q_{1,1} h(z) - \mathbf{G}_{A,\riem_1} h(z)  \]
      by the equation above. 

      Applying the second anchor lemma \cite[Lemma 3.15]{Schippers_Staubach_scattering_I}, we obtain for all $h \in \mathcal{D}(A_1)$
      \begin{equation} \label{eq:jump_on_dense_temp1}
        \mathbf{O}_{2,1} \mathbf{J}^q_{1,2} \mathbf{G}_{A_1,\riem_1} h(z)    =
      \mathbf{J}^q_{1,1}  \mathbf{G}_{A_1,\riem_1} h(z) - \mathbf{G}_{A_1,\riem_1} h(z),   
      \end{equation}
      as claimed.   A similar argument shows that for a collar neighbourhood $A_2$ of $\Gamma$ in $\riem_2$, for all $h \in \mathcal{D}(A_2)$ we have
      \begin{equation} \label{eq:jump_on_dense_temp2}
       { \mathbf{O}_{2,1} \mathbf{J}^q_{2,2} \mathbf{G}_{A_2,\riem_2} h(z)    =
      \mathbf{J}^q_{2,1}  \mathbf{G}_{A_2,\riem_2} h(z) +   \mathbf{O}_{2,1}\mathbf{G}_{A_2,\riem_2} h(z).}   
      \end{equation}
      Observe that the derivations of \eqref{eq:jump_on_dense_temp1} and \eqref{eq:jump_on_dense_temp2} required neither the assumption that $\Gamma$ is a BZM quasicircle nor the assumption that $\riem_2$ is connected. 

      A density argument completes the proof of the first claim of (1). 
     Now $\mathbf{G}_{A_1,\riem_1} \mathcal{D}(A_1)$ is dense in $H^1_{\mathrm{conf}}(\riem_1)$ by \cite[Theorem 3.29]{Schippers_Staubach_scattering_I}.
    Thus it is enough to prove the claim for $\mathbf{G}_{A_1,\riem_1} h$ for $h \in \mathcal{D}(A_1)$, since $\mathbf{G}_{A_1,\riem_1}$, $\mathbf{O}_{1,2}$, and $\mathbf{J}_{1,k}^q$ are bounded with respect to $H^1_{\mathrm{conf}}$ by Theorems \ref{th:bounce_bounded}, \ref{thm:bounded_overfare_conf}, and \ref{th:J_bounded_Hconf} respectively.  A similar density argument using \eqref{eq:jump_on_dense_temp2} shows the second claim of (1).  

      {We now prove the first claim of (2).  For any $h \in \mathcal{D}_{\mathrm{harm}}(A_1)$ we have that \eqref{eq:jump_on_dense_temp1} holds.  Arguing as in the proof of part (2) of Theorem \ref{th:J_same_both_sides}, we have that the set of $\dot{H}$ in $\dot{\mathcal{D}}_{\mathrm{harm}}(\riem_1)$
      of the form $H = \mathbf{G}_{A_1,\riem_1} h$ for $h \in \mathcal{D}(A_1)$ are dense in $\dot{\mathcal{D}}_{\mathrm{harm}}(\riem_1)$.  By \eqref{eq:jump_on_dense_temp1} we have for such $\dot{H}$ that
      \[   \dot{\mathbf{O}}_{2,1} \dot{\mathbf{J}}_{1,2} \dot{H} = \dot{\mathbf{J}}_{1,1} \dot{H} - \dot{H}.   \]
      The claim now follows from boundedness of $\dot{\mathbf{J}}_1$ and $\dot{\mathbf{O}}_{2,1}$, which is Theorems \ref{th:jump_bounded_Dirichlet} and \ref{thm:bounded_overfare_Dirichlet} respectively.  The proof of the second claim is similar. 
      }
   \end{proof}

\end{subsection}

\begin{subsection}{Adjoint identities for the Schiffer operators}
 \label{se:Schiffer_adjoint_identities}
 In this section, we prove some identities for the Schiffer operators.  


 \begin{theorem}[Adjoint identities]  \label{th:adjoint_identities} For $j,k =1,2$ 
  $($not necessarily distinct$)$, 
  \[    \mathbf{T}_{j,k}^* = \overline{\mathbf{T}}_{k,j}.      \]
  If the genus of $\mathscr{R}$ is non-zero, then for $k=1,2$ we have 
  \[  \mathbf{R}_k^* = \mathbf{S}_k.      \]
 \end{theorem}
 \begin{proof}
  In the case of a single quasicircle $\Gamma$, these are \cite[Theorems 3.11, 3.12]{Schippers_Staubach_Plemelj}. The proofs there hold for the case of 
  several quasicircles.    
 \end{proof}
 Also, observe that if we define 
 \begin{equation}\label{defn: Shk}
      \gls{Sharm} = \mathbf{S}_k \mathbf{P}_k + \overline{\mathbf{S}}_k \overline{\mathbf{P}}_k : \mathcal{A}_{\text{harm}}(\riem_k) \rightarrow \mathcal{A}_{\text{harm}}(\mathscr{R}) 
 \end{equation} 
 then we have by an elementary computation
 \begin{corollary} If the genus of $\mathscr{R}$ is non-zero then for $k=1,2$
   $(\mathbf{R}_k^{\mathrm{h}})^* = \mathbf{S}^{\mathrm{h}}_k$.
 \end{corollary}

 \begin{theorem}[Quadratic adjoint identities, Part I]  \label{th:quadratic_adjoint_one} 
    If $\mathscr{R}$ is of genus $g>0$ then
  \[  \mathbf{S}_1 \mathbf{S}_1^* + \mathbf{S}_2 \mathbf{S}_2^* = \mathbf{I}  \]
  and 
  \[  \overline{\mathbf{S}}_1 \overline{\mathbf{S}}_1^* + \overline{\mathbf{S}}_2 \overline{\mathbf{S}}_2^* = \mathbf{I}.      \]
 \end{theorem}
 \begin{proof}
  These identities follow from the 
  reproducing property of Bergman kernel.  For $\alpha \in \mathcal{A}(\mathscr{R})$ we have, using the fact that quasicircles have measure zero (see e.g. \cite{Lehto})
  \begin{align*}
    (\mathbf{S}_1 \mathbf{S}_1^* + \mathbf{S}_2 \mathbf{S}_2^* )\, \alpha (z) & = \iint_{\riem_1} K_{\mathscr{R}}(z,w) \alpha(w)  + \iint_{\riem_2} K_{\mathscr{R}}(z,w) \alpha(w) \\ & = \iint_{\mathscr{R}} K_{\mathscr{R}}(z,w) \alpha(w)
    = \alpha(w)
  \end{align*}
  which proves the first identity.  The second identity is the complex conjugate of the first.
 \end{proof}
 We will repeatedly use the fact that quasicircles have measure zero in this way, in order to express an integral over $\mathscr{R}$ as the sum of integrals over $\riem_1$ and $\riem_2$, without mentioning it each time. 

 To prove quadratic adjoint identities involving $\mathbf{T}$, we require a lemma.
 \begin{lemma}  \label{le:double_L_vanishes_general_genus}
 For any $w,z \in \mathscr{R}$, 
  \[  \iint_{\mathscr{R},\zeta} L_{\mathscr{R}}(z,\zeta) \wedge \overline{L_\mathscr{R}(\zeta,w)} = K_\mathscr{R}(z,w)      \]
  where the integral is interpreted as a principal value integral.  In particular, if the genus of $\mathscr{R}$ is zero then
   \[  \iint_{\mathscr{R},\zeta} L_{\mathscr{R}}(z,\zeta) \wedge \overline{L_\mathscr{R}(\zeta,w)} = 0.     \]
 \end{lemma}
 {\begin{proof}
  Fix $w=w_0$ and $z=z_0$ in the integrals above.  Let  $\gamma^\varepsilon_{w_0}$ be curves such that $\psi \circ \gamma^\varepsilon_{w_0}$ are given by $|\eta|=\varepsilon$ for a chart $\psi(\zeta)=\eta$ near $w_0$, which takes $w_0$ to $0$. Define $\gamma^\varepsilon_{z_0}$ similarly.  Let $\mathscr{R}^\varepsilon$ be the region in $\mathscr{R}$ bounded by the curves $\gamma^\varepsilon_{z_0}$ and $\gamma^\varepsilon_{w_0}$ but not containing $z_0$ and $w_0$.  We assume these curves have positive orientation with respect to $\mathscr{R}^\varepsilon$. 

   In these coordinates, we have (setting $u=\psi(z)$ and $v=\psi(w)$)

  \[ \frac{1}{\pi i} \partial_{\bar{w}}    \mathscr{G}(\zeta,w) = - \left( \frac{1}{2\pi i} 
    \frac{1}{\bar{\eta}} + \overline{\phi(\eta)} \right)d\overline{v}  \]
  where $\phi$ is a smooth function of $\eta$ which is uniformly bounded near $z$. We suppress dependence on $u$ and $v$ because we are fixing $w=w_0$ and $z=z_0$; however, we retain $d\bar{v}$ to emphasize that the quantity is a form in the $w$ variable.

  We then have
  \begin{align*}
      \iint_\mathscr{R} L_\mathscr{R}(z;\zeta) \wedge_\zeta \overline{L_\mathscr{R}(\zeta;w)} & = \lim_{\varepsilon \searrow 0} \iint_{\mathscr{R}^\varepsilon}  L_\mathscr{R}(z;\zeta) \wedge_\zeta \overline{L_\mathscr{R}(\zeta;w)} \\
      & = \lim_{\varepsilon \searrow 0} \left[ \int_{\gamma^\varepsilon_{w_0}}  L_{\mathscr{R}}(z;\zeta)   \overline{ \frac{1}{\pi i} \partial_w \mathscr{G}(\zeta,w)}   
      + \int_{\gamma^\varepsilon_{z_0}} L_\mathscr{R}(z;\zeta)  \overline{ \frac{1}{\pi i} \partial_w \mathscr{G}(\zeta,w)}   \right]. \\
  \end{align*}

  For $\zeta$ near $w_0$, in $\eta$-coordinates we have $L(z;\zeta) = \rho(\eta)\, d\eta$ for some holomorphic function $\rho(\eta)$. So the first term is (where the integral is with respect to $\eta$)
  \[  \lim_{\varepsilon \rightarrow 0} \int_{\psi \circ \gamma^\varepsilon_{w_0}} \left( \rho(\eta)   \left( \frac{1}{2\pi i} 
    \frac{1}{\overline{\eta}} + \overline{\phi(\eta)}  \right)  d\eta \right)\,du \, d\bar{v} =0.   \]
   Here we have used the fact that if $\eta = \varepsilon e^{i\theta}$ then 
  \[  \frac{d\eta}{\overline{\eta}}=e^{2 i \theta} d\theta.      \]     

  On the other hand, in the second term it is $L_{\mathscr{R}}$ that is singular while $\partial_w \mathscr{G}$ is non-singular.  Fix $w$ and ignore the $dw$.  Now let $\eta=\phi(\zeta)$ be a holomorphic coordinate vanishing at $z$ and let the level curves $\gamma_z^\varepsilon$ be as above, and let $u=\phi(z)$ and $v=\phi(w)$. We may write 
  \[  \frac{1}{\pi i} \partial_{\bar{w}} \mathscr{G}(\zeta,w) = \left( h_1(\eta) + \overline{h_2(\eta)}\right) d\overline{u}       \]
  where $h_1$ and $h_2$ are holomorphic.  Now writing 
  $\overline{h_2(\eta)} = a_0 + a_1 \bar{\eta} + a_2 \bar{\eta}^2 + \cdots$
  and observing that (suppressing the fixed $z$, but keeping $dv$ to indicate the fact that it is a form) 
  \[  L_\mathscr{R}(z,\zeta) = \left(-  \frac{1}{2 \pi i} \frac{d\eta}{\eta^2} + k(\eta) d\eta  \right) dv    \]
  where $k$ is holomorphic.  Integrating this kernel against $\overline{h_2(\eta)} d\bar{u}$ is zero in the limit, so from this it is easily seen that 
  \begin{align*}
    \lim_{\varepsilon \rightarrow 0} \int_{\gamma^\varepsilon_z} L_\mathscr{R}(z;\zeta)   \overline{ \frac{1}{\pi i} \partial_w \mathscr{G}(\zeta,w)}  &  =   
    - \lim_{\varepsilon \rightarrow 0} \int_{\gamma^\varepsilon_z} L_\mathscr{R}(z;\zeta)    \frac{1}{\pi i} \partial_{\bar{w}} \mathscr{G}(\zeta,w) \, du d \bar{v} \\
    & = \lim_{\varepsilon \rightarrow 0} \int_{\psi \circ \gamma^\varepsilon_z}  
    h_1(\eta) \frac{d \eta}{2 \pi i \eta^2} \, du \, d \bar{v}  =  - h_1'(0)  \, du \, d \bar{v}
  \end{align*}
  where the final sign change results from the fact that the curve $\gamma^\varepsilon_z$ is negatively oriented with respect to $z$.   Now observing that 
  \[  - h_1'(0)  \, du \, d \bar{v}= - \frac{1}{\pi i} \partial_z \partial_{\bar{w}} \mathscr{G}(z,w)        = K_\mathscr{R}(z,w) \]
  the proof of the first claim is complete.   

  In the case that $\mathscr{R}$ has genus zero, by  Example \ref{ex:sphere_kernels} we have that $K_{\mathscr{R}}=0$, which proves the second claim. 
 \end{proof}}

Using this lemma, we can prove the following. 
 \begin{theorem}[Quadratic adjoint identities, part II]  \label{th:general_adjoint_double_identities}
  If $\mathscr{R}$ has genus $g>0$, then 
  \begin{align*}
    \mathbf{I} & = \mathbf{T}_{1,1}^* \mathbf{T}_{1,1} + \mathbf{T}_{1,2}^* \mathbf{T}_{1,2} + \overline{\mathbf{S}}_1^* \overline{\mathbf{S}}_1 \\
    \mathbf{I} & = \mathbf{T}_{2,1}^* \mathbf{T}_{2,1} + \mathbf{T}_{2,2}^* \mathbf{T}_{2,2} + \overline{\mathbf{S}}_2^* \overline{\mathbf{S}}_2 \\
    0 & = \mathbf{T}_{1,1}^* \mathbf{T}_{2,1} + \mathbf{T}_{1,2}^* \mathbf{T}_{2,2} + \overline{\mathbf{S}}_1^* \overline{\mathbf{S}}_2 \\
    0 & = \mathbf{T}_{2,2}^* \mathbf{T}_{1,2} + \mathbf{T}_{2,1}^* \mathbf{T}_{1,1} + \overline{\mathbf{S}}_2^* \overline{\mathbf{S}}_1. 
  \end{align*}
  If $\mathscr{R}$ has genus $g=0$, then 
   \begin{align*}
    \mathbf{I} & = \mathbf{T}_{1,1}^* \mathbf{T}_{1,1} + \mathbf{T}_{1,2}^* \mathbf{T}_{1,2}  \\
    \mathbf{I} & = \mathbf{T}_{2,1}^* \mathbf{T}_{2,1} + \mathbf{T}_{2,2}^* \mathbf{T}_{2,2}  \\
    0 & = \mathbf{T}_{1,1}^* \mathbf{T}_{2,1} + \mathbf{T}_{1,2}^* \mathbf{T}_{2,2} \\
    0 & = \mathbf{T}_{2,2}^* \mathbf{T}_{1,2} + \mathbf{T}_{2,1}^* \mathbf{T}_{1,1}.
  \end{align*}
 \end{theorem}
 \begin{proof}  Assume that $\mathscr{R}$ has genus $g >0$.    
  The first identity was proven in \cite{Schippers_Staubach_Plemelj}, in the case of one boundary curve.  The proof given there extends verbatim to the case of several boundary curves and disconnected components without issue. The second identity is just the first, with the roles of $\riem_1$ and $\riem_2$ switched. 
  The fourth identity is just the third with the roles of $\riem_1$ and $\riem_2$ interchanged.  So it is enough to prove the third identity. 

  Let $v \in \mathcal{A}(\riem_1)$ and $u \in \mathcal{A}(\riem_2)$, and denote the Schiffer kernels of $\riem_k$ by $L_k$ for $k=1,2$.  Then setting $M = \mathbf{T}_{1,1}^* \mathbf{T}_{2,1} + \mathbf{T}_{1,2}^*\mathbf{T}_{2,2}$ and applying Theorems \ref{th:Schiffer_vanishing_identity} and \ref{th:adjoint_identities} yields that 
  \begin{align*}
   2i \left< v, M u \right> & = 
    2i \left< \mathbf{T}_{1,1} v , \mathbf{T}_{2,1} u \right> + 2i \left< \mathbf{T}_{1,2} v,\mathbf{T}_{2,2} u \right> \\
    & =  \iint_{1,z} \iint_{1,w} \iint_{2,\zeta} L_{\mathscr{R}}(z,w) \wedge_w \overline{v(w)}
    \wedge_z \overline{L_{\mathscr{R}}(z,\zeta)} \wedge_\zeta u(\zeta)  \\
    & \ \ \ + \iint_{2,z} \iint_{1,w} \iint_{2,\zeta} L_{\mathscr{R}}(z,w) \wedge_w \overline{v(w)}
    \wedge_z \overline{L_{\mathscr{R}}(z,\zeta)} \wedge_\zeta u(\zeta) \\
    & = \iint_{1,z} \iint_{1,w} \iint_{2,\zeta} \left(L_{\mathscr{R}}(z,w) - L_1(z,w) \right) \wedge_w \overline{v(w)} \wedge_z
    \overline{L_{\mathscr{R}}(z,\zeta)}\wedge_\zeta u(\zeta) \\
    & \ \ \ + \iint_{2,z} \iint_{1,w} \iint_{2,\zeta} L_{\mathscr{R}}(z,w) \wedge_w \overline{v(w)}
    \wedge_z \overline{\left( L_{\mathscr{R}}(z,\zeta) -L_2(z,\zeta) \right)} \wedge_\zeta u(\zeta)  \\
    & =  \iint_{1,w} \iint_{2,\zeta}  \overline{v(w)} \wedge_w u(\zeta) \wedge_\zeta \iint_{1,z} \left(L_{\mathscr{R}}(z,w) - L_1(z,w) \right) \wedge_z 
    \overline{L_{\mathscr{R}}(z,\zeta)}      \\
    & \ \ \ + \iint_{1,w} \iint_{2,\zeta} \overline{v(w)}  \wedge_w u(\zeta) \wedge_\zeta \iint_{2,z} L_{\mathscr{R}}(z,w) \wedge_z 
    \overline{\left( L_{\mathscr{R}}(z,\zeta) -L_2(z,\zeta) \right)}. 
  \end{align*}
  Reorganizing the two terms above we obtain 
  \begin{align*}
   2i \left< v, M u \right> & = - \iint_{1,w} \iint_{2,\zeta}  \overline{v(w)} \wedge_w u(\zeta) \wedge_\zeta \iint_{1,z} L_1(z,w) \wedge_z
    \overline{L_{\mathscr{R}}(z,\zeta)}      \\
    & \ \ \ - \iint_{1,w} \iint_{2,\zeta} \overline{v(w)} \wedge_w u(\zeta) \wedge_\zeta \iint_{2,z} L_{\mathscr{R}}(z,w) \wedge_z 
    \overline{L_2(z,\zeta)}  \\
    & \ \ \ + 2 \iint_{1,w} \iint_{2,\zeta} \overline{v(w)} \wedge_w u(\zeta) \wedge_\zeta \iint_{\mathscr{R},z} L_{\mathscr{R}}(z,w) \wedge_z
    \overline{L_{\mathscr{R}}(z,\zeta)}.
  \end{align*}
  Observing that $\zeta$ is not in the closure of $\riem_1$, the first term vanishes by Schiffer's identity (i.e. Theorem \ref{th:Schiffer_vanishing_identity}) applied to $L_1$.  Similarly the second term vanishes because $z$ is not in the closure of $\Sigma_2$.  Thus applying Lemma \ref{le:double_L_vanishes_general_genus}  and Theorem \ref{th:adjoint_identities} yield that
  \begin{align*}
   2i \left< v,Mu \right> & =  2 \iint_{1,w} \iint_{2,\zeta} \overline{v(w)} \wedge_w u(\zeta) \wedge_\zeta K_{\mathscr{R}}(w,\zeta) \\
   & = - {2}  \iint_{1,w} \iint_{2,\zeta} \overline{v(w)} \wedge_w K_{\mathscr{R}}(w,\zeta)  \wedge_\zeta u(\zeta) \\
   & = - 2i \left< v, \overline{\mathbf{R}}_1  \overline{\mathbf{S}}_2 u\right>.
  \end{align*}
  This completes the proof in the case of non-zero genus.  If $\mathscr{R}$ has genus zero, then all the computations above are still valid.  We need only observe that in the last step $K_{\mathscr{R}}=0$ by Example \ref{ex:sphere_kernels}.    
 \end{proof}


 Taking complex conjugates and using the adjoint identities of Theorem \ref{th:adjoint_identities}, we also have for non-zero genus: 
 \begin{align} \label{eq:other_general_adjoint_double}
    \mathbf{I} & = \mathbf{T}_{1,1} \mathbf{T}_{1,1}^* + \mathbf{T}_{2,1} \mathbf{T}_{2,1}^* + {\mathbf{S}}_1^* {\mathbf{S}}_1 \nonumber \\
    \mathbf{I} & = \mathbf{T}_{1,2} \mathbf{T}_{1,2}^* + \mathbf{T}_{2,2} \mathbf{T}_{2,2}^* + {\mathbf{S}}_2^* {\mathbf{S}}_2 \nonumber \\
    0 & = \mathbf{T}_{1,1} \mathbf{T}_{1,2}^* + \mathbf{T}_{2,1} \mathbf{T}_{2,2}^* + {\mathbf{S}}_1^* {\mathbf{S}}_2 \\ \nonumber
    0 & = \mathbf{T}_{2,2} \mathbf{T}_{2,1}^* + \mathbf{T}_{1,2} \mathbf{T}_{1,1}^* + {\mathbf{S}}_2^* {\mathbf{S}}_1, 
  \end{align}
 and in the genus zero case we have 
  \begin{align*}  
    \mathbf{I} & = \mathbf{T}_{1,1} \mathbf{T}_{1,1}^* + \mathbf{T}_{2,1} \mathbf{T}_{2,1}^*  \\
    \mathbf{I} & = \mathbf{T}_{1,2} \mathbf{T}_{1,2}^* + \mathbf{T}_{2,2} \mathbf{T}_{2,2}^*  \\
    0 & = \mathbf{T}_{1,1} \mathbf{T}_{1,2}^* + \mathbf{T}_{2,1} \mathbf{T}_{2,2}^*  \\ 
    0 & = \mathbf{T}_{2,2} \mathbf{T}_{2,1}^* + \mathbf{T}_{1,2} \mathbf{T}_{1,1}^*.
  \end{align*}

 Finally we have the following identity:
  \begin{theorem}[Quadratic adjoint identities, part III]  \label{th:general_adjoint_identity_double_final}  If $\mathscr{R}$ has non-zero genus, then
   \begin{align*}
     0 & = \mathbf{T}_{1,1} \overline{\mathbf{S}}_1^* + \mathbf{T}_{2,1} \overline{\mathbf{S}}_2^* \\
     0 & = \mathbf{T}_{1,2} \overline{\mathbf{S}}_1^* + \mathbf{T}_{2,2} \overline{\mathbf{S}}_2^*.
   \end{align*}
  \end{theorem}
  \begin{proof}
   First, recall that $\mathbf{S}_k^* = \mathbf{R}_k$ by Theorem \ref{th:adjoint_identities}. Thus the identities are equivalent to showing that  
   \[  \iint_{\mathscr{R}} L_{\mathscr{R}}(z,\zeta) \wedge_\zeta \overline{\alpha(\zeta)} = 0   \]
   for $z \in \riem_k$, $k=1,2$ and all $\alpha\in \mathcal{A}(\mathscr{R})$.  

   Fix $z \in \riem_k$.  Let $\gamma_\varepsilon$ be a curve given by 
   $|z-\zeta|=\varepsilon$ in a local coordinate chart, with orientation chosen to be positive with respect to $z$.  
  Stokes' theorem yields that the principal value integral is given by 
   \[   -\frac{1}{\pi i} \lim_{\varepsilon \searrow 0}  \int_{\gamma_\varepsilon}  \partial_z \mathscr{G}(z;\zeta, q) \overline{\alpha(\zeta)}  \]
   where $\mathscr{G}$ is Green's function of $\mathscr{R}$.  
   By Lemma \ref{le:limiting_circle_Schiffer_identity} this is zero.  
  \end{proof}

Taking complex conjugates and using \ref{th:adjoint_identities} we also obtain 
  \begin{align} \label{eq:general_adjoint_identity_double_final}
   0 & = \mathbf{S}_1 \mathbf{T}_{1,1} + \mathbf{S}_{2} \mathbf{T}_{1,2} \nonumber \\
   0 & = \mathbf{S}_{1} \mathbf{T}_{2,1} + \mathbf{S}_{2} \mathbf{T}_{2,2}.
  \end{align}
\end{subsection}
\begin{subsection}{The Schiffer operators on harmonic measures}  \label{se:Schiffer_on_harmonic_measures}
A relationship between the Schiffer operators and the harmonic measure is established in the following result:
\begin{theorem} \label{th:T_and_S_on_harmonic_measures} 
 Let  $d\omega$ be a harmonic measure on $\riem_1$.  Then
 \[  \mathbf{T}_{1,1} \overline{\partial} \omega = - \partial \omega + \mathbf{R}_1 \mathbf{S}_1 {\partial} \omega      \]
 and
     \[  \mathbf{T}_{1,2} \overline{\partial} \omega = \mathbf{R}_2 \mathbf{S}_1 \partial \omega. \]
\end{theorem}
\begin{proof}  Assume that $\omega=1$ on one boundary of $\riem_1$ and $0$ on the others.  It is enough to prove the claim for such $\omega$.  {We will need to use a particular set of limiting curves in computing the boundary integrals, for which the computation simplifies.}
{Let $\Gamma_\varepsilon$ denote the union of the level sets $\omega = \varepsilon$, $\omega= 1-\varepsilon$}. Using \cite[Lemma 3.17]{Schippers_Staubach_scattering_I},  for $\varepsilon$ sufficiently small this consists of $n$ disjoint curves each homotopic to $\partial_k \riem_1$ for a particular $k$.  Also, let $\gamma_r$ be as in Lemma \ref{le:limiting_circle_Schiffer_identity}.  
 We then have that, fixing $q \in \riem_2$, 
 \begin{align*}
    \mathbf{T}_{1,1} \overline{\partial} \omega & = \frac{1}{ \pi i } \iint_{\riem_1} 
    \partial_z \partial_w \mathscr{G}(w;z,q) \wedge_w \overline{\partial} \omega (w) \\
    & = \lim_{\varepsilon \searrow 0} \frac{1}{ \pi i } \int_{\Gamma_\varepsilon,w} \partial_z \mathscr{G}(w;z,q)\, \overline{\partial} \omega(w) - 
    \lim_{r \searrow 0}\frac{1}{ \pi i } \int_{\gamma_r,w} \partial_z \mathscr{G}(w;z,q)\, \overline{\partial} \omega(w).
 \end{align*}
 Applying Lemma \ref{le:limiting_circle_Schiffer_identity} twice and using the fact that $\overline{\partial}\omega(w)=- \partial \omega(w)$ on the level curves $\Gamma_\varepsilon$, we see that 
 \begin{align*}
     \mathbf{T}_{1,1} \overline{\partial} \omega(z) & = - \lim_{\varepsilon \searrow 0} \frac{1}{ \pi i } \int_{\Gamma_\varepsilon,w} \partial_z \mathscr{G}(w;z,q)\, {\partial}\, \omega(w) \\
     & = - \lim_{\varepsilon \searrow 0} \frac{1}{ \pi i } \int_{\Gamma_\varepsilon,w} \partial_z \mathscr{G}(w;z,q)\, {\partial} \omega(w) + 
    \lim_{r \searrow 0}\frac{1}{ \pi i } \int_{\gamma_r,w} \partial_z \mathscr{G}(w;z,q)\, {\partial} \omega(w) \\
     &  \ \ \ \ \ \    - 
    \lim_{r \searrow 0}\frac{1}{ \pi i } \int_{\gamma_r,w} \partial_z \mathscr{G}(w;z,q)\, {\partial} \omega(w) \\
    & = - \frac{1}{ \pi i } \iint_{\riem_1} 
    \partial_z \overline{\partial}_w \mathscr{G}(w;z,q) \wedge_w  {\partial} \omega (w) - \partial \omega(z)  \\
    & = \mathbf{R}_1 \mathbf{S}_1 \partial \omega (z) - \partial \omega (z).
 \end{align*}
 The proof of the second claim is similar, except with the integrals over $\gamma_r$ removed, since for $z \in \riem_2$ there are no singularities in $\riem_1$.
\end{proof}

\begin{definition}
 We say that $u \in \mathcal{A}_{\text{harm}}(\mathscr{R})$ is \emph{piecewise exact} if 
\[  \mathbf{R}_k^{\mathrm{h}} u  \in \mathcal{A}^{\mathrm{e}}_{\mathrm{harm}}(\riem_k)   \]
for $k=1,2$, where $\mathbf{R}_k^{\mathrm{h}}$ is as in Definition \ref{def: restriction ops}.  We denote the space of piecewise exact harmonic forms on $\mathscr{R}$ by $\gls{peform}(\mathscr{R})$. 
\end{definition}

{\begin{definition}\label{def:exact overfare}
  If $\riem_2$ is connected, the \emph{exact overfare} can be defined as follows. Given 
 the spaces $\mathcal{A}^\mathrm{e}$ of Definition \ref{def: exact holo and harm forms} we define 
 \[  \gls{exacto}: \mathcal{A}^{\mathrm{e}}(\riem_2) \rightarrow \mathcal{A}^{\mathrm{e}}(\riem_1) \]
 to be the unique operator satisfying 
 \begin{equation}\label{charac of exact overfare}
   \mathbf{O}^{\mathrm{e}}_{2,1} d = d \mathbf{O}_{2,1}.    
 \end{equation}      
 If $\riem_1$ is connected we may define $\mathbf{O}^\mathrm{e}_{1,2}$ in the same way.
