\begin{corollary} \label{co:overfare_piecewise_exact} 
 For any harmonic measure $d\omega \in \mathcal{A}_{\mathrm{harm}}(\riem_1)$, $\mathbf{S}_1 \partial \omega + \overline{\mathbf{S}}_1 \overline{\partial} \omega = \mathbf{S}_1^{\mathrm{h}} d\omega \in \mathcal{A}_{\mathrm{harm}}^{\mathrm{pe}}(\mathscr{R})$.  
 Furthermore, if $\riem_2$ is connected, then
 \[  \mathbf{O}^{\mathrm{e}}_{2,1} \left(  \mathbf{R}^{\mathrm{h}}_2 \mathbf{S}_1 d \omega \right) =   \mathbf{R}^\mathrm{h}_1 \mathbf{S}^\mathrm{h}_1  d \omega + d\omega.   \]
\end{corollary}
\begin{proof}
 Since all operators involved are complex linear, it is enough to prove this for real harmonic measures $d\omega \in \mathcal{A}_{\mathrm{hm}}(\riem_1)$.  For such harmonic measures, by Theorems \ref{th:jump_derivatives} and \ref{th:T_and_S_on_harmonic_measures},
 \[     d\mathbf{J}^q_{1,1}\, \omega  = \partial \omega + \mathbf{T}_{1,1} \overline{\partial} \omega + \overline{\mathbf{R}}_1 \overline{\mathbf{S}}_1 \overline{\partial} \omega = \mathbf{R}_1 \mathbf{S}_1 \partial \omega + \overline{\mathbf{R}}_1 \overline{\mathbf{S}}_1 \overline{\partial} \omega  \]
 and 
 \[  d \mathbf{J}^q_{1,2}\, \omega = \mathbf{T}_{1,2} \overline{\partial} \omega + \overline{\mathbf{R}}_2 \overline{\mathbf{S}}_1 \overline{\partial} \omega = \mathbf{R}_2 \mathbf{S}_1 \partial \omega + \overline{\mathbf{R}}_2 \overline{\mathbf{S}}_1 \overline{\partial} \omega  \]
 which proves the first claim. 

 Now if $\riem_2$ is connected, then $\mathbf{O}_{2,1}^{\mathrm{e}}$ is well-defined (if not, it's only defined up to addition of a harmonic measure on $\riem_1$.) 
 By the transmitted jump formula (Theorem \ref{th:Overfare_with_correction_functions}), 
 \begin{align*}
     \dot{\mathbf{O}}_{2,1} \dot{\mathbf{J}}_{1,2} \, \dot{\omega} = \dot{\mathbf{J}}_{1,1} \, \dot{\omega} - \dot{\omega}.
 \end{align*}
 Taking $d$ of both sides and applying the previous two equations and \eqref{charac of exact overfare}, completes the proof of the theorem. 
\end{proof}
\begin{remark}  \label{re:nonself-overfare}
 Note that this shows that an element of $\mathcal{A}^{\mathrm{pe}}_{\text{harm}}$ need not be its own overfare.
\end{remark}

Another identity for the harmonic measures and $\mathbf{S}$ operator is the following. 

\begin{theorem} \label{th:S_on_harmonic_measures}
 Let $\omega_1$ be a harmonic function on $\riem_1$ which is constant on each boundary curve.  Let $\omega_2 = \mathbf{O}_{1,2}\, \omega_1$.  If either $\riem_1$ or $\riem_2$ is connected, then 
 \[ \mathbf{S}_1^{\mathrm{h}} \, d\omega_1 = -\mathbf{S}_2^{\mathrm{h}} \, d \omega_2. \]
\end{theorem}
\begin{proof} Assume that $\riem_1$ is connected. 
 By Theorem \ref{th:J_same_both_sides}
 \[ \dot{\mathbf{J}}_{1,2}\, \dot{\omega}_1 = - \dot{\mathbf{J}}_{2,2} \dot{\mathbf{O}}_{1,2}\, \dot{\omega}_1 = - \dot{\mathbf{J}}_{2,2}\, \dot{\omega}_2.    \]
 Applying $d$ to both sides we get
 \begin{align*}
   \mathbf{R}_2 \mathbf{S}_1  \partial \omega_1 +  \overline{\mathbf{R}}_2 \overline{\mathbf{S}}_1 \overline{\partial}   \omega_1 & = \mathbf{T}_{1,2}\, \overline{\partial} \omega_1 +  {\mathbf{R}}_2  {\mathbf{S}}_1 \partial \omega_1 =
  d \mathbf{J}_{1,2}\, \omega_1 = - d \mathbf{J}_{2,2}\, \omega_2  \\
  & = - \partial \omega_2 - \mathbf{T}_{22}\, \overline{\partial} \omega_2 - \overline{\mathbf{R}}_{2} \overline{\mathbf{S}}_2\, \overline{\partial} \omega_2 \\ &  =  -{\mathbf{R}}_{2} {\mathbf{S}}_2 {\partial} \omega_2 - \overline{\mathbf{R}}_{2} \overline{\mathbf{S}}_2 \, \overline{\partial} \omega_2
 \end{align*}
 where we have used Theorem \ref{th:T_and_S_on_harmonic_measures}.  Therefore $\mathbf{R}_2^\mathrm{h} \mathbf{S}_1^\mathrm{h}\, d \omega_1 = - \mathbf{R}_2^\mathrm{h} \mathbf{S}_2^\mathrm{h} \, \omega_2$ which proves the claim by analytic continuation to $\mathscr{R}$. 

 If, on the other hand, $\riem_2$ is connected, we have $\omega_1=\mathbf{O}_{2,1} \omega_2$. One can now repeat the proof with the roles of $1$ and $2$ switched.
\end{proof}

This immediately leads to a characterization of which harmonic measures lie in the kernel of $\mathbf{S}$ and $\mathbf{T}_{12}$. 
