 We review some facts about harmonic one-forms on compact Riemann surfaces; see for example \cite[Chapter III]{Farkas_Kra}. We start by recalling  the standard way to define harmonic one-forms $H_C$ such that 
\begin{equation}\label{eq:H_forms_definition}
     (\alpha,\ast H_C) = \int_C \alpha 
\end{equation}   
for all $\alpha \in \mathcal{A}_{\text{harm}}(\mathscr{R})$.  
Given a curve $C$, let $\Omega$ be a strip to the left of $C$, and let $f$ a real-valued function which is $1$ on $C$, smooth on $\Omega$, and $0$ outside of $\Omega$.  Thus, there is a steady increase from $0$ to $1$ as one approaches $C$ from the left, and a jump back down to $0$ as one crosses the curve.  Then $df$ is smooth, and we have 
\begin{align*}
 (\alpha,\ast df)_{\mathscr{R}} & = \iint_{\mathscr{R}} \alpha \wedge \ast \ast \overline{df} = -\iint_{\mathscr{R}} \alpha \wedge   {df}  \\
 & = -\iint_{\Omega} \alpha \wedge   {df} = \int_C f \alpha \\
 &= \int_C \alpha.
\end{align*} 
By the Hodge theorem, there is a unique harmonic one-form $H_C$ in the same equivalence class as $df$.  Now co-exact forms are orthogonal to closed forms because 
\[  (\alpha,\ast dg )_{\mathscr{R}} ={-} \iint_{\mathscr{R}} \alpha \wedge dg =  \iint_{\mathscr{R}} d (g \alpha) =0.    \]
Thus 
\[  (\alpha,\ast H_C)_{\mathscr{R}}  = (\alpha,\ast df)_{\mathscr{R}} = \int_C \alpha. \]

Now let $\mathscr{R}$ be separated into two surfaces $\riem_1$ and $\riem_2$ by a collection of curves $\partial_k \riem_1$ as in Figure \ref{fig:boundary_curves}.  We assume that $\riem_1$ and $\riem_2$ are both connected.
\begin{figure}
     \includegraphics[width=9cm]{boundary_curves.pdf}
     \caption{The one-forms $df_{k}$}
     \label{fig:boundary_curves}
 \end{figure} 
The strips defining $df_k$, $k=1,2,3$ are the horizontal strips and the boundary curves are the vertical curves. Since $H_{C_k}$ and $df_k$ are in the same cohomology class, we have (by taking analytic limiting curves approaching $\partial_m \riem_1$)
\[ \int_{\partial_m \riem_1}  H_{C_k} = \int_{\partial_m \riem_1} df_k. \]
Here we let $k=1,\ldots,n-1$ where $n$ is the number of boundary curves (in Figure \ref{fig:boundary_curves} we have $n=4$).

We see that
\begin{align}  \label{eq:integrals_of_Hcs} \nonumber
 \int_{\partial_1 \riem_1} H_{C_k} & = \left\{ \begin{array}{ll} -1 & k=1 \\ 0 & \text{otherwise} \end{array} \right. \\  \nonumber
\int_{\partial_2 \riem_1} H_{C_k} & = \left\{ \begin{array}{ll} 1 & k=1 \\ -1 & k=2 \\ 0 & \text{otherwise} \end{array} \right. \\ 
\vdots & \ \ \ \ \ \ \ \vdots \\ \nonumber
\int_{\partial_{n-1}  \riem_1} H_{C_k} & = \left\{ \begin{array}{ll} 1 & k={n-2} \\ -1 & k=n-1 \\ 0 & \text{otherwise} \end{array} \right. \\ \nonumber 
\int_{\partial_n \riem_1} H_{C_k} & = \left\{ \begin{array}{ll} 1 & k={n-1}  \\  0 & \text{otherwise} \end{array} \right. 
\end{align}
Furthermore, the integral around any $C_k$ or internal homology curve is zero.
\begin{remark}
 The reason for the differing first and last integrals is that we haven't included the redundant $H_{C_n}$ which corresponds to a curve traversing the outside of the entire surface.
\end{remark}

We have the following result:\\
\begin{theorem} \label{th:piecewise_exact_characterize}  
Assume that $\riem_1$ and $\riem_2$ are connected.   Then  
\[ \mathcal{A}_{\mathrm{harm}}^{\mathrm{pe}}(\mathscr{R})  = \{   \mathbf{S}_1 \partial \omega +   \overline{\mathbf{S}}_1 \overline{\partial} \omega : d\omega \in { \mathcal{A}_{\mathrm{harm}}(\riem_1) } \}.   \] 
\end{theorem}
\begin{proof}
 The fact that $\mathbf{S}_1 \partial \omega +   \overline{\mathbf{S}}_1 \overline{\partial} \omega$ is piecewise exact for $d\omega \in \mathcal{A}_{\mathrm{hm}}(\riem_1)$ follows from Theorem \ref{th:jump_derivatives}. We need to show that such forms span the space. 

 To do so we first need an identity. 
 Let $\omega_k$ be the harmonic function which is one on the $k$th boundary curve and zero on the remaining boundary curves. Set 
 \[  \beta_k = \mathbf{S}_1 \partial \omega_k +   \overline{\mathbf{S}}_1 \overline{\partial} \omega_k   \]
 We then have that by definition of $H_{C_j}$  
 \begin{align*}
   \int_{C_j} \beta_k & = (\beta_k,\ast H_{C_j})_{\mathscr{R}} \\
   & = (\mathbf{S}^{\mathrm{h}}_1 d\omega,\ast H_{C_j})_{\mathscr{R}} \\
   & = (d\omega, \mathbf{R}_1^{\mathrm{h}} \ast H_{C_j})_{\riem_1} \\
   & = \left(d\omega, \mathbf{R}_1^{\mathrm{h}}\left[ \frac{1}{2} \left(\ast H_{C_j} -i H_{C_j} \right)+  \frac{1}{2} \left(\ast H_{C_j} +i H_{C_j} \right) \right] \right)_{\riem_1}.
 \end{align*}
 So 
 \begin{align*}
   \int_{C_j} \beta_k & =  \left(  \partial \omega_k, \frac{1}{2} \mathbf{R}_1\left( \ast H_{C_j} -i H_{C_j} \right)  \right)_{\riem_1} +
   \left(  \, \overline{\partial} \omega_k, \frac{1}{2}\overline{\mathbf{R}_1}  \left( \ast H_{C_j} + i H_{C_j} \right)  \right)_{\riem_1}
   \\  & =  \left( d \omega_k, \frac{1}{2} \mathbf{R}_1\left( \ast H_{C_j} -i H_{C_j} \right)  \right)_{\riem_1} +
   \left(  \, d\omega_k, \frac{1}{2}\overline{\mathbf{R}_1}  \left( \ast H_{C_j} + i H_{C_j} \right)  \right)_{\riem_1}
   \\
   & = \left(  d \omega_k,  \mathbf{R}^{\mathrm{h}}_1 \ast H_{C_j}  \right)_{\riem_1}.
 \end{align*}

 So we have
 \begin{align} \label{eq:integral_beta_is_integral_H}
  \int_{C_j} \beta_k  
  & = - \iint_{\riem_1} d \omega_k \wedge H_{C_j} \nonumber \\
  & = - \int_{\partial \riem_1} \omega_k H_{C_j} \nonumber \\
  & = - \int_{\partial_k \riem_1} H_{C_j}.
 \end{align}
 It now follows immediately from \eqref{eq:integrals_of_Hcs} that the $\beta_k$ span $\mathcal{A}^{\mathrm{pe}}_{\mathrm{harm}}(\mathscr{R})$. This completes the proof.
\end{proof}



We also have the following elementary fact.
\begin{proposition} \label{pr:period_submatrix_also_positive}
 Fix a bordered Riemann surface $\riem$ of type $(g,n)$. Fix a subcollection $\gamma_1,\ldots,\gamma_m$ of the boundary curves $\{ \partial_1 \riem,\ldots, \partial_n \riem \}$. For any $c_1,\ldots,c_m \in \mathbb{C}$, there is an $\omega \in \mathcal{A}_{\mathrm{hm}}(\riem)$ whose boundary values are only non-zero on $\gamma_1,\ldots,\gamma_m$, such that 
 \[  \int_{\gamma_k} \omega = c_k.   \]
\end{proposition}
\begin{proof}
 Let $j_1,\ldots,j_m$ be the indices of the subcollection of curves; that is, $\gamma_{l} =\partial_{j_l} \riem$ for $l=1,\ldots,m$. Following a similar strategy as in the proof of Corollary \ref{co:boundary_periods_specified_starmeasure}, it is readily seen that we need to prove the existence of a solution to the system of equations 
  \[  c_k=  \int_{\gamma_k}  \sum_{l=1}^n a_l \ast d \omega_{j_l} =\sum_{l=1}^n \int_{\partial_{j_k} \riem}   a_l \ast d \omega_{j_l}= \sum_{l=1}^n\Pi_{j_k j_l} a_l .      \]
 This follows from the fact that any square submatrix of a positive-definite matrix is also positive-definite.
\end{proof}

Now we define a subclass of the harmonic measures which lie in the kernel of $\mathbf{T}_{1,2}$. 

 \begin{definition}  
  We say that $\omega \in \mathcal{D}_{\text{harm}}(\riem_1)$ is \emph{bridgeworthy} if
  \begin{enumerate}
   \item it is constant on each boundary curve;
   \item on any pair of boundary curves $\partial_k \riem_1$ and $\partial_m \riem_1$ that bound the same connected component of $\riem_2$, the boundary values of $\omega$ are equal.
  \end{enumerate}

  We say that $\alpha \in \mathcal{A}_{\mathrm{hm}}(\riem_1)$ is bridgeworthy if $\alpha = d\omega$ for some bridgeworthy harmonic function $\omega$.  Denote the collection of bridgeworthy harmonic functions by
 $\gls{Dbw}(\riem_1)$,  and the collection of bridgeworthy  harmonic one-forms by 
 $\gls{Abw}(\riem_1)$.  The same definitions apply to $\riem_2$.
 \end{definition}
 The name is meant to invoke the following geometric picture: $\omega$ is bridgeworthy if it has the same constant value on any pair of boundary curves which are connected by a ``bridge'' in $\riem_2$. 

 \begin{remark} If $\riem_1$ has more than one connected component, then  a bridgeworthy harmonic one-form has anti-derivatives which are not bridgeworthy. This is because one can add to a bridgeworthy harmonic function $\omega$ any function which is constant on connected components without changing $d\omega$. 
 \end{remark}


We will also need the following characterization of the kernel of $\mathbf{S}_k^{\mathrm{h}}$.
