\begin{section}{Schiffer operators: cohomology and index theorems} \label{se:index_cohomology}
\begin{subsection}{Schiffer operators and cohomology}  \label{se:Schiffer_cohomology}

 In this section, we investigate the effect of the Schiffer operators with the cohomology classes of the one-forms on $\riem_1$ and $\riem_2$. The main tool to do so is the overfared jump formula. The results of this section will be used in the next two sections in determining their kernels, cokernels, and Fredholm indices.   

 We begin by characterizing the kernels and images of the restriction operator $\mathbf{R}_k$ and its adjoint $\mathbf{S}_k$.  

 \begin{theorem}  \label{th:S_kernel_range}   The Schiffer operators $\mathbf{R}_k$ and $\mathbf{S}_k$ satisfy
  \begin{align*} 
    \mathrm{Ker}(\mathbf{R}_k) & = \{0\} \\
    \mathrm{Im}(\mathbf{S}_k) & = \mathcal{A}(\mathscr{R}) \\
    \mathrm{Ker}(\mathbf{S}_k) & = [\mathbf{R}_k \mathcal{A}(\mathscr{R}) ]^\perp 
  \end{align*}
  for $k=1,2$.  The image of $\mathbf{R}_k$ is a $g$-dimensional subspace. 
  The corresponding statements hold for the complex conjugates.
 \end{theorem}
 \begin{proof} 
  The first statement is proven using analytic continuation.  The second statement follows from the first, and {Theorem \ref{th:adjoint_identities} which in turn yields that $\text{Im}(\mathbf{S}_k) = [\text{Ker} \, \mathbf{R}_k]^\perp$.}  The remaining statements are elementary.
 \end{proof}

 This yields the following:
 \begin{theorem}   \label{th:S_an_isomorphism} We have
  \begin{align*}
      \mathbf{S}_k \mathbf{R}_k : \mathcal{A}(\mathscr{R}) & \rightarrow \mathcal{A}(\mathscr{R}) \\
      \overline{\mathbf{S}}_k \overline{\mathbf{R}}_k : \overline{\mathcal{A}(\mathscr{R})} & \rightarrow \overline{\mathcal{A}(\mathscr{R})}
  \end{align*}
  are isomorphisms.
 \end{theorem}
 \begin{proof} It is enough to prove the first claim. 
  By Theorem \ref{th:S_kernel_range}, we have that $\mathbf{S}_k$ is surjective.  Thus for any $y \in \mathcal{A}(\mathscr{R})$ there is a $u \in \mathcal{A}(\riem_k)$ such that $\mathbf{S}_k u = y$.  Writing $u=v+w$ in terms of the orthogonal decomposition $\mathcal{A}(\riem_k) = [\mathbf{R}_k\mathcal{A}(\mathscr{R})]^\perp \oplus [\mathbf{R}_k \mathcal{A}(\mathscr{R})]$, since by Theorem \ref{th:S_kernel_range} we also have that $\mathbf{S}_k v=0$, we see that 
  \[ y = \mathbf{S}_k u = \mathbf{S}_k w   \]
  so $y \in \mathrm{Im}(\mathbf{S}_k \mathbf{R}_k),$ and thus $\mathbf{S}_k \mathbf{R}_k$ is surjective. Now since $\text{Ker}(\mathbf{S}_k \mathbf{R}_k )=(\mathrm{Im} (\mathbf{S}_k \mathbf{R}_k ))^{\perp}= \mathcal{A}(\mathscr{R}) ^{\perp}=0 $, we also have that $\mathbf{S}_k \mathbf{R}_k$ is injective.

 \end{proof}
  In what follows, we will apply the identities of Section \ref{se:Schiffer_Cauchy} to investigate how the Schiffer operators affect the cohomology classes of the one-forms to which they are applied.  The spaces
  \[  [\mathbf{R}_k \mathcal{A}(\mathscr{R})]^\perp = \{   {\alpha} \in \mathcal{A}(\riem_k) : (\alpha,{R}_k \beta) =0 \ \ \ \  \forall \beta \in \mathcal{A}(\mathscr{R}) \}= 
  [\mathbf{R}_k \mathcal{A}(\mathscr{R})]^\perp   \]
  and their complex conjugates
 \[   [\overline{\mathbf{R}}_k \overline{\mathcal{A}(\mathscr{R})}]^\perp  
    =  \{   \overline{\alpha} \in \overline{\mathcal{A}(\riem_k)} : (\overline{\alpha},{R}_k \overline{\beta}) =0 \ \ \ \  \forall \overline{\beta} \in \overline{\mathcal{A}(\mathscr{R})} \}  \]
  introduced in the proof above will play an important role.    
  \begin{remark}
    Throughout,  $[\mathbf{R}_k \mathcal{A}(\mathscr{R})]^\perp$ will always refer to the orthogonal complement in $\mathcal{A}(\riem_k)$ rather that in $\mathcal{A}_{\mathrm{harm}}(\riem_k)$, and similarly for $[\overline{\mathbf{R}}_k \overline{\mathcal{A}(\mathscr{R})}]^\perp$.  
  \end{remark}



     By a capped surface, we mean the special case that $\riem_1$ consists of $n$ simply-connected domains.   We say that $\riem_2$ is capped by $\riem_1$. 

    Recalling  $\mathbf{O}^\mathrm{e}_{2,1}$ from {Definition \ref{def:exact overfare}} and the projection operator \[  \overline{\mathbf{P}}_{1}: \mathcal{A}_{\mathrm{harm}}(\riem_1) \rightarrow \overline{\mathcal{A}(\riem_1)}, \] we have the following theorem of   M. Shirazi \cite{Shirazi_thesis,Schippers_Shirazi_Staubach}. 
  \begin{theorem} \label{th:Mohammad_isomorphism}
    Assume that $\riem_2$ is capped by $\riem_1$.  Then 
   \[\mathbf{T}_{1,2}([\overline{\mathbf{R}}_1 \overline{\mathcal{A}(\mathscr{R})}]^\perp  ) = 
   \mathcal{A}^\mathrm{e}(\riem_2) \]
   and 
   $\mathbf{T}_{1,2}:[\overline{\mathbf{R}}_1 \overline{\mathcal{A}(\mathscr{R})}]^\perp   \rightarrow \mathcal{A}^\mathrm{e}(\riem_2)$ is an isomorphism with inverse $-\overline{\mathbf{P}}_1 \mathbf{O}^\mathrm{e}_{2,1}$. In particular, 
   \[ \mathrm{Im}(\overline{\mathbf{P}}_1\mathbf{O}_{2,1}^{\mathrm e}) = [\overline{\mathbf{R}}_1 \overline{\mathcal{A}(\mathscr{R})}]^\perp.  \]
  \end{theorem}
  \begin{proof}
   We show that $\mathbf{T}_{1,2}([\overline{\mathbf{R}}_1 \overline{\mathcal{A}(\mathscr{R})}]^\perp) \subseteq  
   \mathcal{A}^\mathrm{e}(\riem_2)$.  Since each connected component of $\riem_1$ is simply connected, for any $\overline{\alpha} \in [\overline{\mathbf{R}}_1 \overline{\mathcal{A}(\mathscr{R})}]^\perp$, there is an $H \in \overline{\mathcal{D}(\riem_1)}$ such that $\overline{\alpha} =\overline{\partial} H$. Since by Theorem \ref{th:S_kernel_range} $\overline{\mathbf{S}}_1 \overline{\alpha} =0$, Theorem   \ref{th:jump_derivatives} yields that
   \[ \mathbf{T}_{1,2} \overline{\alpha} = \mathbf{T}_{1,2} \overline{\alpha}  + \overline{\mathbf{S}}_1 \overline{\alpha} = d \mathbf{J}^q_{1,2} H \in \mathcal{A}^\mathrm{e}(\riem_2).   \]
   Note that the computation is valid for any fixed value of $q$.

   To show that it is onto, let ${\beta} \in \mathcal{A}^\mathrm{e}(\riem_2)$, so that there is some $h \in \mathcal{D}(\riem_2)$ such that $\partial h = \beta$. 
   Setting $H= - \mathbf{O}_{2,1} h$, we have by Theorem \ref{th:J_same_both_sides} 
   \[  \dot{\mathbf{J}}_{1,2} \dot{\mathbf{O}}_{1,2} H = - \dot{\mathbf{J}}_{1,2} \dot{\mathbf{O}}_{2,1} h = + \dot{\mathbf{J}}_{2,2}  h = \dot{h}. \]
    where we have used Theorem \ref{th:jump_on_holomorphic}.  
   Since $\beta = \partial h = dh$, Theorem
   \ref{th:jump_derivatives} yields
   \[  \beta = d \dot{\mathbf{J}}_{1,2} \dot{H} = \mathbf{T}_{1,2} \overline{\partial} H + \overline{\mathbf{R}}_2 \overline{\mathbf{S}}_1 \overline{\partial} H.  \]
   Since the left hand side is holomorphic, $\overline{\mathbf{R}}_2 \overline{\mathbf{S}}_1 \overline{\partial} H=0$, so by Theorem \ref{th:S_kernel_range} $\overline{\partial} H \in
  [\overline{\mathbf{R}}_1 \overline{\mathcal{A}(\mathscr{R})}]^\perp$.

  Next we show that $\mathbf{T}_{1,2}$ is injective on $[\overline{\mathbf{R}}_1 \overline{\mathcal{A}(\mathscr{R})}]^\perp$. Let $\overline{\alpha}  \in [\overline{\mathbf{R}}_1 \overline{\mathcal{A}(\mathscr{R})}]^\perp$. Again since the components of $\riem_1$ are simply connected, we can assume that $\overline{\alpha} = \overline{\partial} H$ for some $H \in \overline{\mathcal{D}(\riem_1)}$. By Theorem
  \ref{th:Overfare_with_correction_functions} 
  \[   \dot{\mathbf{O}}_{2,1} \dot{\mathbf{J}}_{12}  \dot{H} = \dot{\mathbf{J}}_{1,1} \dot{H} - \dot{H}
         \]
  so differentiating and applying Theorems \ref{th:jump_derivatives}
  and \ref{th:S_kernel_range} we obtain
  \[  \mathbf{O}^e_{1,2} \mathbf{T}_{1,2} \overline{\alpha}  = d \mathbf{J}^q_{1,1} H = \partial H + \mathbf{T}_{1,1} \overline{\partial} H - dH = -\overline{\alpha} + \mathbf{T}_{1,1} \overline{\alpha}.   \]
  Thus $-\overline{\mathbf{P}}_1\mathbf{O}^\mathrm{e}_{2,1}$ is a left inverse for the restriction of $\mathbf{T}_{1,2}$ to $[\overline{\mathbf{R}}_1 \overline{\mathcal{A}(\mathscr{R})}]^\perp$. This proves injectivity, and since we already have surjectivity and boundedness, the restriction of $\mathbf{T}_{1,2}$ is invertible with inverse $-\overline{\mathbf{P}}_1\mathbf{O}^\mathrm{e}_{2,1}$ as claimed.
  \end{proof}

 We will improve and extend this theorem in different ways below. 
 The following corollary and lemma allows us to make use of the jump formula to examine cohomology classes.  

\begin{corollary} \label{co:specify_internal_periods}
 Let $\riem$ be a Riemann surface of type $(g,n)$ with internal homology basis $\{\gamma_1,\ldots,\gamma_{2g}\}$. For any constants $\lambda_1,\ldots,\lambda_{2g} \in \mathbb{C}$ there is an $\alpha \in \mathcal{A}(\riem)$ such that
 \[  \int_{\gamma_k} \alpha =  \lambda_k,  \ \ \ \ \ k=1,\ldots,2g.    \]
 The same claim obviously holds for $\overline{\mathcal{A}(\riem)}$.  
\end{corollary}
\begin{proof}  Sew on caps to $\riem$ to obtain a compact surface $\mathscr{R}$ of genus $g$, where $\riem_1$ are the caps and $\riem_2=\riem$.  So we prove the claim for $\riem= \riem_2$.  

 By the Hodge theorem applied to $\mathscr{R}$, there is a $\zeta = \xi + \overline{\eta} \in \mathcal{A}_{\text{harm}}(\mathscr{R})$ such that
 \[   \int_{\gamma_k} \zeta = \lambda_k      \]
 for $k=1,\ldots,n$.  Now since $\mathbf{S}_1 \mathbf{R}_1:\mathcal{A}(\mathscr{R}) \rightarrow \mathcal{A}(\mathscr{R})$ is an isomorphism by Theorem \ref{th:S_kernel_range},   there is a $\overline{\sigma} \in \overline{\mathcal{A}(\mathscr{R})}$ such that $\overline{\mathbf{S}}_1 \overline{\mathbf{R}}_1 \overline{\sigma} = \overline{\eta}$. 

 Since the components of $\riem_1$ are simply connected, $\overline{\mathbf{R}}_1 \overline{\sigma}$ is exact, so there is an $H \in \overline{\mathcal{D}_{\mathrm{harm}}(\riem_1)}$ such that $\overline{\partial} H = \overline{\mathbf{R}}_1 \overline{\sigma}$.  So 
 by Theorem \ref{th:jump_derivatives} we have 
 \[ \overline{\mathbf{R}}_2 \overline{\mathbf{S}}_1 \overline{\mathbf{R}}_1 \overline{\sigma}  + \mathbf{T}_{1,2} \overline{\mathbf{R}}_1 \overline{\sigma} = d \mathbf{J}^q_{1,2} H \in \mathcal{A}^\mathrm{e}_{\text{harm}}(\riem_2)  \]
 so 
 $\mathbf{R}_2 \xi - \mathbf{T}_{1,2} \overline{\mathbf{R}}_1 \overline{\sigma}$
 has the desired periods. 
\end{proof}

 \begin{lemma} \label{le:dbar_representative}
  Let $\riem$ be an arbitrary Riemann surface of type $(g,n)$.  Given any $\overline{\alpha} \in \overline{\mathcal{A}(\riem)}$, there is an $h \in \mathcal{D}_{\mathrm{harm}}(\riem)$ such that $\overline{\partial} h = \overline{\alpha}$.  Any other such $\tilde{h}$ is such that $h-\tilde{h} \in \mathcal{D}(\riem)$.  

  The corresponding statement holds for $\alpha \in \mathcal{A}(\riem)$, replacing $\overline{\partial}$ with $\partial$.  
 \end{lemma}
\begin{proof} Fix $\overline{\alpha} \in \overline{\mathcal{A}(\riem)}$.
 First, we show that there is a $\beta \in \mathcal{A}(\riem)$ such that $\overline{\alpha} - \beta$ is exact. 
 By Corollary \ref{co:specify_internal_periods}, for any $\overline{\alpha} \in \overline{\mathcal{A}(\riem)}$ we may find a ${\delta} \in {\mathcal{A}(\riem)}$ such that 
 \[  \int_{\gamma_k} ( \overline{\alpha} - {\delta} ) = 0    \]
 for $k=1,\ldots,2g$.  So it is enough to show that for any constants $\mu_1,\ldots,\mu_n$ such that $\mu_1 + \cdots + \mu_n = 0$  there is a ${\nu} \in {\mathcal{A}(\riem_2)}$ such that 
 \begin{equation} \label{eq:rep_lemma_temp}
    \int_{\partial_k \riem} \nu = \mu_k    
 \end{equation}
 for $k=1,\ldots,n$.  By Corollary \ref{co:boundary_periods_specified_starmeasure} there is a harmonic measure $d\omega \in \mathcal{A}_{\text{hm}}(\riem)$ such that $\ast d \omega$ satisfies \eqref{eq:rep_lemma_temp}.  Setting
 \[   \nu = \ast d \omega + i d\omega \in {\mathcal{A}(\riem)},      \]
 since $d\omega$ is exact, $\nu$ has the same periods as $\ast d \omega$. Setting $\beta = \delta + \nu$ proves the claim. 

 So let $\beta$ be such that $\overline{\alpha} - \beta$ is exact.  Letting $h$ be such that $d h= \overline{\alpha} - \beta$ we then have that $\overline{\partial} h=\overline{\alpha}$ as claimed. If $\overline{\partial} \tilde{h} = \overline{\alpha}$ then $\overline{\partial} (h-\tilde{h}) =0$ so $h-\tilde{h} \in \mathcal{D}(\riem)$.  
\end{proof}



 \begin{theorem} \label{th:Schiffer_cohomology}
  For any $\overline{\alpha} \in \overline{\mathcal{A}(\riem_1)}$,
  \begin{enumerate}
      \item  [$(1)$] $\mathbf{T}_{1,2} \overline{\alpha}+\overline{\mathbf{R}}_2 \overline{\mathbf{S}}_1 \overline{\alpha}$ is exact on $\riem_2$; and 
      \item [$(2)$] $-\overline{\alpha} + \mathbf{T}_{1,1} \overline{\alpha}+\overline{\mathbf{R}}_1 \overline{\mathbf{S}}_1 \overline{\alpha}$ is exact on $\riem_1$.
  \end{enumerate}
  If $\mathscr{R}$ has genus zero, then $\mathbf{T}_{1,2} \overline{\alpha}$ and $-\overline{\alpha} + \mathbf{T}_{1,2} \overline{\alpha}$ are exact. 

  The same statements apply to the complex conjugates, and all statements hold with $1$ and $2$ interchanged.  
 \end{theorem}
 \begin{proof}
  By Lemma \ref{le:dbar_representative} there is an $h \in \mathcal{D}_{\mathrm{harm}}(\riem_1)$ such that $\overline{\partial} h = \overline{\alpha}$. 
  Also, Theorem \ref{th:jump_derivatives} yields that
  \begin{equation} \label{eq:jump_cohomology_identity}
    d \mathbf{J}^q_1 h = \left\{ \begin{array}{ll}  \partial h + \mathbf{T}_{1,1} \overline{\partial} h + \overline{\mathbf{R}}_1 \overline{\mathbf{S}}_1   \overline{\partial} h  & \riem_1 \\
    \mathbf{T}_{1,2} \overline{\partial} h + \overline{\mathbf{R}}_2 
    \overline{\mathbf{S}}_1 \overline{\partial} h & \riem_2. 
    \end{array} \right.         
  \end{equation}
  Now using $dh= \partial h + \overline{\partial} h = \partial h + \overline{\alpha}$ we see that 
  \begin{equation} \label{eq:jump_cohomology_identity_11}
   d \mathbf{J}^q_{1,1} h =  dh - \overline{\alpha} + \mathbf{T}_{1,1} \overline{\alpha}  + \overline{\mathbf{R}}_1 \overline{\mathbf{S}}_1   \overline{\alpha}   
  \end{equation}
  and 
  \begin{equation} \label{eq:jump_cohomology_identity_12} 
       d \mathbf{J}^q_{1,2} h =  \mathbf{T}_{1,2} \overline{\alpha} + \overline{\mathbf{R}}_2 
    \overline{\mathbf{S}}_1 \overline{\alpha}. 
  \end{equation}
  This proves claims (1) and (2).  If $\mathscr{R}$ has genus zero, then the third claim follows from the fact that $K_\mathscr{R}=0$ (see Example \ref{ex:sphere_kernels}).  
  The remaining claims are obvious.
 \end{proof}

 This simple fact is surprisingly illuminating.  We list two immediate corollaries. 
 \begin{corollary}  \label{co:one_plus_T_periods}
  Let $\overline{\alpha} \in \overline{A(\riem_1)}$.  
  For any curve $c$ in $\riem_1$, 
  \begin{align*}
  \int_{c} (\overline{\alpha} - \mathbf{T}_{1,1} \overline{\alpha}) & =  \int_c \overline{\mathbf{S}}_1 \overline{\alpha} \\ & =  \left<  \overline{\alpha}, \ast \overline{\mathbf{R}}_1 H_c  \right>_{\riem_1} \\ & =  \int_c \left[ \mathbf{I} - \mathbf{T}_{1,1}^* \mathbf{T}_{1,1} - \mathbf{T}_{1,2}^* \mathbf{T}_{1,2} \right] \overline{\alpha} 
  \end{align*}
  where $H_c$ is associated to $c$ by \emph{(\ref{eq:H_forms_definition})}.  The same formulas hold with $1$ and $2$ interchanged, as do the complex conjugates.  
 \end{corollary} 
 \begin{proof}
  The first equality follows directly from Theorem \ref{th:Schiffer_cohomology}.  The second equality follows from the definition of $H_c$ and Theorem \ref{th:adjoint_identities}, observing that $\ast$ commutes with $\overline{\mathbf{R}}_1$.  The final equality follows from the identity $\mathbf{T}_{1,1}^* \mathbf{T}_{1,1} + \mathbf{T}_{1,2}^* \mathbf{T}_{1,2} = \mathbf{I} - \overline{\mathbf{R}}_1 \overline{\mathbf{S}}_1$ given in Theorem \ref{th:general_adjoint_double_identities}.  
 \end{proof}


 \begin{corollary}   \label{co:image_Tonetwo_periods}
  For any curve $c$ in $\riem_2$ and $\overline{\alpha} \in 
  \overline{\mathcal{A}(\riem_2)}$
  \begin{align*}
   -\int_{c} \mathbf{T}_{1,2}   \overline{\alpha} & =  \int_c \overline{\mathbf{S}}_2 \overline{\alpha} \\
   & = \left< \overline{\alpha}, \ast \overline{\mathbf{R}}_2 H_c \right>_{\riem_2}  \\
   & = \int_c \left[ \mathbf{I} - \mathbf{T}_{2,2}^* \mathbf{T}_{2,2} - \mathbf{T}_{2,1}^* \mathbf{T}_{2,1} \right] \overline{\alpha}.
  \end{align*}
  The same statement holds with $1$ and $2$ interchanged, and with complex conjugates.
 \end{corollary}
 \begin{proof}  The proof is identical to that of Corollary \ref{co:one_plus_T_periods}, except in the last step we use the identity
   $\mathbf{T}_{2,2}^* \mathbf{T}_{2,2} + \mathbf{T}_{2,1}^* \mathbf{T}_{2,1} + \overline{\mathbf{R}}_2 \overline{\mathbf{S}}_2= \mathbf{I}$
   of Theorem \ref{th:general_adjoint_double_identities}.  
 \end{proof}



   If $\riem_2$ is connected, recall Definition \ref{def:exact overfare}: for 
 $\alpha \in \mathcal{A}^{\mathrm e}_{\text{harm}}(\riem_2)$, we define
 \[   \mathbf{O}^{\mathrm{e}}_{2,1} \alpha= d \mathbf{O}_{2,1} h      \]
 for $dh = \alpha$.  
  \begin{proposition} \label{prop:exact_transmitted_jump} Assume that $\riem_2$ is connected.  
  For $\overline{\alpha} \in \overline{\mathcal{A}(\riem_1)}$ we have
  \[  \mathbf{O}^{\mathrm{e}}_{2,1} \left[ \mathbf{T}_{1,2} \overline{\alpha} + \overline{\mathbf{R}}_{2} \overline{\mathbf{S}}_1 \overline{\alpha} \right] = -\overline{\alpha} + \mathbf{T}_{1,1} \overline{\alpha} + \overline{\mathbf{R}}_{1} \overline{\mathbf{S}}_1 \overline{\alpha}. \]
  In particular, if $\overline{\alpha} \in (\overline{\mathbf{R}}_1 \overline{\mathcal{A}(\mathscr{R})})^\perp$ we have
   \[  \mathbf{O}^{\mathrm{e}}_{2,1}  \mathbf{T}_{1,2} \overline{\alpha} = - \overline{\alpha} + \mathbf{T}_{1,1} \overline{\alpha}.   \]
   The complex conjugate statements hold, as do the statements with the roles of $1$ and $2$ interchanged.
  \end{proposition}
  \begin{proof}
   By Lemma \ref{le:dbar_representative} there is an $h \in \mathcal{D}_{\mathrm{harm}}(\riem_1)$ such that $\overline{\partial} h = \overline{\alpha}$.   Differentiating both sides of the first expression appearing in Theorem \ref{th:Overfare_with_correction_functions} part (1)
   %or \ref{prop:transmitted_jump_with_corrections_caps} as appropriate 
   proves the first claim.  By Theorem \ref{th:S_kernel_range}, $\mathbf{S}_1 \overline{\alpha} = 0$ when $\overline{\alpha} \in (\overline{\mathbf{R}}_1 \overline{\mathcal{A}(\mathscr{R})})^\perp$, which completes the proof. 
  \end{proof}
 \end{subsection}
 \begin{subsection}{Kernel and image of the Schiffer operator $\mathbf{T}_{1,2}$} \label{se:Schiffer_kernel_image}

 In this section, we determine the kernel and image of the Schiffer operator $\mathbf{T}_{1,2}$ in various configurations.

 We require a generalization of Theorem \ref{th:Mohammad_isomorphism}. Namely, we would like to characterize the kernel and image of $\mathbf{T}_{1,2}$ in general. We begin with a partial characterization.

 \begin{theorem} \label{th:general_T12_kernel_on_perp}  Assume that $\riem_2$ is connected.  Then 
  \[ \mathrm{Ker} ( \mathbf{T}_{1,2}) \cap [\overline{\mathbf{R}}_1 \overline{\mathcal{A}(\mathscr{R})}]^\perp = \{0 \}.   \] 
 \end{theorem}
 \begin{proof}
  Assume that $\overline{\alpha} \in \mathrm{Ker} ( \mathbf{T}_{1,2}) \cap [\overline{\mathbf{R}}_1 \overline{\mathcal{A}(\mathscr{R})}]^\perp$. By Lemma \ref{le:dbar_representative} there is a $H \in \mathcal{D}_{\text{harm}}(\riem_1)$ such that $\overline{\partial} H = \overline{\alpha}$. We have $\overline{\mathbf{S}}_1 \overline{\partial} H=0$ by Theorem \ref{th:S_kernel_range} so by Theorem \ref{th:jump_derivatives}
  \[  d \mathbf{J}^q_{1,2} H = \mathbf{T}_{1,2} \overline{\alpha} + \overline{\mathbf{R}}_2 \overline{\mathbf{S}}_1 \overline{\alpha} = 0. \]
  Therefore $\mathbf{J}^q_{1,2} H$ is constant, from which it follows that $\mathbf{O}_{2,1} \mathbf{J}^q_{1,2} H$ is constant. By Theorem \ref{th:Overfare_with_correction_functions} we have
  \[  d(H - \mathbf{J}^q_{1,1} H) = - d \mathbf{O}_{2,1} \mathbf{J}^q_{1,2} H = 0   \]
  so again using Theorem \ref{th:jump_derivatives} and the fact that $\overline{\mathbf{S}}_1 \overline{\partial} H=0$ we obtain 
  \[ \partial H + \overline{\partial} H - \mathbf{T}_{1,1} \overline{\partial} H = 0,    \]
  so equating holomorphic and anti-holomorphic parts
  \[  \overline{\partial} H =0.  \]
  This completes the proof.
 \end{proof}

 We also have the following.
 \begin{theorem} \label{th:general_T12_on_perp_surjective_to_exact} 
 Assume that $\riem_2$ is connected.  
 The image of $[\overline{\mathbf{R}}_1 \overline{\mathcal{A}(\mathscr{R})}]^\perp$ under $\mathbf{T}_{1,2}$ is $\mathcal{A}^{\mathrm{e}}(\riem_2)$. 
 \end{theorem}
 \begin{proof}
  Given any $\beta \in \mathcal{A}^\mathrm{e}(\riem_2)$, let $h \in \mathcal{D}(\riem_2)$ be such that $\partial h = \beta$, which exists by conjugating Lemma \ref{le:dbar_representative}.  Note that $h$ is not necessarily uniquely defined. Set $H=-\mathbf{O}_{2,1}h$. Applying Theorems \ref{th:J_same_both_sides} and \ref{th:jump_on_holomorphic} we obtain that
  \[  \dot{\mathbf{J}}_{1,2} \dot{H} =  \dot{\mathbf{J}}_{2,2} h = \dot{h}.  \]
   Differentiating using Theorem \ref{th:jump_derivatives} we see that
  \[  \mathbf{T}_{1,2} \overline{\partial} H + \overline{\mathbf{R}}_2 \overline{\mathbf{S}}_1 \overline{\partial} H = \beta.  \]
  Since $\beta$ is holomorphic $\overline{\mathbf{R}}_2 \overline{\mathbf{S}}_1 \overline{\partial} H = 0$ so $\overline{\mathbf{S}}_1 \overline{\partial} H = 0$ and hence $\overline{\partial} H \in [\overline{\mathbf{R}}_1 \overline{\mathcal{A}(\mathscr{R})}]^\perp$ by Theorem \ref{th:S_kernel_range}. Furthermore $\mathbf{T}_{1,2} \overline{\partial} H = \beta$ completing the proof.
 \end{proof}

 Theorems \ref{th:general_T12_on_perp_surjective_to_exact} and \ref{th:general_T12_kernel_on_perp} taken together generalize Theorem \ref{th:Mohammad_isomorphism} and \cite[Theorem 4.22]{Schippers_Staubach_Plemelj}. We will extend it still further below. For now, we observe the following corollary.
 Recall the projections $\mathbf{P}_k= \mathbf{P}_{\riem_k}$ and 
 $\overline{\mathbf{P}}_k = \overline{\mathbf{P}}_{\riem_k}$ defined by 
 \eqref{eq:hol_antihol_projections_Bergman}.
 \begin{corollary} \label{co:connected_get_iso}
  Let $\riem_2$ be connected.  Then the restriction of $\mathbf{T}_{1,2}$ to $[\overline{\mathbf{R}}_1 \overline{\mathcal{A}(\mathscr{R})}]^\perp$ is an isomorphism onto $\mathcal{A}^\mathrm{e}(\riem_2)$, with inverse $-\overline{\mathbf{P}}_1 \mathbf{O}^\mathrm{e}_{2,1}$. 
 \end{corollary}
 \begin{proof} 
  The restriction of $\mathbf{T}_{1,2}$ is surjective by Theorem \ref{th:general_T12_on_perp_surjective_to_exact}. Since $\riem_2$ is connected, any function $\omega$ with the bridge property must have the same constant value on each boundary of $\riem_1$, and hence must be constant. So the kernel is trivial.  

  Observe that since $\riem_2$ is connected $\mathbf{O}^\mathrm{e}_{2,1}$ is well-defined by the requirement that $d \mathbf{O}_{2,1} = \mathbf{O}^\mathrm{e}_{2,1}$. The fact that this is the inverse follows as in previous proofs. Let $H \in \mathcal{D}_{\text{harm}}(\riem_1)$ be such that $\overline{\partial} H = \overline{\alpha}$. By Theorems \ref{th:Overfare_with_correction_functions},  \ref{th:jump_derivatives}, and the fact that $\overline{\mathbf{S}}_1 \overline{\alpha}=0$ we see that 
  \[ \mathbf{O}^\mathrm{e}_{2,1} \overline{\alpha} = -\overline{\alpha} + \mathbf{T}_{1,1} \overline{\alpha}. \]
  The claim follows immediately.
 \end{proof}



 In order to determine the image of $\mathbf{T}_{1,2}$, we define certain natural subspaces of $\mathcal{A}(\riem_2)$.  Assume that $\riem_2$ is connected (but not necessarily $\riem_1$).  
 Let $c^k_1,\ldots,c^k_{m_k}$ be a fixed homology basis of simple closed curves for $\riem_k$ for $k=1,2$.  

 We then have a linear map 
 \begin{align}\label{capital Xi}
  \Xi_k: \mathcal{A}(\mathscr{R}) & \rightarrow \mathbb{C}^{m_k} \\\nonumber
  u & \mapsto \left( \int_{c^k_1} u,\ldots, \int_{c^k_{m_k}} u \right)
 \end{align}
 and the linear map 
 \begin{align}\label{capital Xibar}
  \overline{\Xi_k}: \overline{\mathcal{A}(\mathscr{R})} & \rightarrow \mathbb{C}^{m_k} \\\nonumber
  \overline{u} & \mapsto \left( \int_{c^k_1} \overline{u},\ldots, \int_{c^k_{m_k}} \overline{u} \right). 
 \end{align}
 We then define the subspaces 
 \begin{align}\label{capital Xk}
    X_k & = \text{Im}(\Xi_k) \subseteq \mathbb{C}^{m_k} \\
    \overline{X}_k & = \text{Im}(\overline{\Xi}_k) \subseteq \mathbb{C}^{m_k}.
 \end{align}
 Although $\Xi_k$ and $\overline{\Xi}_k$ depend on the choice of basis, $X_k$ and $\overline{X}_k$ do not.  
 It will sometimes be convenient to choose specific homology bases and an ordering.  Note that some curves in the homology base of $\mathcal{A}(\mathscr{R})$ may appear in the homology base of both $\riem_1$ and $\riem_2$, and that some curves in the homology base of $\mathcal{A}(\mathscr{R})$ might not appear in the homology base of either $\riem_1$ or $\riem_2$.  



 We then define the following subspaces of $\mathcal{A}(\riem_2)$: 
 \begin{equation}\label{svensk a}
\gls{gota}({\riem}_k) = \left\{  \alpha \in \mathcal{A}({\riem}_k) : \left( \int_{c^k_1} \alpha ,\ldots,\int_{c^k_{m_k}} \alpha  \right) \in X_k  \right\}.    
 \end{equation}  
 and 
 \begin{equation}\label{svensk abar}
    \mathrm{\textgoth{A}}^-(\riem_k) = \left\{  \alpha \in \mathcal{A}(\riem_k) : \left( \int_{c^k_1} \alpha ,\ldots,\int_{c^{k}_{m_k}} \alpha  \right) \in \overline{X}_k         \right\}  
 \end{equation}     
 for $k=1,2$.  
 Note that it is most certainly {\bf not} true that $\mathrm{\textgoth{A}}^-(\riem_k) = \overline{\mathrm{\textgoth{A}}(\riem_k)}$.   

 The definition immediately implies that
 \begin{proposition}  For $k=1,2$, given $\alpha \in \mathcal{A}(\riem_k)$, it holds that
 $\alpha \in \emph{{\textgoth{A}}}(\riem_k)$ if and only if $\alpha$ is in the same cohomology class as an element of $\mathbf{R}_k\mathcal{A}(\mathscr{R})$.  Similarly, $\alpha \in \emph{{\textgoth{A}}}^-(\riem_k)$ if and only if $\alpha$ is in the same cohomology class as an element of $\overline{\mathbf{R}}_k \overline{\mathcal{A}(\mathscr{R})}$.  
 \end{proposition}

 Another useful fact is the following.
 \begin{proposition}  \label{pr:XplusXbar_is_all}  
  For $k=1,2$ 
  \[  X_k {+} \overline{X}_k = \mathbb{C}^{m_k}.  \]
 \end{proposition}
 \begin{proof}
   This is an immediate consequence of the Hodge theorem, which says that every cohomology class on $\mathscr{R}$ has a representative in $\mathcal{A}_{\text{harm}}(\mathscr{R})$.  Thus every possible configuration of periods of $c^k_1,\ldots,c^k_{m_k}$ in $\mathscr{R}$ (and so, in particular of of $c^k_1,\ldots,c^k_{m_k}$ in $\riem_k$)  can be attained by an element of  $\mathcal{A}_{\text{harm}}(\mathscr{R})$.  
 \end{proof}





 The following theorem establishes the behaviour of $\mathbf{T}_{1,2}$ on its entire domain.    

 \begin{theorem} 
  \label{th:Tonetwo_iso_improved}  Assume that $\riem_2$ is connected.  
  Let 
  \[ \overline{W}_1 = \left\{\overline{\mu} \in \overline{\mathbf{R}}_1 \overline{\mathcal{A}(\mathscr{R})};\,\, \overline{\mathbf{R}}_2 \overline{\mathbf{S}}_1 {\overline{\mu} } \in \overline{\mathcal{A}^{\mathrm{e}}(\riem_2)} \right\}  \]
    We have 
    \begin{equation*}
      \mathrm{Im}(\mathbf{T}_{1,2})  = \emph{{\textgoth{A}}}^-(\riem_2)
    \end{equation*}
    and
    \begin{equation*}
     \mathrm{Ker}(\mathbf{T}_{1,2}) \cong  \overline{W}_1.
    \end{equation*}
    The same claim follows for the complex conjugates and with $1$ and $2$ interchanged.
 \end{theorem}
 \begin{proof}
    It follows from Theorem \ref{th:Schiffer_cohomology} that $\text{Im}(\mathbf{T}_{1,2}) \subseteq \mathrm{\textgoth{A}}^-(\riem_2)$.  We show that $\mathrm{\textgoth{A}}^-(\riem_2)  \subseteq  \text{Im}(\mathbf{T}_{1,2})$. 
 Let $\beta \in \mathrm{\textgoth{A}}^-(\riem_2)$. Again applying Theorem  \ref{th:Schiffer_cohomology}, since $\overline{\mathbf{S}}_1 \overline{\mathbf{R}}_1$ is an isomorphism by Theorem \ref{th:S_an_isomorphism}, we can find $\overline{\gamma} \in \overline{\mathcal{A}(\mathscr{R})}$ such that 
   \[  \beta - \mathbf{T}_{1,2}   \overline{\mathbf{R}}_1 \overline{\gamma}  \in \mathcal{A}^e(\riem_2).  \]
 By Theorem \ref{th:general_T12_on_perp_surjective_to_exact} there is an $\overline{\alpha} \in (\overline{\mathbf{R}}_1 \overline{\mathcal{A}(R)})^\perp$ such that 
   \[  \mathbf{T}_{1,2} \overline{\alpha} = \beta - \mathbf{T}_{1,2}  \overline{\mathbf{R}}_1 \overline{\gamma} \]
   which completes the proof of the first claim.

   We now prove the second claim. 
   Let $\overline{\mu} \in \overline{W}_1$. Since $\mathbf{T}_{1,2} \overline{\mu} + \overline{\mathbf{R}}_2 \overline{\mathbf{S}}_1 \overline{\mu}$ is exact by Theorem \ref{th:Schiffer_cohomology}, so is $\mathbf{T}_{1,2} \mu$.  Thus by Theorem \ref{th:general_T12_on_perp_surjective_to_exact} there is an $\overline{\alpha} \in  (\overline{\mathbf{R}}_1 \overline{\mathcal{A}(R)})^\perp$ such that $\mathbf{T}_{1,2} \overline{\alpha} = - \mathbf{T}_{1,2} \overline{\mu}$ so $\overline{\alpha} + \overline{\mu} \in \mathrm{Ker} (\mathbf{T}_{1,2})$.  We define 
   \begin{align*}
      \Phi:\overline{W}_1 & \rightarrow \mathrm{Ker}(\mathbf{T}_{1,2}) \\
      \overline{\mu} & \mapsto \overline{\alpha} + \overline{\mu}.
   \end{align*}
   This is well-defined, since if $\overline{\alpha} + \overline{\mu}$ and $\overline{\beta} + \overline{\mu}$ are both in $\mathrm{Ker}( \mathbf{T}_{12})$ for $\overline{\beta},\overline{\alpha} \in [\overline{\mathbf{R}}_1 \overline{\mathcal{A}(\mathscr{R})}]^\perp$ then $\overline{\alpha} - \overline{\beta} \in [\overline{\mathbf{R}}_1 \overline{\mathcal{A}(\mathscr{R})}]^\perp \cap \mathrm{Ker}( \mathbf{T}_{1,2})$ so $\overline{\alpha} -\overline{\beta} =0$ by Theorem \ref{th:general_T12_kernel_on_perp}.  

   This map is surjective. Assume that $\overline{\gamma}  \in \mathrm{Ker}(\mathbf{T}_{1,2})$.  Write $\overline{\gamma} = \overline{\alpha} + \overline{\mu}$ for $\overline{\alpha} \in  (\overline{\mathbf{R}}_1 \overline{\mathcal{A}(R)})^\perp$ and $\overline{\mu} \in \overline{\mathbf{R}}_1 \overline{\mathcal{A}(\mathscr{R})}$. Since $\mathbf{T}_{1,2} \overline{\alpha} = -\mathbf{T}_{1,2} \overline{\mu}$ and the former is exact by Theorem \ref{th:general_T12_on_perp_surjective_to_exact} we see that $\mathbf{T}_{1,2} \overline{\mu}$ is exact. Thus by Theorem \ref{th:Schiffer_cohomology} $\overline{\mathbf{R}}_2 \overline{\mathbf{S}}_1 \overline{\mu}$ is exact.  So $\overline{\mu} \in \overline{W}_1$ and $\Phi(\overline{\gamma}) = \overline{\gamma}$. 

   This map is injective.  Assume that $\Phi(\overline{\mu})=0$. Then $\overline{\alpha} + \overline{\mu} =0$.  Using Theorem \ref{th:general_T12_kernel_on_perp} and the fact that $\overline{\alpha} \in [\overline{\mathbf{R}}_1 \overline{\mathcal{A}(\mathscr{R})}]^\perp$ we obtain that $\overline{\mu} \in [\overline{\mathbf{R}}_1 \overline{\mathcal{A}(\mathscr{R})}]^\perp$.  So $\overline{\mu}=0$. 
 \end{proof}
 \begin{remark} \label{re:explicit_Tpartialinverse_construction}
  The element $\overline{\alpha}$ corresponding to $\overline{\mu}$ in the definition of $\Phi$ can be constructed explicitly as follows.  Given $\overline{\mu} \in \overline{W}_1$, since $\mathbf{T}_{1,2} \overline{\mu}$ is exact, there is an $h \in \mathcal{D}(\riem_2)$ such that $\partial h = \mathbf{T}_{1,2} \overline{\mu}$. Set $H=  \mathbf{O}_{2,1} h$.   So 
  \[  \mathbf{J}_{1,2}^q H = -\mathbf{J}^q_{2,2} h = -h + c \]
  for some $c$ which is constant on connected components, by Theorems \ref{th:J_same_both_sides} and \ref{th:jump_on_holomorphic}.  So applying Theorem \ref{th:jump_derivatives} we obtain 
  \[  \mathbf{T}_{1,2} \overline{\partial} H + \overline{\mathbf{R}}_2  \overline{\mathbf{S}}_1 \overline{\partial} H =  d \mathbf{J}_{1,2} H = - \partial h = -\mathbf{T}_{1,2} \overline{\mu}. \]
  But since the right hand side is holomorphic, we must have that $\overline{\mathbf{R}}_2  \overline{\mathbf{S}}_1 \overline{\partial} H =0$ so by analytic continuation and Theorem \ref{th:S_kernel_range} we see that $\overline{\alpha} =\overline{\partial} H \in [\overline{\mathbf{R}}_1 \overline{\mathcal{A}(\mathscr{R})}]^\perp$ and
  \[  \mathbf{T}_{1,2} (\overline{\alpha} + \overline{\mu} ) =0. \]
  We may summarize this by saying that 
  \[  \Phi =  \mathbf{I} - \overline{\mathbf{P}}_1 d \mathbf{O}_{2,1} d^{-1} \mathbf{T}_{1,2}     \]
  observing that this is well-defined by the proof of the theorem.
 \end{remark}


   This has the following important consequence.
   \begin{corollary}  \label{co:T_plus_extra_surjective_capped}  Let $\riem_2$ be capped by $\riem_1$.  Then $\mathrm{ker}(\mathbf{T}_{1,2})$ is trivial.
   Furthermore, 
    any $\alpha \in \mathcal{A}(\riem_2)$ can be written 
    \[  \alpha = \mathbf{T}_{1,2} \overline{\gamma} + \mathbf{R}_2  \tau + \partial \omega  \]
    for unique $\overline{\gamma} \in \overline{\mathcal{A}(\riem_1)}$, $\tau \in \mathcal{A}(\mathscr{R})$, and $d\omega \in \mathcal{A}_{\mathrm{hm}}(\riem_2)$.     That is 
    \[    \mathcal{A}(\riem_2) = \emph{\textrm{\textgoth{A}}}^{-}(\riem_2) \oplus \mathbf{R}_2 \mathcal{A}(\mathscr{R}) \oplus \partial \mathcal{D}_{\mathrm{hm}}(\riem_2).       \]
    The same claim holds for complex conjugates.
   \end{corollary}
   \begin{proof}  
    Since any exact form on $\mathscr{R}$ is zero, we see that $\overline{W}_1 = \{0 \}$, so the kernel is zero by Theorem \ref{th:Tonetwo_iso_improved}.  
    Since the periods of elements of $\mathbf{R}_2 \mathscr{A}_{\mathrm{harm}}(\mathscr{R})$ are zero around the boundary curves $\partial_k \riem_2$ for all $k$, we see that $\ast \mathcal{A}_{\mathrm{hm}}(\riem_2)$ and $\mathbf{R}_2 \mathscr{A}_{\mathrm{harm}}(\mathscr{R})$ are linearly independent. Using the decomposition 
    \[  \partial \omega = \frac{1}{2}\left( d\omega + i \ast d\omega \right) \]
    shows that $\partial \mathcal{D}_{\mathrm{harm}}(\riem_2)$ and $\mathbf{R}_2 \mathcal{A}_{\mathrm{harm}}(\mathscr{R})$ are linearly independent. 

    Now $X_1$ and $\overline{X}_1$ are linearly independent, since each has dimension $g$, and the dimension of $X_1 + \overline{X}_1$ is $2g$.  Thus since $\text{Im}(\mathbf{T}_{1,2}) = {\mathrm{\textgoth{A}}}^{-}(\riem_2)$ by Theorem \ref{th:Tonetwo_iso_improved}, this proves that 
    \[  \mathcal{A}(\riem_2) = {\textrm{\textgoth{A}}}^{-}(\riem_2)  + \mathbf{R}_2 \mathcal{A}(\mathscr{R}) + \partial \mathcal{D}_{\mathrm{hm}}(\riem_2).  \]
    decomposition. Linear independence proves that the decomposition is a direct sum, and uniqueness of $\tau$. The uniqueness of $\overline{\partial} \omega$ follows from Theorem \ref{th:period_matrix_invertible}, and uniqueness of $\overline{\gamma}$ follows from triviality of the kernel of $\mathbf{T}_{1,2}$.  
   \end{proof}

\end{subsection}
\begin{subsection}{Fredholm index of the Schiffer operator} \label{th:index_and_examples}
 In this section, we derive the Fredholm index of the Schiffer operator $\mathbf{T}_{1,2}$ for the case where $\riem_1$ and $\riem_2$ are connected, and for the case that $\riem_2$ is capped by $\riem_1$. 
 We also determine general formulas for the dimensions of the kernel and cokernel which could be used to derive index theorems in other configurations.

 In the following, we first observe that 
  \begin{equation} \label{eq:kernel_Xi_and_W}
   \mathrm{dim} \, \mathrm{Ker}(\Xi_1) = \mathrm{dim}\, W_2. 
  \end{equation} 
  This follows directly from the definitions together with the fact that $\mathbf{R}_1 \mathbf{S}_1$ is an isomorphism by Theorem \ref{th:S_kernel_range}.  
 The same claim holds with $1$ and $2$ interchanged, as does the complex conjugate. 

 \begin{theorem}  \label{th:X_k_analysis}
  Assume that $\riem_1$ and $\riem_2$ are connected. Let $g$ be the genus of $\mathscr{R}$ and $g_1$,$g_2$ be the genuses of $\riem_1$ and $\riem_2$ respectively. 
  \begin{equation}  \label{eq:dimX1_and_W_2}
   \mathrm{dim}\, X_1   = g - \mathrm{dim} W_2 
  \end{equation}
  and
  \begin{equation}  \label{eq:dimX1_and_X1intersectX1bar}
   \mathrm{dim}\, X_1  = g_1 + \frac{n-1}{2} + \frac{1}{2} \, \mathrm{dim}(X_1 \cap \overline{X}_1). 
  \end{equation}
  The same claims hold with $1$ and $2$ interchanged. 
 \end{theorem}
 \begin{proof}
   The first claim follow from the fact that 
   \[  X_1 = \mathrm{Im} (\Xi_1), \ \ \  \]
   equation \eqref{eq:kernel_Xi_and_W}, and the fact that $\mathcal{A}(\mathscr{R})$ has dimension $g$.   

   To prove the second claim, first observe that every homology class in $\riem_1$ is represented by a homology class in $\mathscr{R}$ (note that this depends on the assumptions on the configuration $\riem_1$, $\riem_2$, $\mathscr{R}$).  So 
   \[ \mathrm{dim} (X_1+ \overline{X}_1) = 2g_1 + n-1.  \] 
   Using this together with the fact that 
   \[  \mathrm{dim}\, (X_1+\overline{X}_1) = \mathrm{dim}\, X_1 + \mathrm{dim}\,\overline{X}_1 - \mathrm{dim}\, (X_1 \cap \overline{X}_1) = 2 \, \mathrm{dim}\, X_1 - \mathrm{dim}\, (X_1 \cap \overline{X}_1)  \]
   proves the claim.
 \end{proof}
 Combining these two claims, together with properties of the Schiffer operator, results in the following. 
 \begin{theorem}  \label{th:Schiffer_index_theorem}
  Assume that $\riem_1$ and $\riem_2$ are connected. Let $g$ be the genus of $\mathscr{R}$ and $g_1$,$g_2$ be the genuses of $\riem_1$ and $\riem_2$ respectively. Then 
  \[ \mathrm{Index} (\mathbf{T}_{1,2}) = g_1 - g_2.  \]
  The same claim holds with $1$ and $2$ switched.  
 \end{theorem}
 \begin{proof}
  Combining the two equations in Theorem \ref{th:X_k_analysis}, we obtain \begin{align}  \label{eq:index_temp_zero}
      g- \mathrm{dim}\, W_2 & = g_1 + \frac{n-1}{2} + \frac{1}{2} \mathrm{dim}\,(X_1 \cap \overline{X}_1 ) \nonumber \\ 
      g- \mathrm{dim}\, W_1 & = g_2 + \frac{n-1}{2} + \frac{1}{2} \mathrm{dim}\,(X_2 \cap \overline{X}_2 ) 
  \end{align}
  so since $g_1 + g_2 + n-1 = g$ we obtain 
  \begin{align} \label{eq:index_proof_temp} 
     \mathrm{dim}\, W_2 + \frac{1}{2} \mathrm{dim}\, (X_1\cap \overline{X}_1) & = g_2 + \frac{n-1}{2} \nonumber \\ 
      \mathrm{dim}\, W_1 + \frac{1}{2} \mathrm{dim}\, (X_2\cap \overline{X}_2) & = g_1 + \frac{n-1}{2}
  \end{align}

  Next we compute the dimension of the cokernel of $\mathbf{T}_{1,2}$. By Theorem \ref{th:Tonetwo_iso_improved}, we have that all harmonic forms with periods in $\overline{X}_2$ are in the image of $\mathbf{T}_{1,2}$, from which we conclude that
  \begin{align*}
   \mathrm{dim}\, \mathrm{Coker}( \mathbf{T}_{1,2}) & = 2g_2 + n-1 -
   \mathrm{dim}\, X_2  \\
   & = g_2 + \frac{n-1}{2} - \frac{1}{2} \mathrm{dim}\,(X_2 \cap \overline{X}_2)
  \end{align*}
  where we have used equation \eqref{eq:dimX1_and_X1intersectX1bar} with $1$ replaced by $2$.  However, since
  $\mathbf{T}_{1,2}^* = \overline{\mathbf{T}}_{2,1}$, by Theorem \ref{th:adjoint_identities} we have 
  \[  \mathrm{dim}\, \mathrm{Coker}( \mathbf{T}_{1,2}) = \mathrm{dim}\, \mathrm{Ker}\, \mathbf{T}_{2,1} = \mathrm{dim}\, W_2 \]
  where we have used Theorem \ref{th:Tonetwo_iso_improved}. Thus 
  \begin{equation*}
   \mathrm{dim}\, W_2 = g_2 + \frac{n-1}{2} - \frac{1}{2} \mathrm{dim}\,(X_2 \cap \overline{X}_2)
  \end{equation*} 
  which upon comparison with \eqref{eq:index_proof_temp} yields that
  \begin{equation} \label{eq:intersections_X12_equal}
     \frac{1}{2} \, \mathrm{dim}\,(X_1 \cap \overline{X}_1) =  
  \frac{1}{2} \, \mathrm{dim}\,(X_2 \cap \overline{X}_2).   
  \end{equation} 
  Now using this fact together with equation \eqref{eq:index_proof_temp} we obtain  
  \begin{align*}
     \mathrm{dim}\, \mathrm{Ker}( \mathbf{T}_{1,2}) - \mathrm{dim}\, \mathrm{Coker}( \mathbf{T}_{1,2}) & = \mathrm{dim}\, \mathrm{Ker}( \mathbf{T}_{1,2}) - \mathrm{dim}\, \mathrm{Ker}( \overline{\mathbf{T}}_{2,1}) \\
     & =\mathrm{dim}\, W_1 - \mathrm{dim}\, W_2 \\
     & = g_1 - g_2 
  \end{align*}
  as claimed. 

  To prove the final claim, just switch the roles of $1$ and $2$ in the proof, which can be done by the symmetry of the conditions.
 \end{proof}

 \begin{remark}  Under the same assumptions, the proof also shows the following interesting facts. 
  By equations \eqref{eq:index_temp_zero} and \eqref{eq:index_proof_temp}, together with the fact that
  $\mathrm{dim}\, (X_1 \cap \overline{X}_1) = \mathrm{dim}\, (X_2 \cap \overline{X}_2)$ by \eqref{eq:intersections_X12_equal}, we obtain  
  \[ g_1 -g_2 = \mathrm{dim}\, W_1 - \mathrm{dim}\,W_2 = \mathrm{dim}\, X_1 - \mathrm{dim}\, X_2.  \] 
  Furthermore, \eqref{eq:index_proof_temp} implies that 
  \[  \mathrm{dim}\, (X_k \cap X_k) = n - 1 \ \  \mathrm{mod}\, 2  \]
  for $k=1,2$.  
 \end{remark}

 We also have the following.
 \begin{theorem} \label{th:index_capped_surface}
  Let $\riem_2$ be a surface of genus $g$ capped by $\riem_1$, where $\riem_1$ has $n$ connected components.  Then 
  \[  \mathrm{Index} ( \mathbf{T}_{1,2}) = - \mathrm{Index} ( \mathbf{T}_{2,1}) = 1-n-g.  \]
 \end{theorem}
 \begin{proof}
  The fact that the index of $\mathbf{T}_{1,2}$ is $1-n-g$ follows directly from Corollary \ref{co:T_plus_extra_surjective_capped} together with the facts that the dimension of $\partial \mathcal{D}_{\mathrm{harm}}(\riem_2)$ is $n-1$ and the dimension of $\mathcal{A}(\mathscr{R})$ is $g$. Using \ref{th:adjoint_identities} we have 
  \[ \mathrm{Index} ( \mathbf{T}_{2,1}) = - \mathrm{Index} ( \mathbf{T}_{2,1}^* )=  - \mathrm{Index} ( \overline{\mathbf{T}}_{1,2}) = - \mathrm{Index} ( {\mathbf{T}}_{1,2})\]
  which completes the proof.
 \end{proof}

 {The index theorems above connect conformally invariant quantities (the index of $\mathbf{T}_{1,2}$) to topologically invariant quantities. 
 The Schiffer operators are conformally invariant, as we saw in \eqref{eq:Schiffer_operators_conformally_invariant}. Thus their spectra, kernels, images, and indices are all conformally invariant. 
 Because the spaces $W_k$ are conformally but not obviously topologically invariant, it is interesting that they cancel in the proof of Theorem \ref{th:Schiffer_index_theorem}, and only topological data remains. The question then arises: are the dimensions of the cokernel and kernel themselves topological invariants? In other words, is it possible to choose topologically equivalent configurations with distinct dimensions for the cokernel and kernel of $\mathbf{T}_{1,2}$?  Either answer would be of great interest. 

 In fact, the kernels and cokernels are related to the image of the period map of $\mathscr{R}$, restricted to homology curves in $\riem_1$ or $\riem_2$.  The following example, the case of a genus two torus sliced by one curve, illustrates this. We also explicitly compute $W_1$ (defined implicitly in Theorem \ref{th:Tonetwo_iso_improved}) for this example, which turns out to be trivial. Although it therefore does not provide a counterexample to the topological invariance of the cokernel and kernel, the approach might however be a promising way to seek one. We leave this as an open problem.
 }


{Returning to the problem of computation of $W_1$, following \cite{Roydenperiods}, we start by recalling some basic facts regarding periods and related matrices. Let the compact Riemann surface \(\mathscr{R}\) have a canonical homology basis \(\left\{A_{j}, B_{j}\right\},\) where the \(A_{j}\) and \(B_{j}\)
are smooth simple closed curves with intersection numbers given
by
$$
\begin{array}{l}{\left[A_{j} \times B_{k}\right]=\delta_{j k}} \\ {\left[A_{j} \times A_{k}\right]=0} \\ {\left[B_{j} \times B_{k}\right]=0}\end{array}.
$$
When we are not interested in the intersection properties, we set $C_{j+g}=B_{j},\, 1 \leq j \leq g.$



If $\alpha$ and $\alpha^{\prime}$ are two closed forms with periods $a_{j}, b_{j}$ and $a_{j}^{\prime}, b_{j}^{\prime},$ respectively, around $\left\{A_{j}, B_{j}\right\}$, then  \emph{Riemann's bilinear relations} (or Riemann's period relations) state that
\begin{equation}\label{Riemann relations}
    \int_{\mathscr{R}} \alpha \wedge \alpha^{\prime}=\sum_{j}\left(a_{j} b_{j}^{\prime}-a_{j}^{\prime} b_{j}\right).
\end{equation}


Now let \(\omega_{j}\) be the harmonic one-form on \(\mathscr{R}\) whose period
around \(C_{k}\) is \(\delta_{j k} \) and \(w_{j}\) be the holomorphic one-form on \(\mathscr{R}\)  whose periods around \(A_{k}\) are \(\delta_{j k} .\) Then the entries of the so-called \emph{Riemann matrix} \(\Pi=\left[\pi_{j k}\right]\)
are given by
$$
\pi_{j k}=\int_{B_{k}} w_{j}.
$$
Since \(w_{j} \wedge w_{k}=0,\) 
\eqref{Riemann relations} yields that
\begin{equation}\label{symmetry of Riemann}
    0=\int w_{j} \wedge w_{k}=\pi_{k j}-\pi_{j k}.
\end{equation}


Thus \(\Pi\) is a symmetric matrix. 



Note also that, since period of \(w_{j}\) is \(\delta_{j k}\) around \(A_{k}\) and is \(\pi_{j k}\) around \(B_{k},\)
one has
\begin{equation}\label{Roydens trick}
  w_{j}=\omega_{j}+\sum_{k} \pi_{j k} \omega_{k+g}.  
\end{equation}
\begin{figure}
     \includegraphics[width=9cm]{period_curves.pdf}
     \caption{Genus two Riemann surface and its homology basis}
     \label{fig:period_curves}
 \end{figure} 
Now let $\mathscr {R}$ be the Riemann surface depicted in Figure \ref{fig:period_curves} and let us apply the information above to the problem of characterization of the set 
\begin{equation}\label{charac Vj}
    V_2:=\{w\in{\mathcal{A}(\mathscr{R})};\, \mathbf{R}_{2}{w} \in {\mathcal{A}^{\mathrm{e}}(\Sigma_2)}\}.
\end{equation}

We note that in the computation of $W_1$ mentioned above, we can confine ourselves to the computation of $V_2$. Here we have that \(w_{1}=\omega_{1}+\sum_{k=1}^{2}\pi_{1 k} \omega_{k+2}\) and
\(w_{2}=\omega_{2}+\sum_{k=1}^{2} \pi_{2 k} \omega_{k+2}\) and we seek a holomorphic one-form given by \(N_{1} w_{1}+N_{2} w_{2},\) with $N_j \in \mathbb{C},$ which is in \(V_{2}\). Therefore
$$\int_{A_{2}} (N_{1} w_{1}+N_{2} w_{2})=0 .$$ However, \eqref{Roydens trick} yields that $$0=\int_{A_{2}} N_{1} w_{1}+N_{2} w_{2}=\int_{A_{2}} \Big(N_{1} \omega_{1}+N_{1} \sum_{k=1}^{2} \pi_{1 k} \omega_{k+2}+N_{2} \omega_{2}+N_{2} \sum_{k} \pi_{2 k} \omega_{k+2}\Big)
=N_{2}.$$
Furthermore
\(\int_{B_{2}} N_{1} w_{1}=\int_{B_{2}} (N_{1} \omega_{1}+N_{1} \sum_{k=1} ^{2}\pi_{1 k} \omega_{k+2})=N_{1} \pi_{12}\).
Hence \(V_{2}\) is non-empty if and only if \(\pi_{12}=0\). Therefore by \eqref{symmetry of Riemann}, for $\mathscr{R}$ as in Figure \ref{fig:period_curves}, $V_2$ is non-empty if and only if the Riemann matrix has the form
\begin{equation}
  \begin{pmatrix}
\pi_{11} & 0\\
0 & \pi_{22}
\end{pmatrix}
 \end{equation}
 However, as was shown by M. Gerstenhaber in \cite{Gerstenhaber}, no  surface of genus 2 has  a diagonal matrix for a Riemann matrix, and therefore $V_2$ is indeed empty.

} 
\end{subsection}
\end{section}



