\subsection{Quiver varieties vs Calogero--Moser varieties}\label{sub:quiver-cm}

Assume $\ell\in\ZM_{>0}$. Recall that we assumed $\Gamma=\ZM/\ell\ZM$. Let us review the isomorphism in Theorem~\ref{thm:CMquiveriso} in this case. We include the additional $\CM^\times$-action.


Assume that $n \ge 2$.
We set $\zeta=\exp(2\pi \sqrt{-1} /\ell)$. We denote by $s$ the permutation matrix corresponding to the 
transposition $(1,2)$ and we set
$$t=\diag(\zeta,1,\dots,1) \in \Gamma_n.$$
Then $s$, $t$, $t^2$,\dots, $t^{\ell-1}$ is a set of representatives of conjugacy 
classes of reflections in $\Gamma_n$. For simplicity, we set 
$$
a=c_s\qquad\text{and}\qquad k_j=\frac{1}{\ell} \sum_{i=1}^{\ell-1} \zeta^{-i(j-1)} c_{t^i}
$$
for $j \in \ZM/\ell\ZM$. Then
\equat\label{eq:k}
k_0+\cdots + k_{\ell-1} = 0\qquad \text{and}\qquad c_{t^i}=\sum_{j \in \ZM/\ell\ZM} \zeta^{i(j-1)} k_j
\endequat
for $1 \le i \le \ell-1$. Finally, if $i \in \ZM/\ell\ZM$, we set

\equat
\bc_i=
\begin{cases}
k_{-i}-k_{1-i} & \text{if $i \neq 0$,}\\
-a +k_0-k_1 & \text{if $i=0$.}\\
\end{cases}
\endequat\label{eq:theta-k}
and $\bc=(\bc_i)_{i \in \ZM/\ell\ZM}$. 




\bigskip

There is a $\CM^\times$-action on $\XC_\bc(n\delta)$ given by $\xi\cdot (X,Y,x,y)=(\xi^{-1}X,\xi Y,x,y)$. 
The following proposition is a $\CM^\times$-equivariant version of Theorem~\ref{thm:CMquiveriso} in this situation, see also Remark~\ref{rem:C*-on-CM}. However, the choice of the parameter $\bc$ in terms of $c$ here is different from the choice made in Theorem~\ref{thm:CMquiveriso} by multiplication by a constant. This choice is made to be compatible with \cite{BM}.

The following result is proved in~\cite[Theorem~3.10]{GordonQuiver}. (Note that our $k_i$ is related to Gordon's $H_i$ via $H_i=k_{-i}-k_{1-i}$.) 

\begin{prop}\label{prop:quiver-cm}
There is a $\CM^\times$-equivariant 
isomorphism of varieties
$$\ZCB_{\! c} \longiso \XC_\bc(n\delta).$$
\end{prop}

In the above isomorphism, the parameter $a$ of the variety $\ZCB_{\! c}$ corresponds to $~-(\sum_{i\in \ZM/\ell\ZM}\bc_i)=- \bc(\delta)$ for $\XC_\bc(n\delta)$. 
Note that $a=-\bc(\delta)$ is invariant under the transformation of the parameter $\bc\mapsto s_j^*(\bc)$. From now on, we assume $a\ne 0$. 

\begin{remark}
	All statements in Section~\ref{sub:quiver-cm} also make sense for $n=1$ with the following modifications. We have no transposition $s$, so we have no parameter $a$. On the other hand, for $n=1$, the variety $\XC_\bc(n\delta)$ does not depend on $\bc_0$. 

	We can also use the convention that for $n=0$ the Calogero--Moser variety is a point. Then Proposition~\ref{prop:quiver-cm} still holds.
\end{remark}

Recall also from~\cite[\S{11}]{EG} the following result, which follows from Proposition~\ref{prop:quiver-cm}.

\bigskip

\begin{lem}\label{lem:dim-CM}
	If $n \ge 0$, then $\XC_\bc(n\delta)$ is normal of dimension $2n$.
\end{lem}

\subsection{Semisimple representations in $\Rep_{\bc}(\Qov^\ell)$}

Denote by $\Rep_{\bc}(\Qov^\ell)$ the additive category of representations $(X,Y)$ of $\Qov^\ell$ satisfying the moment map relations $\widehat\mu_\alpha(X,Y)=\Irm_\bc(\alpha)$, where $\alpha$ is the dimension vector of the representation $(X,Y)$. 
Since we assume $a\ne 0$, we are in the setup of Section~\ref{sec:nonzero}. Then the set $\Sigma_\bc$ of dimension vectors of simple representations in $\Rep_{\bc}(\Qov^\ell)$ is the same as the set of simple roots $\Delta(\bc)$ in $R_\bc$. The set of dimension vectors of semisimple representations is the set $\SS{\bc}$ of (possibly zero) sums of the elements of $\Sigma_\bc$. Moreover, since each element of $\SS{\bc}$ has a unique decomposition as a sum of elements of $\Sigma_\bc=\Delta(\bc)$, for each $\alpha\in \SS{\bc}$ there exists a unique up to isomorphism semisimple representation in $\Rep_\bc(\Qov^\ell)$. Let us denote this representation by $L(\alpha)$. We see in particular that for each $\alpha\in \ZM_{\geqslant 0}^{\ZM/\ell\ZM}$, the variety $\mf{M}_\bc(\alpha)$ is either a singleton or empty. More precisely, we have 
$$
\mf{M}_\bc(\alpha)
=
\begin{cases}
\{L(\alpha)\}&\mbox{ if $\alpha\in \SS{\bc}$},\\
\emptyset &\mbox{ else}.
\end{cases}
$$




\subsection{Symplectic leaves}
\label{subs:symp-leaves}

Denote by $\Rep_{\bc}(\oQulinf)$ the category of representations $(X,Y,x,y)$ of $\oQulinf$ whose dimension vector is of the form $\widehat\alpha$ for some $\alpha\in \ZM^{\ZM/\ell\ZM}$ and satisfying the moment map relations $\widehat\mu_\alpha(X,Y)=\Irm_\bc(\alpha)$. This category is not additive because we have imposed that the representations have dimension $1$ at the vertex $\infty$. However, it does make sense to add an object of $\Rep_{\bc}(\Qov^\ell)$ and an object of $\Rep_{\bc}(\oQulinf)$, getting an object of $\Rep_{\bc}(\oQulinf)$.

An object $M$ of $\Rep_{\bc}(\oQulinf)$ is indecomposable as a representation of the quiver $\oQulinf$ if and only if the only possible decomposition $M=M_0\oplus M_1$ with $M_0\in \Rep_{\bc}(\oQulinf)$ and $M_1\in \Rep_{\bc}(\Qov^\ell)$ is $M=M\oplus 0$.


\begin{remark}
\label{rk:couple-equiv-nd}
Assume $\alpha\in E_\bc$. Then, by Proposition~\ref{prop:Cadmissiblemove}, the pair $(\alpha,\bc)$ is equivalent to a pair of the form $(n\delta,\bc')$ with $n\geqslant 0$. In particular, by Proposition~\ref{prop:quiver-cm}, the variety $\XC_\bc(\alpha)$ is isomorphic to the Calogero--Moser variety.
\end{remark}

Each object $M\in\Rep_{\bc}(\Qov^\ell)$ has a unique decomposition $M=M_0\oplus M_1$ such that $M_0\in \Rep_{\bc}(\oQulinf)$, $M_1\in \Rep_{\bc}(\Qov^\ell)$ and $M_0$ is indecomposable. Set $\dim^{\rm reg}M=\dim M_0\in \ZM^{\ZM/\ell\ZM}$.

Take a point $[M]\in\XC_\bc(\alpha)$ presented by a semisimple representation $M\in \Rep_{\bc}(\oQulinf)$.

\begin{lem}
\label{lem:symple-leaves-descr}
Two points of $[M], [M']\in \XC_\bc(\alpha)$ are in the same symplectic leaf if and only if we have $\rdim(M)=\rdim(M')$.
\end{lem}
\begin{proof}
Let us decompose $M$ in a direct sum of simple representations $M=\bigoplus_{r=0}^k M_r$, where $M_0\in \Rep_{\bc}(\oQulinf)$ and other summands are in $\Rep_{\bc}(\Qov^\ell)$.

Once we know the dimension vector $\alpha'$ of $M_0$, we know automatically $k$ and the dimension vectors of $M_1, M_2, \ldots,M_k$ (up to a permutation) because $L(\alpha-\alpha')$ is the unique semisimple representation in $\Rep_{\bc}(\Qov^\ell)$ of dimension vector $\alpha-\alpha'$. Then the statement follows from the description of symplectic leaves given in \cite[Theorem~1.9]{BellSchedQuiver}. 
\end{proof}

For two dimension vectors $\alpha$ and $\alpha'$ we set $\LG^\alpha_{\alpha'}=\{[M]\in \XC_\bc(\alpha);~\rdim(M)=\alpha'\}$. By Lemma~\ref{lem:symple-leaves-descr} $\LG^\alpha_{\alpha'}$ is either a symplectic leaf of $\XC_\bc(\alpha)$ or is empty. Note that the labeling used here is different from the labeling of symplectic leaves in Section~\ref{sec:nonzero}. The leaf $\LG^\alpha_{\alpha'}$ here corresponds to $\LG(\alpha-\alpha')$ in Section~\ref{sec:nonzero}.

\begin{lem}
\label{lem:order-sym-leaves}
The symplectic leaves $\LG^\alpha_{\alpha'}\subset \XC_\bc(\alpha)$ define a finite stratification of $\XC_\bc(\alpha)$ into locally closed subsets.
For two symplectic leaves $\LG^\alpha_{\alpha'}$ and $\LG^\alpha_{\alpha''}$ of $\XC_\bc(\alpha)$ we have $\LG^\alpha_{\alpha'}\subset \overline{\LG^\alpha_{\alpha''}}$ if and only if $\alpha''-\alpha'\in \SS{\bc}$.
\end{lem}
\begin{proof}
This statement is a special case of \cite[Proposition~3.6]{BellSchedQuiver}. See also the proof of Proposition~\ref{prop:leafclosure1} for more details.



\end{proof}

\begin{prop}
\label{prop:can-decomp-of-d}
 \mbox{ }
 $(i)$ For each dimension vector $\alpha$ such that $\XC_\bc(\alpha)\ne \emptyset$, there is a decomposition $\alpha=\alpha^0+\alpha^1$ such that $\alpha^0\in E_\bc$ and $\alpha^1\in\SS{\bc}$ such that for any other decomposition $\alpha=\alpha'^0+\alpha'^1$ with $\alpha'^0\in E_\bc$ and $\alpha'^1\in\SS{\bc}$ we have $\alpha^0-\alpha'^0\in \SS{\bc}$. 

$(ii)$ $\LG_{\alpha^0}$ is the unique open symplectic leaf in $\XC_\bc(\alpha)$.

$(iii)$ We have an isomorphism of varieties 
$$
\XC_\bc(\alpha^0)\cong \XC_\bc(\alpha),\qquad [M]\mapsto [M\oplus L(\alpha^1)].
$$
\end{prop}

\begin{proof}

By \cite[Corollary~1.45]{MartinoThesis}, the smooth locus of $\XC_\bc(\alpha)$ is a symplectic leaf. Then it should be of the form $\LG^\alpha_{\alpha^0}$ for some $\alpha^0$.

Since $\XC_\bc(\alpha)$ is irreducible by \cite[Corollary~1.4]{CBdecomp}, we have $\overline{\LG^\alpha_{\alpha^0}}=\XC_\bc(\alpha)$.
Then, by Lemma~\ref{lem:order-sym-leaves}  for any other symplectic leaf $\LG^\alpha_{\alpha'_0}$ we have $\alpha^0-\alpha'^0\in\SS{\bc}$. This proves $(i)$ and $(ii)$.

Part $(iii)$ follows from \cite[Theorem~1.1]{CBdecomp}.
\end{proof}

Now, we set $\XC_\bc(\alpha)^{\rm reg}=\LG^\alpha_{\alpha^0}$. 
Assume that $\alpha$ and $\alpha'$ are such that $\LG^\alpha_{\alpha'}$ is non-empty.

\begin{lem}
The closure of $\LG^\alpha_{\alpha'}$ is isomorphic to $\XC_{\bc}(\alpha')$. 
\end{lem}

\begin{proof}
Lemma~\ref{lem:normalization-leaf-cl} and Proposition~\ref{prop:leafclosurenormal} imply that the map
$$
\phi\colon\XC_{\bc}(\alpha')\to \overline{\LG^\alpha_{\alpha'}},\qquad [M]\mapsto [M\oplus L(\alpha-\alpha')]
$$
is an isomorphism.


\end{proof}

\begin{cor}
\label{coro:norm-cl-leaf}
The closure of each symplectic leaf $\LG^\alpha_{\alpha'}$ of the variety $\XC_{\bc}(\alpha)$ is isomorphic to a variety of the form $\XC_{\bc'}(r\delta)$ for some $r\geqslant 0$ and some $\bc'\in \CM^{\ZM/\ell\ZM}$. 
\end{cor}
\begin{proof}

First of all, note that $\alpha'\in E_\bc$. By Remark~\ref{rk:couple-equiv-nd}, the pair $(\alpha',\bc)$ is equivalent to some pair of the form $(r\delta,\bc')$ where $r\geqslant 0$ and $\bc'\in \CM^{\ZM/\ell\ZM}$. Then the isomorphism \eqref{eq:iso-lusztig} yields $\XC_{\bc}(\alpha')\cong \XC_{\bc'}(r\delta)$.
\end{proof}

Combining the corollary above with Proposition~\ref{prop:quiver-cm} yields the following theorem.

\begin{thm}\label{thm:GM1nclosure}
The closure of each symplectic leaf of the Calogero--Moser variety of type $G(\ell,1,n)$ with $a\ne 0$ is isomorphic to a Calogero--Moser variety of type $G(\ell,1,r)$ for some $r\in [0;n]$. In particular, all leaf closures are normal when $a \neq0$. 
\end{thm}

\begin{remark}
\label{rem:param-c'-cyclic}
We explain the relationship between the parameters of the two Calogero--Moser varieties in Theorem~\ref{thm:GM1nclosure}. The Calogero--Moser variety $\ZCB_{c}(G(\ell,1,n))$ is isomorphic to the quiver variety $\XC_\bc(n\delta)$.  The closure of the symplectic leaf $\LG^{n\delta}_{\alpha'}$ is isomorphic to  $\XC_\bc(\alpha')$. Just as in the proof of Proposition~\ref{prop:wbccomp}, we can find $w\in W^\aff$ that realizes the equivalence between $(\alpha',\bc)$ and $(w\star\alpha' = r \delta,w^*(\bc))$. Set $\bc'=w^*(\bc)$. We have an isomorphism $\XC_\bc(\alpha')\cong \XC_{\bc'}(r\delta)$. Since $w\star\alpha'=r\delta$, Lemma~\ref{lem:affWeyl_translation-roots} implies that $w=x t_{\alpha'}$, where $x\in W$. Then, by Lemma~\ref{lem:affWeyl_translation-theta}, $\bc'=(xt_{\alpha'})^*(\bc)=x^*(\bc-a\overline{\alpha'})$. Moreover, the action the element $x\in W$ on $\CM^{\ZM/\ell\ZM}$ corresponds to some permutation of the parameters $k_0,k_1,\ldots,k_{\ell-1}$ (see \cite[Remark~3.5]{BM}) and a permutation of the parameters does not change the Calogero--Moser variety up to isomorphism, see Remark~\ref{rem:finiteWisoparameters}.

Therefore, the parameters $a, k_0,k_1,\ldots,k_{\ell-1}$ (corresponding to $\bc$) of the original the Calogero--Moser variety $\ZCB_{c}(G(\ell,1,n))$ are related to the parameters $a', k'_0,k'_1,\ldots,k'_{\ell-1}$ (corresponding to $\bc'$) of the new Calogero--Moser variety $\overline{\LG^{n\delta}_{\alpha'}} \cong \ZCB_{c'}(G(\ell,1,r))$ as follows:
$$
a'=a,\qquad k'_i=k_i+(\alpha'_{1-i}-\alpha'_{-i}).
$$
In the case where $n$, resp $r$, is equal to $1$, we can forget the parameter $a$, resp. $a'$. In the case $r=0$, the variety $\XC_{\bc'}(r\delta)$ is just a point.
\end{remark}





\subsection{$\CM^\times$-fixed points}
\label{subs:C-fixed-points}



For each $J\subset \ZM/\ell\ZM$ we denote by $W_J$ the parabolic subgroup of $W^\aff$ generated by $s_i$ for $i\in J$. Let us say that $\bc$ is \emph{$J$-standard} if the stabilizer $W^\aff_\bc$ of $\bc$ in $W^\aff$ is equal to $W_J$. We say that $\bc\in\CM^{\ZM/\ell\ZM}$ is \emph{standard} it is $J$-standard for some $J\subset \ZM/\ell\ZM$. For a standard $\bc$, the set $J$ is the set of indices $i\in \ZM/\ell\ZM$ such that $\bc_i=0$.

Now, let us describe the $\CM^\times$-fixed points of $\XC_\bc(\alpha)$. First of all, each pair $(\alpha,\bc)$ is equivalent to a pair whose $\bc$ is standard by Lemma~\ref{lem:wparabolicrootsystem}.

The following lemma is obvious.
	\begin{lem}
			\label{lem:Sigma-th-simple}
		Assume that $\bc$ is $J$-standard. Then we have $\Sigma_\bc=\{e_i;~i\in J\}$.
	\end{lem}
	Let us now assume that $\bc$ is $J$-standard. 
For each partition $\mu$, we construct a $\CM^\times$-fixed point in $\XC_{\bc}(\Res_\ell(\mu))$. This construction is essentially the same as \cite[Section~5]{Przez}. However \cite{Przez} assumes that the variety $\XC_{\bc}(\Res_\ell(\mu))$ is smooth and we don't need this assumption. 

We are going to use the Frobenius forms of partitions: each partition $\mu$ can be described by some $k\in\ZM_{\geqslant 0}$ and $a_1,\ldots, a_k, b_1,\ldots,b_k\in \ZM_{\geqslant 0}$, where $k$ is maximal such that the Young diagram of $\mu$ contains a box in position $(k,k)$ and for each $r\in [1;k]$ there are $a_r$ boxes on the right of $(r,r)$ and $b_r$ boxes below $(r,r)$.
In other words, we see the Young diagram of the partition $\mu$ as a union of $k$ hooks. The box at position $(i,j)$ is in the $r$th hook if $\min(i,j)=r$. The numbers $a_r$ and $b_r$ are the lengths of the arm and of the leg of $r$th hook respectively. 

For $i\in \ZM$, we use the convention that $\bc_i$ means $\bc_{(i\smod l)}$. Set $\beta_r=\sum_{i=-b_r}^{a_r}\bc_i$. 

Let $V$ be a complex vector space with basis $\{v_{r,j};~r\in[1;k];~j\in[-b_r,a_r]\}$. It has a $\ZM$-grading $V=\bigoplus_{j\in \ZM} V_j$ such that $v_{r,j}\in V_j$. Consider two endomorphisms $X$ and $Y$ of this vector space given by
$$
X(v_{r,j})=
\begin{cases}
v_{r,j-1} &\mbox{ if } j>-b_r,\\
0 &\mbox{ if } j=-b_r,
\end{cases}
$$
and
$$
Y(v_{r,j})=
\begin{cases}
(\sum_{i=-b_r}^j \bc_{i})v_{r,j+1}+\sum_{t>r} \beta_tv_{t,j+1} &\mbox{ if } j\in[-b_r,-1]\\
-(\sum_{i=j+1}^{a_r}\bc_{i})v_{r,j+1}-\sum_{t<r}\beta_tv_{t,j-1} &\mbox{ if } j\in [0;a_r-1],\\
-\sum_{t<r}\beta_tv_{t,j-1} &\mbox{ if } j=a_r,\\
\end{cases}
$$

Consider also the linear maps $x\colon \CM\to V_0$ and $y\colon V_0\to \CM$ given by 
$$
x(1)=-\sum_{r=1}^k \beta_r v_{r,0}\qquad  \mbox{ and } \qquad y(v_{r,0})=1.
$$

Then $(X,Y,x,y)$ yields a representation $A^\infty_\mu$ of the quiver $\oQuii$. Applying the map $\iota$ as in Definition~\ref{def:map-i-inf}, we get a representation $A_\mu$ of the quiver $\oQulinf$. It satisfies the moment map relation $\widehat\mu_\alpha(A_\mu)=I_\bc(\alpha)$. 


\begin{lem}
\label{lem:structure-Amu}

Assume that $\bc$ is $J$-standard.

\begin{enumerate}
\item[(i)] If $\mu$ is a $J$-core, then $A_\mu$ is simple. 


\item[(ii)] Assume that  $b$ is a removable box of $\mu$ with $\ell$-residue $i\in J$. Then we have either a short exact sequence
$$
0\to  L(e_i)\to A_{\mu}\to A_{\mu\backslash b}\to 0
$$
or a short exact sequence
$$
0\to A_{\mu\backslash b}\to A_{\mu}\to  L(e_i)\to 0.
$$
\end{enumerate}

\end{lem}
\begin{proof}
First, we prove (ii). Assume that $b$ is the box as in the statement.  Assume that it is in the $r$th hook. Let $j$ be the $\infty$-residue of $b$.

Assume first $j<0$. We have $X(v_{r,j})=Y(v_{r,j})=0$.  Then the vector $v_{r,j}$ spans a subrepresentation isomorphic to $L(e_i)$. We get a short exact sequence
$$
0\to  L(e_j)\to A_{\mu}\to A_{\mu\backslash b}\to 0.
$$

Now, assume $j\geqslant 0$. Then we see that $A_{\mu\backslash b}$ is a subrepresentation of $A_{\mu}$. It is spanned by all basis vectors except $v_{r,j}$.
Then we have a short exact sequence
$$
0\to A_{\mu\backslash b}\to A_{\mu}\to  L(e_j)\to 0.
$$

\medskip
Now, let us prove (i). First of all, we note that the assumption that $\bc$ is $J$-standard implies that if for some $a,b\in \ZM$, $a\leqslant b$ we have $\bc_a+\bc_{a+1}+\ldots+\bc_{b-1}+\bc_b=0$, then we have $\bc_a=\bc_{a+1}=\ldots=\bc_{b-1}=\bc_b=0$. 
If $\mu$ is a $J$-core, then the numbers $\beta_1, \beta_2,\ldots,\beta_k$ are non-zero. Indeed, if some $\beta_r$ is zero, then $\beta_k$ is also zero. Then the $\ell$-residues of all boxes of the $k$th hook are in $J$. In particular, the $k$th hook contains a removable box whose residue is in $J$. This contradicts the fact that $\mu$ is a $J$-core.

In view of Lemma~\ref{lem:Sigma-th-simple}, if the representation $A_\mu$ is not simple, then it must either contain a subrepresentation of the form $L(e_i)$, or it must have a quotient of the form $L(e_i)$. Let us show that both situations are impossible when $\mu$ is a $J$-core.

Assume that $A_\mu$ has a subrepresentation isomorphic to $L(e_i)$. Let $v$ be a vector that spans this subrepresentation. We can write $v=\sum\limits_{j\in \ZM, j\equiv i \smod l}v_j$, where $v_j\in V_j$. Take $j$ in this decomposition such that $v_j\ne 0$. Then the vector $v_j$ also spans a subrepresentation of $A_\mu$ isomorphic to $L(e_i)$.


Let $t$ be the number of boxes of $\mu$ with the $\infty$-residue $j$. Write $v_j=\sum_{r=1}^t\lambda_r v_{r,j}$. Then $X(v)=0$ is only possible when $\lambda_1=\ldots=\lambda_{t-1}=0$, so the vector $v_{t,j}$ spans $L(e_i)$.

Assume $j<0$.  Since the box $b$ corresponding to the vector $v_{t,j}$ cannot be removable, the diagram of $\mu$ either contains the box below $b$ or the box on the right of $b$. In the first case we must have $X(v_{t,j})\ne 0$ and in the second case we must have $Y(v_{t,j})\ne 0$. This is a contradiction.

Assume $j>0$. Then $X(v_{t,j})\ne 0$. This is a contradiction.

Assume $j=0$. Then, since $\beta_1\ne 0$, $Y(v_{t,0})\ne 0$ is only possible for $t=1$. However, this implies that $\mu$ contains only one hook (i.e., we have $k=1$). Since the box $b$ corresponding to the vector $v_{1,0}$ cannot be removable, the diagram of $\mu$ either contains the box below $b$ or the box on the right of $b$. The first case is not possible because it implies $X(v_{1,0})\ne 0$. In the second case we must have $\bc_1+\bc_2+\ldots+\bc_{a_1}=0$. However, this implies ${a_1}=0$ and then the unique box with $\infty$-residue $a_1$ is removable. This is a contradiction.

Now, assume that $A_\mu$ has a quotient isomorphic to $L(e_i)$. Then the dual representation $A_\mu^*$ contains a submodule isomorphic to $L(e_i)$. An argument as above show that this is impossible if $A_\mu$ is a $J$-core.


\end{proof}

Denote by $A'_\mu$ the semisimplification of $A_\mu$, i.e., $A'_\mu$ is the direct sum of the Jordan-H\"older subquotients of $A_\mu$.

\begin{cor} 
\label{coro:structure-Amu}
	Assume $\mu\in \PC$ and set $\lambda=\Core_J(\mu)$. Then the representation $A'_\mu$ has the following decomposition in a direct sum of simple representations
	$$
	A'_\mu=A_\lambda\oplus \bigoplus_j L(e_j),
	$$
where the sum is taken by the multiset of $\ell$-residues of $\mu\smallsetminus\lambda$.
\end{cor}

\begin{defn}
	We say that the representation $(X,Y,x,y)$ of $\oQulinf$ is $\ZM$-\emph{gradable} if it is isomorphic to the image by $\iota$ (see Definition~\ref{def:map-i-inf}) of some representation $L$ of $\oQuii$. In this case we say that $L$ is a \emph{graded lift} of $(X,Y,x,y)$.
\end{defn}

A  $\ZM$-gradable representation yields a $\CM^\times$-fixed point in $\XC_\bc(\alpha)$.

\begin{lem}
Assume that $(X,Y,x,y)$ is simple and $\ZM$-gradable. Then its $\ZM$-grading is unique. 
\end{lem} 
\begin{proof}
Since we assume $a\ne 0$, the vector $v=x(1)$ must be non-zero (here $1$ is a vector spanning the $\infty$-component of the representation, which is isomorphic to $\CM$). Then $v$ should be in $\ZM$-degree $0$. Since the representation is simple, the vectors of the form $X^{a_1}Y^{b_1}\ldots X^{a_k}Y^{b_k}(v)$ and the vector $1$ span the representation. But then vector $X^{a_1}Y^{b_1}\ldots X^{a_k}Y^{b_k}(v)$ must be in $\ZM$-degree $b_1-a_1+\ldots+b_k-a_k$. This shows that the $\ZM$-grading is unique. 
\end{proof}

\begin{example}
\label{ex:Res-Amu}
If $\mu$ is a $J$-core, then the representation $A_\mu$ is simple. It is $\ZM$-gradable by construction. Its graded lift $A^\infty_\mu$ is unique. The $\ZM$-graded dimension of the graded lift $A^\infty_\mu$ is $\Res_\infty(\mu)$.
\end{example}

\begin{cor} 
\label{coro:isom-if-same-Jcore}
For $\mu,\eta \in \PC_\nu(n\ell+|\nu|)$, the representations $A'_{\mu}$ and $A'_{\eta}$ are isomorphic if and only if $\mu$ and $\eta$ have the same $J$-cores.
\end{cor}

\begin{proof}
Let $\lambda$ and $\rho$ be the $J$-cores of $\mu$ and $\eta$ respectively.

Assume that $A'_{\mu}$ and $A'_{\eta}$ are isomorphic. We see from Corollary~\ref{coro:structure-Amu} that the representations $A_{\lambda}$ and $A_{\rho}$ are also isomorphic. Now, Example~\ref{ex:Res-Amu} implies $\Res_\infty(\lambda)=\Res_\infty(\rho)$, this yields $\lambda=\rho$. 

Now, assume that we have $\lambda=\rho$. Since we have $\mu,\eta\in \PC_\nu(n\ell+|\nu|)$, the partitions $\mu$ and $\eta$ have the same residues equal to $\Res_\ell(\nu)+n\delta$. Then $\mu\smallsetminus\lambda$ and $\eta \smallsetminus\rho$ have the same residues. Then Corollary~\ref{coro:structure-Amu} implies that $A'_{\mu}$ and $A'_{\eta}$ are isomorphic.
\end{proof}


\begin{remark}
For each partition $\mu$, we have a $\CM^\times$-fixed point $[A'_\mu]\in \XC_\bc(\Res_\ell(\mu))$ presented by the representation $A'_\mu$. 
 Assume $\alpha\in E_\bc$, see Remark~\ref{rk:couple-equiv-nd}. Write $\alpha=\Res_\ell(\nu)+n\delta$, where $\nu\in\CC_\ell$. By \cite[Proposition~8.3~(i)]{GordonQuiver}, the $\CM^\times$-fixed points in $\XC_\bc(\alpha)$ are parameterized by $J$-cores of elements of $\PC_\nu(n\ell+|\nu|)$. On the other hand, we have already constructed the same number of $\CM^\times$-fixed points $[A'_\mu]$ for $\mu\in\PC_\nu(n\ell+|\nu|)$, see Corollary~\ref{coro:isom-if-same-Jcore}.
This implies that each $\CM^\times$-fixed point in $\XC_\bc(\alpha)$ is of the form $[A'_\mu]$.
\end{remark}



\subsection{Combinatorial parameterization of symplectic leaves}

\begin{lem}
\label{lem:equiv-simple-nd}
The following conditions are equivalent.
\begin{enumerate}
    \item[(i)]  The pair $(\alpha,\bc)$ is equivalent to a pair of the form $(n\delta,\bc')$ with $n\geqslant 0$.
    \item[(ii)] We have $\alpha\in E_\bc$.
\end{enumerate}
\end{lem}
\begin{proof}
$(ii)$ implies $(i)$ by Remark~\ref{rk:couple-equiv-nd}.

Now, let us prove that $(i)$ implies $(ii)$. Assume that $(\alpha,\bc)$ satisfies $(i)$. Since the isomorphism \eqref{eq:iso-lusztig} sends simple representations to simple representations by construction, it is enough to assume $\alpha=n\delta$. Let $\alpha^0$ be associated to $\alpha=n\delta$ and $\bc$ as in Proposition~\ref{prop:can-decomp-of-d}. Then $(ii)$ is equivalent to $\alpha^0=\alpha$. 

Assume that $\alpha^0\ne \alpha$. Since the pair $(\alpha^0,\bc)$ satisfies $(ii)$, it also satisfies $(i)$. So, it must be equivalent to a pair of the form $(n'\delta,\bc')$. Since we have $\alpha^0-n'\delta\in \ZM_{\geqslant 0}^{\ZM/\ell\ZM}$ and $0\ne n\delta-\alpha^0\in \ZM_{\geqslant 0}^{\ZM/\ell\ZM}$,  we get $n>n'$.

Now, we get $\XC_{\bc}(n\delta)\cong \XC_{\bc}(\alpha^0)$ by Proposition~\ref{prop:can-decomp-of-d} $(iii)$ and we have $\XC_{\bc}(\alpha^0)\cong \XC_{\bc'}(n'\delta)$ by \eqref{eq:iso-lusztig}. This is impossible because by Lemma~\ref{lem:dim-CM} we have $\dim \XC_{\bc}(n\delta)=2n$, $\dim \XC_{\bc'}(n'\delta)=2n'$ and $n'<n$.
\end{proof}

The following lemma is a combinatorial version of Proposition~\ref{prop:Cadmissiblemove}. 

\begin{lem}\label{lem:descr-Eth}
Assume that $\bc$ is $J$-standard. Then $\alpha\in E_\bc$ if and only if we have 
$$
\alpha=\Res_\ell(\nu)+r\delta
$$
with $r\geqslant 0$ and $\nu\in \CC_\ell\cap\CC_J$.
\end{lem}
\begin{proof}
The parabolic subgroup $W_J$ of $W^{\rm aff}$ is the stabilizer of $\bc$ in $W^{\rm aff}$.
Writing $\alpha=\Res_\ell(\nu)+r\delta$ as in \eqref{eq:d-via-core-n}, we have $r\in\ZM$ and $\nu\in\CC_\ell$.

\medskip
Assume $\alpha\in E_\bc$. Then Lemma~\ref{lem:equiv-simple-nd} implies that $r\geqslant 0$ and we can find $x\in W^\aff$ (see  Remark~\ref{rem:equiv=shortest}) such that $x(\alpha)=r\delta$ and $x$ is the shortest element in the coset $xW_J\in W^\aff/W_J$.  

Let $w$ be the shortest element in $x^{-1}W$. We have $\nu=x^{-1}(\emptyset)=w(\emptyset)$. Assume that $\nu$ is not a $J$-core. Then we have $|s_i(\nu)|<|\nu|$ for some $i\in J$; this corresponds to the case $(3)$ in  Remark~\ref{rem:W-act-lcores}. Then Lemma~\ref{lem:nu-w-i} implies $\ell(s_iw)<\ell(w)$. Then we also have $\ell(s_ix^{-1})<\ell(x^{-1})$ or equivalently $\ell(xs_i)<\ell(x)$. This contradicts the fact that $x$ is the shortest element in $xW_J$. Thus, $\nu$ must be a $J$-core.

\medskip
Now, assume that we have $\alpha=\Res_\ell(\nu)+r\delta$ for $r\geqslant 0$ and $\nu\in\CC_\ell\cap\CC_J$. Let $w$ be the element of $W^\aff$ such that $w(\emptyset)=\nu$ and such that $w$ is the shortest element in $wW$. It is enough to prove that $w$ in the shortest element in $W_Jw$. Indeed, if we prove this, then by Remark~\ref{rem:equiv=shortest} we have $(\alpha,\bc)\sim (w^{-1}\star\alpha,{(w^{-1}})^*(\bc))=(r\delta,(w^{-1})^*(\bc))$ and then by Lemma~\ref{lem:equiv-simple-nd} we have $\alpha\in E_\bc$.


 Since $\nu$ is a $J$-core, for each $i\in J$ we have $|s_i(\nu)|\geqslant |\nu|$. This means that for each $i\in J$, we are either in situation $(1)$ or in situation $(2)$ of Remark~\ref{rem:W-act-lcores}. In both cases Lemma~\ref{lem:nu-w-i} yields $\ell(s_iw)>\ell(w)$. 
\end{proof}


\begin{remark}
\label{rem:dim-nd+nu}
Assume that $\bc$ is $J$-standard and fix $\alpha\in E_\bc$. By Lemma~\ref{lem:descr-Eth} above, we can write $\alpha$ in the form $\alpha=\Res_\ell(\nu)+n\delta$ with $n\geqslant 0$ and $\nu\in \CC_\ell\cap\CC_J$. Then by Lemma~\ref{lem:equiv-simple-nd}, the pair $(\alpha,\bc)$ is equivalent to $(n\delta,\bc')$ for some $\bc'\in \CM^{\ZM/\ell\ZM}$. 
Then Lemma~\ref{lem:dim-CM} implies that the variety $\XC_\bc(\Res_\ell(\nu)+n\delta)$ is normal of dimension $2n$.
\end{remark}


We see that the elements of $E_\bc$ are in bijection with the pairs $(\nu,r)$ where $\nu$ is an $\ell$-core that is a $J$-core and $r\in \ZM_{\geqslant 0}$.

Assume that $\bc$ is $J$-standard. Then we have a partial order $\succcurlyeq$ on $E_\bc$ given by $\alpha\succcurlyeq\alpha'$ if $\alpha-\alpha'\in \sum_{j\in J} \ZM_{\geqslant 0} e_j$. In other words, we have $\alpha\succcurlyeq\alpha'$ if and only if $\LG^\alpha_{\alpha'}\ne \emptyset$. Using the bijection above, we may consider the order $\succcurlyeq$ as an order on the set $(\CC_\ell\cap\CC_J)\times \ZM_{\geqslant 0}$. 

\begin{lem}
We have $(\nu_1,r_1)\succcurlyeq (\nu_2,r_2)$ if and only if $r_1\geqslant r_2$ and there exists a partition $\lambda\in \PC_{\nu_1}(|\nu_1|+\ell(r_1-r_2))$ such that $\Core_J(\lambda)=\nu_2$.
\end{lem}
\begin{proof}
Assume $(\nu_1,r_1)\succcurlyeq (\nu_2,r_2)$. Then $\dim \XC_\bc(\Res_\ell(\nu_1)+r_1\delta)=2r_1$ and  $\dim \XC_\bc(\Res_\ell(\nu_2)+r_2\delta)=2r_2$ by Remark~\ref{rem:dim-nd+nu}. By Corollary~\ref{coro:norm-cl-leaf} and its proof, the normalization of the closure of the symplectic leaf $\LG^{\Res_\ell(\nu_1)+r_1\delta}_{\Res_\ell(\nu_2)+r_2\delta}$ is isomorphic to $\XC_\bc(\Res_\ell(\nu_2)+r_2\delta)$. In particular, 
$$
\dim\XC_\bc(\Res_\ell(\nu_1)+r_1\delta)\geqslant\dim\LG^{\Res_\ell(\nu_1)+r_1\delta}_{\Res_\ell(\nu_2)+r_2\delta}
$$ 
implies $r_1\geqslant r_2$.

Now, $(\nu_1,r_1)\succcurlyeq (\nu_2,r_2)$ implies $\Res_\ell(\nu_1)+r_1\delta \succcurlyeq \Res_\ell(\nu_2)+r_2\delta$ and then $(\nu_1,r_1-r_2)\succcurlyeq (\nu_2,0)$. This means that the variety $\XC_\bc(\Res_\ell(\nu_1)+(r_1-r_2)\delta)$ contains the symplectic leaf $\LG^{\Res_\ell(\nu_1)+(r_1-r_2)\delta}_{\Res_\ell(\nu_2)}$. This symplectic leaf is $0$-dimensional, so it is a $\CM^\times$-fixed point. Then by Section~\ref{subs:C-fixed-points}, this should be a point of the form $[A'_\lambda]$ for some $\lambda\in \PC_{\nu_1}(|\nu_1|+l(r_1-r_2))$. By Corollary~\ref{coro:structure-Amu}, we have $\dim^\reg(A'_\lambda)=\Res_\ell(\Core_J(\lambda))$. Then $[A'_\lambda]\in \LG^{\Res_\ell(\nu_1)+(r_1-r_2)\delta}_{\Res_\ell(\nu_2)}$ implies $\Core_J(\lambda)=\nu_2$.

\medskip
Conversely, if $r_1\geqslant r_2$ and there exists such a partition $\lambda$, then the $\CM^\times$-fixed point $[A'_\lambda]$ of $\XC_\bc(\Res_\ell(\nu_1)+(r_1-r_2)\delta)$ is a symplectic leaf. Since $\dim^\reg(A'_\lambda)=\Res_\ell(\Core_J(\lambda))=\Res_\ell(\nu_2)$, this is the symplectic leaf $\LG^{\Res_\ell(\nu_1)+(r_1-r_2)\delta}_{\Res_\ell(\nu_2)}$. Then we have $(\nu_1,r_1-r_2)\succcurlyeq (\nu_2,0)$. This implies $\Res_\ell(\nu_1)+(r_1-r_2)\delta \succcurlyeq \Res_\ell(\nu_2)$ and hence $(\nu_1,r_1)\succcurlyeq (\nu_2,r_2)$.
\end{proof}


Assume that $\bc$ is $J$-standard and $\alpha\in E_\bc$. Write $\alpha=\Res_\ell(\nu)+n\delta$, $\nu\in\CC_\ell\cap\CC_J,n\geqslant 0$.
\begin{cor}
For $\alpha'\in \ZM/\ell\ZM$, the following conditions are equivalent.
\begin{enumerate}
    \item[(i)] We have $\LG^\alpha_{\alpha'}\ne \emptyset$.
    \item[(ii)] There exists a partition $\lambda\in\PC_\nu(n'\ell+|\nu|)$ for some $n'\in[0;n]$ such that 
    \[
    \alpha'=\Res_\ell(\Core_J(\lambda))+(n-n')\delta.
    \]
\end{enumerate}
\end{cor}

\begin{proof}
Write $\alpha'=\Res_\ell(\nu')+r'\delta$. Then $\LG^\alpha_{\alpha'}\ne \emptyset$ is equivalent to $(\nu,n)\succcurlyeq (\nu',r')$. By the lemma above, this is equivalent to $n\geqslant r'$ and the existence of a partition $\lambda\in \PC_{\nu}(\ell(n-r')+|\nu|)$ such that $\Core_J(\lambda)=\nu'$. Moreover, the condition $\Core_J(\lambda)=\nu'$ is equivalent to $\Res_\ell(\Core_J(\lambda))=\Res_\ell(\nu')=\alpha'-r'\delta$. Now we see that $(i)$ is equivalent to $(ii)$ with $n'=n-r'$.
\end{proof}

In particular, we see that the symplectic leaves of $\XC_\bc(\alpha)$ are parameterized by $\ell$-cores of $J$-cores of elements of $\PC_\nu(n'\ell+|\nu|)$ for $n'\in [0;n]$. Note that by Lemma~\ref{lem:lcore-of-Jcore}, the $\ell$-cores of $J$-cores are also $J$-cores. We sum up this in the following proposition.

\begin{prop}
\label{prop:comb-param-leaves}
The symplectic leaves of $\XC_\bc(\alpha)$ are paremeterized by a subset of the set $\CC_\ell\cap\CC_J$. This subset is the image of the set $\coprod_{n'=0}^n \PC_\nu(n'\ell+|\nu|)$ by the map $\Core_\ell\circ \Core_J$.    
\end{prop}


Since each pair $(n\delta,\bc)$ is equivalent to a pair of the form $(\alpha,\bc')$ such that $\bc'$ is $J$-standard for some $J$ and $\alpha\in E_{\bc'}$ (see Lemma~\ref{lem:equiv-simple-nd}), the description above gives a parameterization of the symplectic leaves of an arbitrary Calogero--Moser variety of type $G(\ell,1,n)$ with $a\ne 0$.

\begin{example}
\label{ex:comb-l=2}

Assume $\ell=2$. In this case the set $\CC_2$ of $2$-cores is labeled by nonnegative integers. We have $\CC_2=\{\nu_t,t\in \ZM_{\geqslant 0}\}$ where $\nu_t$ is the partition staircase $\nu_t=(t,t-1,t-2,\ldots,2,1)$ of $t(t+1)/2$ ($\nu_0$ is the empty partition). The two possible non-trivial examples of $J$ are $J_0=\{0\}$ and $J_1=\{1\}$. Then the $2$-cores $\nu_2, \nu_4, \nu_6,\ldots$ are $J_0$-cores and not $J_1$-cores, the $2$-cores $\nu_1, \nu_3, \nu_5,\ldots$ are $J_1$-cores and not $J_0$-cores, the $2$-core $\nu_0=\emptyset$ is a $J_0$-core and a $J_1$-core.  
Let us write $c=(c_1,c_\gamma)$ for the parameters of the Calogero--Moser variety to make this example easily comparable to Section~\ref{sec:hyperoctahedral}. We always assume $c_1\ne 0$ here.
Let us understand how the combinatorial parametrization of symplectic leaves of the Calogero--Moser variety looks from the point of view of Proposition \ref{prop:comb-param-leaves}.
Assume that we have $c_\gamma=\pm mc_1$ with integer $m> 0$. Then the Calogero--Moser variety is isomorphic to the quiver variety $\XC_{\bc'}(n\delta)$ with $\bc'=(\pm m-1,\mp m)$. Then there is a $\bc'$-admissible $w$ such that 
$$
w(\bc')=
\begin{cases}
(-1,0) & \mbox{ if $m$ is even},\\
(0,-1) & \mbox{ if $m$ is odd}.
\end{cases}
$$
Set $\bc=w(\bc')$. Set $J=J_1$ if $m$ is even and $J=J_0$ if $m$ is odd.  The parameter $\bc$ is $J$-standand. Note that we have $w(\nu_0)=\nu_{m-1}$, in particular the Calogero--Moser variety is isomorphic to $\XC_{\bc'}(n\delta)\cong \XC_\bc(n\delta+\Res_\ell(\nu_{m-1}))$. 

Now, we would like to find all possible $\nu'\in (\Core_\ell\circ \Core_J)(\coprod_{n'=0}^n \PC_{\nu_{m-1}}(n'\ell+|\nu_{m-1}|))$. 
If $n\leqslant m$, then each $\lambda\in \coprod_{n'=0}^n \PC_{\nu_{m-1}}(n'\ell+|\nu_{m-1}|))$ is a $J$-core. (To see this, we need to use the presentation of cores by abaci, see \cite[Section 2]{BJV}.) In this case, we get $(\Core_\ell\circ \Core_J)(\lambda)=\Core_\ell(\lambda)=\nu_{m-1}$. So, the only possible $\nu'$ that we may get is $\nu'=\nu_{m-1}$. In this case the Calogero--Moser variety is smooth. Now, if $n\geqslant m+1$ then it is also possible to get $\nu'=\nu_{m+1}$. If $n\geqslant 2(m+2)$ then it is also possible to get $\nu'=\nu_{m+3}$, etc. If $n\geqslant k(m+k)$ then it is also possible to get $\nu'=\nu_{m-1+2k}$. Finally, we see that the symplectic leaves are labeled by the following subset of $\CC_2\cap\CC_J$: $\{\nu_{m-1},\nu_{m+1},\nu_{m+3},\ldots,\nu_{m-1+2k}\}$ where $k$ is the maximal non-negative integer such that $n\geqslant k(m+k)$.


The case $m=0$ is a bit special; $\nu_{m-1}$ does not make sense here. Assume $c_\gamma=0$. Then the Calogero--Moser variety is isomorphic to $\XC_\bc(n\delta)$ with $\bc=(-1,0)$. Set $J=J_1$. In this case, the Calogero--Moser variety is never smooth for $n>0$, the symplectic leaves are labeled by $\{\nu_{0},\nu_{1},\nu_{3},\ldots,\nu_{2k-1}\}$ where $k$ is the maximal positive integer such that $n\geqslant k^2$.
\end{example}


\section{Slices to symplectic leaves.}\label{sec:slices}

In this section we describe the transverse slices to the symplectic leaves in the Calogero--Moser variety. 


\subsection{Transverse Singularities}

In this section, we explain how Crawley-Boevey's \'etale local normal form \cite{CBnormal} can be used to explicitly compute a transverse slice to each symplectic leaf $\LG$ in a quiver variety. A transverse slice $(S,o)$ to a $2k$-dimensional leaf $\LG$ is a pointed Poisson variety together with a local isomorphism $(\mf{M}_{\bc}(\alpha),p) \cong (\mathbb{A}^{2k} \times S, (0,o))$ of Poisson varieties for each $p \in \LG$. Here $\mathbb{A}^{2k}$ is equipped with the usual symplectic structure. "Local isomorphism'' usually means formally local, however it is consequence of Crawley-Boevey's construction that "local isomorphism'' will mean \'etale locally in this article. 
Since the local isomorphism is Poisson, $\{ o \}$ will be a symplectic leaf in $S$ so that the leaf in $\mathbb{A}^{2k} \times S$ containing $(0,o)$ is $\mathbb{A}^{2k} \times \{ o \}$.

Before we state the result, we introduce one piece of notation. Let $L \subset H$ denote the set of loops in the set $H$ of oriented edges of our graph $\mathsf{G}$. For each dimension vector $\alpha$, taking trace at loops defines a $G(\alpha)$-equivariant map $\Tr_L \colon \Rep(\alpha) \to \C^{2\ell}$, where $2 \ell = |L|$. The restriction of this map to $\mu^{-1}(\bc)$ descends to $\mf{M}_{\bc}(\alpha)$. We define $\mf{M}_{\bc}^0(\alpha) = \Tr_L^{-1}(0)$. Then, provided $\alpha_i \neq 0$ for all $i$, we have $\mf{M}_{\bc}(\alpha) \cong \mf{M}_{\bc}^0(\alpha) \times \C^{2 \ell}$.

Given a leaf $\LG \subset \mf{M}_{\bc}(\alpha)$ labeled by a representation type $\tau = (n_1,\beta^{(1)}; \ds;n_k,\beta^{(k)})$ as in \eqref{eq:taureptype}, we define a new graph $\mathsf{G}(\tau)$ (the \textit{ext-graph}) as follows. The vertices of $\mathsf{G}(\tau)$ are $f_1,\ds, f_k$, thought of as being labeled by the roots $\beta^{(i)}$. In $\mathsf{G}(\tau)$, there are $-(\beta^{(i)},\beta^{(j)})$ edges between $i$ and $j$ if $i \neq j$ and $p(\beta^{(i)})$ loops at $i$. The $k$-tuple $\bn = (n_1, \ds, n_k)$ forms a dimension vector for the ext-graph $\mathsf{G}(\tau)$. Note that when $\beta^{(i)} \neq \beta^{(j)}$, \cite[Proposition~2.6]{CBKimura} says that $-(\beta^{(i)},\beta^{(j)}) = \dim \Ext^1_{\Pi^{\bc}}(M_i,M_j) \ge 0$, where $M_i,M_j$ are simple $\Pi^{\bc}$-modules of dimension $\beta^{(i)}$ and $\beta^{(j)}$ respectively. If $\beta^{(i)}= \beta^{(j)}$ then $p(\beta^{(i)}) \ge 0$ implies that $-(\beta^{(i)},\beta^{(j)}) < 0$ only when $\beta^{(i)}$ is real, in which case $i = j$ because real roots can only appear once in any given representation type.

\begin{thm}\label{thm:CBLunaslice}
	For each $p \in \LG$ there is a local isomorphism 
	$$
	(\mf{M}_{\bc}(\mathsf{G},\alpha), p) \cong (\mf{M}_{0}(\mathsf{G}(\tau),\bn),0) \cong (\mf{M}_{0}^0(\mathsf{G}(\tau),\bn) \times \mathbb{A}^{2 \ell},(0,0)).
	$$
	Moreover, $(\mf{M}_{0}^0(\mathsf{G}(\tau),\bn) ,0)$ is a transverse slice to $\LG$ at $p$. 
\end{thm}

\begin{proof}
The local isomorphism follows directly from \cite[Corollary~4.10]{CBnormal}. The only thing to check is the last statement. For $(\mf{M}_{0}^0(\mathsf{G}(\tau),\bn) ,0)$ to be a transverse slice, we require (a) the isomorphism $\mf{M}_{0}(\mathsf{G}(\tau),\bn) \cong \mf{M}_{0}^0(\mathsf{G}(\tau),\bn) \times \mathbb{A}^{2 \ell}$ is Poisson, with the non-degenerate Poisson structure on $\mathbb{A}^{2 \ell}$, and (b) $\dim \mc{L} = 2 \ell$.

Recall that $\mc{O}(\mf{M}_{0}(\mathsf{G}(\tau),\bn))$ is generated by traces of oriented cycles. If $\mf{l}$ is the necklace Lie algebra of $\mathsf{G}(\tau)$ then the morphism $\mf{l} \to \mc{O}(\mf{M}_{0}(\mathsf{G}(\tau),\bn))$ given by $\omega \mapsto \Tr \omega$ is a surjective Lie algebra homomorphism, where the codomain is a Lie algebra via the Poisson bracket; see \cite[Theorem~1.8]{VdenBDouble}. As a closed subvariety, $\mathbb{A}^{2 \ell} \subset \mf{M}_{0}(\mathsf{G}(\tau),\bn)$ is the zero set of all functions $\Tr \omega$ as $\omega$ runs over all oriented cycles that contain at least one arrow between distinct vertices (equivalently, whose support is more than one vertex). If $I \subset \mf{l}$ is the span of all such cycles then one can check from the necklace formula that $I$ is an ideal of $\mf{l}$. Moreover, the formula implies that $\mc{O}(\mf{M}_{0}(\mathsf{G}(\tau),\bn)) \to \mc{O}( \mathbb{A}^{2 \ell} )$ is a morphism of Poisson algebras confirming (a).

The leaf in $\mf{M}_{0}(\mathsf{G}(\tau),\bn)$ containing the point $0$ is labeled by representation type $(n_1,f_1;n_2,f_2;\ds; n_k,f_k)$ and hence has dimension 
\[
2 \sum_{i=1}^k p(f_i) = 2 \sum_{i=1}^k p(\beta^{(i)}) = 2 \ell,
\]
confirming (b). 
\end{proof}

We end with basic observations that allow us to explicitly identify the transverse slices in examples; these observations will be useful later. The first is immediate. 

\begin{lem}\label{lem:quiverbraking1}
	Assume that $0$ is a vertex for the graph $\mathsf{G}$ and $\alpha$ a dimension vector with $\alpha_0 = 1$. If $\ell$ is the number of loops at vertex $0$ then $\mf{M}_{\bc}(\mathsf{G},\alpha) \cong \mf{M}_{\bc}(\mathsf{G}^{\circ},\alpha) \times \C^{2 \ell}$, where $\mathsf{G}^{\circ}$ is the graph obtained by removing the $\ell$ loops at $0$. 
\end{lem}

\begin{remark}\label{rem:loopsatone}
In the setting of Theorem~\ref{thm:CBLunaslice}, assume that $n_i = 1$ for all imaginary $\beta^{(i)}$. Since $\beta$ is imaginary if and only if $p(\beta) > 0$, this means that $\mbf{n}_i = 1$ for all vertices $i$ in $\mathsf{G}(\tau)$ with at least one loop. Then combining Theorem~\ref{thm:CBLunaslice} with Lemma~\ref{lem:quiverbraking1} shows that $\mf{M}_{0}^0(\mathsf{G}(\tau),\bn) \cong \mf{M}_{0}(\mathsf{G}(\tau)^{\circ},\bn)$, where $\mathsf{G}(\tau)^{\circ}$ now means "remove all loops in $\mathsf{G}(\tau)$".
\end{remark}

Let $\mathsf{G}(1), \ds, \mathsf{G}(k)$ be a collection of graphs with dimension vectors $\alpha(1), \ds, \alpha(k)$ and distinguished vertex $0_j \in \mathsf{G}(j)$ such that $\alpha(j)_{0_j} = 1$ and $\mathsf{G}(j)$ has no loops at $0_j$ for all $j$. We form the new graph $\mathsf{G}$ by gluing these graphs at the distinguished vertex (labeled $0$ in $\mathsf{G}$). Note that each $\mathsf{G}(j)$ is a full subgraph of $\mathsf{G}$. There is a dimension vector $\alpha$ for $\mathsf{G}$ with $\alpha_0 = 1$ such that $\alpha |_{\mathsf{G}(j)} = \alpha(j)$ for all $j$. Let $\bc(j)$ be parameters for the $\mathsf{G}(j)$ such that $\bc(j)(e_{0_j}) = 0$. They extend to a parameter $\bc$ for $\mathsf{G}$ with $\bc(e_0) = 0$. 


\begin{lem}\label{lem:quiverbraking2}
Assume that the graphs $\mathsf{G}(1), \ds, \mathsf{G}(k)$ etc. are given as above. If $\dim \mf{M}_{\bc}(\mathsf{G},\alpha) = 2 p(\alpha)$ and $\dim \mf{M}_{\bc(j)}(\mathsf{G}(j),\alpha(j)) = 2 p (\alpha(j))$ for all $i = 1, \ds, k$ then there is an isomorphism  
		$$
	\prod_{j = 1}^k \mf{M}_{\bc(j)}(\alpha(j)) \iso \mf{M}_{\bc}(\alpha).
		$$

\end{lem}

\begin{proof}
Let $\Rep(\alpha)$ be the representation space, with $\bw = 0$, as in \eqref{eq:repspace}. Then $\Rep(\alpha) = \prod_{j = 1}^k \Rep(\alpha(j))$ and there is a diagonal embedding $G(\alpha) \hookrightarrow \prod_{j = 1}^k G(\alpha(j))$ such that the identification is $G(\alpha)$-equivariant. We claim that the resulting embedding 
\[
\bigotimes_{j = 1}^k \C[\Rep(\alpha(j))]^{G(\alpha(j))} \hookrightarrow    \C[\Rep(\alpha)]^{G(\alpha)}
\]
is an isomorphism. As noted in the proof of Proposition~\ref{prop:leafclosurenormal}, $\C[\Rep(\alpha)]^{G(\alpha)}$ is generated by all traces $\Tr \omega$ of oriented cycles $\omega$ in $\mathsf{G}$. If such a cycle does not pass through $0$ then it is entirely contained in one $\mathsf{G}(j)$ and is clearly invariant under the larger group. If $\omega$ does pass through $0$, then 
we may write
    \[
       \Tr \omega = \prod_{x} \Tr \omega{(x)}
    \]
    where $\omega{(x)}$ is a cycle beginning and ending at $0$, passing through that vertex just once. Then $\omega{(x)}$ again lies entirely in some $\mathsf{G}(j)$ and is invariant under the larger group. The claim follows.



Next, the relations defining $\mu^{-1}(\bc)$ at vertex $0$ can be written $\sum_{j = 1}^k \mu_j^{-1}(\bc(j)) = 0$, where $\mu_j$ is the moment map for $G(\alpha(j))$ acting on $\Rep(\alpha(j))$. Thus, $I(\mu^{-1}(\bc)) \subset I(\mu_1^{-1}(\bc(1)),\ds, \mu_k^{-1}(\bc(k)))$ in $\C[\Rep(\alpha)]$ and we get a surjection
\begin{align*}
\C[\mu^{-1}(\bc)]^{G(\alpha)} & = \left( \C[\Rep(\alpha)] / I(\mu^{-1}(\bc))\right)^{G(\alpha)} \to \left( \C[\Rep(\alpha)] / I(\mu_1^{-1}(\bc(1)),\ds, \mu_k^{-1}(\bc(k)))\right)^{G(\alpha)} \\
& = \left( \C[\Rep(\alpha)] / I(\mu_1^{-1}(\bc(1)),\ds, \mu_k^{-1}(\bc(k)))\right)^{\prod_j G(\alpha(j))} = \bigotimes_{j = 1}^k \C[\mu_j^{-1}(\bc(j))]^{G(\alpha(j))}. 
\end{align*}
Thus, there is a closed embedding 
\begin{equation}\label{eq:productclosedembed}
	\prod_{j = 1}^k \mf{M}_{\bc}(\alpha(j)) \hookrightarrow \mf{M}_{\bc}(\alpha).    
\end{equation}
Finally, write $\alpha(j) = \alpha(j)' + e_{0}$ so that $(\alpha(j)',\alpha(s)') = 0$ for $j \neq s$ and $\alpha = \alpha(1)' + \cdots + \alpha(k)' + e_{0}$. Then, using that $(e_0,e_0) = 2$,  
\begin{align*}
    p(\alpha) & = 1 - (1/2)( \alpha(1)' + \cdots + \alpha(k)' + e_{0},\alpha(1)' + \cdots ) \\
    & = - \sum_{i = 1}^k  ((1/2)(\alpha(i)',\alpha(i)') + (e_{0},\alpha(i)'))  \\
    & = k - (1/2) \sum_{i = 1}^k \left( (\alpha(i)',\alpha(i)') + 2 (e_{0},\alpha(i)') + (e_{0},e_0) \right) \\
    & = \sum_{i = 1}^k p(\alpha(i)).
\end{align*}
Therefore, the assumption $\dim \mf{M}_{\bc}(\mathsf{G},\alpha) = 2 p(\alpha)$ and $\dim \mf{M}_{\bc(j)}(\mathsf{G}(j),\alpha(j)) = 2 p (\alpha(j))$ for all $i = 1, \ds, k$ implies that \eqref{eq:productclosedembed} is a closed embedding of irreducible varieties of the same dimension. Thus, it is an isomorphism. 
\end{proof}

Lemma~\ref{lem:quiverbraking1} says that we can forget any loops at a vertex $i$ with $\alpha_i = 1$ and Lemma~\ref{lem:quiverbraking2} says that we can "break'' the graph into its connected parts at vertex $i$ if it has no loops and $\alpha_i = 1$. 

\subsection{Transverse Singularities in Calogero--Moser varieties}\label{sec:nonzerotransverse}

Assume first that $\bc(\delta) = -1$. We fix a leaf $\LG(\beta)$ in $\ZCB_{c}(\Gamma_n)$. Recall that the set $\Delta(\bc) = \{ \eta^{(1)}, \ds, \eta^{(s)} \}$ of minimal roots in $R^+_{\bc}$ is a set of simple roots for the root system $R_{\bc}$. 


As explained previously, we may assume that $w(\Delta(\bc)) = w(R^+_{\bc}) \cap \Delta$ and hence $R^+_{\bc}$ is conjugate to a parabolic subsystem of $R$. Let $\mathsf{G}(\bc)$ be the subgraph of the affine Dynkin graph $\mathsf{G}(\Gamma)$ obtained by deleting the vertices not in $w(R^+_{\bc}) \cap \Delta$. Then $\mathsf{G}(\bc)$ is a disjoint union of finite Dynkin diagrams. Since $\beta \in \Xi(\bc)$, we may write $\beta = v_1 \eta^{(1)} + \cdots + v_s \eta^{(s)}$ and think of $\bv = (v_1, \ds, v_s)$ as a dimension vector for $\mathsf{G}(\bc)$. We define a framing vector $\bw = (w_1, \ds, w_s)$ for $\mathsf{G}(\bc)$ by 
$$
w_i := (\beta + \Lambda_0, \eta^{(i)}).
$$

\begin{thm}\label{thm:transversenonzerolevel}
	Let $\beta \in \Xi(\bc)$ with $\varrho(\beta) \le n$.  The transverse slice to $\LG(\beta)$ in $\ZCB_{c}(\Gamma_n)$ is isomorphic to the framed quiver variety $\mf{M}_0(\mathsf{G}(\bc),\bw,\bv)$. 
\end{thm}

\begin{proof}
Recall from the proof of Theorem~\ref{thm:nonzerolevelleaves} that $\beta$ corresponds to the representation type 
\[
\tau = (\gamma(m,\nu),(v_1,\eta^{(1)};\ds; v_s,\eta^{(s)})),
\]
where $\nu = \beta - \beta_0 \delta$ and $m = n - \qu(\beta)$. The ext-graph $\mathsf{G}(\tau)$ in this case is obtained from $\mathsf{G}(\bc)$ by adding one additional vertex $\infty$ corresponding to the vector $\gamma(m,\nu)$ and $m = p(\gamma(m,\nu))$ loops at the vertex $\infty$. The dimension at vertex $\infty$ is $1$ and the number of arrows from $\infty$ to $\eta^{(i)}$ is 
\[
 - (e_{\infty} + \gamma(m,\nu),\eta^{(i)}) = (\beta - n \delta - e_{\infty},\eta^{(i)}) = (\beta - e_{\infty}, \eta^{(i)}) = (\beta + \Lambda_0, \eta^{(i)})=w_i.
\]
Therefore, Lemma~\ref{lem:quiverbraking1} says that $\mf{M}_{0}(\mathsf{G}(\tau),e_{\infty} + \bv) \cong \mf{M}_{0}(\mathsf{G}(\tau)^{\circ},e_{\infty} + \bv) \times \C^{2m}$; see also Remark~\ref{rem:loopsatone}. But $\mathsf{G}(\tau)^{\circ}$ equals the graph $\mathsf{G}(\bc)'$ we obtain by deframing $\mathsf{G}(\bc)$ with respect to framing vector $\bw$; see Section~\ref{sec:CBtrick}. In other words, 
\[
\mf{M}_{0}(\mathsf{G}(\tau)^{\circ},e_{\infty} + \bv) \cong \mf{M}_0(\mathsf{G}(\bc),\bw,\bv).
\]
Therefore, Theorem~\ref{thm:CBLunaslice} implies that a transverse slice to $\LG(\beta)$ is given by $\mf{M}_0(\mathsf{G}(\bc),\bw,\bv)$. 
\end{proof}

Our next goal is to show that if $\mathsf{G}$ is any finite type (ADE) graph and $\Gamma\subset \SL(2,\C)$ the group corresponding to the affine Dynkin graph $\widetilde{\mathsf{G}}$ then every framed Nakajima quiver variety associated to $\mathsf{G}$ can be realized as a transverse slice to $\LG$ in $\ZCB_{c}(\Gamma_n)$ for some leaf $\LG$ and $n,c$. 

\begin{lem}\label{lem:rootssimplesub}
    Let $\Phi \subset R$ be the finite and affine root system respectively associated to $\Gamma \subset \SL(2,\C)$. Assume $\bc(\delta) = 1$ and we are given $\{ \eta^{(1)}, \ds, \eta^{(r)} \} \subset R^+_{\bc}$ such that the Cartan matrix $C$, with $C_{i,j} := (\eta^{(i)},\eta^{(j)})$ for $1 \le i, j \le r$, is equivalent to the Cartan matrix of $\Phi$. Then $\{ \eta^{(1)}, \ds, \eta^{(r)} \}$ is a set of simple roots for $R_{\bc}^+$ and $R_{\bc}^+ \cong \Phi$. 
\end{lem}

\begin{proof}
First we note that $C_{i,j} \le 0$ for $i \neq j$ since $C$ is assumed equivalent to the Cartan matrix for $\Phi$. This implies that $\{ \eta^{(1)}, \ds, \eta^{(r)} \}$ is a set of simple roots for a root subsystem $\Psi$ of $R_{\bc}$ by \cite[Lemma~1]{DyerLehrer}. The rank of $C$ is $r$. By Lemma~\ref{lem:wparabolicrootsystem},  $R_{\bc}$ is a equivalent to a parabolic root system in $R$. Therefore, the rank of $R_{\bc}^+$ is at most $r$ too. This means that $R_{\bc}$ must also have rank exactly $r$. Since $R_{\bc}$ is a equivalent to a parabolic root system in $R$, its Cartan matrix $C(\bc)$ with respect to $\Delta(\bc)$ is equivalent to a (proper) submatrix of the Cartan matrix for the affine root system $R$. 

Therefore, we are in the following situation: we have a finite root system $R_{\bc}$ obtained by deleting one vertex of the simply-laced affine Dynkin graph $\widetilde{\mathsf{G}}$, which contains a subsystem $\Psi$ of type $\mathsf{G}$. We claim that $\Psi = R_{\bc}$. First note that $R_{\bc}$ must be irreducible. Indeed, $\Psi$ is an irreducible subsystem of the same rank as $R_{\bc}$, which means that the Weyl group $W(\Phi)$ acts irreducibly on its reflection representation $\mathfrak{h} = \Span_{\R}(\Psi) = \Span_{\R}(R_{\bc})$, so $W(R_{\bc})$ must also act irreducibly since $W(\Psi) \subset W(R_{\bc})$. In type $\mathsf{A},\mathsf{D},\mathsf{E}_6$ the equality is clear since all irreducible parabolic subsystems of $\widetilde{\mathsf{A}}_{r}$, resp. $\widetilde{\mathsf{D}}_{r}$ or $\widetilde{\mathsf{E}}_{6}$, obtained by deleting one vertex are of type $\mathsf{A}_{r}$, resp. of type $\mathsf{D}_r$ or type $\mathsf{E}_6$. In $\widetilde{\mathsf{E}}_{7}$, the irreducible parabolic subsystems of rank $7$ are of type $\mathsf{E}_{7}$ or $\mathsf{A}_{7}$. But $|\Psi| = |\mathsf{E}_{7}| = 126 > 56 = |\mathsf{A}_{7}|$ so we must have $\Psi = R_{\bc}$ of type $\mathsf{E}_{7}$. Finally, in $\widetilde{\mathsf{E}}_{8}$, the irreducible parabolic subsystems of rank $7$ are of type $\mathsf{E}_{8}, \mathsf{D}_8,\mathsf{A}_{8}$. But $|\Psi| = |\mathsf{E}_{8}| = 240 > 112 = |\mathsf{D}_{8}|, 72 = |\mathsf{A}_{8}|$, so we must have $\Psi = R_{\bc}$. 
    \end{proof}

\begin{prop}\label{prop:transversearbitrary}
    Let $\mathsf{G}$ be a finite type Dynkin graph and $\Gamma\subset \SL(2,\C)$ the group corresponding to the affine Dynkin graph $\widetilde{\mathsf{G}}$. For any pair $(\bw,\bv)$ of dimension vectors for $\mathsf{G}$, there exists $n, c$ and a leaf $\LG$ such that $\mf{M}_0(\mathsf{G},\bw,\bv)$ is isomorphic to the transverse slice to $\LG$ in $\ZCB_{c}(\Gamma_n)$.   
\end{prop}

\begin{proof}
Let $\Phi$ denote the finite root system associated to $\mathsf{G}$. First note that \cite[Proposition~3.9]{McGertyNevinsGalois} says that there exists $\bv' \le \bv$ such that $\mf{M}_0(\mathsf{G},\bw,\bv) \cong \mf{M}_0(\mathsf{G},\bw,\bv')$ with $\sum_{i=1}^r w_i \Lambda_i - \sum_i v_i' e_i$ a dominant weight; here $\bv' = (v_1', \ds, v_r')$. This means that 
    \[
    k_i := w_i - \sum_j v_j' (e_i,e_j) \in \Z_{\ge 0}, \quad \forall \, 1 \le i \le r. 
    \]
    Let $\bc_i = -k_i$ and $\bc_0 = 1 + \sum_{i = 1}^r \delta_i k_i$ so that $\bc(\delta) = 1$. Let $\eta^{(i)} = e_i + k_i \delta$. Then $\eta^{(i)} \in R_{\bc}^+$ for all $i$. Notice that $C_{i,j} := (\eta^{(i)},\eta^{(j)}) = (e_i,e_j)$, implying that the Cartan matrix $C$ equals the Cartan matrix for $\Phi$. Lemma~\ref{lem:rootssimplesub} then implies that $\Delta(\bc) = \{ \eta^{(1)}, \ds, \eta^{(r)} \}$.  If $\beta := \sum_{i = 1}^r v_i' \eta^{(i)}$ then we claim that $\beta \in \Xi(\bc)$. Indeed, assume that $\eta = \sum_{i = 1}^r u_i \eta^{(i)} \in \SS{\bc}$ with $\eta \succ \beta$; that is, $u_i \ge v_i'$ for all $i$ and $\eta \neq \beta$. Then, 
    \begin{align*}
        2(\qu(\eta) - \qu(\beta)) & = 2 \eta_0 + (\eta,\eta) - 2 \beta_0 - (\beta,\beta) \\
        & = 2 \sum_{i = 1}^r u_i k_i + (\eta,\eta) - 2 \sum_{i = 1}^r v_i' k_i - \sum_{i,j} v_i' v_j' (e_i,e_j) \\
        & = 2 \sum_{i = 1}^r u_i \left(w_i - \sum_{j = 1}^r v_j' (e_i,e_j) \right) + (\eta,\eta) - 2 \sum_{i = 1}^r v_i' \left(w_i - \sum_{j = 1}^r v_j' (e_i,e_j) \right)- \sum_{i,j} v_i' v_j' (e_i,e_j) \\
        & = 2 \sum_{i = 1}^r (u_i - v_i') w_i - 2 \sum_{i,j} u_i v_j' (e_i,e_j) + \sum_{i,j} u_i u_j(e_i,e_j) + \sum_{i,j} v_i'v_j' (e_i,e_j)\\
        & = 2 \sum_{i = 1}^r (u_i - v_i') w_i + (\mbf{u} - \bv',\mbf{u} - \bv'),
    \end{align*}
    where $\mbf{u} = \sum_{i = 1}^r u_i e_i$. Now, $( - , - )$ is positive definite on $\boldsymbol{\Lambda}$ and $0 \neq \mbf{u} - \bv' \in \boldsymbol{\Lambda}$. Hence, $(\mbf{u} - \bv',\mbf{u} - \bv') > 0$. This implies that $\qu(\eta) > \qu(\beta)$ and thus $\beta \in \Xi(\bc)$. 

    Finally, note that 
    \[
    (\beta+ \Lambda_0, \eta^{(i)}) = \sum_{j = 1}^r v_j'(\eta^{(j)},\eta^{(i)}) + (\Lambda_0, \eta^{(i)}) = \sum_{j = 1}^r v_j'(e_j,e_i) + k_i = w_i. 
    \]
    Then the claim of the proposition follows from Theorem~\ref{thm:transversenonzerolevel} if we take any $n \ge \varrho(\beta)$. 
\end{proof}

Note that taking $n = \varrho(\beta)$ in the proof of Proposition~\ref{prop:transversearbitrary} shows that the finite type quiver variety $\mf{M}_0(\mathsf{G},\bw,\bv)$ can be realized as a transverse slice to a zero-dimensional leaf in some Calogero--Moser variety. 

\begin{rem}\label{rem:rangeofslices}
If $\mathsf{G} = \mathsf{A}_{\ell-1}$, for some $\ell \ge 2$, then the quiver varieties $\mf{M}_0(\mathsf{G},\bw,\bv)$ are isomorphic to type $\mathsf{A}$ Slodowy slices $S(\mu,\nu)$ (and any type $\mathsf{A}$ Slodowy slice can be realized this way); see \cite[Section~8]{Nak1994} and \cite{MaffeiA}. By \cite{MVyb}, we may equivalently identify $\mf{M}_0(\mathsf{G},\bw,\bv)$ with a slice in the affine Grassmaniann of type $\mathsf{A}$. Therefore, given any Slodowy slice of type $\mathsf{A}$ or any slice in the affine Grassmaniann of type $\mathsf{A}$, one can always find $n,c$ and a leaf $\LG \subset \ZCB_{c}(\Gamma_n)$, with $\Gamma = \Z / \ell \Z$, such that the singularity transverse to $\LG$ is isomorphic to this slice. 
\end{rem}

Now we assume that $\bc(\delta) = 0$. For each irreducible factor $\Phi_i$ of $\Phi_{\bc}$ we have a finite subgroup $\Gamma(i)$ of $\SL(2,\C)$ whose affine Dynkin diagram (via the McKay correspondence) is the affinization of the Dynkin diagram of $\Phi_i$. 

\begin{lem}\label{lem:transversezerolevel}
	If $\rho = (0,(n,\delta - \theta(i); n h(i)_1,\alpha(i)_1; \dots ))$ and $p \in \LG{(\emptyset,\rho)}$, then $(\ZCB_{c}(\Gamma_n),p) \cong (\C^{2n}/\Gamma(i)_n, 0)$.  
\end{lem}

\begin{proof}
	If we consider first the representation type $(1, \delta - \theta(i);h(i)_1,\alpha(i)_1; \dots )$ then the corresponding ext-graph is just $\mathsf{G}(\Gamma(i))$, with dimension vector $\delta(i)$, the minimal imaginary root for $\mathsf{G}(\Gamma(i))$. This implies that the ext-graph for $(\emptyset,\rho)$ is the affine Dynkin diagram associated to $\Gamma(i)$ and the dimension vectors are $(\Lambda_0, n \delta(i))$. Then the isomorphism follows from Theorem~\ref{thm:CMquiveriso}. 
\end{proof}

\begin{prop}
	Assume $\bc(\delta) = 0$. If $p \in \LG{(\lambda,\rho)}$ then 
	$$
	(\ZCB_{c}(\Gamma_n),p) \cong \left(\C^{2 |\lambda|}/ \s_{\lambda} \times \prod_{i = 1}^{\ell} \C^{2 \rho_i} / \Gamma(i)_{\rho_i}, 0\right).
	$$
\end{prop}

\begin{proof}
Recall from \eqref{eq:degeneratelambdadecomp} that the leaf $\LG_{(\lambda,\rho)}$ is labeled by representation type 
\[
		(0,(\lambda_1,\delta;\lambda_2,\delta;\ds;\rho_1,\delta - \theta(1);\rho_1 h(1)_1, \alpha(1)_1; \dots ;\rho_1 h(1)_{r_1}, \alpha(1)_{r_1};\rho_2,\delta - \theta(2);\ds )).    
\]
	The ext-graph associated to $(\lambda,\rho)$ has a central vertex corresponding to the factor $e_{\infty}$. The dimension at this vertex is one. One can check that the hypothesis of Lemma~\ref{lem:quiverbraking2} hold because $p(e_{\infty} + n \delta) = p_{\Lambda_0}(n \delta) = n$ and 
 \[
 \sum_{i = 1}^{\ell(\lambda)} p_{\Lambda_0}(\lambda_i \delta) + \sum_{j = 1}^{\ell} p_{\Lambda_0}(\rho_j \delta(j)) =  \sum_{i = 1}^{\ell(\lambda)} \lambda_i + \sum_{j = 1}^{\ell} \rho_j = |\lambda | + |\rho | = n.
 \]
Therefore, the associated quiver variety can be expressed as a product, one factor for each connected component of the graph we get by breaking the graph at this central vertex; see \eqref{eq:diagramquiverbreaking} for a visualization. The representation type $(0,(\lambda_i,\delta))$ has ext-graph the one vertex and one loop (or Jordan) graph and dimension vectors $(\Lambda_0,\lambda_i e_0)$. The ext-graph of the representation type $(0,(\rho_i,\delta - \theta(i);\rho_i h(i)_1, \alpha(i)_1; \dots ;\rho_i h(i)_{r_i}, \alpha(i)_{r_i}))$ is described in Lemma~\ref{lem:transversezerolevel}. Thus,
 \[
 \mf{M}_0(\mathsf{G}(\tau),\mathbf{n}) \cong \prod_{j = 1}^{\ell(\lambda)} \XC_0(\mathsf{G}_J, \lambda_j \delta) \times \prod_{i = 1}^{\ell} \XC_0(\mathsf{G}(\Gamma),\rho_i \delta(i)). 
 \]
It has been shown in \cite[Lemma~2.11]{GanGinzburg} that each $\XC_0(\mathsf{G}_J,\lambda_j \delta)$ is isomorphic to $\C^{2 \lambda_j} / \s_{\lambda_j}$. Theorem~\ref{thm:CMquiveriso} says that $\XC_0(\mathsf{G}(\Gamma),\rho_i \delta(i)) \cong \C^{2 \rho_i} / \Gamma(i)_{\rho_i}$. The claim follows. 
\end{proof}



\section{The hyperoctahedral group}\label{sec:hyperoctahedral}

As an extended example, we consider the case where $\Gamma_n$ is the hyperoctahedral group. That is, $\Gamma = \Z / 2 \Z$ and $\Gamma_n$ is the Weyl group of type $\mathsf{B}_n$. 

\subsection{The proof of Theorem~\ref{thm:mainsing}}\label{sec:mainsingproof}

The rational Cherednik algebra $\Hb_{c}(\Gamma_n)$ (at $t = 0$) associated to the Weyl group $\Gamma_n = W(\B_n)$ depends on the choice of a pair of parameters $c = (c_1,c_{\gamma}) \in \C^2$. We recall the following theorem by Martino \cite[Theorem~8.2]{MarsdenWeinsteinStratification}. 

\begin{thm}\label{thm:BSympleaves} 
	Let $c = (c_1,c_{\gamma})$.
	\begin{enumerate}
		\item[(i)] \label{thm:BSympleaves:singular}  $\ZCB_{c}(\Gamma_n)$ is singular if and only if $c_1 = 0$ or $c_{\gamma} = m c_1$ for some integer $-n < m < n$.  
		\item[(ii)] If $c_1 = 0$ but $c_{\gamma} \neq 0$, then the symplectic leaves of $\ZCB_{c}(W)$ are parameterized by the set $\mc{P}(n)$ of partitions of $n$. For $\lambda \in \mc{P}(n)$, the corresponding leaf $\LG_{\lambda}$ has dimension $2 \ell(\lambda)$, where $\ell(\lambda)$ is the length of $\lambda$.
		\item[(iii)] If $c_{\gamma} = m c_1$, with $c_1 \neq 0$, then there is a bijection $k \mapsto \LG_k$,
		$$
		\{ \textrm{symplectic leaves $\LG$ of $\ZCB_{c}(W)$} \ \} \stackrel{1 : 1}{\longleftrightarrow} \{ k \in \Z_{\ge 0} \ | \ k(k+m) \le n \} \;.
		$$
		Moreover, $\dim \LG_{k} = 2(n - k(k+m))$.
	\end{enumerate}
\end{thm}

In this case, the graph $\mathsf{G}$ is the affine Dynkin quiver of type $\widetilde{\mathsf{A}}_1$ (with $2$ vertices). 
The minimal imaginary root is $\delta = e_0 + e_1$. By Theorem~\ref{thm:CMquiveriso}, there is an isomorphism $\ZCB_{c}(\Gamma_n) \cong \XC_{{\bc}}(n \delta)$, where 
 \begin{equation}\label{eq:lambdakappc1}
\bc = (- c_1 + c_{\gamma}, - c_{\gamma}).
 \end{equation}
Part (ii) of Theorem~\ref{thm:BSympleaves} is a special case of Proposition~\ref{prop:labelleaveslevel0}, where the condition $c_{\gamma} \neq 0$ means that the surface $X_{\bc}$ is smooth and hence the leaves are labeled by pairs $(\lambda,\rho)$, where $\rho$ is an empty composition. The leaf $\LG({\lambda})$ for $\lambda \in \mc{P}(n)$ is labeled by the representation type
\begin{equation}\label{eq:leafLrho}
	\tau = (0,(\lambda_1,\delta; \ds ;\lambda_{\ell},\delta)).
\end{equation}
Part (iii) of Theorem~\ref{thm:BSympleaves} is a special case of Theorem~\ref{thm:nonzerolevelleaves}. It was already shown in \cite[Proposition~5.7]{MartinoThesis} that, when $c_{\gamma} = \pm m c_1$, the leaf $\LG_k$ is labeled by the representation type
\begin{equation}\label{eq:leafLk}
	\tau = (n \delta - k \eta^{(1)},(k,\eta^{(1)})),
\end{equation}
where $\eta^{(1)}$ is unique (real) root in $R^+_{\bc}$. Thus, $\beta = k \eta^{(1)} \in \Xi({\bc})$. Specifically, $\eta^{(1)} = m e_0 + (m-1) e_1$ when $c_{\gamma} = m c_1$ with $1 \le m < n$ and $\eta^{(1)} = m e_0 + (m+1) e_1$ when $c_{\gamma} = - m c_1$ with $0 \le m < n$. See also Example \ref{ex:comb-l=2} for the combinatorial parameterization of symplectic leaves in this case.

Recall from the introduction that $\mc{O}(k,N)$ denotes the $GL(N)$-orbit of all matrices $X \in \mf{gl}(N)$ of rank $k$ with $X^2 = 0$. 

\begin{lem}\label{lem:singLk}
	Assume $c_{\gamma} = m c_1$ for $1 \le m \le n-1$ and $c_1 \neq 0$. Then there is an isomorphism of \'etale germs 
    \[
    (\ZCB_{c}(\Gamma_n),p) \cong (\overline{\mc{O}(k,2k+m)} \times T^* (\C^{n - k(k+ m)}),0)
    \]
    for any $p \in \LG_k$ and $k \in \Z_{\ge 0}$ such that $k(k+m) \le n$. 
\end{lem}

\begin{proof}
We note, for the computations below, that 
$$
(e_{\infty},\delta) = -1, \quad (e_{\infty}, \eta^{(1)}) = -m, \quad (\delta,\eta^{(1)}) = 0. 
$$
The lemma is a special case of Theorem~\ref{thm:transversenonzerolevel}. In this case, there exists simple representations $M,N$ of the deformed preprojective algebra such that $\dim M = e_{\infty} + n \delta - k \eta^{(1)}$, $\dim N = \eta^{(1)}$ and $p$ corresponds to the point $M \oplus N^{\oplus k}$. We have
\begin{align}
	p(e_{\infty} + n \delta - k \eta^{(1)}) & = p_{\Lambda_0}(n \delta - k \eta^{(1)}) \\
 & = 1 - (1/2) ((e_{\infty},e_{\infty}) + 2n (e_{\infty}, \delta) + k^2 (\eta^{(1)},\eta^{(1)}) - 2 k (e_{\infty},\eta^{(1)})) \\
  & = n - k(m + k).  \label{eq:peinftycomputation}  
\end{align}
    Theorem~\ref{thm:CBLunaslice} says that the germ $(\XC_{{\bc}}(n \delta),p)$ is isomorphic to the quiver variety $(\mathfrak{M}_0(\mathsf{G}(\bc),(k,1)),0)$, where $\mathsf{G}(\bc)$ is the graph with $2$ vertices, $p(\eta^{(1)}) = 0$ loops at the first vertex, $p(e_{\infty} + n \delta - k \eta^{(1)}) = n - k(m + k)$ loops at the second vertex and 
	$$
	- (e_{\infty} + n \delta - k \eta^{(1)},\eta^{(1)}) = 2k + m
	$$
	edges between the first and second vertex. This means that $\mathsf{G}(\bc)$ is the $(2k+m)$-Kronecker graph. Notice that $(k,1)$ is an indivisible imaginary root with $p((k,1)) = k(k+m)$. It is straight-forward to check that $\mathfrak{M}_0(\mathsf{G}(\bc),(k,1)) = \overline{\mc{O}(k,2k + m)}$.
\end{proof}  



Identical to Lemma~\ref{lem:singLk}, we have:

\begin{lem}\label{lem:singLk2}
	Assume $c_{\gamma} = -m c_1$ for $0 \le m \le n-1$ and $c_1 \neq 0$. Then there is an isomorphism of \'etale germs 
    \[
    (\ZCB_{c}(\Gamma_n),p) \cong (\overline{\mc{O}(k,2k+m)} \times T^*( \C^{n - k(k+ m)}),0)
    \]
    for $p \in \LG_k$ and $k \in \Z_{\ge 0}$ such that $k(k+m) \le n$.
\end{lem}

\begin{lem}
	Assume $c_1 = 0$ and $c_\gamma\ne 0$. If $\lambda \in \mc{P}(n)$ and $p \in \LG_{\lambda}$ then we have an isomorphism of \'etale germs 
	$$
	(\ZCB_{c}(\Gamma_n),p) \cong ((\h \times \h^*)/\s_{\lambda} \times T^* \C^{\ell(\lambda)},0), 
	$$ 
 where $\h$ denoted the reflection representation for $\s_{\lambda}$. 
\end{lem}

\begin{proof}
 In this case, there exist pairwise non-isomorphic simple representations $M_{\infty},M_1, \ds, M_{\ell}$ of the deformed preprojective algebra such that $\dim M_{\infty} = e_{\infty}$ and $\dim M_i = \delta$ for $i > 0$ so that the point $p$ corresponds to the semi-simple representation $M_0 \oplus M_1^{\oplus \lambda_1} \oplus \cdots \oplus M_{\ell}^{\oplus \lambda_{\ell}}$. Theorem~\ref{thm:CBLunaslice} says that $(\ZCB_{c}(\Gamma_n),p)$ is isomorphic to the quiver variety $\mathfrak{M}_0(\mathsf{G}(\bc),(1,\lambda_1, \ds, \lambda_{\ell}))$, where $\mathsf{G}(\bc)$ is a graph with one central vertex $\infty$, $\ell$ outer vertices, and an edge between $\infty$ and each outer vertex and a single loop at each outer vertex. This is illustrated as
 \begin{equation}\label{eq:diagramquiverbreaking}
      \begin{tikzcd}
 	\stackrel{\lambda_2}{\bullet} \arrow[out=165,in=105,loop,looseness=5,no head] & \stackrel{\lambda_1}{\bullet} \arrow[out=120,in=60,loop,looseness=5,no head] & \\
 	\stackrel{\lambda_3}{\bullet} \arrow[out=150,in=210,loop,looseness=5,no head] & \ar[dl,no head]  \ar[l,no head] \ar[lu,no head] \ar[u,no head]    \stackrel{1}{\bullet}  & \\
 	\stackrel{\lambda_4}{\bullet}\arrow[out=195,in=255,loop,looseness=6,no head]  \ar[out=325,in=340,uur,dashed,no head,looseness=2,no head] & & 
 \end{tikzcd}
 \end{equation}
 Let $\mathsf{G}_J$ be the one loop (and one vertex) graph. Since the dimension at the central vertex is $1$ and one can check that the hypothesis of Lemma~\ref{lem:quiverbraking2} hold, we can "break'' the quiver variety at this vertex to get an isomorphism 
 $$
 \mf{M}_{0}(\mathsf{G}(\bc),(1,\lambda_1, \ds, \lambda_{\ell})) \cong \XC_0(\mathsf{G}_J,(\lambda_1)) \times \cdots \times \XC_0(\mathsf{G}_J,(\lambda_{\ell})). 
 $$
 It is well-known \cite[Lemma~2.11]{GanGinzburg} that if $\h$ is the reflection representation for $\s_n$ then 
 $$
 \XC_0(\mathsf{G}_J,(n)) \cong \C^{2n} / \s_n \cong (\h \times \h^*)/ \s_n \times T^* \C.
 $$
The result follows. 
\end{proof}  




\begin{remark}
	In the case $c_1 = 1$ and $c_{\gamma} = m c_1$, and $n = k(k+m)$, there is a bijection between the symplectic leaves $\mc{O}(r, 2k + m)$ in $\overline{\mc{O}(k,2k + m)}$ and the leaves $\LG_r$ in $\ZCB_{c}(\Gamma_n)$. This bijection preserves dimension. Moreover, in both cases the order one gets is a total ordering. 
\end{remark}


\subsection{Leaf closures} In this section, we give a proof of Theorem~\ref{thm:mainclosureB}. 


\begin{thm}\label{thm:quiverleafclosurempos}
	If $c_1 = 1$ and $c_{\gamma} = m$ with $1 \le m < n$ then 
	$$
	\overline{\LG}_k \cong \ZCB_{c'}(\Gamma_{n - k(k+m)})
	$$
	where $c_1' = 1$ and $c_{\gamma}' = m+2k$. 
\end{thm}

\begin{proof}
In order to apply Theorem~\ref{thm:quiverleafclosure}, we work in the quiver variety $\XC_{{\bc}}(n \delta)$. By \eqref{eq:lambdakappc1}, the parameter ${\bc}$ equals $(m-1,-m)$. As noted in the proof of Lemma~\ref{lem:singLk}, the semisimple representations $M$ belonging to $\LG_k$ are of the form $M = M_0 \oplus M_1^{\oplus k}$, where $\dim M_0 = e_{\infty} + n \delta - k \eta^{(1)}$ and $\dim M_1 = \eta^{(1)}$. Since $m \ge 0$, $\eta^{(1)} = m e_0 + (m-1) e_1$ as in \cite[Lemma~5.4]{MartinoThesis}. Then the decomposition $\tau$ labeling $\LG_k$ is $(n \delta - k \eta^{(1)},(k,\eta^{(1)}))$. Proposition~\ref{prop:leafclosurenormal} says that the leaf closure is normal and this closure can be identified with  
	$$
	\XC_{\bc}(n \delta - k \eta^{(1)}) \times \mf{M}_{{\bc}}(\eta^{(1)}) \cong \XC_{{\bc}}(n \delta - k \eta^{(1)})
	$$
	because $\eta^{(1)}$ is a real root so $\mf{M}_{{\bc}}(\eta^{(1)}) = \{ \mr{pt} \}$. Therefore, we need to identify $\XC_{{\bc}}(n \delta - k \eta^{(1)})$ with a Calogero--Moser variety. Note that $p_{\Lambda_0}(n \delta - k \eta^{(1)}) = n - k(m+k)$ by \eqref{eq:peinftycomputation}. We need to find a sequence of admissible reflections taking $e_{\infty} + n \delta - k \eta^{(1)}$ to $e_{\infty} + (n - k(m+k)) \delta$. It is shown in the proof of \cite[Proposition 5.7(2)]{MartinoThesis} that  
	\begin{equation}\label{eq:reflectionsbvminusbeta}
	e_{\infty} + n \delta - k \eta^{(1)} = \left\{ \begin{array}{ll}
		(s_1 s_0)^k(e_{\infty} + (n - k(m+k)) \delta) & \textrm{if $c_{\gamma} = m c_1$ for $1 \le m < n$,} \\
		s_0(s_1 s_0)^{k-1}(e_{\infty} + (n - k(m+k)) \delta) & \textrm{if $c_{\gamma} = -m c_1$ for $0 \le m < n$.} \\	
	\end{array}\right. 	
	\end{equation}
	In other words,   
	$$
	(s_0 s_1)^k (e_{\infty} + n \delta - k \eta^{(1)}) = e_{\infty} + (n - k(m+k)) \delta =: \alpha'.
	$$ 
	Since $(e_{\infty},e_0) = -1, (e_{\infty}, e_1) = 0$ and $(e_0, e_1) = -2$, we have 
	$$
	s_0(a e_{\infty} + b e_0 + c e_1) = a e_{\infty} + (a - b + 2c) e_0 + c e_1 , \quad s_1(a e_{\infty} + b e_0 + c e_1) = a e_{\infty} + b e_0 + (2b - c) e_1.
	$$
	The dual action on parameters is given by 
 $$
	s_0^* ({\bc}) = (-{\bc}_0,{\bc}_1 + 2 {\bc}_0), \quad s_1^* ({\bc}) = ({\bc}_0 + 2 {\bc}_1,- {\bc}_1).
	$$ 
	Hence $s_0^* s_1^*({\bc}) = (- {\bc}_0-2 {\bc}_1,2{\bc}_0+3 {\bc}_1)$. Applying this to ${\bc} = (m-1,-m)$, an induction shows that 
	$$
	(s_0^* s_1^*)^k(m-1,-m) = (m + 2k-1,-m-2k) =: {\bc}'. 
	$$
	Moreover, a quick induction shows that the sequence of reflections $s_0 s_1 \cdots s_0 s_1$ is admissible for this ${\bc}$. Therefore, $\XC_{{\bc}}(n \delta - k \eta^{(1)}) \cong \XC_{{\bc}'}(\alpha')$. If we write $\bc' = (-c_1' + c_{\gamma}', -c_{\gamma}')$, as in \eqref{eq:lambdakappc1}, then $c_1' = 1$ and $c_{\gamma}' = m + 2k$. We deduce that $\XC_{{\bc}}(n \delta - k \eta^{(1)}) \cong \ZCB_{c'}(\Gamma_{n - k(k+m)})$ where $c' = (1,m+2k)$.
\end{proof}

\begin{remark}
    We could also apply Proposition~\ref{prop:wbccomp} to compute the parameter $\bc'$ in the proof of Theorem~\ref{thm:quiverleafclosurempos}, thus avoiding the computations with $(s_0 s_1)^k$. Since $\bc(\delta) = -1$ in our setting, Proposition~\ref{prop:wbccomp} shows that 
    \[
    \overline{\LG}_k \cong \XC_{\bc}(n \delta - \beta) \cong \XC_{\bc + \overline{\beta}}((n- k(m+k))\delta)),
    \]
    where $\beta = k \eta^{(1)} = km e_0 + k(m-1) e_1$. Then $\overline{\beta} = (2k,-2k)$ and hence $\bc' = (m+2k-1,-m-2k)$.  
\end{remark}

\begin{thm}\label{thm:Bnminusm}
	If $c_1 = 1$ and $c_{\gamma} = -m$ with $0 \le m < n$ then $\overline{\LG}_k \cong \ZCB_{c'}(\Gamma_{n - k(k+m)})$ where $c_1' = 1$ and $c_{\gamma}' = m+2k$. 
\end{thm}

\begin{proof}
	This is identical to the proof of Theorem~\ref{thm:quiverleafclosurempos}, except that now ${\bc} = (-(m+1),m)$ and 
 \[
 n \delta - k \eta^{(1)} = (n-km) e_0 + (n-k(m+1)) e_1.
 \]
This means that $(n - k(m+k)) \delta = (s_0 s_1)^{k-1} s_0 \star (n \delta - k \eta^{(1)})$ and 
	$$
	{\bc}' := (s_0^* s_1^*)^{k-1} s_0^* (-(m+1),m) = (m + 2k -1, - m - 2k).  
	$$
	since $s_0^*({\bc}) = (m+1, -m - 2)$. Once again, induction shows that the sequence $s_0, s_1, \ds, s_0, s_1, s_0$ is admissible for ${\bc}$.  Therefore, $\XC_{{\bc}}(n \delta - k \eta^{(1)}) \cong \XC_{{\bc}'}((n - k(m+k)) \delta)$. If we write $\bc' = (-c_1' + c_{\gamma}', -c_{\gamma}')$, as in \eqref{eq:lambdakappc1}, then $c_1' = 1$ and $c_{\gamma} = m + 2k$ and thus $c_1 = 1$. We deduce that $\XC_{{\bc}}(n \delta - k \eta^{(1)}) \cong \ZCB_{c'}(\Gamma_{n - k(k+m)})$ where $c' = (1,m+2k)$.
\end{proof}

\begin{thm}
	If $c_1 = 0, c_\gamma = 1$ and $\rho \in \mc{P}(n)$ then $\widetilde{\LG}_{\rho} \cong \ZCB_{c'}(\Z_2 \wr \s(\rho))$, where $c'(t) = 1$ for all reflections $t \in \Z_2^{\ell}$ and $c'(s) = 0$ for all reflections (= transpositions) in $\s(\rho)$.
\end{thm}

\begin{proof}
By \eqref{eq:lambdakappc1}, the parameter ${\bc}$ equals $(-1,1)$. As noted in the proof of Lemma~\ref{lem:singLk}, the semisimple representations $M$ belonging to $\LG_{\rho}$ are of the form $M = M_0 \oplus M_1^{\oplus \rho_1} \oplus \cdots \oplus M_{\ell}^{\oplus \rho_{\ell}}$, where $\dim M_0 = e_{\infty}$ and $\dim M_i = \delta$ otherwise. Since $e_{\infty}$ is a real root, $\XC_{{\bc}}(0)$ is a point. Therefore, Theorem~\ref{thm:quiverleafclosure} says that $	\widetilde{\LG}_{\rho}  \cong \mf{M}_{\bc}(\mathsf{G}(\Gamma),\delta)^{\ell} / \s(\rho)$, where $\ell = \ell(\rho)$. Since ${\bc}_{0}, {\bc}_1 \neq 0$, the quiver variety $\mf{M}_{\bc}(\mathsf{G}(\Gamma),\delta)$ is the generic deformation of the Kleinian singularity $\C^2 / \Z_2$. In other words, $\mf{M}_{{\bc}}(\mathsf{G}(\Gamma),\delta) \cong \ZCB_{c_{\gamma}}(\Z_2)$, where $c_{\gamma} = 1$. It follows that $\mf{M}_{{\bc}}(\mathsf{G}(\Gamma),\delta)^{\ell} / \s(\rho) \cong \ZCB_{c'}(\Z_2 \wr \s(\rho))$, where $c'(t) = 1$ for all reflections $t \in \Z_2^{\ell}$ and $c'(s) = 0$ for all reflections (= transpositions) in $\s(\rho)$. 
\end{proof}


\section*{Index of notation}



\begin{multicols}{2}




	$\Phi$ \ finite (irreducible) simply laced root system \hfill\pageref{rootsystemnotation}

	$\boldsymbol{\Lambda}$ \ root lattice of $\Phi$ \hfill\pageref{rootsystemnotation}

    $\Phi^+$ \ positive roots in $\Phi$ \hfill\pageref{rootsystemnotation}

    $\theta$ \ highest root in $\Phi^+$ \hfill\pageref{rootsystemnotation}

    $W$ \ Weyl group of $\Phi$ \hfill\pageref{sec:anotherpresentation}

    $R$ \ affine simply laced root system \hfill\pageref{rootsystemnotation}

    $R^+$ \ positive roots in $R$ \hfill\pageref{rootsystemnotation}

    $\Delta = \{ e_0, \ds, e_r \}$ \ set of simple roots in $R^+$ \hfill\pageref{rootsystemnotation}

    $\delta$ \ minimal imaginary root in $R$ \hfill\pageref{rootsystemnotation}

    $Q$ \ root lattice for $R$ \hfill\pageref{subs:graphs}

    $W^{\aff}$ \ affine Weyl group \hfill\pageref{rootsystemnotation}

    $F$ \ fundamental region for $\mathsf{G}$ \hfill\pageref{root-sys}

    $\mathsf{G}$ \ graph \hfill\pageref{subs:graphs}

    $\Qu$ \ quiver with underlying graph $\mathsf{G}$ \hfill\pageref{subs:graphs}

    $\mf{M}_{\bc}(\bw,\alpha)$ \ framed quiver variety \hfill\pageref{sec:quivernotation}

    $\mf{M}_{\bc}(\alpha)$ \ unframed ($\bw=0$) quiver variety \hfill\pageref{eq:quivernotation1} 

    $\XC_{\bc}(\alpha)$ \ framed quiver variety with $\bw=\Lambda_0$ \hfill\pageref{eq:quivernotation1} 

    $W_{\mathsf{G}}$ \ Weyl group associated to graph $\mathsf{G}$ \hfill\pageref{subs:graphs}

    $\Gamma$ \ finite subgroup of $SL(2,\C)$ \hfill\pageref{sec:symplc-refl-alg}

    $\mr{P}$\ parabolic subgroup of $\Gamma_n$  \hfill\pageref{sec:paraboliclabel}

    $\s_n$ \ symmetric group on $n$ letters \hfill\pageref{sec:symplc-refl-alg}

    $\Qu^\ell$ \ cyclic quiver of length $\ell$ (infinity linear quiver for $\ell=\infty)$ \hfill\pageref{sec:combinatoricsCM}

    $\Qov^\ell$ \ double quiver for $\Qu^\ell$ \hfill\pageref{sub:quiver-cycl}

    $\Qulinf$\ framed version of $\Qu^\ell$ \hfill\pageref{sub:quiver-cycl}

    $\oQulinf$ \ double quiver for $\Qulinf$ \hfill\pageref{sub:quiver-cycl}

    $\PC$ \ the set of partitions \hfill\pageref{sec:notation}

    $\CC_\ell$ \ the set of $\ell$-cores \hfill\pageref{sec:lcores}

    $\CC_J$ \ the set of $J$-cores \hfill\pageref{sec:Jcore}

    $\Sigma_\bc$ \ the set of dimension vectors of simple representations for the deformed preprojective algebra  \hfill\pageref{root-sys}

    $\Sigma\Sigma_\bc$ \ all possible sums of elements of $\Sigma_\bc$ \hfill\pageref{sec:sympleaf1}

    $E_\bc$ \ framed version of $\Sigma_\bc$ \hfill\pageref{sec:CBtrick}

    $\Hb_c$ \ symplectic reflection algebra  \hfill\pageref{sec:symplc-refl-alg}

    $\ZCB_c$ \ Calogero--Moser variety \hfill\pageref{sec:symplc-refl-alg}

    $\LG$ \ symplectic leaf \hfill\pageref{sec:sympleavesdefn}


\end{multicols}



