It is easy to see that the flower model is mostly affected by the amount of different activity names used in the underlying event log, $\variety$.
We find that all other log complexity measures are unaffected by the amount of different activity names in the event log.

\begin{lemma}
\label{lemma:not-variety-dependent}
Let $\mathcal{C}^L \in \loc \setminus \{\variety\}$ be a log complexity measure.
Then, there are event logs $L_1, L_2$ with $L_1 \sqsubset L_2$ and $\mathcal{C}^L(L_1) < \mathcal{C}^L(L_2)$, but $\variety(L_1) = \variety(L_2)$.
\end{lemma}
\begin{proof}
Consider the following event logs:
\begin{align*}
	L_1 &= [\langle a,b,c,d \rangle^{2}, \langle a,b,c,d,e \rangle^{2}, \langle d,e,a,b \rangle^{2}] \\
	L_2 &= L_1 + [\langle a,b,c,d,e \rangle^{2}, \langle d,e,a,b,c \rangle, \langle c,d,e,a,b \rangle, \langle e,c,d,a,b,c \rangle]
\end{align*}
These two event logs have the following log complexity scores:
\begin{center}
	\begin{tabular}{|c|c|c|c|c|c|c|c|c|c|c|}\hline
		 & $\magnitude$ & $\variety$ & $\support$ & $\tlavg$ & $\tlmax$ & $\levelofdetail$ & $\numberofties$ & $\lempelziv$ & $\numberuniquetraces$ & $\percentageuniquetraces$ \\ \hline
		$L_1$ & $\pad 26 \pad$ & $\pad 5 \pad$ & $\pad 6 \pad$ & $\pad 4.3333 \pad$ & $\pad 5 \pad$ & $\pad 6 \pad$ & $\pad 5 \pad$ & $\pad 13 \pad$ & $\pad 3 \pad$ & $\pad 0.5 \pad$ \\ \hline
		$L_2$ & $\pad 52 \pad$ & $\pad 5 \pad$ & $\pad 11 \pad$ & $\pad 4.7273 \pad$ & $\pad 6 \pad$ & $\pad 23 \pad$ & $\pad 7 \pad$ & $\pad 21 \pad$ & $\pad 6 \pad$ & $\pad 0.5455 \pad$ \\ \hline
	\end{tabular}

	\medskip

	\begin{tabular}{|c|c|c|c|c|c|c|c|c|} \hline
		 & $\structure$ & $\affinity$ & $\deviationfromrandom$ & $\avgdist$ & $\varentropy$ & $\normvarentropy$ & $\seqentropy$ & $\normseqentropy$ \\ \hline
		$L_1$ & $\pad 4.3333 \pad$ & $\pad 0.56 \pad$ & $\pad 0.5757 \pad$ & $\pad 2.6667 \pad$ & $\pad 6.1827 \pad$ & $\pad 0.3126 \pad$ & $\pad 16.0483 \pad$ & $\pad 0.1894 \pad$ \\ \hline
		$L_2$ & $\pad 4.6364 \pad$ & $\pad 0.5829 \pad$ & $\pad 0.6039 \pad$ & $\pad 2.9091 \pad$ & $\pad 29.0428 \pad$ & $\pad 0.4543 \pad$ & $\pad 60.0209 \pad$ & $\pad 0.2921 \pad$ \\ \hline
	\end{tabular}
\end{center}
Thus, all log complexity measures increased, except $\variety$, which is the same for $L_1$ and $L_2$.
Therefore, these event logs show the conjecture for every log complexity measure $\mathcal{C}^L \in \loc \setminus \{\variety\}$. \hfill$\square$
\end{proof}

For two event logs $L_1, L_2$ and their flower models $M_1, M_2$, we can conclude with \cref{lemma:not-variety-dependent} and the discussion above that $M_1$ and $M_2$ differ in their structure if and only if $\variety(L_1) \neq \variety(L_2)$.
Furthermore, we can see that an increase in variety means that the flower model receives a new transition, thus increasing most model complexity scores for the flower model.
If $L_1 \sqsubset L_2$, it is not possible that the model complexity scores of the flower model decrease.

\begin{lemma}
\label{lemma:flower-model-monotone-increasing}
Let $L_1, L_2$ be event logs with $L_1 \sqsubset L_2$. 
Let $M_1, M_2$ be the flower models for $L_1$ and $L_2$. 
Then, $\mathcal{C}^M(M_1) \leq \mathcal{C}^M(M_2)$ for any model complexity measure $\mathcal{C}^M \in \{\size,$ $\crossconn,$ $\controlflow,$ $\separability,$ $\avgconn,$ $\maxconn,$ $\sequentiality,$ $\cyclicity,$ $\netconn\}$.
\end{lemma}
\begin{proof}
Let $L_1, L_2$ be two event logs with $L_1 \sqsubset L_2$.
Then, $\variety(L_1) \leq \variety(L_2)$, since every trace in $L_1$ must be part of $L_2$, and thus, $L_1$ cannot contain any activity names that are not present in $L_2$.
With this observation, we prove $\mathcal{C}^M(M_1) \leq \mathcal{C}^M(M_2)$ for each of the model complexity measures separately.
\begin{itemize}
	\item \textbf{Size $\size$:}
	The flower model of an event log $L$ has exactly $3$ places and exactly $2 + \variety(L)$ transitions.
	Thus, we get
	\begin{align*}
	\size(M_1) = 5 + \variety(L_1) \overset{\variety(L_1) \leq \variety(L_2)}{\leq} 5 + \variety(L_2) = \size(M_2).
	\end{align*}

	\item \textbf{Cross Connectivity $\crossconn$:} 
	Let $M$ be the flower model for an event log $L$ and let $n := \variety(L)$.
	The only connector in the flower model is the place labeled $p$ in \cref{fig:flower-model}.
	Thus, to calculate the cross connectivity of the flower model, this place receives weight $\frac{1}{2n + 2}$, while all other nodes receive weight $1$.
	With this, we can calculate that 
	\[\crossconn(M) = \frac{4 n^4 + 44 n^3 + 143 n^2 + 164 n + 59}{4 (n + 1)^2 (n + 4) (n + 5)}\]
	which is monotonic increasing for increasing $n$, as
	\begin{align*}
	&\frac{\mathrm{d}}{\mathrm{d}n} \left(\frac{4 n^4 + 44 n^3 + 143 n^2 + 164 n + 59}{4 (n + 1)^2 (n + 4) (n + 5)}\right) \\
	= &\frac{389 + 729 n + 575 n^2 + 213 n^3 + 26 n^4}{4 (1 + n)^3 (4 + n)^2 (5 + n)^2} > 0.
	\end{align*}
	Thus, the cross connectivity of te flower model increases when the variety of the underlying event log does.
	Since $\variety(L_1) \leq \variety(L_2)$, we can therefore deduce that $\crossconn(M_1) \leq \crossconn(M_2)$.

	\item \textbf{Control Flow Complexity $\controlflow$:}
	The only connector in the flower model of an event log $L$ is the place labeled $p$ in \cref{fig:flower-model}.
	This place has $\variety(L) + 1$ outgoing edges, so we get
	\begin{align*}
	\controlflow(M_1) = \variety(L_1) + 1 \overset{\variety(L_1) \leq \variety(L_2)}{\leq} \variety(L_2) + 1 = \controlflow(M_2).
	\end{align*}

	\item \textbf{Separability $\separability$:}
	The flower model $M$ for an event log $L$ has exactly three cut-vertices, labeled $p$, $t_1$, and $t_2$ in \cref{fig:flower-model}.
	Since the flower model features $5 + \variety(L)$ nodes in total, we have
	\begin{align*}
	\separability(M_1) = \frac{\variety(L_1)}{\variety(L_1) + 3} \overset{\variety(L_1) \leq \variety(L_2)}{\leq} \frac{\variety(L_2)}{\variety(L_2) + 3} = \separability(M_2)
	\end{align*}
	since, in general, $\frac{x}{y} \leq \frac{x + a}{y + a}$ for any $x, y, a \in \mathbb{R}^+$ with $x \leq y$. 

	\item \textbf{Average Connector Degree $\avgconn$:}
	The only connector in the flower model $M$ for an event log $L$ is the place labeled $p$ in \cref{fig:flower-model}.
	This connector has $\variety(L) + 1$ incoming and $\variety(L) + 1$ outgoing edges, so
	\begin{align*}
	\avgconn(M_1) = 2 \variety(L_1) + 2 \overset{\variety(L_1) \leq \variety(L_2)}{\leq} 2 \variety(L_2) + 2 = \avgconn(M_2).
	\end{align*}

	\item \textbf{Maximum Connector Degree $\maxconn$:}
	The only connector in the flower model $M$ for an event log $L$ is the place labeled $p$ in \cref{fig:flower-model}.
	This connector has $\variety(L) + 1$ incoming and $\variety(L) + 1$ outgoing edges, so
	\begin{align*}
	\maxconn(M_1) = 2 \variety(L_1) + 2 \overset{\variety(L_1) \leq \variety(L_2)}{\leq} 2 \variety(L_2) + 2 = \maxconn(M_2).
	\end{align*}

	\item \textbf{Sequentiality $\sequentiality$:}
	There are exactly $2$ edges in the flower model between non-connector nodes: $(p_i, t_1)$ and $(t_2, p_o)$.
	In total, the flower model contains $2 \cdot \variety(L) + 4$ edges, so
	\begin{align*}
	\sequentiality(M_1) = \frac{2 \cdot \variety(L_1) + 2}{2 \cdot \variety(L_1) + 4} \overset{\variety(L_1) \leq \variety(L_2)}{\leq} \frac{2 \cdot \variety(L_2) + 2}{2 \cdot \variety(L_2) + 4} = \sequentiality(M_2).
	\end{align*}
	since, in general, $\frac{x}{y} \leq \frac{x + a}{y + a}$ for any $x, y, a \in \mathbb{R}^+$ with $x \leq y$.

	\item \textbf{Cyclicity $\cyclicity$:}
	In the flower model $M$ for an event log $L$, exactly $\variety(L) + 1$ nodes lie on a cycle.
	Since there are $5 + \variety(L)$ nodes in total, we have
	\begin{align*}
	\cyclicity(M_1) = \frac{\variety(L_1) + 1}{\variety(L_1) + 3} \overset{\variety(L_1) \leq \variety(L_2)}{\leq} \frac{\variety(L_2) + 1}{\variety(L_2) + 3} = \cyclicity(M_2)
	\end{align*}
	since, in general, $\frac{x}{y} \leq \frac{x + a}{y + a}$ for any $x, y, a \in \mathbb{R}^+$ with $x \leq y$. 

	\item \textbf{Coefficient of Network Connectivity $\netconn$:}
	The flower model for an event log $L$ has $2 \variety(L) + 4$ edges and $5 + \variety(L)$ nodes.
	Therefore
	\begin{align*}
	\netconn(M_1) = \frac{2 \variety(L_1) + 4}{\variety(L_1) + 5} \overset{\variety(L_1) \leq \variety(L_2)}{\leq} \frac{2 \variety(L_2) + 4}{\variety(L_2) + 5}
	\end{align*}
	since, in general, $\frac{x}{y} \leq \frac{x + 2a}{y + a}$ for any $x, y, a \in \mathbb{R}^+$ with $x \leq 2y$, which is true for $x = 2 \variety(L_1) + 4)$ and $y = 5 + \variety(L_1)$.
\end{itemize}
Thus, we showed that $\mathcal{C}^M(M_1) \leq \mathcal{C}^M(M_2)$ for any model complexity measure $\mathcal{C}^M \in \{\size,$ $\crossconn,$ $\controlflow,$ $\separability,$ $\avgconn,$ $\maxconn,$ $\sequentiality,$ $\cyclicity,$ $\netconn\}$. \hfill$\square$
\end{proof}

Next to these monotonic increasing model complexity measures, there are also measures that always return the same complexity score for a flower model.

\begin{lemma}
\label{lemma:flowermodel-constant-complexity}
Let $L_1, L_2$ be event logs and $M_1, M_2$ be the flower models for $L_1$ and $L_2$.
Then, we have $\mathcal{C}^M(M_1) = \mathcal{C}^M(M_2)$ for any model complexity measure $\mathcal{C}^M \in \{\mismatch, \connhet, \tokensplit, \depth, \diameter, \density, \duplicate, \emptyseq\}$.
\end{lemma}
\begin{proof}
Let $L_1, L_2, M_1, M_2$ and $\mathcal{C}^M$ be defined as stated by the lemma. 
We prove $\mathcal{C}^M(M_1) = \mathcal{C}^M(M_2)$ for each of the model complexity measures separately.
\begin{itemize}
	\item \textbf{Connector Mismatch $\mismatch$:}
	The flower model $M$ for an event log $L$ has no connector mismatches:
	The place labeled $p$ in \cref{fig:flower-model} is the only connector in the flower model, and has $\variety(L) + 1$ incoming and outgoing edges.
	Therefore, we have $\mismatch(M) = |(\variety(L) + 1) - (\variety(L) + 1)| = 0$ and thus $\mismatch(M_1) = 0 = \mismatch(M_2)$. 

	\item \textbf{Connector Heterogeneity $\connhet$:}
	The flower model $M$ for an event log $L$ has only one connector, which is the place labeled $p$ in \cref{fig:flower-model}. 
	Thus, every flower model has only one type of connector, leading to the complexity score $\connhet(M) = 1 \cdot \log_2(1) + 0 \cdot \log_2(0) = 0$.
	Therefore, $\connhet(M_1) = 0 = \connhet(M_2)$.

	\item \textbf{Token Split $\tokensplit$:}
	All transitions in the flower model $M$ for an event log have exactly one outgoing edge, so $\tokensplit(M) = 0$, and thus $\tokensplit(M_1) = 0 = \tokensplit(M_2)$.

	\item \textbf{Depth $\depth$:}
	In the flower model $M$ for an event log $L$, all nodes have depth $1$ since a path from $p_i$ or to $p_o$ must always contain the connector $p$, which is a split node and a join node.
	Thus, $\depth(M) = 1$ for any flower model $M$, so $\depth(M_1) = 1 = \depth(M_2)$.

	\item \textbf{Diameter $\diameter$:}
	The only simple path in the flower model $M$ for an event log is $(p_i, t_1, p, t_2, p_o)$.
	Therefore, the longest simple path in $M$ is always $\depth(M) = 5$.
	In turn, we have $\depth(M_1) = 5 = \depth(M_2)$.

	\item \textbf{Density $\density$:}
	The flower model $M$ for an event log $L$ always has exactly $2 \variety(L) + 4$ edges, $3$ places, and $\variety(L) + 2$ transitions.
	Thus, its density score is $\density(M) = \frac{2(\variety(L) + 2)}{2 \cdot (\variety(L) + 2) \cdot (3 - 1)} = \frac{1}{2}$, so $\density(M_1) = \frac{1}{2} = \density(M_2)$.

	\item \textbf{Number of Duplicate Tasks $\duplicate$:}
	The flower model $M$ for an event log contains one transition for each activity in the event log, as well as two $\tau$-transitions.
	Therefore, the only duplicate label in $M$ is the second $\tau$-label, leading to $\duplicate(M) = 1$.
	In turn, $\duplicate(M_1) = 1 = \duplicate(M_2)$.

	\item \textbf{Number of Empty Sequence Flows $\emptyseq$:}
	Since the flower model $M$ for an event log contains no parallel splits or joins, there cannot be any empty sequence flows in the flower model.
	Therefore, $\emptyseq(M) = 0$ for any flower model $M$, and thus $\emptyseq(M_1) = 0 = \emptyseq(M_2)$.
\end{itemize}
Thus, we showed that $\mathcal{C}^M(M_1) = \mathcal{C}^M(M_2)$ for any model complexity measure $\mathcal{C}^M \in \{\mismatch,$ $\connhet,$ $\tokensplit,$ $\depth,$ $\diameter,$ $\density,$ $\duplicate,$ $\emptyseq\}$. \hfill$\square$
\end{proof}

