The fact that the complexity of the trace net is not dependent on the variety $\variety$ already shows that different mining algorithms require different log complexity measures to predict the complexity of their results.
For our analysis of the trace net, we first observe that some of its model complexity scores  must increase if more behavior is added to the underlying event log.
To avoid edge cases or trace nets where some complexity measures are undefined, we require for this entire subsection that $|supp(L)| > 1$ for any event log $L$. 
We allow this restriction, as event logs with just a single trace rarely occur in practice.

\begin{lemma}
\label{lemma:tracenet-monotone-increasing}
Let $L_1, L_2$ be event logs with $L_1 \sqsubset L_2$ and $|supp(L_1)| > 1$.
Let $M_1, M_2$ be the trace nets for $L_1$ and $L_2$. 
Then, $\mathcal{C}^M(M_1) \leq \mathcal{C}^M(M_2)$ for any model complexity measure $\mathcal{C}^M \in \{\size, \controlflow, \avgconn, \maxconn, \diameter, \duplicate\}$.
\end{lemma}
\begin{proof}
Let $L_1, L_2$ be two event logs with $L_1 \sqsubset L_2$. 
With this, we then know that $support(L_1) \subseteq support(L_2)$, since every unique trace in $L_1$ must also be present in $L_2$.
We abbreviate this observation by $(\star)$, and prove $\mathcal{C}^M(M_1) \leq \mathcal{C}^M(M_2)$ for each of the model complexity measures separately.
\begin{itemize}
	\item \textbf{Size $\size$:}
	The trace net contains the places $p_i$ and $p_o$, as well as a path of places and transitions for each trace of the event log.
	This means, in a trace net $M$ for an event log $L$, there are $\sum_{\sigma \in L} |\sigma|$ transitions and $2 + \sum_{\sigma \in L} (|\sigma| - 1)$ places.
	Thus, $\size(M) = 2 + \sum_{\sigma \in L} (2 |\sigma| - 1)$.
	Since $supp(L_1) \subseteq supp(L_2)$, this means:
	\begin{align*}
	\size(M_1) = 2 + \sum_{\sigma \in L_1} (2|\sigma| - 1) \overset{(\star)}{\leq} 2 + \sum_{\sigma \in L_2} (2|\sigma| - 1) = \size(M_2).
	\end{align*}

	\item \textbf{Control Flow Complexity $\controlflow$:}
	The only connector nodes in the trace net are $p_i$ and $p_o$.
	The node $p_i$ is a \texttt{xor}-split, while $p_o$ is a \texttt{xor}-join.
	In a trace net $M$ for an event log $L$, $p_i$ has $|supp(L)|$ outgoing edges, so we have $\controlflow(M) = |supp(L)|$, which means:
	\begin{align*}
	\controlflow(M_1) = |supp(L_1)| \overset{(\star)}{\leq} |supp(L_2)| = \controlflow(M_2).
	\end{align*}

	\item \textbf{Average Connector Degree $\avgconn$:}
	The only connector nodes in the trace net are $p_i$ and $p_o$.
	In a trace net $M$ for an event log $L$, $p_i$ and $p_o$ both have degree $|supp(L)|$, so $\avgconn(M) = \frac{1}{2} \cdot 2 \cdot |supp(L)| = |supp(L)|$, so we get:
	\begin{align*}
	\avgconn(M_1) = |supp(L_1)| \overset{(\star)}{\leq} |supp(L_2)| = \avgconn(M_2).
	\end{align*}

	\item \textbf{Maximum Connector Degree $\maxconn$:}
	The only connector nodes in the trace net are $p_i$ and $p_o$.
	In a trace net $M$ for an event log $L$, $p_i$ and $p_o$ both have degree $|supp(L)|$, so $\maxconn(M) = |supp(L)|$, leading to:
	\begin{align*}
	\maxconn(M_1) = |supp(L_1)| \overset{(\star)}{\leq} |supp(L_2)| = \maxconn(M_2).
	\end{align*}

	\item \textbf{Diameter $\diameter$:}
	In the trace net $M$ for an event log $L$, every trace $\sigma \in L$ creates a unique path $(p_i, \sigma(1), \dots, \sigma(|\sigma|), p_o)$ of length $2 \cdot |\sigma| + 1$.
	Thus, the length of the longest path in $M$ is $\diameter(M) = 2 \tlmax(L) + 1$.
	Since all traces in $L_1$ are also present in $L_2$, this means:
	\begin{align*}
	\diameter(M_1) = 2 \tlmax(L_1) + 1 \overset{(\star)}{\leq} 2 \tlmax(L_2) + 1 = \diameter(M_2).
	\end{align*}

	\item \textbf{Number of Duplicate Tasks $\duplicate$:}
	The number of duplicate tasks in the trace net $M$ for an event log $L$ is exactly the amount of activity name repetitions in the support of the event log $L$.
	Since $supp(L_1) \subseteq supp(L_2)$, this amount of repetitions can only be higher in $L_2$ than in $L_1$, so we get $\duplicate(M_1) \leq \duplicate(M_2)$.
\end{itemize}
Thus, we showed that $\mathcal{C}^M(M_1) \leq \mathcal{C}^M(M_2)$ for any model complexity measure $\mathcal{C}^M \in \{\size, \controlflow, \avgconn, \maxconn, \diameter, \duplicate\}$. \hfill$\square$
\end{proof}

Like for the flower model, there are some model complexity measures that always return the same value for a trace net. 
We will investigate these complexity measures in the next Lemma.

\begin{lemma}
\label{lemma:tracenet-constant-complexity}
Let $L_1, L_2$ be event logs and $M_1, M_2$ be the trace nets for $L_1$ and $L_2$.
Then, $\mathcal{C}^M(M_1) = \mathcal{C}^M(M_2)$, where $\mathcal{C}^M \in \{\mismatch, \connhet, \tokensplit, \separability, \depth, \cyclicity, \emptyseq\}$.
\end{lemma}
\begin{proof}
Let $L_1, L_2, M_1, M_2$ and $\mathcal{C}^M$ be defined as stated by the theorem.
We prove $\mathcal{C}^M(M_1) = \mathcal{C}^M(M_2)$ for each of the model complexity measures separately:
\begin{itemize}
	\item \textbf{Connector Mismatch $\mismatch$:}
	The trace net $M$ for an event log $L$ contains exactly two connectors: $p_i$ and $p_o$.
	$p_i$ has exactly $|supp(L)|$ outgoing edges, and $p_o$ has exactly $|supp(L)|$ incoming arcs, so its connector mismatch score is $\mismatch(M) = \left| |supp(L)| - |supp(L)| \right| = 0$.
	Therefore, we have that $\mismatch(M_1) = 0 = \mismatch(M_2)$.

	\item \textbf{Connector Heterogeneity $\connhet$:}
	The trace net $M$ for an event log $L$ has only the connectors $p_i$ and $p_o$. 
	Both of these connectors are \texttt{xor}-connectors, so $\connhet(M) = - (1 \cdot \log_2(1) + 0 \cdot \log_2(0)) = 0$.
	In turn, we know that $\connhet(M_1) = 0 = \connhet(M_2)$.

	\item \textbf{Token Split $\tokensplit$:}
	Every transition in the trace net $M$ for an event log $L$ has exactly one incoming and one outgoing edge.
	Therefore, there are no transitions in $M$ with more than one outgoing edge, leading to $\tokensplit(M) = 0$.
	Therefore, we get $\tokensplit(M_1) = 0 = \tokensplit(M_2)$.

	\item \textbf{Separability $\separability$:}
	Since we require $|supp(L_1)| > 1$, we know that $M_1$ does not contain any cut-vertices.
	$M_2$ also does not contain any cut-vertices, as $|supp(L_2)| \geq |supp(L_1) > 1$.
	Therefore, $\separability(M_1) = 1 = \separability(M_2)$.

	\item \textbf{Depth $\depth$:}
	In the trace net $M$ for an event log $L$, all nodes except $p_i$ and $p_o$ have in- and out-depth $1$, since $p_i$ and $p_o$ are connectors.
	$p_i$ and $p_o$ themselves, on the other hand, both have in- and out-depth $0$.
	Therefore, $\depth(M) = 1$ and, consequently, $\depth(M_1) = 1 = \depth(M_2)$.

	\item \textbf{Cyclicity $\cyclicity$:}
	The trace net $M$ for an event log $L$ does not contain any cycles, so $\cyclicity(M) = 0$.
	In turn, $\cyclicity(M_1) = 0 = \cyclicity(M_2)$.

	\item \textbf{Number of Empty Sequence Flows $\emptyseq$:}
	In the trace net $M$ for an event log $L$, every transition has exactly one incoming and one outgoing edge.
	Therefore, there are no \texttt{and}-connectors in $M$, which means $\emptyseq(M) = 0$.
	Consequently, $\emptyseq(M_1) = 0 = \emptyseq(M_2)$.
\end{itemize}
Thus, we showed that $\mathcal{C}^M(M_1) = \mathcal{C}^M(M_2)$ for any model complexity measure $\mathcal{C}^M \in \{\mismatch, \connhet, \tokensplit, \separability, \depth, \cyclicity, \emptyseq\}$. \hfill$\square$
\end{proof}

