\begin{theorem}
\label{theo:tracenet-leq-entries}
$(\mathcal{C}^L, \mathcal{C}^M) \in \mleq$ for any log cmplexity measure $\mathcal{C}^L \in \{\magnitude, \support,$ $\tlavg, \lempelziv, \structure, \affinity, \deviationfromrandom, \avgdist,\seqentropy, \normseqentropy\}$ and a model complexity measure $\mathcal{C}^M \in \{\size, \controlflow, \avgconn, \maxconn\}$.
\end{theorem}
\begin{proof}
Let $L_1, L_2,$ be event logs with $L_1 \sqsubset L_2$ and $|supp(L_1)| > 1$, and $M_1, M_2$ be the trace nets for $L_1$ and $L_2$.
By \cref{lemma:tracenet-monotone-increasing}, we know that $L_1 \sqsubset L_2$ and $|supp(L_1)| > 1$ implies $\mathcal{C}^M(M_1) \leq \mathcal{C}^M(M_2)$.
We now need to show that both $\mathcal{C}^M(M_1) < \mathcal{C}^M(M_2)$ and $\mathcal{C}^M(M_1) = \mathcal{C}^M(M_2)$ are possible.
For the former, take the following event logs:
\begin{align*}
	L_1 &= [\langle a,b,c \rangle, \langle a,b,c,d \rangle^{2}, \langle a,b,c,d,e \rangle^{2}, \langle d,e,a,b \rangle] \\
	L_2 &= L_1 + [\langle a,b,c,d,e,f \rangle, \langle a,a,b,c,d,e,f \rangle, \langle a,b,c,d,e,a,b \rangle]
\end{align*}
These two event logs have the following log complexity scores:
