\begin{theorem}
\label{theo:tracnet-less-entries}
Let $\mathcal{C}^M \in \{\size, \controlflow, \avgconn, \maxconn\}$ be a model complexity measure and let $\mathcal{C}^L \in \{\variety, \tlmax, \levelofdetail, \numberofties, \numberuniquetraces, \percentageuniquetraces, \varentropy, \normvarentropy\}$ and be a log complexity measure.
Then, $(\mathcal{C}^L, \mathcal{C}^M) \in \mless$.
\end{theorem}
\begin{proof}
Let $\mathcal{C}^L$ be a log complexity measure and $\mathcal{C}^M$ a model complexity measure allowed by this theorem.
Furthermore, let $L_1 \sqsubset L_2$ be event logs and $M_1, M_2$ their respective trace nets.
In this proof, we first show that $\mathcal{C}^L(L_1) < \mathcal{C}^L(L_2)$ implies $supp(L_1) \subsetneq supp(L_2)$ for all allowed log complexity measures.
\begin{itemize}
	\item \textbf{Variety $\variety$:}
	Suppose $\variety(L_1) < \variety(L_2)$.
	Since $L_1 \sqsubset L_2$, we know that $supp(L_1) \subseteq supp(L_2)$.
	What remains to be shown is $supp(L_1) \neq supp(L_2)$.
	By definition of $\variety$, and since $\variety(L_1) < \variety(L_2)$, there must be an activity name $a$ that occurs in $L_2$, but not in $L_1$.
	This is only possible if there is a trace $\sigma$, such that there is a $i \in \{1, \dots, |\sigma|\}$ with $\sigma(i) = a$, and such that $\sigma \in supp(L_2) \setminus supp(L_1)$.
	Thus, $supp(L_2) \setminus supp(L_1) \neq \emptyset$, and we get $supp(L_1) \neq supp(L_2)$.

	\item \textbf{Maximum Trace Length $\tlmax$:}
	Suppose $\tlmax(L_1) < \tlmax(L_2)$.
	Since $L_1 \sqsubset L_2$, we know that $supp(L_1) \subseteq supp(L_2)$.
	What remains to be shown is $supp(L_1) \neq supp(L_2)$.
	Since the length of the longest trace in $L_2$ is longer than the length of the longest trace in $L_1$, there must be a trace $\sigma \in supp(L_2) \setminus supp(L_1)$ with $|\sigma| > |\rho|$ for all $\rho \in L_1$.
	Thus, we know that $supp(L_2) \setminus supp(L_1) \neq \emptyset$, and therefore $supp(L_1) \neq supp(L_2)$.

	\item \textbf{Level of Detail $\levelofdetail$:}
	Suppose $\levelofdetail(L_1) < \levelofdetail(L_2)$.
	Since $L_1 \sqsubset L_2$, we know that $supp(L_1) \subseteq supp(L_2)$ is true.
	What remains to be shown is $supp(L_1) \neq supp(L_2)$.
	By definition of $\levelofdetail$, since $\levelofdetail(L_1) < \levelofdetail(L_2)$, the DFG of~$L_2$ contains at least one path that is not present in the DFG of~$L_1$.
	But this is only possible if there is at least one edge $(a,b)$ in the DFG of~$L_2$ that is not part of the DFG of~$L_1$.
	By construction of the directly follows graph, this means $a >_{L_2} b$, but $a \not>_{L_1} b$.
	Thus, a $\sigma \in supp(L_2) \setminus supp(L_1)$ must exist with $\sigma(i) = a$ and $\sigma(i+1) = b$ for some $i \in \{1, \dots |\sigma|-1\}$.
	Therefore, $supp(L_2) \setminus supp(L_1) \neq \emptyset$, and we get that $supp(L_1) \neq supp(L_2)$.

	\item \textbf{Number of Ties $\numberofties$:}
	Suppose that $\numberofties(L_1) < \numberofties(L_2)$.
	Since $L_1 \sqsubset L_2$, we know $supp(L_1) \subseteq supp(L_2)$.
	What remains to be shown is $supp(L_1) \neq supp(L_2)$.
	Since $\numberofties(L_1) < \numberofties(L_2)$, there are activity names $a,b$ with $a >_{L_2} b$ but $a \not>_{L_1} b$ or $b >_{L_1} a$.
	Since adding behavior to an event log cannot remove any direct neighborhoods of activities, we know that $a \not>_{L_1}$ is true.
	Then, there must be a trace $\sigma \in supp(L_2) \setminus supp(L_1)$ with $\sigma(i) = a$ and $\sigma(i+1) = b$ for some $i \in \{1, \dots |\sigma|-1\}$.
	Therefore, $supp(L_2) \setminus supp(L_1) \neq \emptyset$, and we get $supp(L_1) \neq supp(L_2)$.

	\item \textbf{Number of Distinct Traces $\numberuniquetraces$:}
	Suppose $\numberuniquetraces(L_1) < \numberuniquetraces(L_2)$.
	Since $L_1 \sqsubset L_2$, we know $supp(L_1) \subseteq supp(L_2)$.
	What remains to be shown is $supp(L_1) \neq supp(L_2)$.
	Since $\numberuniquetraces(L_1) < \numberuniquetraces(L_2)$, we know by definition that $|supp(L_1)| < |supp(L_2)|$.
	Thus, $supp(L_1) \neq supp(L_2)$ must be true.

	\item \textbf{Percentage of Distinct Traces $\percentageuniquetraces$:}
	Let $\percentageuniquetraces(L_1) < \percentageuniquetraces(L_2)$.
	Since $L_1 \sqsubset L_2$, we know $supp(L_1) \subseteq supp(L_2)$.
	What remains to be shown is $supp(L_1) \neq supp(L_2)$.
	Since $\percentageuniquetraces(L_1) < \percentageuniquetraces(L_2)$, we know by definition that $\frac{|supp(L_1)|}{\sum_{\sigma \in L_1} L_1(\sigma)} < \frac{|supp(L_2)|}{\sum_{\sigma \in L_2} L_2(\sigma)}$.
	But since $L_1 \sqsubset L_2$, we know that the inequality $\sum_{\sigma \in L_1} L_1(\sigma) < \sum_{\sigma \in L_2} L_2(\sigma)$ is true.
	Thus, the previous inequality can only be true if $|supp(L_1)| < |supp(L_2)|$, so $supp(L_1) \neq supp(L_2)$.

	\item \textbf{Variant Entropy $\varentropy$:}
	Suppose $\varentropy(L_1) < \varentropy(L_2)$.
	Since $L_1 \sqsubset L_2$, we know that $supp(L_1) \subseteq supp(L_2)$.
	What remains to be shown is that $supp(L_1) \neq supp(L_2)$.
	Since $\varentropy(L_1) < \varentropy(L_2)$, we know by definition that there must be a node in the prefix automaton of $L_2$ that is not present in the prefix automaton of $L_1$.
	In turn, a trace $\sigma \in supp(L_2) \setminus supp(L_1)$ must exist that deviates from all traces in $L_1$ after a (possibly empty) common prefix.
	Since $supp(L_2) \setminus supp(L_1) \neq \emptyset$, $supp(L_1) \neq supp(L_2)$.

	\item \textbf{Normalized Variant Entropy $\normvarentropy$:}
	Since $|S| \cdot \ln(|S|)$ can only increase for larger event logs, $\normvarentropy(L_1) < \normvarentropy(L_2)$ directly implies that $\varentropy(L_1) < \varentropy(L_2)$.
	But as we have already seen, the latter implies $supp(L_1) \neq supp(L_2)$.
\end{itemize}
Since the trace net $M$ for an event log $L$ includes a unique path for each trace in $supp(L)$, we can quickly verify that $\mathcal{C}^M(M_1) < \mathcal{C}^M(M_2)$ if $supp(L_1) \neq supp(L_2)$, where $\mathcal{C}^M \in \{\size, \controlflow, \avgconn, \maxconn\}$. \hfill$\square$
\end{proof}

\begin{theorem}
\label{theo:tracenet-equals-entries}
Let $\mathcal{C}^L \in \loc$ be any log complexity measure and $\mathcal{C}^M$ be a model complexity measure with $\mathcal{C}^M \in \{\mismatch, \connhet, \tokensplit, \separability, \depth, \cyclicity, \emptyseq\}$.
Then, we have $(\mathcal{C}^L, \mathcal{C}^M) \in \meq$.
\end{theorem}
\begin{proof}
By \cref{lemma:tracenet-constant-complexity}, $\mathcal{C}^M(M_1) = \mathcal{C}^M(M_2)$ for any trace nets $M_1, M_2$.
Therefore, the implication $\mathcal{C}^L(L_1) < \mathcal{C}^L(L_2) \Rightarrow \mathcal{C}^M(M_1) = \mathcal{C}^M(M_2)$ is true for all event logs $L_1, L_2$, where $M_1, M_2$ are the trace nets for $L_1, L_2$. \hfill$\square$
\end{proof}

