\begin{theorem}
\label{theo:tracenet-density-greater-entries}
Let $\mathcal{C}^L \in \{\tlmax, \numberofties\}$ be a log complexity measure.
Then, $(\mathcal{C}^L, \density) \in \mgreater$.
\end{theorem}
\begin{proof}
As argued in the proof of \cref{theo:tracenet-density-geq-entries}, the density of a trace net $M$ for an event log $L$ is $\density(M) = \frac{1}{1 + \sum_{\sigma \in L} (|\sigma| - 1)}$.
Thus, the density of $M$ lowers if $1 + \sum_{\sigma \in L} (|\sigma| - 1)$ increases.
\begin{itemize}
	\item \textbf{Maximum Trace Length $\tlmax$:}
	Let $L_1, L_2$ be two event logs with $L_1 \sqsubset L_2$ and $\tlmax(L_1) < \tlmax(L_2)$.
	Then, there must be a trace $\sigma \in supp(L_2) \setminus supp(L_1)$ with $|\sigma| > 2$, since all traces in $L_1$ have length at least $1$.
	But then, $|\sigma| - 1 \geq 1$ and therefore
	\begin{align*}
	1 + \sum_{\sigma \in L_1} (|\sigma| - 1) < 1 + \sum_{\sigma \in L_2} (|\sigma| - 1).
	\end{align*}

	\item \textbf{Number of Ties $\numberofties$:}
	Let $L_1, L_2$ be two event logs with $L_1 \sqsubset L_2$ and $\numberofties(L_1) < \numberofties(L_2)$.
	Then, there must be two activity names $a, b$ with $a >_{L_2} b$ and $b \not>_{L_2} a$, but with $a \not>_{L_1} b$ or $b >_{L_1} a$.
	Since $L_1 \sqsubset L_2$ and $b \not>_{L_2} a$, out of the latter two, only $a \not>_{L_1} b$ can be true.
	In turn, there must be a trace $\sigma \in supp(L_2) \setminus supp(L_1)$ with $\sigma(i) = a$ and $\sigma(i+1) = b$ for some $i \in \{1, \dots, |\sigma| - 1\}$.
	But then, $|\sigma| \geq 2$ and therefore $|\sigma| - 1 \geq 1$, so
	\begin{align*}
	1 + \sum_{\sigma \in L_1} (|\sigma| - 1) < 1 + \sum_{\sigma \in L_2} (|\sigma| - 1).
	\end{align*}
\end{itemize}
Thus, for any event logs $L_1, L_2$ and their trace nets $M_1, M_2$, we have shown that
$\tlmax(L_1) < \tlmax(L_2) \Rightarrow \density(M_1) > \density(M_2)$ and, similarly, $\numberofties(L_1) < \numberofties(L_2) \Rightarrow \density(M_1) > \density(M_2)$. \hfill$\square$
\end{proof}

