For the remainder of this subsection, we will analyze the model complexity of the trace net in more depth and characterize the model complexity scores of the trace net by using log complexity measures.
Since many complexity scores for the trace net are dependent of the amount of places in the trace net, we define 
\[\mathcal{N}(L) := \sum_{\sigma \in L} (|\sigma| - 1)\]
for an event log $L$ as the total number of neighborhoods in distinct traces of $L$.
Since two transitions in the trace net are connected via a place, the total amount of places in the trace net is $2 + \mathcal{N}(L)$.
We need to increase $\mathcal{N}(L)$ by two for the initial place $p_i$ and the final place $p_o$.
With this notion, we can now analyze the model complexity scores of the trace net $M$ for an event log $L$ over a set of activities $A$.

\begin{itemize}
	\item \textbf{Size $\size$:}
	As argued before, the trace net contains $2 + \mathcal{N}(L)$ places.
	Furthermore, it contains $\sum_{\sigma \in L} |\sigma|$ transitions.
	Thus, we have:
	\begin{align*}
	\size(M) &= 2 + \sum_{\sigma \in L} (2|\sigma| + 1) = 2 + \left(\sum_{\sigma \in L} 2(|\sigma| - 1)\right) + |supp(L)| \\
	&= 2 + 2\mathcal{N}(L) + \numberuniquetraces(L)
	\end{align*}

	\item \textbf{Connector Mismatch $\mismatch$:}
	If $|supp(L)| = 1$, there are no connectors in $M$ and $\mismatch(M) = 0$.
	Otherwise, the only connectors in $M$ are $p_i$ and $p_o$.
	The place $p_i$ has $|supp(L)|$ outgoing, while the place $p_o$ has $|supp(L)|$ incoming edges.
	Thus, we get $\mismatch(M) = \left| |supp(L)| - |supp(L)| \right| = 0$.

	\item \textbf{Connector Heterogeneity $\connhet$:}
	If $|supp(L)| = 1$, there are no connectors in $M$ and $\connhet$ is undefined.
	Otherwise, the only connectors in $M$ are $p_i$ and $p_o$.
	Both of these connectors are \texttt{xor}-connectors, so we get the connector heterogeneity score $\connhet(M) = - \left(1 \cdot \log_2(1) + 0 \cdot \log_2(0)\right) = 0$.

	\item \textbf{Cross Connectivity $\crossconn$:}
	For readability, let $n := |supp(L)|$. 
	There are only two nodes in $M$ that have a weight $\neq 1$: $p_i$ and $p_o$.
	This results in only the edges leaving $p_i$ and the edges entering $p_o$ having weight $\frac{1}{n}$, while all other edges in $M$ have weight $1$.
	Thus, or the connection values in the trace net $M$, we get:
	\begin{itemize}
		\item $V(p_i, x) = \frac{1}{n}$ for all nodes $x$ of $M$ with $x \neq p_i$ and $x \neq p_o$,
		\item $V(p_i, p_o) = \frac{1}{n^2}$,
		\item Let $\sigma \in L$ be a trace and $i \in \{1, \dots, |\sigma|\}$. 
		Then, the transition for $\sigma(i)$ has $|\sigma| - i$ times the value $1$ with succeeding transitions, $|\sigma| - 1$ times value $1$ with succeeding places except $p_o$, and value $\frac{1}{n}$ with the place $p_o$.
		\item Let $\sigma \in L$ be a trace and $i \in \{1, \dots, |\sigma|\}$. 
		Then, the place $p_{\sigma(i)}$ in the postset of the transition for $\sigma(i)$ has $|\sigma| - i$ times the value $1$ with succeeding transitions, $|\sigma| - i - 1$ times the value $1$ with succeeding places except $p_o$, and value $\frac{1}{n}$ with the place $p_o$. 
	\end{itemize}
	Since all other connections have value $0$, we get, for the sum of these values:
	\begin{align*}
	&\frac{1}{n^2} + \sum_{\sigma \in L} \left(\sum_{i = 1}^{|\sigma|} \left(2 (|\sigma| - i) + \frac{2}{n}\right) + \sum_{j = 1}^{|\sigma|-1} \left(2\left(|\sigma| - j\right) - 1 + \frac{2}{n}\right)\right) \\
	=\: &\frac{1}{n^2} + \sum_{\sigma \in L} \frac{(2|\sigma| - 1) \cdot (n(|\sigma| - 1) + 2)}{n} \\
	=\: &\frac{1}{n} \cdot \left(\frac{1}{n} + \sum_{\sigma \in L} (2|\sigma| - 1) \cdot (n(|\sigma| - 1) + 2)\right) \\
	=\: &\frac{1}{n} \cdot \left(\frac{1}{n} + n \cdot \sum_{\sigma \in L} (2|\sigma| - 1) \cdot \left(|\sigma| - 1 + \frac{2}{n}\right)\right)
	\end{align*}
	In turn, the cross connectivity of the trace net is:
	\[\crossconn(M) = 1 - \frac{\frac{1}{n^2} + \sum_{\sigma \in L} (2|\sigma| - 1) \cdot \left(|\sigma| - 1 + \frac{2}{n}\right)}{\left(2 + 2\mathcal{N}(L) + \numberuniquetraces(L)\right) \cdot \left(1 + 2\mathcal{N}(L) + \numberuniquetraces(L))\right)}\]

	\item \textbf{Token Split $\tokensplit$:}
	Since every transition in $M$ has exactly one incoming and one outgoing edge, it contains no \texttt{and}-splits.
	Therefore, $\tokensplit(M) = 0$.

	\item \textbf{Control Flow Complexity $\controlflow$:}
	If $|supp(L)| = 1$, the trace net $M$ does not contain any connectors, and thus $\controlflow(M) = 0$.
	Otherwise, the only connector nodes in $M$ are $p_i$ and $p_o$.
	$p_i$ is an \texttt{xor}-split and $p_o$ an \texttt{xor}-join, so $\controlflow(M) = |\post{p_i}| = |supp(L)| = \numberuniquetraces(L)$.

	\item \textbf{Separability $\separability$:}
	If $|supp(L)| = 1$, every node in $M$ except $p_i$ and $p_o$ is a cut-vertex, so $\separability(M) = 0$.
	Otherwise, $M$ does not contain any cut-vertices, so $\separability(M) = 1$.

	\item \textbf{Average Connector Degree $\avgconn$:}
	If $|supp(L)| = 1$, the trace net $M$ contains no connectors and thus, the average connector degree is undefined.
	Otherwise, only the places $p_i$ and $p_o$ are connectors in $M$.
	Both places have degree $|supp(L)|$, so the average connector degree of the trace net is $\avgconn(M) = \frac{|supp(L)| + |supp(L)|}{2} = |supp(L)| = \numberuniquetraces(L)$.

	\item \textbf{Maximum Connector Degree $\maxconn$:}
	If $|supp(L)| = 1$, the trace net $M$ contains no connectors and thus, the maximum connector degree is undefined.
	Otherwise, only the places $p_i$ and $p_o$ are connectors in $M$.
	Both places have degree $|supp(L)|$, so the maximum connector degree of the trace net is $\maxconn(M) = |supp(L)| = \numberuniquetraces(L)$.

	\item \textbf{Sequentiality $\sequentiality$:}
	If $|supp(L)| = 1$, the trace net $M$ contains no connectors and thus, every edge in $M$ connects two non-connector nodes, leading to $\sequentiality(M) = 0$.
	Otherwise, only the edges leaving $p_i$ or entering $p_o$ have a connector node at their head or tail.
	Since $M$ contains $2|T|$ edges in total, we get $\sequentiality(M) = 1 - \frac{2|T| - 2|supp(L)|}{2|T|} = \frac{2|supp(L)|}{2|T|} = \frac{\numberuniquetraces(L)}{\mathcal{N}(L) + \numberuniquetraces(L)}$.

	\item \textbf{Depth $\depth$:}
	If $|supp(L)| = 1$, there trace net $M$ does not contain any connectors, and thus, the in- and out-depth of every node in $M$ is $0$, leading to $\depth(M) = 0$.
	Otherwise, every node except $p_i$ and $p_o$ have in- and out-depth $1$, while $p_i$ and $p_o$ have in- and out-depth $0$.
	Thus, $\depth(M) = \max\{0,1\} = 1$.

	\item \textbf{Diameter $\diameter$:}
	The diameter of the trace net $M$ is dependent on the length of the longest trace in $L$.
	Let $\sigma \in L$ be a trace with maximum length in $L$.
	Then, one of the paths through the trace net $M$ with maximal length is the path $(p_i, \sigma(1), p_{\sigma(1)}, \sigma(2), \dots, p_{|\sigma|-1}, \sigma(|\sigma|), p_o)$, where $p_{\sigma(i)}$ is the place in the postset of the transition for $\sigma(i)$ for any $i \in \{1, \dots, |\sigma\}$. 
	The length of this path is $\diameter(M) = 1 + 2 \max\{|\sigma| \mid \sigma \in L\} = 1 + 2 \cdot \tlmax(L)$.

	\item \textbf{Cyclicity $\cyclicity$:}
	The trace net $M$ does not introduce any cycles, so it has no nodes that lie on such cycles.
	Therefore, $\cyclicity(M) = 0$.

	\item \textbf{Coefficent of Network Connectivity $\netconn$:}
	Since by construction, every transition in $M$ has exactly one incoming and one outgoing edge, $M$ contains $2|T|$ edges in total.
	Thus, $\netconn(M) = \frac{2|T|}{|P| + |T|} = \frac{2(\mathcal{N}(L) + \numberuniquetraces(L))}{2 + 2 \mathcal{N}(L) + \numberuniquetraces(L)}$.

	\item \textbf{Density $\density$:}
	Since by construction, every transition in $M$ has exactly one incomin and one outgoing edge, $M$ contains $2|T|$ edges in total.
	Thus, $\density(M) = \frac{2|T|}{2|T|(|P| - 1)} = \frac{1}{|P| - 1} = \frac{1}{1 + \mathcal{N}(L)}$.

	\item \textbf{Number of Duplicate Tasks $\duplicate$:}
	The number of duplicate tasks in the trace net $M$ is exactly the amount of event name repetitions in the support of the event log $L$.
	Thus, $\duplicate(M) = \sum_{a \in A} (|\{(i,j) \mid \sigma_i \in L: \sigma_i(j) = a\}| - 1)$.

	\item \textbf{Number of Empty Sequence Flows $\emptyseq$:}
	Since the trace net $M$ does not contain any \texttt{and}-connectors, the number of empty sequence flows in $M$ is $\emptyseq(M) = 0$ by definition.
\end{itemize}
These findings conclude our analysis of the trace net miner.
