\begin{theorem}
\label{theo:alphaminer-duplicate-entries}
$(\mathcal{C}^L, \duplicate) \in \meq$ for any log complexity measure $\mathcal{C}^L \in \loc$.
\end{theorem}
\begin{proof}
The alpha miner constructs exactly one transition for each activity name in the event log.
Since no other transitions are constructed by the algorithm, a model $M$ found by the alpha algorithm always has $\duplicate(M) = 0$. \hfill$\square$
\end{proof}

Except for $\duplicate$, none of the complexity scores of models found by the alpha miner can be described with current log complexity measures.
This is because the structure of these models highly depend on the set $Y_L$, which is not covered by current log complexity measures.
In fact, a model $M$ constructed by the alpha miner for an event log $L$ has exactly $2 + |Y_L|$ places and $\variety(L)$ transitions.
The edges present in $M$ are also encoded in $Y_L$, as every element $(A, B) \in Y_L$ issues $|A| + |B|$ edges being constructed in $M$.
Furthermore, $M$ contains $|A_I|$ edges starting from $p_i$ and $|A_O|$ edges ending in $p_o$.
Regarding the connectors in the model $M$ found by the alpha algorithm, we have:
\begin{align*}
	S_{\texttt{xor}}^M &= \{(B,C) \in Y_L \mid 1 < |C|\} \cup \{(\emptyset, A_I) \mid 1 < |A_I|\} \\
	J_{\texttt{xor}}^M &= \{(B,C) \in Y_L \mid 1 < |B|\} \cup \{(A_O, \emptyset) \mid 1 < |A_O|\} \\
	S_{\texttt{and}}^M &= \{b \in A \mid 1 < |\{(B, C) \in Y_L \mid b \in B\}|\} \\
	J_{\texttt{and}}^M &= \{c \in A \mid 1 < |\{(B, C) \in Y_L \mid c \in C\}|\}
\end{align*}
We will now describe the model complexity scores of a model $M$ found by the alpha algorithm for an event log $L$ over $A$.

\begin{itemize}
	\item \textbf{Size $\size$:}
	As argued before, $M$ contains $2 + |Y_L|$ places and $\variety(L)$ transitions.
	Thus, $\size(M) = 2 + |Y_L| + \variety(L)$.

	\item \textbf{Mismatch $\mismatch$:}
	With the notions above, the amount of mismatches between \texttt{xor}-connectors is  $MM_{\texttt{xor}} = \left| \sum_{(B,C) \in S_{\texttt{xor}}} |C| - |B| \right|$, while the amount of mismatches between \texttt{and}-connectors is 
	\[MM_{\texttt{and}} = \left|\sum_{a \in A} |\{(B,C) \in Y_L \mid a \in B\}| - |\{(B,C) \in Y_L \mid a \in C\}| \right|\]
	With these notions, $\mismatch(M) = MM_{\texttt{xor}} + MM_{\texttt{and}}$.

	\item \textbf{Connector Heterogeneity $\connhet$:}
	For the connector heterogeneity score, we take $r_{\texttt{xor}}^M = \frac{|S_{\texttt{xor}}^M \cup J_{\texttt{xor}}^M|}{|S_{\texttt{xor}}^M \cup J_{\texttt{xor}}^M \cup S_{\texttt{and}}^M \cup J_{\texttt{and}}^M|}$ and $r_{\texttt{and}}^M = \frac{|S_{\texttt{and}}^M \cup J_{\texttt{and}}^M|}{|S_{\texttt{xor}}^M \cup J_{\texttt{xor}}^M \cup S_{\texttt{and}}^M \cup J_{\texttt{and}}^M|}$ to calculate the connector heterogeneity $\connhet(M) = -(r_{\texttt{xor}}^M \cdot \log_2(r_{\texttt{xor}}^M) + r_{\texttt{and}}^M \cdot \log_2(r_{\texttt{and}}^M))$.

	\item \textbf{Cross Connectivity $\crossconn$:}
	The cross connectivity metric depends not only on properties of single nodes, but instead on all paths through the net. 
	While it would be possible to describe the scores of this measure with just $Y_L$ and $\variety(L)$, we doubt that such a description would yield any value due to its complexity, and therefore skip this metric.

	\item \textbf{Token Split $\tokensplit$:}
	With the notions above, we can describe the score of the token split measure as $\tokensplit(M) = \sum_{a \in S_{\texttt{and}}^M} \left(|\{(B,C) \in Y_L \mid a \in B\}| - 1\right)$.

	\item \textbf{Control Flow Complexity $\controlflow$:}
	With the notions above, we describe $M$'s control flow complexity score by $\controlflow(M) = |S_{\texttt{and}}^M| + \sum_{(B,C) \in S_{\texttt{xor}}^M} |B|$.

	\item \textbf{Separability $\separability$:}
	Like the cross connectivity metric, separability depends on the structure of the whole result, rather than properties of single nodes.
	A description for this measure would be highly complex and therefore of little value, so we skip this measure.

	\item \textbf{Average Connector Degree $\avgconn$:}
	With the previous notions, we define $C_{\texttt{xor}}^M = S_{\texttt{xor}}^M \cup J_{\texttt{xor}}^M$ as the set of all \texttt{xor}-connectors, and $C_{\texttt{and}}^M = S_{\texttt{and}}^M \cup J_{\texttt{and}}^M$ as the set of all \texttt{and}-connectors.
	The degree of an \texttt{xor}-connector $(B,C)$ in $M$ is $\text{deg}((B,C)) = |B| + |C|$, while the degree of an \texttt{and}-connector $a$ in $M$ is $\text{deg}(a) = |\{(B,C) \in Y_L \mid a \in B\}| + |\{(B,C) \in Y_L \mid a \in C\}|$.
	With this, we can describe the average connector degree of $M$ as: 
	\[\avgconn(M) = \frac{\sum_{(B,C) \in C_{\texttt{xor}}^M} \text{deg}((B,C)) + \sum_{a \in C_{\texttt{and}}^M} \text{deg}(a)}{|C_{\texttt{xor}}^M| + |C_{\texttt{and}}^M|}.\]

	\item \textbf{Maximum Connector Degree $\maxconn$:}
	With the same definitions for $C_{\texttt{xor}}^M$, $C_{\texttt{and}}^M$, $deg((B,C))$ for some $(B,C) \in C_{\texttt{xor}}^M$, and $deg(a)$ for some $a \in C_{\texttt{and}}^M$, we can describe the maximum connector degree as
	\[\maxconn(M) = \max(\{\text{deg}((B,C)) \mid (B,C) \in C_{\texttt{xor}}^M\} \cup \{\text{deg}(a) \mid a \in C_{\texttt{and}}^M\}).\]

	\item \textbf{Sequentiality $\sequentiality$}:
	With $C_{\texttt{xor}}^M = S_{\texttt{xor}}^M \cup J_{\texttt{xor}}^M$ and $C_{\texttt{and}}^M = S_{\texttt{and}}^M \cup J_{\texttt{and}}^M$, we can describe the sequentiality score of the alpha miner result $M$ as
	\[\sequentiality(M) = \sum_{(B,C) \in (Y_L \setminus C_{\texttt{xor}}^M)} |\{b \in B \mid b \not\in C_{\texttt{and}}^M\}| + |\{c \in C \mid c \not\in C_{\texttt{and}}^M\}|.\]

	\item \textbf{Depth $\depth$:}
	Since the depth of a node is dependent on the paths through $M$, we cannot describe the depth of $M$ in simple terms. 
	Therefore, we will skip this measure.

	\item \textbf{Diameter $\diameter$:}
	The diameter of the net is dependent on all paths through $M$, so we cannot describe it for $M$ in simple terms.
	Therefore, we will skip this measure.

	\item \textbf{Cyclicity $\cyclicity$:}
	Which nodes lie on cycles depends on the cyclic paths in the net $M$. 
	We cannot describe this notion in simple terms, so we will skip this measure.

	\item \textbf{Coefficient of Network Connectivity $\netconn$:}
	By the previous discussions, we know that $M$ contains $2 + |Y_L| + \variety(L)$ nodes and $|A_I| + |A_O| + \sum_{(B,C) \in Y_L} |B| + |C|$ edges, so its coefficient of network connectivity is 
	\[\netconn(M) = \frac{|A_I| + |A_O| + \sum_{(B,C) \in Y_L} |B| + |C|}{2 + |Y_L| + \variety(L)}.\] 

	\item \textbf{Density $\density$:}
	By the previous discussions, we know that $M$ contains exactly $2 + |Y_L|$ places, $\variety(L)$ transitions, and $|A_I| + |A_O| + \sum_{(B,C) \in Y_L} |B| + |C|$ edges. 
	Thus, its density is 
	\[\density(M) = \frac{|A_I| + |A_O| + \sum_{(B,C) \in Y_L} |B| + |C|}{2 \cdot \variety(L) \cdot (1 + |Y_L|)}.\]

	\item \textbf{Number of Duplicate Tasks $\duplicate$:}
	The alpha miner constructs exactly one transition for every activity name in the event log $L$, and no transitions beyond that.
	Therefore, in every model found by the alpha algorithm, each transition label occurs exactly once, giving us $\duplicate(M) = 0$.

	\item \textbf{Number of Empty Sequence Flows $\emptyseq$:}
	The number of empty sequence flows can be described as $\emptyseq(M) = |\{(B,C) \in Y_L \mid B \subseteq S_{\texttt{and}}^M \land C \subseteq J_{\texttt{and}}^M\}|$.
\end{itemize}
These findings conclude our analysis of the alpha miner. 
