\begin{theorem}
\label{theo:dfg-seq-entries}
$(\mathcal{C}^L, \sequentiality) \in \norel$ for any event log complexity measure $\mathcal{C}^L \in \loc$.
\end{theorem}
\begin{proof}
Consider the following event logs:
\begin{align*}
	L_1 &= [\langle a,b,d,e \rangle^{2}, \langle a,c,d,e \rangle^{2}, \langle a,b,c,d,e \rangle, \langle e \rangle] \\
	L_2 &= L_1 + [\langle a,b,d,a,c,d \rangle^{2}, \langle a,b,c,d,e,f,g \rangle] \\
	L_3 &= L_2 + [\langle a,b,d,a,b,d,a,c,d \rangle, \langle a,b,c,d,e,f,h \rangle]
\end{align*}
\cref{fig:dfg-sequentiality} shows the directly follows graphs $G_1, G_2, G_3$ for the event logs $L_1, L_2, L_3$.
