Due to its construction, many complexity scores of a model $M$ found by the directly follows miner for an event log $L$ can be described by the complexity scores of its underlying directly follows graph $G = (V,E)$.
In contrast to the previous sections, we will start by comparing the complexity scores of models found by the directly follows miner to the complexity scores of their underlying directly follows graph, as these findings will render some analyses trivial.
\begin{itemize}
	\item \textbf{Size $\size$:}
	Every node in $G$ becomes a place in $M$, so the number of places in $M$ is $|P| = |V|$.
	Furthermore, every edge in $G$ issues the creation of exactly one transition in $M$, so $|T| = |E|$.
	Therefore, we can describe the size of $M$ as $\size(M) = \size(G) + |E| = 2 + \variety(L) + |A_I| + |A_O|$.

	\item \textbf{Connector Mismatch $\mismatch$:}
	By construction, only places in $M$ can be connectors, as all transitions have exactly one incoming and one outgoing edge.
	A place $p_v$ in $M$ has $x$ incoming and $y$ outgoing edges if its corresponding node $v \in V$ has $x$ incoming and $y$ outgoing edges.
	Thus, the set of connectors in $M$ is the same as in $G$, and every connector in $M$ has the same in- and out-degree as its corresponding node in $G$.
	Therefore, $\mismatch(M) = \mismatch(G) = \left| \sum_{a \in S_{\texttt{xor}}^G} |\succ_L(a)| + \sum_{a \in J_{\texttt{xor}}^G} |\succ_L^{-1}(a)| \right|$.

	\item \textbf{Connector Heterogeneity $\connhet$:}
	In directly follows graphs, it did not make sense to calculate the entropy of connectors, as this modeling type does not contain semantics for parallelism.
	A model found by the directly follows miner, on the other hand, is a workflow net and thus has the required semantics.
	However, due to its construction, $M$ contains only \texttt{xor}-connectors, so $\connhet(M) = - (1 \cdot \log_2(1) + 0 \cdot \log_2(0)) = 0$.

	\item \textbf{Token Split $\tokensplit$:}
	In directly follows graphs, it did not make sense to calculate the entropy of connectors, as this modeling type does not contain semantics for parallelism.
	A model found by the directly follows miner, on the other hand, is a workflow net and thus has the required semantics.
	However, due to its construction, $M$ contains no transitions with more than one outgoing edge, so $\tokensplit(M) = 0$.

	\item \textbf{Control Flow Complexity $\controlflow$:}
	Every transition in $M$ has exactly one incoming and one outgoing arc by construction, so there are no \texttt{and}-connectors in $M$.
	But as argued earlier, every \texttt{xor}-connector in $G$ has a corresponding \texttt{xor}-connector in $M$ with the same amount of incoming and outgoing edges.
	Therefore, $\controlflow(M) = \controlflow(G) = \sum_{a \in S_{\texttt{xor}}^G} |\succ_L(a)|$.

	\item \textbf{Average Connector Degree $\avgconn$:}
	As argued earlier, every \texttt{xor}-connector in $G$ has a corresponding \texttt{xor}-connector in $M$ with the same amount of incoming and outgoing edges.
	Since there are no other connectors in $M$, we get $\avgconn(M) = \avgconn(G) = \frac{\sum_{a \in C_{\texttt{xor}}^G} (|\succ_L(a)| + |\succ_L^{-1}(a)|)}{|C_{\texttt{xor}}^G|}$.

	\item \textbf{Maximum Connector Degree $\avgconn$:}
	As argued before, all \texttt{xor}-connectors in $G$ have a corresponding \texttt{xor}-connector in $M$ with the same amount of incoming and outgoing edges.
	Since there are no other connectors in $M$, we get $\maxconn(M) = \maxconn(G) = \max\{|\succ_L(a)| + |\succ_L^{-1}(a)| \mid a \in C_{\texttt{xor}}^G\}$.

	\item \textbf{Sequentiality $\sequentiality$:}
	In $M$, no transition can be a connector of any type.
	Thus, all edges in $M$ have at least one non-connector endpoint.
	Whether the other endpoint $p_v$ of such an edge is also a non-connector depends on whether its corresponding node $v \in V'$ is a connector.
	If $p_v$ is not a connector, then it has exactly one incoming and one outgoing edge when $v \not\in \{\triangleright, \square\}$, and exactly one adjacent edge otherwise.
	Thus, $M$ has a sequentiality score of $\sequentiality(M) = 2 |V' \setminus (C_{\texttt{xor}}^G \cup \{\triangleright, \square\})| + |\{p_i \mid \triangleright \in C_{\texttt{xor}}^G\}| + |\{p_o \mid \square \in C_{\texttt{xor}}^G\}\}|$.

	\item \textbf{Diameter $\diameter$:}
	By construction, every path $(\triangleright, v_1, \dots, v_k, \square)$ in $G$ corresponds to a path $(p_{\triangleright}, v_1, p_{v_1}, \dots, v_k, p_{v_k}, \tau, p_{\square})$ in $M$, where $k \in \mathbb{N}_0$.
	Since there are no other paths in $M$, the longest path in $G$ of length $\ell$ corresponds to the longest path in $M$, which has length $2 \ell - 1$.
	Thus, $\diameter(M) = 2 \diameter(G) - 1$.

	\item \textbf{Coefficient of Network Connectivity $\netconn$:}
	Since each transition in $M$ has exactly one incoming and one outgoing edge, and contains $|>_L| + |A_I| + |A_O|$ transitions in total, there are $2(|>_L| + |A_I| + |A_O|)$ edges in $M$.
	Thus, $\netconn(M) = \frac{2(|>_L| + |A_I| + |A_O|)}{2 + \variety(L) + |>_L| + |A_I| + |A_O|} = \frac{2|V| \cdot \netconn(G)}{|V| + |E|}$.

	\item \textbf{Density $\density$:}
	As argued before, $M$ contains $2(|>_L| + |A_I| + |A_O|)$ edges in total.
	Thus, $\density(M) = \frac{2(|>_L| + |A_I| + |A_O|)}{2(|>_L| + |A_I| + |A_O|) \cdot (1 + \variety(L)} = \frac{1}{1 + \variety(L)}$.

	\item \textbf{Number of Empty Sequence Flows $\emptyseq$:}
	Since $M$ does not contain any \texttt{and}-connectors, there cannot be any places in $M$ that have just \texttt{and}-connectors in their pre- and postset. 
	In turn, $\emptyseq(M) = 0$.
\end{itemize}
