With the observations of \cref{table:dfm-model-complexity}, the analysis of $\mismatch$, $\controlflow$, $\avgconn$, and $\maxconn$ become trivial, since these measures return the exact same score for the directly follows graph and for the model found by the directly follows miner.
Thus, we can reuse our results of \cref{sec:dfg} for these measures.

\begin{theorem}
\label{theo:dfm-size-cfc-leq-entries}
Let $\mathcal{C}^L \in (\loc \setminus \{\variety, \levelofdetail, \numberofties\})$ be a log complexity measure and $\mathcal{C}^M \in \{\size, \controlflow\}$.
Then, $(\mathcal{C}^L, \mathcal{C}^M) \in \mleq$.
\end{theorem}
\begin{proof}
Let $M$ be the model found by the directly follows miner for an event log $L$, and $G$ be the directly follows graph for $L$.
The claim of this theorem is obvious for $\controlflow$, since $\controlflow(M) = \controlflow(G)$, and $(\mathcal{C}^L, \controlflow) \in \mleq$ by \cref{theo:dfg-cfc-leq-entries}.
For $\size$, we can use the same examples as in this theorem.
First, consider the logs:
\begin{align*}
	L_1 &= [\langle a,b,c,c \rangle^2, \langle c,c,d,e \rangle] \\
	L_2 &= L_1 + [\langle a,b,c,d,e \rangle]
\end{align*}
Let $M_1, M_2$ be the models found by the directly follows miner for $L_1, L_2$.
Then, $\size(M_1) = 16 = \size(M_2)$.
As we have seen in \cref{theo:dfg-cfc-leq-entries}, all log complexity scores except $\variety, \levelofdetail, \numberofties$, and $\affinity$ strictly increase for these event logs.
For $\affinity$, we can again use the event logs
\begin{align*}
	L_1 &= [\langle a,b,c,c \rangle, \langle c,c,d,e \rangle] \\
	L_2 &= L_1 + [\langle a,b,c,d,e \rangle]
\end{align*}
in which affinity increases. 
But the directly follows graphs, and therefore the models found by the directly follows miner, are the same for $L_1$ and $L_2$.
Thus, $\mathcal{C}^L(L_1) < \mathcal{C}^L(L_2)$ and $\size(M_1) = \size(M_2)$ is possible.

To see that $\mathcal{C}^L(L_1) < \mathcal{C}^L(L_2)$ and $\size(M_1) < \size(M_2)$ is also possible, consider the following event logs, which were already used and analyzed for their directly follows graph in \cref{theo:dfg-cfc-leq-entries}:
\begin{align*}
	L_1 &= [\langle a,b,c,d \rangle^{2}, \langle a,b,c,d,e \rangle^{2}, \langle d,e,a,b \rangle^{2}] \\
	L_2 &= [\langle a,b,c,d,e \rangle^{2}, \langle d,e,a,b,c \rangle, \langle c,d,e,a,b \rangle, \langle e,c,d,a,b,c,f \rangle]
\end{align*}
The models $M_1, M_2$ found by the directly follows miner for these event logs fulfill $\size(M_1) = 17 < 25 = \size(M_2)$, but \cref{theo:dfg-cfc-leq-entries} shows that all log complexity scores strictly increase for these two event logs.
Thus, $\mathcal{C}^L(L_1) < \mathcal{C}^L(L_2)$ and $\size(M_1) < \size(M_2)$ is also possible.

Finally, it is not possible that $\size$ decreases, as the size of the directly follows model $M$ is exactly the amount of nodes and edges in its underlying directly follows graph $G$. 
The latter can only increase when adding behavior to the underlying event log, as already discussed in \cref{sec:dfg}. \hfill$\square$
\end{proof}

\begin{theorem}
\label{theo:dfm-size-cfc-less-entries}
Let $\mathcal{C}^L \in (\loc \setminus \{\variety, \levelofdetail, \numberofties\})$ be a log complexity measure and $\mathcal{C}^M \in \{\size, \controlflow\}$.
Then, $(\mathcal{C}^L, \mathcal{C}^M) \in \mless$.
\end{theorem}
\begin{proof}
The claim is trivial for $\mathcal{C}^M = \controlflow$, since for any model $M$ found by the directly follows miner for an event log $L$, we have $\controlflow(M) = \controlflow(G)$, where $G = (V,E)$ is the directly follows graph for $L$.
\cref{theo:dfg-cfc-less-entries} shows that the claim is true for $\controlflow(G)$, so we can deduce that it also holds for $\controlflow(M)$.
Furhtermore, \cref{theo:dfg-cfc-less-entries} discusses that an increase in $\mathcal{C}^L$ means that at least one new edge gets introduced to the directly follows graph.
Since $\size(M) = \size(G) + |E|$, we can immediately see that $\size(M_1) < \size(M_2)$ for two models $M_1,M_2$ found by the directly follows miner for event logs $L_1, L_2$, if $\mathcal{C}^L(L_1) < \mathcal{C}^L(L_2)$. \hfill$\square$
\end{proof}

\begin{theorem}
\label{theo:dfm-mismatch-entries}
$(\mathcal{C}^L, \mismatch) \in \norel$ for any log complexity measure $\mathcal{C}^L \in \loc$.
\end{theorem}
\begin{proof}
Let $L_1 \sqsubset L_2$ be event logs, $G_1, G_2$ their directly follows graphs, and $M_1, M_2$ the models found by the directly follows miner for $L_1, L_2$.
Then, we know that $\mismatch(M_1) = \mismatch(G_1)$ and $\mismatch(M_2) = \mismatch(G_2)$.
Furthermore, by \cref{theo:dfg-mismatch-entries}, we know $\mismatch(G_1) < \mismatch(G_2)$, $\mismatch(G_1) > \mismatch(G_2)$, and $\mismatch(G_1) = \mismatch(G_2)$ are possible when event log complexity increases.
Thus, $\mismatch(M_1) < \mismatch(M_2)$, $\mismatch(M_1) > \mismatch(M_2)$, and $\mismatch(M_1) = \mismatch(M_2)$ are all possible as well. \hfill$\square$
\end{proof}

\begin{theorem}
\label{theo:dfm-equals-entries}
$(\mathcal{C}^L, \mathcal{C}^M) \in \meq$ for any log complexity measure $\mathcal{C}^L \in \loc$ and any $\mathcal{C}^M \in \{\connhet, \tokensplit, \emptyseq\}$.
\end{theorem}
\begin{proof}
Let $L$ be an event log and $M$ be the model found by the directly follows miner for $L$.
By construction, all transitions in $M$ have exactly one incoming and one outgoing edge.
Thus, there are no \texttt{and}-connectors in $M$.
In turn, we get $\connhet(M) = 0$, $\tokensplit(M) = 0$, and $\emptyseq(M) = 0$, so for two event logs $L_1, L_2$ and their directly follows models $M_1, M_2$, we always have $\mathcal{C}^M(M_1) = \mathcal{C}^M(M_2)$. \hfill$\square$
\end{proof}

\begin{theorem}
\label{theo:dfm-crossconn-entries}
$(\mathcal{C}^L, \crossconn) \in \norel$ for any log complexity measure $\mathcal{C}^L \in \loc$.
\end{theorem}
\begin{proof}
We can use the same counter examples as those of \cref{theo:dfg-crossconn-entries}.
For models $M_1, M_2, M_3$ found by the directly follows miner for the event logs 
\begin{align*}
	L_1 &= [\langle a,b \rangle^{5}, \langle c,d \rangle, \langle e,f \rangle, \langle g \rangle] \\
	L_2 &= L_1 + [\langle a,b,c,d \rangle, \langle s,t,u,v,w,x,y,z \rangle] \\
	L_3 &= L_2 + [\langle h,i,j,k,l,m,n,o,p \rangle]
\end{align*}
we get $\crossconn(M_1) \approx 0.8893 > \crossconn(M_2) \approx 0.8775 < 0.8911$.
Since $\affinity$ and $\normvarentropy$ do not strictly increase for these event logs, we also use the second counter example of \cref{theo:dfg-crossconn-entries}.
For models $M_1, M_2, M_3$ found by the directly follows miner for hte event logs
\begin{align*}
	L_1 &= [\langle a,b,c,d \rangle, \langle c,d,e,f \rangle, \langle e,f,g \rangle, \langle a,b \rangle, \langle c,d \rangle, \langle e,f \rangle, \langle g \rangle] \\
	L_2 &= L_1 + [\langle a,b,c,d \rangle^{2}, \langle q,r,s,t \rangle, \langle u,v,w,x,y,z \rangle] \\
	L_3 &= L_2 + [\langle a,b,c,d \rangle^{3}, \langle h \rangle, \langle i \rangle, \langle j \rangle]
\end{align*}
we have $\crossconn(M_1) \approx 0.9675 > \crossconn(M_2) \approx 0.931 < \crossconn(M_3) \approx 0.9496$, while the scores of $\affinity$ and $\normvarentropy$ strictly increase.
Thus,in total it is not possible to predict the behaviour of $\crossconn$ when log complexity increases. \hfill$\square$
\end{proof}

