\begin{theorem}
\label{theo:dfm-acd-entries}
$(\mathcal{C}^L, \avgconn) \in \norel$ for any log complexity measure $\mathcal{C}^L \in \loc$.
\end{theorem}
\begin{proof}
Let $L_1 \sqsubset L_2$ be event logs, $G_1, G_2$ be their directly follows graphs, and $M_1, M_2$ the models found by the directly follows miner for $L_1, L_2$.
By previous discussion, we know that $\avgconn(M_1) = \avgconn(G_1)$ and $\avgconn(M_2) = \avgconn(G_2)$.
Furthermore, by \cref{theo:dfg-acd-entries}, we know $\avgconn(G_1) < \avgconn(G_2)$, $\avgconn(G_1) > \avgconn(G_2)$, and $\avgconn(G_1) = \avgconn(G_2)$ are possible when log complexity increases.
Thus, $\avgconn(M_1) < \avgconn(M_2)$, $\avgconn(M_1) > \avgconn(M_2)$, and $\avgconn(M_1) = \avgconn(M_2)$ are all possible as well. \hfill$\square$
\end{proof}

\begin{theorem}
\label{theo:dfm-mcd-entries}
$(\mathcal{C}^L, \maxconn) \in \mleq$ for any log complexity measure $\mathcal{C}^L \in \loc$.
\end{theorem}
\begin{proof}
Let $L_1 \sqsubset L_2$ be event logs, $G_1, G_2$ be their directly follows graphs, and $M_1, M_2$ the models found by the directly follows miner for $L_1, L_2$.
By previous discussion, we know that $\maxconn(M_1) = \maxconn(G_1)$ and $\maxconn(M_2) = \maxconn(G_2)$.
Furthermore, by \cref{theo:dfg-mcd-diam-entries}, we know that $\mathcal{C}^L(L_1) < \mathcal{C}^L(L_2)$ always implies $\maxconn(G_1) \leq \maxconn(G_2)$, and $\maxconn(G_1) < \maxconn(G_2)$ and $\maxconn(G_1) = \maxconn(G_2)$ are both possible outcomes.
Thus, we can deduce that $\mathcal{C}^L(L_1) < \mathcal{C}^L(L_2)$ always implies $\maxconn(M_1) \leq \maxconn(M_2)$, and both $\maxconn(M_1) < \maxconn(M_2)$ and $\maxconn(M_1) = \maxconn(M_2)$ are possible outcomes. \hfill$\square$
\end{proof}

